/**
 * 创建标签页
 * @param {string} type - 标签类型
 * @param {string} title - 标签标题
 * @param {object} data - 额外数据
 * @returns {object} 标签对象
 */
function createTab(type, title, data = {}) {
  const id = `tab_${++tabState.tabCounter}`;
  return { id, type, title, data };
}

function getCaseManagerTabNumber(tab) {
  const fromData = Number(tab?.data?.instanceNo || 0);
  if (Number.isInteger(fromData) && fromData > 0) return fromData;
  const match = String(tab?.title || '').match(/^案件管理\s*(\d+)$/);
  if (match) return Number(match[1]);
  return tab?.type === TAB_TYPES.CASE_MANAGER ? 1 : 0;
}

function nextCaseManagerTabNumber() {
  const used = new Set(
    tabState.tabs
      .filter(tab => tab.type === TAB_TYPES.CASE_MANAGER)
      .map(getCaseManagerTabNumber)
      .filter(Boolean)
  );
  let no = 1;
  while (used.has(no)) no += 1;
  return no;
}

function normalizeCaseManagerTabs() {
  const used = new Set();
  tabState.tabs
    .filter(tab => tab.type === TAB_TYPES.CASE_MANAGER)
    .forEach(tab => {
      let no = getCaseManagerTabNumber(tab);
      if (!no || used.has(no)) {
        no = 1;
        while (used.has(no)) no += 1;
      }
      used.add(no);
      tab.data = { ...(tab.data || {}), instanceNo: no };
      tab.title = `案件管理 ${no}`;
    });
}

/**
 * 打开一个标签页
 * @param {string} type - 标签类型
 * @param {string} title - 标签标题
 * @param {object} data - 额外数据（文章ID、URL等）
 */
function openTab(type, title, data = {}) {
  // 检查是否已存在相同实例的标签（除了主标签）。法律知识中心按 claim_id
  // 区分具体结论页，因此不同结论可以同时打开。
  if (type !== TAB_TYPES.MAIN) {
    const existingTab = tabState.tabs.find(t => 
      t.type === type && 
      (type === TAB_TYPES.MAIN || 
       (type === TAB_TYPES.ARTICLE && t.data.articleId === data.articleId) ||
       (type === TAB_TYPES.LEGAL_KNOWLEDGE && Number(t.data?.claimId || 0) === Number(data.claimId || 0)) ||
       (type === TAB_TYPES.FADA_WANG) ||
       (type === TAB_TYPES.INTEREST_CALC) ||
       (type === TAB_TYPES.SUOHAN) ||
       (type === TAB_TYPES.POWER_ATTORNEY) ||
       (type === TAB_TYPES.REP_IDENTITY_CERT) ||
       (type === TAB_TYPES.DOCUMENT_BUNDLE) ||
       (type === TAB_TYPES.QUICK_APPROVAL) ||
       (type === TAB_TYPES.KB_STATS) ||
       (type === TAB_TYPES.KNOWLEDGE_EXPAND) ||
       (type === TAB_TYPES.RECOMMENDATIONS) ||
       (type === TAB_TYPES.AI_API_MANAGER) ||
       (type === TAB_TYPES.MCP_MANAGER) ||
        (type === TAB_TYPES.SKILL_MANAGER) ||
        (type === TAB_TYPES.RECORDING) ||
        (type === TAB_TYPES.QQ_MAIL) ||
        (type === TAB_TYPES.QQ_EXMAIL) ||
        (type === TAB_TYPES.NETEASE_EXMAIL) ||
        (type === TAB_TYPES.INVOICE_CENTER) ||
        (type === TAB_TYPES.MINGSI_MEETING) ||
        (type === TAB_TYPES.DOWNLOAD_CENTER) ||
        (type === TAB_TYPES.SCANNER_INBOX) ||
       (type === TAB_TYPES.TEAM_EXPENSES) ||
       (type === TAB_TYPES.COURT_DIRECTORY) ||
       (type === TAB_TYPES.COURT_ONLINE) ||
       (type === TAB_TYPES.AUTOMATED_FILING) ||
        (type === TAB_TYPES.USER_MANUAL) ||
        (type === TAB_TYPES.PERSONAL_CENTER) ||
       (type === TAB_TYPES.AI_ASK))
    );
    if (existingTab) {
      if (
        data.caseId &&
        [TAB_TYPES.SUOHAN, TAB_TYPES.POWER_ATTORNEY, TAB_TYPES.REP_IDENTITY_CERT, TAB_TYPES.DOCUMENT_BUNDLE].includes(type)
      ) {
        existingTab.data = {...(existingTab.data || {}), caseId:Number(data.caseId)};
        const frame = document.getElementById(existingTab.id)?.querySelector('iframe');
        const paths = {
          [TAB_TYPES.SUOHAN]:'/suohan-generator',
          [TAB_TYPES.POWER_ATTORNEY]:'/power-attorney-generator',
          [TAB_TYPES.REP_IDENTITY_CERT]:'/rep-identity-cert-generator',
          [TAB_TYPES.DOCUMENT_BUNDLE]:'/document-bundle-generator',
          [TAB_TYPES.BUSINESS_APPROVAL]:'/business-approval-generator'
        };
        if (frame) frame.src = `${paths[type]}?v=2026090402&case_id=${encodeURIComponent(data.caseId)}`;
      }
      // 切换到已存在的标签
      switchTab(existingTab.id);
      // 如果是文章，刷新内容
      if (type === TAB_TYPES.ARTICLE && data.articleId) {
        loadArticleInTab(existingTab.id, data.articleId);
      }
      if (type === TAB_TYPES.FADA_WANG && data.itemId) {
        existingTab.data = { ...existingTab.data, itemId: data.itemId };
        navigateFadaTabToItem(existingTab.id, data.itemId);
      }
      saveTabsState();
      return;
    }
  }

  // 创建新标签
  if (type === TAB_TYPES.CASE_MANAGER) {
    const instanceNo = Number(data.instanceNo || 0) || nextCaseManagerTabNumber();
    data = { ...data, instanceNo };
    title = `案件管理 ${instanceNo}`;
  }
  const tab = createTab(type, title, data);
  tabState.tabs.push(tab);
  
  // 创建标签页内容
  createTabPage(tab);
  
  // 渲染标签
  renderTabs();
  
  // 切换到新标签
  switchTab(tab.id);
  saveTabsState();
}

function caseManagerFrameSrc(tab) {
  const view = tab?.data?.viewState || {};
  const params = new URLSearchParams({ v: '2026090402', workspace_id: String(tab?.id || 'case-manager') });
  if (view.initialTab === 'courtOnline') params.set('tab', 'courtOnline');
  if (Number(view.courtRecordId || 0) > 0) params.set('court_record', String(Number(view.courtRecordId)));
  const numericParams = {
    series_body_scroll: view.bodyScrollTop,
    series_table_scroll_top: view.tableScrollTop,
    series_table_scroll_left: view.tableScrollLeft,
  };
  Object.entries(numericParams).forEach(([key, value]) => {
    const number = Number(value || 0);
    if (Number.isFinite(number) && number > 0) params.set(key, String(Math.round(number)));
  });
  const seriesId = Number(view.seriesId || 0);
  const seriesTab = view.seriesTab === 'public' ? '/public' : '';
  const hash = seriesId > 0 ? `#series/${seriesId}${seriesTab}` : '';
  return `/case-manager?${params.toString()}${hash}`;
}

/**
 * 创建标签页内容区域
 */
function createTabPage(tab) {
  const contentArea = $('tab-content-area');
  if (!contentArea) {
    console.error('tab-content-area not found');
    return;
  }
  
  const pageEl = document.createElement('div');
  pageEl.className = 'tab-page';
  pageEl.id = tab.id;
  pageEl.dataset.tabId = tab.id;
  pageEl.dataset.tabType = tab.type;
  
  switch (tab.type) {
    case TAB_TYPES.ARTICLE:
      // 文章详情页
      pageEl.innerHTML = `
        <div class="tab-article-loading">加载中...</div>
      `;
      break;
      
    case TAB_TYPES.FADA_WANG:
      // 法答网页面
      pageEl.innerHTML = `<iframe src="/fada-wang${tab.data?.itemId ? `?item=${encodeURIComponent(tab.data.itemId)}` : ''}" class="tab-iframe" frameborder="0"></iframe>`;
      break;
      
    case TAB_TYPES.INTEREST_CALC:
      // 利息计算器
      pageEl.innerHTML = `<iframe src="/interest-calculator" class="tab-iframe" frameborder="0"></iframe>`;
      break;
      
    case TAB_TYPES.SUOHAN:
      // 所函生成器
      pageEl.innerHTML = `<iframe src="/suohan-generator?v=2026082101${tab.data?.caseId ? `&case_id=${encodeURIComponent(tab.data.caseId)}` : ''}" class="tab-iframe" frameborder="0"></iframe>`;
      break;
      
    case TAB_TYPES.POWER_ATTORNEY:
      // 授权委托书生成器
      pageEl.innerHTML = `<iframe src="/power-attorney-generator?v=2026082102${tab.data?.caseId ? `&case_id=${encodeURIComponent(tab.data.caseId)}` : ''}" class="tab-iframe" frameborder="0"></iframe>`;
      break;
      
    case TAB_TYPES.REP_IDENTITY_CERT:
      // 法定代表人证明书生成器
      pageEl.innerHTML = `<iframe src="/rep-identity-cert-generator?v=2026080803${tab.data?.caseId ? `&case_id=${encodeURIComponent(tab.data.caseId)}` : ''}" class="tab-iframe" frameborder="0"></iframe>`;
      break;

    case TAB_TYPES.DOCUMENT_BUNDLE:
      // 文书合集生成器
      pageEl.innerHTML = `<iframe src="/document-bundle-generator?v=2026090402${tab.data?.caseId ? `&case_id=${encodeURIComponent(tab.data.caseId)}` : ''}" class="tab-iframe" frameborder="0"></iframe>`;
      break;

    case TAB_TYPES.BUSINESS_APPROVAL:
      // 业务审批表生成器
      pageEl.innerHTML = `<iframe src="/business-approval-generator?v=2026090401${tab.data?.caseId ? `&case_id=${encodeURIComponent(tab.data.caseId)}` : ''}" class="tab-iframe" frameborder="0"></iframe>`;
      break;

    case TAB_TYPES.QUICK_APPROVAL:
      // 快速报批
      pageEl.innerHTML = '<iframe src="/quick-approval?v=2026091403" class="tab-iframe" frameborder="0" title="快速报批"></iframe>';
      break;
      
    case TAB_TYPES.KB_STATS:
      // 知识库可视化统计
      pageEl.innerHTML = `<iframe src="/kb-stats" class="tab-iframe" frameborder="0"></iframe>`;
      break;

    case TAB_TYPES.KNOWLEDGE_EXPAND:
      // 探索
      pageEl.innerHTML = `<iframe src="/knowledge-expand" class="tab-iframe" frameborder="0"></iframe>`;
      break;

    case TAB_TYPES.LEGAL_KNOWLEDGE:
      pageEl.innerHTML = `<iframe src="/legal-knowledge${tab.data?.claimId ? `?claim_id=${encodeURIComponent(tab.data.claimId)}` : ''}" class="tab-iframe legal-knowledge-frame" frameborder="0"></iframe>`;
      break;

    case TAB_TYPES.RECOMMENDATIONS:
      // 今日推荐
      pageEl.innerHTML = `<iframe src="/recommendations" class="tab-iframe" frameborder="0"></iframe>`;
      break;

    case TAB_TYPES.RESEARCH_PROJECTS:
      activateResearchStateForTab(tab.id);
      pageEl.innerHTML = `<div class="research-shell" id="research-shell-${tab.id}">加载中...</div>`;
      setTimeout(() => initResearchProjectsPage(tab.id), 0);
      break;

    case TAB_TYPES.CASE_MANAGER:
      pageEl.innerHTML = `<iframe src="${caseManagerFrameSrc(tab)}" class="tab-iframe" frameborder="0"></iframe>`;
      break;

    case TAB_TYPES.COURT_DIRECTORY:
      pageEl.innerHTML = '<iframe src="/court-directory" class="tab-iframe" frameborder="0" title="法院通讯录"></iframe>';
      break;

    case TAB_TYPES.COURT_ONLINE:
      pageEl.innerHTML = `<iframe src="/case-manager?tab=courtOnline&mode=court-online&workspace_id=${encodeURIComponent(tab.id)}&court_record=${encodeURIComponent(tab.data?.recordId || '')}&court_kind=${encodeURIComponent(tab.data?.courtKind || '')}&court_q=${encodeURIComponent(tab.data?.courtQuery || '')}" class="tab-iframe" frameborder="0" title="一张网"></iframe>`;
      break;

    case TAB_TYPES.AUTOMATED_FILING:
      pageEl.innerHTML = '<iframe src="/automation-filing" class="tab-iframe" frameborder="0" title="自动化立案"></iframe>';
      break;

    case TAB_TYPES.CASE_FILES:
      pageEl.innerHTML = `<iframe src="/case-files?case_id=${encodeURIComponent(tab.data?.caseId || '')}&title=${encodeURIComponent(tab.data?.caseTitle || '案件')}" class="tab-iframe case-files-frame" frameborder="0" title="案件文件"></iframe>`;
      break;

    case TAB_TYPES.CASE_ARCHIVE:
      pageEl.innerHTML = `<iframe src="/case-archive?case_id=${encodeURIComponent(tab.data?.caseId || '')}" class="tab-iframe" frameborder="0" title="案卷归档工作台"></iframe>`;
      break;

    case TAB_TYPES.AI_ASK:
      pageEl.classList.add('ask-tab-page');
      pageEl.innerHTML = '<div class="ask-tab-mount"></div>';
      break;

    case TAB_TYPES.AI_API_MANAGER:
      pageEl.innerHTML = '<iframe src="/ai-api-manager" class="tab-iframe ai-api-manager-frame" frameborder="0" title="AI API 管理"></iframe>';
      break;

    case TAB_TYPES.MCP_MANAGER:
      pageEl.innerHTML = '<iframe src="/mcp-manager" class="tab-iframe mcp-manager-frame" frameborder="0" title="MCP 服务管理"></iframe>';
      break;

    case TAB_TYPES.SKILL_MANAGER:
      pageEl.innerHTML = '<iframe src="/skill-manager" class="tab-iframe skill-manager-frame" frameborder="0" title="Skill 管理"></iframe>';
      break;

    case TAB_TYPES.RECORDING:
      pageEl.innerHTML = '<iframe src="/recording" class="tab-iframe recording-frame" frameborder="0" title="会议录音" allow="microphone; autoplay; fullscreen"></iframe>';
      break;

    case TAB_TYPES.QQ_MAIL:
      pageEl.innerHTML = '<iframe src="/qq-mail" class="tab-iframe qq-mail-frame" frameborder="0" title="QQ 邮箱邮件管理"></iframe>';
      break;

    case TAB_TYPES.QQ_EXMAIL:
      pageEl.innerHTML = '<iframe src="/qq-mail?account=qq_exmail" class="tab-iframe qq-mail-frame" frameborder="0" title="腾讯企业邮箱邮件管理"></iframe>';
      break;

    case TAB_TYPES.NETEASE_EXMAIL:
      pageEl.innerHTML = '<iframe src="/qq-mail?account=netease_exmail" class="tab-iframe qq-mail-frame" frameborder="0" title="网易企业邮箱邮件管理"></iframe>';
      break;

    case TAB_TYPES.INVOICE_CENTER:
      pageEl.innerHTML = '<iframe src="/invoice-center?account=' + encodeURIComponent(tab.data?.account || 'qq_mail') + '" class="tab-iframe invoice-center-frame" frameborder="0" title="发票中心"></iframe>';
      break;

    case TAB_TYPES.MINGSI_MEETING:
      pageEl.innerHTML = '<iframe src="/mingsi-meeting?v=room-labels-20260831" class="tab-iframe" frameborder="0" title="会议室预定"></iframe>';
      break;

    case TAB_TYPES.DOWNLOAD_CENTER:
      pageEl.innerHTML = '<iframe src="/download-center" class="tab-iframe" frameborder="0" title="下载中心"></iframe>';
      break;

    case TAB_TYPES.SCANNER_INBOX:
      pageEl.innerHTML = '<iframe src="/scanner-inbox" class="tab-iframe" frameborder="0" title="打印机扫描盘"></iframe>';
      break;

    case TAB_TYPES.TEAM_EXPENSES:
      pageEl.innerHTML = '<iframe src="/case-manager?tab=prepaidExpenses&mode=team-expenses" class="tab-iframe" frameborder="0" title="团队费用管理"></iframe>';
      break;

    case TAB_TYPES.USER_MANUAL:
      pageEl.innerHTML = '<iframe src="/user-manual" class="tab-iframe user-manual-frame" frameborder="0" title="使用说明书"></iframe>';
      break;

    case TAB_TYPES.PERSONAL_CENTER:
      pageEl.innerHTML = '<iframe src="/personal-center" class="tab-iframe personal-center-frame" frameborder="0" title="个人中心"></iframe>';
      break;

    case TAB_TYPES.EXTERNAL:
      // 外部链接 - 微信公众号页面（使用代理绕过 X-Frame-Options）
      const externalUrl = tab.data.url || '';
      const externalTitle = tab.data.title || '外部链接';
      // 使用代理接口
      const proxiedUrl = '/api/proxy?url=' + encodeURIComponent(externalUrl);
      pageEl.innerHTML = `
        <div class="tab-external-container">
          <div class="tab-external-header">
            <span class="tab-external-title">${escapeHtml(externalTitle)}</span>
            <a href="${externalUrl}" target="_blank" class="tab-external-open-btn" onclick="event.stopPropagation()">
              在新窗口打开 ↗
            </a>
          </div>
          <iframe src="${proxiedUrl}" class="tab-iframe tab-external-iframe tab-wechat-iframe" frameborder="0"
            sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox allow-top-navigation-by-user-activation"
            allow="autoplay; fullscreen; payment"></iframe>
        </div>
      `;
      break;

    default:
      pageEl.innerHTML = '<div class="tab-unknown">未知内容</div>';
  }
  
  // 先将元素添加到 DOM，确保 loadArticleInTab 能找到它
  contentArea.appendChild(pageEl);

  if (tab.type === TAB_TYPES.AI_ASK) {
    mountAskPanelInTab(tab, pageEl);
  }
  
  // 文章详情需要异步加载内容
  if (tab.type === TAB_TYPES.ARTICLE) {
    loadArticleInTab(tab.id, tab.data.articleId);
  }
}

/**
 * 在标签页中加载文章内容
 */
async function loadArticleInTab(tabId, articleId) {
  const pageEl = $(tabId);
  if (!pageEl) {
    console.error('Tab page element not found:', tabId);
    return;
  }
  
  // 重新渲染前先落盘当前位置，避免“先滚动再立刻重载”时丢失最新位置
  flushArticleReadPositionForTab(tabId);
  // 引用/笔记/关键词等明确跳转优先于上次阅读位置；渲染前先记录，渲染过程中这些标记会被消费
  const hasPendingNavigation = Boolean(
    state.pendingNoteId ||
    (state.pendingScrollOffset !== null && state.pendingScrollOffset !== undefined) ||
    state.pendingHighlight
  );
  
  try {
    // 显示加载状态
    pageEl.innerHTML = `
      <div class="tab-article-loading">
        <div class="spinner"></div>
        <span>加载中...</span>
      </div>
    `;
    
    // 获取文章数据
    const a = await apiFetch(`/api/articles/${articleId}`);
    
    // 更新标签标题
    const tab = tabState.tabs.find(t => t.id === tabId);
    if (tab) {
      tab.title = a.title;
      tab.data = { ...(tab.data || {}), article: a };
      renderTabs();
    }
    
    // 渲染完整文章详情
    await renderArticleDetailInTab(tabId, a);
    
    // 恢复上次阅读位置（强制刷新 / 关闭标签 / 服务器重启后再次打开时自动定位）
    if (!hasPendingNavigation) restoreArticleReadPositionInTab(tabId, a.id);
    
  } catch (e) {
    const stackText = String((e && e.stack) || e || '');
    pageEl.innerHTML = `<div class="tab-error">加载失败: ${e.message}<pre style="margin-top:12px;white-space:pre-wrap;word-break:break-all;font-size:11px;line-height:1.6;color:#64748b">${stackText}</pre></div>`;
  }
}

/**
 * 在标签页中渲染完整文章详情
 */
const ARTICLE_META_PERSON_ICON = `<svg class="meta-tag-icon" width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="5" r="2.5" fill="none" stroke="currentColor" stroke-width="1.35"/><path d="M3.5 13c.35-2.55 2-4 4.5-4s4.15 1.45 4.5 4" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round"/></svg>`;
const ARTICLE_META_TAG_ICON = `<svg class="meta-tag-icon" width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 3h5.1l5.9 5.9-4.6 4.6L3 7.6V3z" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linejoin="round"/><circle cx="5.5" cy="5.5" r=".9" fill="currentColor"/></svg>`;
const ARTICLE_META_EDIT_ICON = `<svg class="meta-action-icon" width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M3 11.5V14h2.5L13 6.5 9.5 3 2 10.5l1 1z" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linejoin="round"/><path d="M8.8 3.7l3.5 3.5" fill="none" stroke="currentColor" stroke-width="1.35"/></svg>`;
const ARTICLE_META_FILE_ICON = `<svg class="meta-tag-icon" width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2.5h5l3 3V13a.8.8 0 01-.8.8H4.8A.8.8 0 014 13V2.5z" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"/><path d="M9 2.7V6h3.1M6 8.5h4M6 11h3" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/></svg>`;

async function renderArticleDetailInTab(tabId, a) {
  const pageEl = $(tabId);
  if (!pageEl) return;
  
  const domains = (a.domains || []).map(d =>
    `<span class="meta-tag domain">${escapeHtml(d)}</span>`
  ).join('');

  const sourceTag = `<span class="meta-tag source">${
    a.source_type === 'url' ? '网页' : (a.source_type === 'manual' ? '手动创建' : '本地文件')
  }</span>`;
  const dateTag = `<span class="meta-tag date">${formatDate(a.created_at)}</span>`;

  // 提取作者标签
  const tags = a.tags || [];
  const authorTag = tags
    .filter(t => t.startsWith('作者:'))
    .map(t => {
      const author = t.replace('作者:', '');
      return `<span class="meta-tag author" onclick="openEditAuthorModal('${escapeHtml(author)}')">${ARTICLE_META_PERSON_ICON}<span>${escapeHtml(author)}</span></span>`;
    })
    .join('');

  // 提取非作者标签
  const customTags = tags
    .filter(t => !t.startsWith('作者:'))
    .map(t => `<span class="meta-tag tag">${ARTICLE_META_TAG_ICON}<span>${escapeHtml(t)}</span></span>`)
    .join('');

  // 编辑标签按钮
  const editTagsBtn = `<button class="btn-secondary article-meta-edit-btn" onclick="openEditTagsModal()">${ARTICLE_META_EDIT_ICON}<span>编辑标签</span></button>`;

  const sourceLink = a.source_url
    ? `<a class="meta-link" href="${escapeHtml(a.source_url)}" target="_blank" rel="noopener">${escapeHtml(truncate(a.source_url, 60))}</a>`
    : a.source_localpath
      ? `<span class="meta-localpath" title="点击在原路径打开文件" onclick="openLocalPath('${escapeHtml(a.source_localpath)}')">
           <svg width="13" height="13" viewBox="0 0 13 13" style="margin-right:4px;vertical-align:-2px"><path d="M1.5 3H5l1 1.5h5.5a.5.5 0 01.5.5v5a.5.5 0 01-.5.5h-10a.5.5 0 01-.5-.5V3.5a.5.5 0 01.5-.5z" stroke="currentColor" stroke-width="1.2" fill="none"/></svg>${escapeHtml(a.source_localpath)}</span>`
      : (a.source_filename
        ? `<span class="meta-tag date" style="cursor:pointer" onclick="openLocalFile('${escapeHtml(a.source_filename)}')">${ARTICLE_META_FILE_ICON}<span>${escapeHtml(a.source_filename)}</span></span>`
        : '');

  // 正文与智能目录一起渲染：系统生成的目录不再插入正文，改由左侧侧栏展示
  const renderedBody = renderBodyContentWithToc(a.content);
  const sidebarHasToc = Array.isArray(renderedBody.toc) && renderedBody.toc.length > 0;

  pageEl.innerHTML = `
    <div class="tab-article-detail">
      <!-- 顶部工具栏 -->
      <div class="tab-article-toolbar">
        <div class="tab-article-toolbar-left">
          <span class="tab-article-title">${escapeHtml(a.title)}</span>
          <button class="btn-icon article-title-edit-btn" title="编辑标题" aria-label="编辑标题" onclick="enableEditTitle()">
            <svg width="15" height="15" viewBox="0 0 16 16" aria-hidden="true"><path d="M3 11.5V14h2.5L13 6.5 9.5 3 2 10.5l1 1z" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linejoin="round"/><path d="M8.8 3.7l3.5 3.5" fill="none" stroke="currentColor" stroke-width="1.35"/></svg>
          </button>
        </div>
        <div class="tab-article-toolbar-right">
          <!-- 文章内搜索栏（带下拉列表） -->
          <div style="position:relative;display:flex;flex:1;gap:4px;align-items:center">
            <div class="detail-search-bar" style="flex:1">
              <svg class="detail-search-icon" width="14" height="14" viewBox="0 0 16 16"><circle cx="6.5" cy="6.5" r="5" stroke="currentColor" stroke-width="1.5" fill="none"/><path d="M10.5 10.5L14 14" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
              <input type="text" id="tab-detail-search-input-${tabId}" class="detail-search-input" placeholder="搜索…" oninput="onTabDetailSearchInput('${tabId}')" onkeydown="onTabDetailSearchKeydown(event, '${tabId}')" />
              <button class="detail-search-clear" onclick="clearTabDetailSearch('${tabId}')" style="display:none">
                <svg width="12" height="12" viewBox="0 0 12 12"><path d="M2 2l8 8M10 2L2 10" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
              </button>
            </div>
            <!-- 搜索结果下拉列表 -->
            <div id="tab-detail-search-dropdown-${tabId}" class="detail-search-dropdown" style="display:none;position:absolute;top:100%;left:0;right:0;z-index:9999;max-height:320px;overflow-y:auto;background:var(--bg-card);border:1px solid var(--border);border-radius:6px;box-shadow:0 4px 16px rgba(0,0,0,0.12);margin-top:4px"></div>
          </div>
          <button class="btn-icon btn-article-ask" title="针对本文AI增强" onclick="openArticleAskPanel(${a.id})">
            <span class="ai-wordmark" aria-hidden="true">AI</span>
          </button>
      <button class="btn-icon" title="关联案件" onclick="addArticleToResearchProject(${a.id})">
            <svg width="16" height="16" viewBox="0 0 16 16"><path d="M2 3h4l1 1.4h7v8.6H2z" stroke="currentColor" stroke-width="1.4" fill="none"/><path d="M8 7v4M6 9h4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>
          </button>
          <button class="btn-icon" title="显示/隐藏知识关联" onclick="toggleTabRelationsPanel('${tabId}')">
            <svg width="16" height="16" viewBox="0 0 16 16"><circle cx="4" cy="8" r="2" fill="none" stroke="currentColor" stroke-width="1.3"/><circle cx="12" cy="4" r="2" fill="none" stroke="currentColor" stroke-width="1.3"/><circle cx="12" cy="12" r="2" fill="none" stroke="currentColor" stroke-width="1.3"/><path d="M5.8 7.1l4.3-2.2M5.8 8.9l4.3 2.2" stroke="currentColor" stroke-width="1.3"/></svg>
          </button>
          <button class="btn-icon" title="显示/隐藏笔记" onclick="toggleTabNotesPanel('${tabId}')">
            <svg width="16" height="16" viewBox="0 0 16 16"><path d="M3 3h10v8l-4 2-4-2V3z" stroke="currentColor" stroke-width="1.4" fill="none"/><path d="M5 5.5h6M5 8h4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>
          </button>
          <button class="btn-icon btn-delete" title="删除" onclick="deleteArticleFromTab('${tabId}', ${a.id})">
            <svg width="16" height="16" viewBox="0 0 16 16"><path d="M2 4h12M5 4V2.5h6V4M6 7v5M10 7v5M3 4l1 9.5a1 1 0 001 1h6a1 1 0 001-1L13 4" stroke="currentColor" stroke-width="1.4" fill="none" stroke-linecap="round"/></svg>
          </button>
          <button class="btn-icon" title="关闭" onclick="closeTab('${tabId}')">
            <svg width="16" height="16" viewBox="0 0 18 18"><path d="M2 2l14 14M16 2L2 16" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>
          </button>
        </div>
      </div>
      <!-- 元信息 -->
      <div class="tab-article-meta">${domains}${sourceTag}${authorTag}${customTags}${editTagsBtn}${dateTag}${sourceLink}</div>
      <!-- 内容区域 -->
      <div class="tab-article-content">
        <div class="tab-article-summary ${a.summary ? 'has-content' : ''}">
          <div class="sidebar-panes" data-toc-empty="${sidebarHasToc ? 'false' : 'true'}">
            <section class="sidebar-pane pane-toc"
              onmouseenter="if(this.parentNode.dataset.tocEmpty!=='true') this.parentNode.dataset.expand='toc'"
              onmouseleave="if(this.parentNode.dataset.tocEmpty!=='true'&&this.parentNode.dataset.expand==='toc') delete this.parentNode.dataset.expand">
              <header class="sidebar-pane-header"><span class="sidebar-pane-title">智能目录</span></header>
              <div class="sidebar-pane-body sidebar-toc-list">${renderSidebarTocHtml(renderedBody.toc, `tab-detail-body-${tabId}`)}</div>
            </section>
            <section class="sidebar-pane pane-summary"
              onmouseenter="if(this.parentNode.dataset.tocEmpty!=='true') this.parentNode.dataset.expand='summary'"
              onmouseleave="if(this.parentNode.dataset.tocEmpty!=='true'&&this.parentNode.dataset.expand==='summary') delete this.parentNode.dataset.expand">
              <header class="sidebar-pane-header"><span class="sidebar-pane-title">摘要</span></header>
              <div class="sidebar-pane-body">
                <div class="summary-text markdown-summary">${renderSummaryMarkdown(a.summary || '暂无摘要')}</div>
                <div class="tab-summary-actions">
                  <button class="tab-summary-ai-btn" onclick="regenerateArticleSummary(${a.id}, '${tabId}', this)" title="根据正文重新生成摘要">
                    <span class="summary-ai-icon">✦</span> AI 重新生成
                  </button>
                  <button class="tab-summary-edit-btn" onclick="openEditSummaryModalInTab('${tabId}')">
                    <svg width="13" height="13" viewBox="0 0 14 14"><path d="M3 10l8-8 3 3-8 8z" stroke="currentColor" stroke-width="1.4" fill="none"/><path d="M11 2v3M11 5h3" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>
                    编辑
                  </button>
                </div>
              </div>
            </section>
          </div>
        </div>
        <div class="tab-article-body" onscroll="handleArticleScroll('${tabId}', this)">
          <div class="article-knowledge-panel" id="article-knowledge-${tabId}">
            <div class="article-knowledge-header">
              <div><strong>关联知识</strong><span class="article-knowledge-hint">法律问题、规则结论与核验状态</span></div>
              <div class="article-knowledge-actions">
                <button class="btn-secondary" onclick="extractKnowledgeFromArticle(${a.id}, '${tabId}', this)">AI 重新提取</button>
              </div>
            </div>
            <div class="article-knowledge-content">正在加载…</div>
          </div>
          <div class="tab-article-body-header">
            <span class="body-label">正文</span>
          </div>
          <div class="tab-article-body-text" id="tab-detail-body-${tabId}">${renderedBody.html}</div>
        </div>
        <aside class="tab-relations-panel hidden" id="article-relations-${tabId}">
          <div class="relations-panel-header">
            <div class="relations-panel-title">
              <span class="relations-panel-mark" aria-hidden="true"></span>
              <span class="relations-panel-eyebrow">知识网络</span>
              <strong>知识关联</strong>
              <small>已确认关系、候选提及与反向引用</small>
            </div>
            <div class="relations-panel-actions">
              <button type="button" class="btn-icon" title="重新识别关联" onclick="scanArticleRelations(${a.id}, '${tabId}', false)">↻</button>
              <button type="button" class="btn-icon" title="关闭知识关联" onclick="toggleTabRelationsPanel('${tabId}', false)">✕</button>
            </div>
          </div>
          <div class="relations-panel-content"><div class="relations-empty">正在加载关联…</div></div>
        </aside>
        <div class="tab-article-notes" id="tab-detail-notes-${tabId}">
          <div class="notes-header">
            <h3>阅读笔记</h3>
          </div>
          <div class="notes-list" id="tab-notes-list-${tabId}">
            <div class="notes-empty">暂无笔记</div>
          </div>
          <div class="notes-input-area">
            <textarea id="tab-note-input-${tabId}" class="note-textarea" placeholder="添加笔记..."></textarea>
            <div class="notes-actions">
              <button class="btn-primary btn-add-note" onclick="addNoteFromTab('${tabId}', ${a.id})">
                <svg width="14" height="14" viewBox="0 0 14 14"><path d="M7 1v12M1 7h12" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
                保存笔记
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="article-reading-actions" aria-label="文章阅读操作">
      <button class="article-reading-action article-edit-action" type="button"
              onclick="openEditBodyModalInTab('${tabId}')" title="编辑正文">
        <svg width="15" height="15" viewBox="0 0 16 16" aria-hidden="true"><path d="M3 11.5V14h2.5L13 6.5 9.5 3 2 10.5l1 1z" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linejoin="round"/><path d="M8.8 3.7l3.5 3.5" fill="none" stroke="currentColor" stroke-width="1.45"/></svg>
        <span>编辑正文</span>
      </button>
      <button class="article-reading-action article-back-to-top" id="article-back-to-top-${tabId}"
              type="button" aria-label="返回文章顶部" title="返回文章顶部"
              data-article-tab-id="${tabId}">
        <svg width="15" height="15" viewBox="0 0 18 18" aria-hidden="true">
          <path d="M4 7l5-5 5 5M9 2v13" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        <span>一键置顶</span>
      </button>
    </div>
  `;
  
  // 文章可能在后台异步加载完成。只有它仍是当前激活标签时，才允许更新
  // 全局“当前文章”；否则较慢返回的其他标签会污染当前标签的编辑/标签等操作。
  if (tabState.activeTabId === tabId) {
    currentArticleId = a.id;
    state.currentArticle = a;
  }
  
  // 保存当前文章ID到标签页元素
  pageEl.dataset.articleId = a.id;

  // 正文和笔记都是异步加载的；先绑定返回顶部按钮，避免笔记请求异常时跳过初始化。
  setupArticleBackToTop(tabId);
  setupTabArticleNoteSync(tabId);
  
  // 设置文本选中功能
  setupTabTextSelection(tabId);

  // PDF 页面图片版正文：构建可选中文字层（loadNotesForTab 会重渲染并再次增强）
  enhancePdfPageGalleries($(`tab-detail-body-${tabId}`));
  
  // 记录真正打开正文；这一步只执行本地规则识别，超长文章不会调用 AI。
  const relationOpen = registerArticleRelationOpen(a.id, tabId);

  // 加载笔记
  await Promise.all([
    loadNotesForTab(tabId, a.id),
    loadArticleKnowledge(tabId, a.id),
    relationOpen,
  ]);
  await loadArticleRelations(a.id, tabId);

  handlePendingTabArticleNavigation(tabId);
}

const RELATION_SOURCE_LABELS = { content: '正文', summary: '摘要', note: '阅读笔记' };
const RELATION_NODE_LABELS = { statute_provision: '法条', issue: '法律问题', case: '案例' };
const RELATION_MEANINGS = {
  cites: '本文引用该法条',
  applies: '本文将该法条作为裁判或论证依据',
  discusses: '本文讨论该法律问题',
  supports: '本文内容支持该结论',
  opposes: '本文内容反对该结论',
  limits: '本文对该结论设置限制或例外',
  distinguishes: '本文将其与其他规则或情形作出区别',
  related_to: '与本文内容一般相关',
};

function relationExcerpt(value, maxLength = 92) {
  const text = String(value || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > maxLength ? `${text.slice(0, maxLength)}…` : text;
}

function relationPanelFor(tabId = '') {
  if (tabId) return document.getElementById(`article-relations-${tabId}`);
  return document.getElementById('relations-panel');
}

function relationApiOptions(payload) {
  return {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload || {}),
  };
}

async function registerArticleRelationOpen(articleId, tabId = '') {
  try {
    const estimate = await apiFetch(`/api/articles/${articleId}/relation-open`, { method: 'POST' });
    if (!estimate.prompt_required) return estimate;
    const confirmed = window.confirm(
      `这是一篇超长文章（${Number(estimate.characters || 0).toLocaleString()} 字符）。\n\n` +
      `完整 AI 识别预计分为 ${estimate.estimated_batches || 0} 批，可能产生较高费用。` +
      `当前已完成不调用 AI 的法条和别名识别。\n\n是否现在启动完整 AI 扫描？`
    );
    if (confirmed) {
      await scanArticleRelations(articleId, tabId, true, true);
    } else {
      await apiFetch(
        `/api/articles/${articleId}/relation-scan`,
        relationApiOptions({ use_ai: false, dismiss_ai_prompt: true })
      );
    }
    return estimate;
  } catch (error) {
    console.warn('关系识别初始化失败:', error);
    return null;
  }
}

async function loadArticleRelations(articleId, tabId = '') {
  const panel = relationPanelFor(tabId);
  const content = panel?.querySelector('.relations-panel-content') ||
                  document.getElementById('relations-panel-content');
  if (!content) return;
  try {
    const data = await apiFetch(`/api/articles/${articleId}/relations`);
    renderArticleRelations(content, data, articleId, tabId);
    const body = tabId
      ? document.getElementById(`tab-detail-body-${tabId}`)
      : document.getElementById('detail-body');
    applyRelationHighlights(body, [...(data.confirmed || []), ...(data.candidates || [])]);
  } catch (error) {
    content.innerHTML = `<div class="relations-empty">关联加载失败：${escapeHtml(error.message || String(error))}</div>`;
  }
}

function renderArticleRelations(container, data, articleId, tabId = '') {
  const labels = data.relation_labels || {};
  const confirmed = data.confirmed || [];
  const candidates = data.candidates || [];
  const backlinks = data.backlinks || [];
  const estimate = data.estimate || {};
  const relationOptions = Object.entries(labels).map(([value, label]) =>
    `<option value="${escapeAttr(value)}">${escapeHtml(label)}</option>`
  ).join('');
  const confirmedHtml = confirmed.length ? confirmed.map(item => `
    <div class="relation-link-card-wrap relation-confirmed-card">
      <button type="button" class="relation-link-card" onclick="openKnowledgeNode(${Number(item.target_node_id)})">
        <span class="relation-type-badge">${escapeHtml(labels[item.relation_type] || item.relation_type)}</span>
        <span>
          <b><i>${escapeHtml(RELATION_NODE_LABELS[item.node_type] || '知识')}</i>${escapeHtml(item.target_title)}</b>
          <small>${escapeHtml(RELATION_MEANINGS[item.relation_type] || '与本文相关')}</small>
          <small>${escapeHtml(RELATION_SOURCE_LABELS[item.source_kind] || item.source_kind)} · ${escapeHtml(relationExcerpt(item.mention_text))}</small>
        </span>
      </button>
      <button type="button" class="relation-locate-btn" data-relation-source="${escapeAttr(JSON.stringify({
        article_id: articleId,
        source_kind: item.source_kind,
        char_start: item.char_start,
        mention_text: item.mention_text,
      }))}" onclick="openRelationSourceButton(this)">定位原文</button>
    </div>`).join('') : '<div class="relations-empty">暂无已确认关联</div>';
  const candidateHtml = candidates.length ? candidates.slice(0, 30).map(item => `
    <div class="relation-candidate" data-mention-id="${Number(item.id)}" data-target-node-id="${Number(item.target_node_id)}">
      <button type="button" class="relation-candidate-title" onclick="openKnowledgeNode(${Number(item.target_node_id)})">
        <b><i>${escapeHtml(RELATION_NODE_LABELS[item.node_type] || '知识')}</i>${escapeHtml(item.target_title)}</b>
        <small>${escapeHtml(RELATION_MEANINGS[item.relation_type] || '与本文相关')}</small>
        <small>${escapeHtml(RELATION_SOURCE_LABELS[item.source_kind] || item.source_kind)} · ${escapeHtml(relationExcerpt(item.mention_text))}</small>
      </button>
      <select class="relation-type-select" aria-label="关系类型">
        ${relationOptions.replace(`value="${escapeAttr(item.relation_type)}"`, `value="${escapeAttr(item.relation_type)}" selected`)}
      </select>
      <div class="relation-review-actions">
        <button type="button" class="btn-secondary relation-review-locate" data-relation-source="${escapeAttr(JSON.stringify({
          article_id: articleId,
          source_kind: item.source_kind,
          char_start: item.char_start,
          mention_text: item.mention_text,
        }))}" onclick="openRelationSourceButton(this)">定位</button>
        <button type="button" class="btn-primary" onclick="reviewRelationMention(${Number(item.id)}, 'confirmed', ${articleId}, '${escapeAttr(tabId)}', this)">确认</button>
        <button type="button" class="btn-secondary" onclick="confirmSameTargetRelations(${Number(item.target_node_id)}, ${articleId}, '${escapeAttr(tabId)}')">确认同类</button>
        <button type="button" class="btn-link-danger" onclick="reviewRelationMention(${Number(item.id)}, 'rejected', ${articleId}, '${escapeAttr(tabId)}', this)">忽略</button>
      </div>
    </div>`).join('') : '<div class="relations-empty">没有待确认提及</div>';
  const backlinkHtml = backlinks.length ? backlinks.map(item => `
    <button type="button" class="relation-link-card backlink" data-relation-source="${escapeAttr(JSON.stringify({
      article_id: item.source_article_id,
      source_kind: item.source_kind,
      char_start: item.char_start,
      mention_text: item.mention_text,
    }))}" onclick="openRelationSourceButton(this)">
      <span class="relation-back-arrow">←</span>
      <span><b>${escapeHtml(item.source_title)}</b><small>定位引用 · ${escapeHtml(relationExcerpt(item.mention_text))}</small></span>
    </button>`).join('') : '<div class="relations-empty">暂无其他文章引用本文</div>';
  const aiAction = estimate.long_article && !estimate.cached_ai
    ? `<button type="button" class="relation-ai-scan" onclick="confirmLongArticleRelationScan(${articleId}, '${escapeAttr(tabId)}', ${Number(estimate.characters || 0)}, ${Number(estimate.estimated_batches || 0)})">AI 完整扫描（${Number(estimate.estimated_batches || 0)} 批）</button>`
    : '';
  container.innerHTML = `
    ${aiAction}
    <div class="relations-overview" aria-label="关联概览">
      <div><strong>${confirmed.length}</strong><span>已关联</span></div>
      <div><strong>${candidates.length}</strong><span>待确认</span></div>
      <div><strong>${backlinks.length}</strong><span>引用本文</span></div>
    </div>
    <details class="relation-group relation-group-confirmed" open>
      <summary>
        <span><strong>已关联</strong><small>已经人工确认的知识关系</small></span>
        <em>${confirmed.length}</em>
      </summary>
      <div class="relation-group-body">${confirmedHtml}</div>
    </details>
    <details class="relation-group relation-group-candidates" ${candidates.length ? 'open' : ''}>
      <summary>
        <span><strong>待确认</strong><small>核验关系类型后再加入知识网络</small></span>
        <em>${candidates.length}</em>
      </summary>
      <div class="relation-group-body">${candidateHtml}</div>
    </details>
    <details class="relation-group relation-group-backlinks">
      <summary>
        <span><strong>引用本文</strong><small>其他文章对本文知识节点的引用</small></span>
        <em>${backlinks.length}</em>
      </summary>
      <div class="relation-group-body">${backlinkHtml}</div>
    </details>`;
}

async function reviewRelationMention(mentionId, status, articleId, tabId = '', button = null) {
  const card = button?.closest('.relation-candidate');
  const relationType = card?.querySelector('.relation-type-select')?.value;
  if (button) button.disabled = true;
  try {
    await apiFetch(`/api/knowledge-mentions/${mentionId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status, relation_type: relationType || undefined }),
    });
    await loadArticleRelations(articleId, tabId);
  } catch (error) {
    showToast(error.message || '关联审核失败', 'error');
    if (button) button.disabled = false;
  }
}

async function confirmSameTargetRelations(targetNodeId, articleId, tabId = '') {
  const panel = relationPanelFor(tabId);
  const cards = [...(panel?.querySelectorAll(`.relation-candidate[data-target-node-id="${targetNodeId}"]`) || [])];
  for (const card of cards) {
    const mentionId = Number(card.dataset.mentionId || 0);
    const relationType = card.querySelector('.relation-type-select')?.value;
    if (!mentionId) continue;
    await apiFetch(`/api/knowledge-mentions/${mentionId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'confirmed', relation_type: relationType || undefined }),
    });
  }
  await loadArticleRelations(articleId, tabId);
}

async function scanArticleRelations(articleId, tabId = '', useAi = false, confirmedLong = false) {
  try {
    const result = await apiFetch(
      `/api/articles/${articleId}/relation-scan`,
      relationApiOptions({ use_ai: !!useAi, confirmed_long_article_cost: !!confirmedLong })
    );
    if (useAi) {
      showToast(result.ai_created ? 'AI 关系扫描已加入队列' :
        (result.ai_reason === 'cached' ? '已复用现有 AI 扫描结果' : '已完成规则识别'));
    } else {
      showToast(`已完成本地识别，新增 ${result.rule_scan?.created || 0} 条候选`);
    }
    await loadArticleRelations(articleId, tabId);
    return result;
  } catch (error) {
    showToast(error.message || '关系识别失败', 'error');
    return null;
  }
}

function scanCurrentArticleRelations(useAi = false) {
  const articleId = state.currentArticle?.id || currentArticleId;
  if (articleId) scanArticleRelations(articleId, '', useAi, false);
}

function toggleRelationsPanel(force) {
  const panel = document.getElementById('relations-panel');
  if (!panel) return;
  const shouldShow = typeof force === 'boolean' ? force : panel.classList.contains('hidden');
  panel.classList.toggle('hidden', !shouldShow);
  if (shouldShow) {
    const articleId = state.currentArticle?.id || currentArticleId;
    if (articleId) loadArticleRelations(articleId);
  }
}

function toggleTabRelationsPanel(tabId, force) {
  const panel = relationPanelFor(tabId);
  if (!panel) return;
  const shouldShow = typeof force === 'boolean' ? force : panel.classList.contains('hidden');
  panel.classList.toggle('hidden', !shouldShow);
  if (shouldShow) {
    const articleId = Number(document.getElementById(tabId)?.dataset?.articleId || 0);
    if (articleId) loadArticleRelations(articleId, tabId);
  }
}

function confirmLongArticleRelationScan(articleId, tabId, characters, batches) {
  const confirmed = window.confirm(
    `正文共 ${Number(characters || 0).toLocaleString()} 字符，预计调用 ${batches || 0} 个 AI 批次。\n\n确认启动完整扫描？`
  );
  if (confirmed) scanArticleRelations(articleId, tabId, true, true);
}

function applyRelationHighlights(root, mentions) {
  if (!root) return;
  root.querySelectorAll('mark.knowledge-relation-mark').forEach(mark => {
    const parent = mark.parentNode;
    while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
    mark.remove();
    parent.normalize();
  });
  const usable = (mentions || []).filter(item =>
    item.source_kind === 'content' && item.mention_text &&
    item.mention_text.length >= 2 && item.mention_text.length <= 120
  ).slice(0, 100);
  usable.forEach(item => {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        const parent = node.parentElement;
        if (!parent || parent.closest('mark,button,script,style')) return NodeFilter.FILTER_REJECT;
        return node.nodeValue?.includes(item.mention_text) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
      },
    });
    const node = walker.nextNode();
    if (!node) return;
    const index = node.nodeValue.indexOf(item.mention_text);
    const range = document.createRange();
    range.setStart(node, index);
    range.setEnd(node, index + item.mention_text.length);
    const mark = document.createElement('mark');
    mark.className = `knowledge-relation-mark ${item.status}`;
    mark.dataset.nodeId = item.target_node_id;
    mark.title = `${item.target_title || '关联知识'}（${item.status === 'confirmed' ? '已确认' : '待确认'}）`;
    mark.addEventListener('click', event => {
      event.stopPropagation();
      openKnowledgeNode(Number(item.target_node_id));
    });
    range.surroundContents(mark);
  });
}

async function openKnowledgeNode(nodeId) {
  try {
    const node = await apiFetch(`/api/knowledge-nodes/${nodeId}`);
    let overlay = document.getElementById('knowledge-node-modal');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'knowledge-node-modal';
      overlay.className = 'modal-overlay';
      overlay.addEventListener('click', event => {
        if (event.target === overlay) overlay.classList.remove('open');
      });
      document.body.appendChild(overlay);
    }
    const labels = node.relation_labels || {};
    const backlinks = node.backlinks || [];
    const nodeTypeLabel = RELATION_NODE_LABELS[node.node_type] || '知识节点';
    let contentHtml = '';
    if (node.node_type === 'statute_provision') {
      contentHtml = node.source_text ? `
        <section class="knowledge-node-content">
          <h3>法条原文</h3>
          <div class="knowledge-node-source">${escapeHtml(node.source_text).replace(/\n/g, '<br>')}</div>
          <button type="button" class="btn-secondary knowledge-node-open-source"
                  data-relation-source="${escapeAttr(JSON.stringify({
                    article_id: node.article_id,
                    source_kind: 'content',
                    char_start: node.source_char_start,
                    mention_text: node.title,
                  }))}"
                  onclick="openRelationSourceButton(this);document.getElementById('knowledge-node-modal').classList.remove('open')">
            在法规原文中打开并定位
          </button>
        </section>` : '';
    } else if (node.node_type === 'issue') {
      const claims = node.claims || [];
      contentHtml = `
        <section class="knowledge-node-content">
          <h3>该问题下的法律结论 ${claims.length}</h3>
          ${claims.length ? claims.map(claim => `
            <article class="knowledge-node-claim">
              <strong>${escapeHtml(claim.statement || '')}</strong>
              ${claim.conditions_text ? `<p><b>适用条件：</b>${escapeHtml(claim.conditions_text)}</p>` : ''}
              ${claim.exceptions_text ? `<p><b>例外或限制：</b>${escapeHtml(claim.exceptions_text)}</p>` : ''}
              ${(claim.evidence || []).length ? `
                <div class="knowledge-node-evidence">
                  ${(claim.evidence || []).slice(0, 3).map(evidence => `
                    <button type="button" data-relation-source="${escapeAttr(JSON.stringify({
                      article_id: evidence.article_id,
                      source_kind: 'content',
                      char_start: evidence.char_start,
                      mention_text: evidence.quote,
                    }))}" onclick="openRelationSourceButton(this);document.getElementById('knowledge-node-modal').classList.remove('open')">
                      来源：${escapeHtml(evidence.article_title || '文章')} · ${escapeHtml(relationExcerpt(evidence.quote, 70))}
                    </button>`).join('')}
                </div>` : ''}
            </article>`).join('') : '<div class="relations-empty">该问题尚无已提取的具体法律结论。</div>'}
        </section>`;
    } else if (node.node_type === 'case') {
      contentHtml = `
        <section class="knowledge-node-content">
          <h3>案例内容</h3>
          <div class="knowledge-node-source">${escapeHtml(node.source_text || '暂无摘要')}</div>
          ${node.article_id ? `
            <button type="button" class="btn-secondary knowledge-node-open-source"
                    data-relation-source="${escapeAttr(JSON.stringify({
                      article_id: node.article_id,
                      source_kind: 'content',
                      char_start: 0,
                      mention_text: node.title,
                    }))}"
                    onclick="openRelationSourceButton(this);document.getElementById('knowledge-node-modal').classList.remove('open')">
              打开案例文章
            </button>` : ''}
        </section>`;
    }
    overlay.innerHTML = `
      <div class="modal knowledge-node-dialog">
        <div class="modal-header">
          <div class="knowledge-node-heading" data-node-symbol="${escapeAttr(
            node.node_type === 'statute_provision' ? '法' : node.node_type === 'issue' ? '问' : '案'
          )}">
            <span class="knowledge-node-type">${escapeHtml(nodeTypeLabel)}</span>
            <h2>${escapeHtml(node.title)}</h2>
            <p>权威原文与知识引用链</p>
          </div>
          <button class="btn-icon knowledge-node-close" aria-label="关闭关联详情" title="关闭"
                  onclick="document.getElementById('knowledge-node-modal').classList.remove('open')">✕</button>
        </div>
        ${node.source_status === 'missing_source' ? '<div class="knowledge-node-warning">尚未收录权威原文，当前仅汇总引用关系。</div>' : ''}
        ${contentHtml}
        <div class="knowledge-node-backlinks">
          <div class="knowledge-node-section-head">
            <div><h3>反向引用</h3><p>以下内容引用或适用本知识节点</p></div>
            <em>${backlinks.length}</em>
          </div>
          ${backlinks.length ? backlinks.map(item => `
            <button class="relation-link-card backlink" data-relation-source="${escapeAttr(JSON.stringify({
              article_id: item.source_article_id,
              source_kind: item.source_kind,
              char_start: item.char_start,
              mention_text: item.mention_text,
            }))}" onclick="openRelationSourceButton(this);document.getElementById('knowledge-node-modal').classList.remove('open')">
              <span class="relation-type-badge">${escapeHtml(labels[item.relation_type] || item.relation_type)}</span>
              <span>
                <b>${escapeHtml(item.source_title)}</b>
                <small>${escapeHtml(RELATION_MEANINGS[item.relation_type] || '与本文相关')}</small>
                <small>点击后定位引用 · ${escapeHtml(relationExcerpt(item.context_text || item.mention_text, 110))}</small>
              </span>
            </button>`).join('') : '<div class="relations-empty">暂无已确认引用</div>'}
        </div>
      </div>`;
    overlay.classList.add('open');
  } catch (error) {
    showToast(error.message || '知识节点加载失败', 'error');
  }
}

function openRelationSource(item) {
  const articleId = Number(item?.article_id || 0);
  if (!articleId) return;
  if (item.source_kind === 'content' && Number.isFinite(Number(item.char_start))) {
    state.pendingScrollOffset = Number(item.char_start);
    state.pendingCitationQuote = item.mention_text || '';
  } else {
    state.pendingHighlight = item.mention_text || '';
  }
  openArticleInTab(articleId, item.title || '文章详情');
}

function openRelationSourceButton(button) {
  try {
    openRelationSource(JSON.parse(button?.dataset?.relationSource || '{}'));
  } catch (error) {
    console.warn('无法解析反向引用位置:', error);
  }
}

const KNOWLEDGE_STATUS_LABELS = {
  pending: '待审核', approved: '已通过', rejected: '已驳回',
  needs_review: '需复核', merged: '已合并', queued: '等待提取',
  running: '正在提取', completed: '提取完成', failed: '提取失败',
};

async function loadArticleKnowledge(tabId, articleId) {
  const panel = document.getElementById(`article-knowledge-${tabId}`);
  const content = panel?.querySelector('.article-knowledge-content');
  if (!content) return;
  try {
    const data = await apiFetch(`/api/articles/${articleId}/knowledge`);
    const claims = data.claims || [];
    const job = data.job;
    const jobBadge = job
      ? `<span class="knowledge-status ${escapeHtml(job.status)}">${escapeHtml(KNOWLEDGE_STATUS_LABELS[job.status] || job.status)}</span>`
      : '<span class="knowledge-status idle">尚未提取</span>';
    if (!claims.length) {
      content.innerHTML = `<div class="article-knowledge-empty">${jobBadge}<span>${job?.status === 'failed' ? escapeHtml(job.error || '提取失败，可重新尝试') : '暂无关联结论'}</span></div>`;
      return;
    }
    content.innerHTML = `
      <div class="article-knowledge-job">${jobBadge}<span>共 ${claims.length} 条结论</span></div>
      <div class="article-knowledge-list">
        ${claims.slice(0, 8).map(claim => renderArticleKnowledgeClaim(claim, tabId)).join('')}
      </div>`;
  } catch (error) {
    content.innerHTML = `<div class="article-knowledge-empty">关联知识加载失败：${escapeHtml(error.message || String(error))}</div>`;
  }
}

function renderArticleKnowledgeClaim(claim, tabId) {
  const claimId = Number(claim?.id || 0);
  const evidenceItems = Array.isArray(claim?.evidence) ? claim.evidence : [];
  const evidence = evidenceItems[0] || null;
  const paragraphLabel = evidence?.paragraph_index ? `第 ${evidence.paragraph_index} 段` : '对应原文';
  const sourceButton = evidence ? `
    <button type="button" class="article-knowledge-source"
            data-char-start="${evidence.char_start ?? ''}"
            data-quote="${escapeAttr(evidence.quote || '')}"
            onclick="jumpToArticleKnowledgeSource('${escapeAttr(tabId)}', this)"
            title="在当前文章中定位并高亮该结论的原文依据">
      <span aria-hidden="true">↳</span> 查看原文 · ${escapeHtml(paragraphLabel)}${evidenceItems.length > 1 ? `（共 ${evidenceItems.length} 处）` : ''}
    </button>` : '';
  return `
    <div class="article-knowledge-item" data-claim-id="${claimId}">
      <button type="button" class="article-knowledge-main" onclick="openLegalKnowledgeTab(${claimId})"
              title="在法律知识中心中打开这条规则结论">
        <span class="knowledge-status ${escapeHtml(claim.review_status)}">${escapeHtml(KNOWLEDGE_STATUS_LABELS[claim.review_status] || claim.review_status)}</span>
        <span class="article-knowledge-copy">
          <b>${escapeHtml(claim.issue_title || '未命名问题')}</b>
          <small>${escapeHtml(claim.statement)}</small>
          <span class="article-knowledge-open-label">在知识中心查看结论 →</span>
        </span>
      </button>
      ${sourceButton}
    </div>`;
}

function jumpToArticleKnowledgeSource(tabId, button) {
  const rawOffset = button?.dataset?.charStart;
  const quote = button?.dataset?.quote || '';
  const charOffset = rawOffset !== '' && Number.isFinite(Number(rawOffset)) ? Number(rawOffset) : null;
  if (charOffset !== null) {
    scrollTabBodyToOffset(tabId, charOffset, quote);
  } else {
    const keyword = normalizeArticleNavigationKeyword(quote);
    if (keyword) highlightAndScrollInArticleTab(tabId, keyword);
  }
}

async function extractKnowledgeFromArticle(articleId, tabId, button) {
  if (button) button.disabled = true;
  try {
    await apiFetch(`/api/articles/${articleId}/knowledge-extract?force=true`, { method: 'POST' });
    showToast('已加入知识提取队列');
    await loadArticleKnowledge(tabId, articleId);
  } catch (error) {
    showToast(error.message || '知识提取任务创建失败', 'error');
  } finally {
    if (button) button.disabled = false;
  }
}

function getArticleTabScrollContainers(tabId) {
  const page = document.getElementById(tabId);
  if (!page) return [];
  return [
    page.querySelector('.tab-article-body'),
    page.querySelector('.tab-article-content'),
    page.querySelector('.tab-article-detail'),
    page,
  ].filter(Boolean);
}

/* ─────────────────────────────────────────────
   文章阅读位置持久化：强制刷新 / 关闭标签 / 服务器重启后恢复
   ───────────────────────────────────────────── */
const ARTICLE_READ_POSITION_KEY = 'legal_kb_article_read_positions';
const articleReadPositionSaveTimers = new Map();
let articleReadPositionCache = null;

function loadArticleReadPositionMap() {
  if (articleReadPositionCache) return articleReadPositionCache;
  try {
    const raw = JSON.parse(localStorage.getItem(ARTICLE_READ_POSITION_KEY) || '{}');
    articleReadPositionCache = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  } catch (_) {
    articleReadPositionCache = {};
  }
  return articleReadPositionCache;
}

function saveArticleReadPositionMap(map) {
  articleReadPositionCache = map;
  try {
    localStorage.setItem(ARTICLE_READ_POSITION_KEY, JSON.stringify(map));
  } catch (_) { /* ignore */ }
}

function setSavedArticleReadPosition(articleId, top) {
  const id = Number(articleId);
  if (!id) return;
  const value = Math.max(0, Math.round(Number(top) || 0));
  const map = loadArticleReadPositionMap();
  const record = map[String(id)];
  if (record && typeof record === 'object' && Number(record.top) === value) return;
  map[String(id)] = { top: value, savedAt: Date.now() };
  saveArticleReadPositionMap(map);
}

function getSavedArticleReadPosition(articleId) {
  const id = Number(articleId);
  if (!id) return 0;
  const record = loadArticleReadPositionMap()[String(id)];
  if (!record || typeof record !== 'object') return 0;
  const top = Number(record.top);
  return Number.isFinite(top) && top > 0 ? top : 0;
}

function removeSavedArticleReadPosition(articleId) {
  const id = Number(articleId);
  if (!id) return;
  const map = loadArticleReadPositionMap();
  if (!(String(id) in map)) return;
  delete map[String(id)];
  saveArticleReadPositionMap(map);
}

function scheduleArticleReadPositionSave(articleId, scroller) {
  const id = Number(articleId);
  if (!id || !scroller) return;
  const key = String(id);
  if (articleReadPositionSaveTimers.has(key)) {
    clearTimeout(articleReadPositionSaveTimers.get(key));
  }
  articleReadPositionSaveTimers.set(key, setTimeout(() => {
    articleReadPositionSaveTimers.delete(key);
    if (scroller.isConnected) setSavedArticleReadPosition(id, scroller.scrollTop || 0);
  }, 350));
}

function flushArticleReadPositionForTab(tabId) {
  const page = document.getElementById(tabId);
  const articleId = Number(page?.dataset?.articleId || 0);
  const scroller = page?.querySelector('.tab-article-body');
  if (articleId && scroller) setSavedArticleReadPosition(articleId, scroller.scrollTop || 0);
}

function flushAllArticleReadPositions() {
  document.querySelectorAll('.tab-page[data-article-id]').forEach(page => {
    const articleId = Number(page.dataset.articleId || 0);
    if (!articleId) return;
    const scroller = page.querySelector('.tab-article-body');
    if (scroller) setSavedArticleReadPosition(articleId, scroller.scrollTop || 0);
  });
}

function restoreArticleReadPositionInTab(tabId, articleId) {
  // 引用定位、笔记定位、关键词高亮等明确跳转优先于上次阅读位置恢复
  const target = getSavedArticleReadPosition(articleId);
  if (!target) return;
  let attempts = 0;
  let lastApplied = null;
  const tryApply = () => {
    const scroller = document.getElementById(tabId)?.querySelector('.tab-article-body');
    if (!scroller) return;
    // 用户已手动滚动：放弃校正，避免把用户拽回原位
    if (lastApplied !== null && Math.abs(scroller.scrollTop - lastApplied) > 2) return;
    const max = Math.max(0, scroller.scrollHeight - scroller.clientHeight);
    if (max > 0) {
      scroller.scrollTop = Math.min(target, max);
      lastApplied = scroller.scrollTop;
      // 文档已足够高、目标位置可用，恢复完成
      if (max >= target) return;
    }
    // PDF 等逐页图片异步加载会让文档高度持续增长：反复校正，
    // 直到高度达到目标位置或用户开始手动滚动。
    attempts += 1;
    if (attempts < 120) setTimeout(tryApply, 350);
  };
  requestAnimationFrame(tryApply);
}

function updateArticleBackToTopVisibility(tabId) {
  const button = document.getElementById(`article-back-to-top-${tabId}`);
  if (!button) return;
  const containers = getArticleTabScrollContainers(tabId);
  const offset = Math.max(...containers.map(container => container.scrollTop || 0), 0);
  button.classList.toggle('is-visible', offset > 320);
}

function handleArticleScroll(tabId, scroller) {
  updateArticleBackToTopVisibility(tabId);
  scheduleTabNoteSync(tabId);
  if (!scroller) return;
  const page = scroller.closest('.tab-page');
  const articleId = Number(page?.dataset?.articleId || 0)
    || Number(tabState.tabs.find(tab => tab.id === tabId)?.data?.articleId || 0);
  if (articleId) scheduleArticleReadPositionSave(articleId, scroller);
}

/* ── 正文滚动 ↔ 右侧笔记栏同步 + 可见笔记连线 ────────────────────
   正文滚动时，笔记栏自动滚动到当前位置对应的笔记；屏幕上同时可见的
   正文笔记序号角标与笔记卡片之间，用极细的淡红色平直折线相连。 */
const tabNoteSyncState = {};

function setupTabArticleNoteSync(tabId) {
  const page = document.getElementById(tabId);
  const contentEl = page?.querySelector('.tab-article-content');
  if (!page || !contentEl || contentEl.querySelector('.note-connector-layer')) return;
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', 'note-connector-layer');
  svg.setAttribute('aria-hidden', 'true');
  contentEl.appendChild(svg);
  tabNoteSyncState[tabId] = { hover: false, lockUntil: 0, currentItemEl: null, raf: 0 };
  const notesEl = $(`tab-detail-notes-${tabId}`);
  const listEl = $(`tab-notes-list-${tabId}`);
  if (notesEl) {
    notesEl.addEventListener('pointerenter', () => {
      const state = tabNoteSyncState[tabId];
      if (state) state.hover = true;
    });
    notesEl.addEventListener('pointerleave', () => {
      const state = tabNoteSyncState[tabId];
      if (state) state.hover = false;
    });
    // 用户在笔记栏内滚动时短暂锁定同步，避免两个滚动源相互拉扯。
    notesEl.addEventListener('wheel', () => {
      const state = tabNoteSyncState[tabId];
      if (state) state.lockUntil = Date.now() + 700;
    }, { passive: true });
  }
  if (listEl) {
    listEl.addEventListener('scroll', () => scheduleTabNoteSync(tabId), { passive: true });
    // 悬停笔记卡片时实时重绘，联动高亮对应折线。
    listEl.addEventListener('mouseover', e => {
      if (e.target.closest('.note-item')) scheduleTabNoteSync(tabId);
    });
    listEl.addEventListener('mouseout', e => {
      if (e.target.closest('.note-item')) scheduleTabNoteSync(tabId);
    });
  }
  // 悬停正文笔记角标时同样实时重绘（正文纸面会整体重渲染，监听器挂在滚动容器上委托处理）。
  const scroller = contentEl.querySelector('.tab-article-body');
  if (scroller) {
    scroller.addEventListener('mouseover', e => {
      if (e.target.closest('.note-anchor-badge, .pdf-page-note-badge')) scheduleTabNoteSync(tabId);
    });
    scroller.addEventListener('mouseout', e => {
      if (e.target.closest('.note-anchor-badge, .pdf-page-note-badge')) scheduleTabNoteSync(tabId);
    });
  }
}

function scheduleTabNoteSync(tabId) {
  const state = tabNoteSyncState[tabId];
  if (!state || state.raf) return;
  state.raf = requestAnimationFrame(() => {
    state.raf = 0;
    renderTabNoteConnections(tabId);
  });
}

window.addEventListener('resize', () => {
  Object.keys(tabNoteSyncState).forEach(scheduleTabNoteSync);
});

/** 收集正文内所有笔记角标（文本锚点角标与 PDF 页角标），按文档顺序去重。
    必须用单次选择器合并两类角标，保证 querySelectorAll 返回统一的文档顺序；
    分两次查询再拼接会破坏顺序，导致 PDF 文章里“已越过中央的页角标”被排在
    文本锚点之后，同步定位失效。 */
function collectBodyNoteAnchors(bodyEl) {
  const anchors = [];
  const seen = new Set();
  bodyEl.querySelectorAll('.note-anchor .note-anchor-badge, .pdf-page-note-badge, .pdf-text-badge').forEach(el => {
    const noteId = el.closest('.note-anchor')?.dataset.noteId || el.dataset.noteId;
    if (!noteId || seen.has(noteId)) return;
    seen.add(noteId);
    anchors.push({ noteId, el, rect: el.getBoundingClientRect() });
  });
  return anchors;
}

function rectsOverlap(a, b, margin = 2) {
  return a.right + margin > b.left && a.left - margin < b.right
    && a.bottom + margin > b.top && a.top - margin < b.bottom;
}

/** 正文滚动时，把笔记栏同步滚动到当前可见位置对应的笔记。 */
function syncTabNotesListWithBody(tabId) {
  const state = tabNoteSyncState[tabId];
  const bodyEl = $(`tab-detail-body-${tabId}`);
  const listEl = $(`tab-notes-list-${tabId}`);
  const notesEl = $(`tab-detail-notes-${tabId}`);
  if (!state || !bodyEl || !listEl || !notesEl || notesEl.classList.contains('hidden')) return;
  if (state.hover || Date.now() < state.lockUntil) return;

  const anchors = collectBodyNoteAnchors(bodyEl);
  if (!anchors.length) return;
  // 参考线必须以滚动容器为准：正文纸面（tab-detail-body-*）随滚动移动，其 rect 不能作为视口参考。
  const scroller = bodyEl.closest('.tab-article-body') || bodyEl;
  const bodyRect = scroller.getBoundingClientRect();
  // 以正文栏视口的垂直中央为参照：角标滚动到中央的笔记即为当前笔记，
  // 其卡片被滚动到笔记栏中央，并由折线相连、高亮显示。
  const refY = bodyRect.top + bodyRect.height / 2;
  let current = null;
  for (const anchor of anchors) {
    if (anchor.rect.top + anchor.rect.height / 2 <= refY) current = anchor;
    else break;
  }
  // 阅读位置尚未越过任何笔记锚点：保持笔记栏现状，不强制回滚到顶部。
  if (!current) return;
  const item = getNoteElementById(listEl, current.noteId);
  if (!item) return;
  const listRect = listEl.getBoundingClientRect();
  const itemRect = item.getBoundingClientRect();
  // 当前笔记滚动到笔记栏视口的中央位置；首尾笔记受列表边界约束自然停在顶部/底部。
  const target = itemRect.top - listRect.top + listEl.scrollTop - (listEl.clientHeight - itemRect.height) / 2;
  const max = Math.max(0, listEl.scrollHeight - listEl.clientHeight);
  const clamped = Math.max(0, Math.min(target, max));
  if (Math.abs(listEl.scrollTop - clamped) > 2) listEl.scrollTop = clamped;
  if (item !== state.currentItemEl) {
    listEl.querySelectorAll('.note-item.active').forEach(el => el.classList.remove('active'));
    item.classList.add('active');
    state.currentItemEl = item;
  }
}

/** 重绘正文角标与笔记卡片之间的淡红色平直折线。 */
function renderTabNoteConnections(tabId) {
  syncTabNotesListWithBody(tabId);
  const page = document.getElementById(tabId);
  const overlay = page?.querySelector('.note-connector-layer');
  if (!overlay) return;
  const bodyEl = $(`tab-detail-body-${tabId}`);
  const listEl = $(`tab-notes-list-${tabId}`);
  const notesEl = $(`tab-detail-notes-${tabId}`);
  const origin = overlay.getBoundingClientRect();
  const paths = [];

  if (bodyEl && listEl && notesEl && !notesEl.classList.contains('hidden')) {
    // 可见性判断同样以滚动容器（.tab-article-body）为视口参考，纸面 rect 会随滚动偏移。
    const scroller = bodyEl.closest('.tab-article-body') || bodyEl;
    const bodyRect = scroller.getBoundingClientRect();
    const listRect = listEl.getBoundingClientRect();
    // 折线只在“正文纸面右缘 → 笔记栏左缘”之间的间隙内弯折，避免竖线穿过正文文字区。
    const paperEl = bodyEl.querySelector('.tab-article-body-text');
    const paperRight = (paperEl ? paperEl.getBoundingClientRect().right : bodyRect.right - 24) - origin.left;
    const gapRight = notesEl.getBoundingClientRect().left - origin.left;
    // 折点尽量靠右、贴近笔记栏一侧，竖线沿间隙右缘走，进一步远离正文纸面。
    let bendX = gapRight - 12;
    if (bendX > gapRight - 3) bendX = gapRight - 3;
    if (bendX < paperRight + 2) bendX = paperRight + 2;
    const anchors = collectBodyNoteAnchors(bodyEl);
    for (const anchor of anchors) {
      const item = getNoteElementById(listEl, anchor.noteId);
      if (!item) continue;
      const badgeRect = anchor.rect;
      const itemRect = item.getBoundingClientRect();
      if (!rectsOverlap(badgeRect, bodyRect) || !rectsOverlap(itemRect, listRect)) continue;
      const chip = item.querySelector('.note-card-index');
      const chipRect = chip ? chip.getBoundingClientRect() : null;
      const x1 = badgeRect.right - origin.left;
      // 从角标上缘引出横线：上标角标高出正文行，其上方为行间隙，横线不穿过当前行文字。
      const y1 = badgeRect.top + 1 - origin.top;
      const x2 = itemRect.left - origin.left;
      const y2 = (chipRect ? chipRect.top + chipRect.height / 2 : itemRect.top + 18) - origin.top;
      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      // 当前笔记、悬停的笔记卡片或悬停的正文角标，对应折线高亮显示。
      const highlighted = item.classList.contains('active') || item.matches(':hover') || anchor.el.matches(':hover');
      path.setAttribute('class', `note-connector-line${highlighted ? ' note-connector-line-highlight' : ''}`);
      path.setAttribute('d', `M${x1} ${y1} H${bendX} V${y2} H${x2}`);
      paths.push(path);
    }
  }
  overlay.innerHTML = '';
  paths.forEach(path => overlay.appendChild(path));
}

function setupArticleBackToTop(tabId) {
  const button = document.getElementById(`article-back-to-top-${tabId}`);
  if (!button) return;
  const containers = getArticleTabScrollContainers(tabId);
  const update = () => updateArticleBackToTopVisibility(tabId);
  containers.forEach(container => container.addEventListener('scroll', update, { passive: true }));
  requestAnimationFrame(update);
}

function scrollArticleTabToTop(tabId) {
  const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  getArticleTabScrollContainers(tabId).forEach(container => {
    if (container.scrollTop > 0) {
      container.scrollTo({ top: 0, behavior: reducedMotion ? 'auto' : 'smooth' });
    }
  });
}

// 事件委托不依赖文章详情的异步初始化；即使笔记或其他附属请求失败，按钮仍可正常工作。
document.addEventListener('scroll', event => {
  const scroller = event.target instanceof Element
    ? event.target.closest('.tab-article-body')
    : null;
  const page = scroller?.closest('.tab-page');
  if (page?.id) updateArticleBackToTopVisibility(page.id);
}, true);

document.addEventListener('click', event => {
  const button = event.target.closest?.('.article-back-to-top');
  if (!button) return;
  event.preventDefault();
  const tabId = button.dataset.articleTabId || button.closest('.tab-page')?.id;
  if (tabId) scrollArticleTabToTop(tabId);
});

function shouldUseTabbedArticleReader() {
  return !!(window.matchMedia && window.matchMedia('(max-width: 760px)').matches);
}

async function refreshCurrentArticleView(articleId) {
  const id = Number(articleId || 0);
  if (!id) return;
  const activeTab = tabState.tabs.find(tab =>
    tab.id === tabState.activeTabId &&
    tab.type === TAB_TYPES.ARTICLE &&
    Number(tab.data?.articleId) === id
  );
  const articleTab = activeTab || tabState.tabs.find(tab =>
    tab.type === TAB_TYPES.ARTICLE && Number(tab.data?.articleId) === id
  );
  if (!articleTab) {
    await openDetail(id);
    return;
  }
  const page = $(articleTab.id);
  const previousScroll = {
    page: page?.scrollTop || 0,
    content: page?.querySelector('.tab-article-content')?.scrollTop || 0,
  };
  await loadArticleInTab(articleTab.id, id);
  switchTab(articleTab.id);
  const refreshedPage = $(articleTab.id);
  if (refreshedPage) refreshedPage.scrollTop = previousScroll.page;
  const refreshedContent = refreshedPage?.querySelector('.tab-article-content');
  if (refreshedContent) refreshedContent.scrollTop = previousScroll.content;
}

function handlePendingTabArticleNavigation(tabId) {
  const pendingNoteId = state.pendingNoteId;
  const pendingOffset = state.pendingScrollOffset;
  const pendingCitationQuote = state.pendingCitationQuote;
  const pendingHighlight = state.pendingHighlight;

  if (pendingNoteId) {
    state.pendingNoteId = null;
    setTimeout(() => jumpToNoteInTab(tabId, pendingNoteId), 180);
  }

  if (pendingOffset !== null && pendingOffset !== undefined) {
    state.pendingScrollOffset = null;
    state.pendingCitationQuote = null;
    setTimeout(() => scrollTabBodyToOffset(tabId, pendingOffset, pendingCitationQuote), 180);
  }

  if (pendingHighlight) {
    state.pendingHighlight = null;
    const searchKw = normalizeArticleNavigationKeyword(pendingHighlight);
    if (searchKw) {
      setTimeout(() => highlightAndScrollInArticleTab(tabId, searchKw), 220);
    }
  }
}

function normalizeArticleNavigationKeyword(value) {
  const cleaned = String(value || '').replace(/[…（）【】《》「」"'.,;:?!()]/g, '').trim();
  if (!cleaned) return '';
  if (cleaned.length > 40) {
    const midStart = Math.max(0, Math.floor(cleaned.length / 2) - 20);
    return cleaned.substring(midStart, midStart + 40);
  }
  return cleaned.length > 20 ? cleaned.substring(0, 20) : cleaned;
}

function scrollTabBodyToOffset(tabId, charOffset, keyword) {
  const bodyEl = document.getElementById(`tab-detail-body-${tabId}`);
  if (!bodyEl || charOffset === null || charOffset === undefined) return;

  const walker = document.createTreeWalker(bodyEl, NodeFilter.SHOW_TEXT, null, false);
  let accumulated = 0;
  let targetNode = null;
  let nodeOffset = 0;

  while (walker.nextNode()) {
    const node = walker.currentNode;
    const len = node.textContent.length;
    if (accumulated + len > charOffset) {
      targetNode = node;
      nodeOffset = Math.max(0, charOffset - accumulated);
      break;
    }
    accumulated += len;
  }

  const quoteMatch = findCitationQuoteNode(bodyEl, keyword);
  if (quoteMatch) targetNode = quoteMatch;
  if (!targetNode) return;
  highlightCitationTarget(targetNode, bodyEl);
}

function findCitationQuoteNode(root, quote) {
  const normalized = String(quote || '').replace(/\s+/g, ' ').trim();
  if (!root || normalized.length < 6) return null;
  const candidates = [normalized.slice(0, 60), normalized.slice(0, 36), normalized.slice(0, 20)];
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const candidate of candidates) {
    if (candidate.length < 6) continue;
    const compactCandidate = candidate.replace(/\s+/g, '');
    const match = nodes.find(node => node.textContent.replace(/\s+/g, '').includes(compactCandidate));
    if (match) return match;
  }
  return null;
}

function highlightCitationTarget(targetNode, bodyEl) {
  if (!targetNode || !bodyEl) return;
  bodyEl.querySelectorAll('.citation-target-highlight').forEach(el => {
    el.classList.remove('citation-target-highlight');
  });
  const element = targetNode.nodeType === Node.TEXT_NODE ? targetNode.parentElement : targetNode;
  const block = element?.closest('p, li, blockquote, h1, h2, h3, h4, div.body-paragraph') || element;
  if (!block || block === bodyEl) return;
  block.classList.add('citation-target-highlight');
  block.scrollIntoView({ behavior: 'smooth', block: 'center' });
  window.setTimeout(() => block.classList.remove('citation-target-highlight'), 8000);
}

function highlightAndScrollInArticleTab(tabId, keyword) {
  const input = document.getElementById(`tab-detail-search-input-${tabId}`);
  if (input) input.value = keyword;
  applyTabDetailSearch(tabId, keyword);
  setTimeout(() => scrollToTabDetailMatch(tabId), 0);
}

// 标签页摘要编辑
function openEditSummaryModalInTab(tabId) {
  if (!state.currentArticle) return;
  $('edit-summary-input').value = state.currentArticle.summary || '';
  $('edit-summary-modal').classList.add('open');
  setTimeout(() => $('edit-summary-input').focus(), 50);
}

/** 安全渲染摘要中的常用 Markdown。原文先转义，再添加受控标签。 */
function renderSummaryMarkdown(markdown) {
  const source = String(markdown || '').replace(/\r\n?/g, '\n').trim();
  if (!source) return '';

  const inline = value => escapeHtml(value)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/__(.+?)__/g, '<strong>$1</strong>')
    .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');

  const output = [];
  let listType = '';
  const closeList = () => {
    if (listType) output.push(`</${listType}>`);
    listType = '';
  };

  source.split('\n').forEach(rawLine => {
    const line = rawLine.trim();
    if (!line) {
      closeList();
      return;
    }
    const heading = line.match(/^(#{1,3})\s+(.+)$/);
    const unordered = line.match(/^[-*+]\s+(.+)$/);
    const ordered = line.match(/^\d+[.、]\s*(.+)$/);
    if (heading) {
      closeList();
      output.push(`<h${heading[1].length}>${inline(heading[2])}</h${heading[1].length}>`);
    } else if (unordered || ordered) {
      const nextType = unordered ? 'ul' : 'ol';
      if (listType !== nextType) {
        closeList();
        listType = nextType;
        output.push(`<${listType}>`);
      }
      output.push(`<li>${inline((unordered || ordered)[1])}</li>`);
    } else {
      closeList();
      output.push(`<p>${inline(line)}</p>`);
    }
  });
  closeList();
  return output.join('');
}

async function regenerateArticleSummary(articleId, tabId, button) {
  if (!articleId || button?.disabled) return;
  const originalHtml = button ? button.innerHTML : '';
  if (button) {
    button.disabled = true;
    button.classList.add('is-loading');
    button.textContent = '正在生成…';
  }

  try {
    // 摘要生成需要等待模型完成推理，不能使用普通写请求的 30 秒超时。
    const result = await apiFetch(`/api/articles/${articleId}/summary/regenerate`, {
      method: 'POST',
      timeoutMs: 120000,
    });
    const summary = String(result?.summary || '').trim();
    if (!summary) throw new Error('AI 未返回有效摘要');

    if (state.currentArticle?.id === articleId) state.currentArticle.summary = summary;
    const articleInList = state.articles.find(article => article.id === articleId);
    if (articleInList) articleInList.summary = summary;
    const tab = tabState.tabs.find(item => item.id === tabId);
    if (tab?.data?.article) tab.data.article.summary = summary;

    // 优先从用户刚点击的按钮定位摘要区域，避免标签页 id 或状态不同步时更新失败。
    const page = document.getElementById(tabId);
    const summaryContainer = button?.closest('.tab-article-summary')
      || page?.querySelector('.tab-article-summary');
    const summaryText = summaryContainer?.querySelector('.summary-text');
    if (summaryText) summaryText.innerHTML = renderSummaryMarkdown(summary);
    summaryContainer?.classList.add('has-content');

    const detailSummary = $('detail-summary');
    if (detailSummary && state.currentArticle?.id === articleId) {
      renderLegacyDetailSummary(detailSummary, summary);
    }
    showToast('摘要已由 AI 重新生成');
  } catch (error) {
    const aborted = error?.name === 'AbortError'
      || /fetch is aborted|aborted|aborterror/i.test(String(error?.message || ''));
    const message = aborted
      ? '生成时间超过 2 分钟，请稍后重试或检查 AI 模型服务'
      : (error.message || '请稍后重试');
    alert('AI 重新生成摘要失败：' + message);
  } finally {
    if (button) {
      button.disabled = false;
      button.classList.remove('is-loading');
      button.innerHTML = originalHtml;
    }
  }
}

// 标签页正文编辑
async function openEditBodyModalInTab(tabId) {
  const tab = tabState.tabs.find(item => item.id === tabId && item.type === TAB_TYPES.ARTICLE);
  const articleId = Number(tab?.data?.articleId || 0);
  if (!tab || !articleId) return;

  // 编辑器必须绑定到用户实际点击的标签，而不是可能被其他异步请求改写的
  // state.currentArticle。标签恢复后若尚未带回文章对象，再按该标签 ID 精确加载。
  let article = tab.data?.article;
  if (!article || Number(article.id) !== articleId) {
    try {
      article = await apiFetch(`/api/articles/${articleId}`);
    } catch (error) {
      alert('正文加载失败：' + (error.message || '请稍后重试'));
      return;
    }
    const currentTab = tabState.tabs.find(item => item.id === tabId);
    if (!currentTab || Number(currentTab.data?.articleId || 0) !== articleId) return;
    currentTab.data = { ...(currentTab.data || {}), article };
  }

  const returnContext = _createBodyEditorReturnContext('tab', tabId, articleId);
  enableEditBody(article, returnContext);
}

// 标签页文章搜索状态
const tabDetailSearch = {};

/**
 * 移除文章内搜索高亮，并重新合并高亮拆分出的相邻文本节点。
 * 若只把 mark 替换成文本，连续修改检索词时一个完整词语会被拆在
 * 多个 Text 节点中，后续搜索便无法命中跨节点的内容。
 */
function unwrapDetailSearchMarks(scope) {
  if (!scope) return;
  const parents = new Set();
  scope.querySelectorAll('mark.detail-search-mark').forEach(mark => {
    const parent = mark.parentNode;
    if (!parent) return;
    parents.add(parent);
    parent.replaceChild(document.createTextNode(mark.textContent || ''), mark);
  });
  parents.forEach(parent => parent.normalize());
}

/**
 * 在页面实际可见的文本流中查找并高亮关键字。
 *
 * 正文中的法条、问题等内容可能已经被知识关联包在 mark 元素中，
 * 也可能因为链接、强调等行内标签被拆成多个 Text 节点。搜索不能按
 * 单个文本节点逐一匹配，否则这些用户眼中连续可见的文字会被漏掉。
 */
function highlightVisibleText(root, keyword, sectionName = '正文') {
  if (!root || !keyword) return [];

  const nodes = [];
  let visibleText = '';
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement;
      if (!parent || !node.nodeValue) return NodeFilter.FILTER_REJECT;
      if (parent.isContentEditable) return NodeFilter.FILTER_REJECT;
      if (parent.closest('script,style,textarea,input,button,mark.detail-search-mark,.pdf-source-text,.pdf-page-note-btn,.pdf-page-note-badge')) {
        return NodeFilter.FILTER_REJECT;
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });

  let node;
  while ((node = walker.nextNode())) {
    const start = visibleText.length;
    visibleText += node.nodeValue;
    nodes.push({ node, start, end: visibleText.length, spans: [] });
  }

  const haystack = visibleText.toLocaleLowerCase();
  const needle = String(keyword).toLocaleLowerCase();
  if (!needle) return [];

  const logicalMatches = [];
  let position = haystack.indexOf(needle);
  while (position !== -1) {
    logicalMatches.push({
      start: position,
      end: position + keyword.length,
      before: visibleText.slice(Math.max(0, position - 35), position),
      after: visibleText.slice(position + keyword.length, position + keyword.length + 35),
      marks: [],
    });
    position = haystack.indexOf(needle, position + Math.max(keyword.length, 1));
  }
  if (!logicalMatches.length) return [];

  // 将每个“可见文本流”命中区间映射回一个或多个真实 Text 节点。
  for (let matchIndex = 0; matchIndex < logicalMatches.length; matchIndex++) {
    const match = logicalMatches[matchIndex];
    for (const entry of nodes) {
      if (entry.end <= match.start || entry.start >= match.end) continue;
      entry.spans.push({
        start: Math.max(match.start, entry.start) - entry.start,
        end: Math.min(match.end, entry.end) - entry.start,
        matchIndex,
      });
    }
  }

  // 每个文本节点只重建一次，避免修改 DOM 后令其余区间失效。
  for (const entry of nodes) {
    if (!entry.spans.length || !entry.node.parentNode) continue;
    const text = entry.node.nodeValue;
    const fragment = document.createDocumentFragment();
    let cursor = 0;
    entry.spans.sort((a, b) => a.start - b.start);
    for (const span of entry.spans) {
      if (span.start > cursor) fragment.appendChild(document.createTextNode(text.slice(cursor, span.start)));
      const mark = document.createElement('mark');
      mark.className = 'detail-search-mark';
      mark.textContent = text.slice(span.start, span.end);
      logicalMatches[span.matchIndex].marks.push(mark);
      fragment.appendChild(mark);
      cursor = span.end;
    }
    if (cursor < text.length) fragment.appendChild(document.createTextNode(text.slice(cursor)));
    entry.node.parentNode.replaceChild(fragment, entry.node);
  }

  return logicalMatches.map(match => {
    const representative = match.marks[0];
    if (representative) {
      representative._searchCtx = {
        before: match.before,
        after: match.after,
        section: sectionName,
      };
      representative._searchParts = match.marks;
    }
    return representative;
  }).filter(Boolean);
}

/**
 * 标签页文章内搜索输入
 */
function onTabDetailSearchInput(tabId) {
  const input = document.getElementById(`tab-detail-search-input-${tabId}`);
  if (!input) return;
  const kw = input.value.trim();
  const clearBtn = input.parentElement && input.parentElement.querySelector('.detail-search-clear');
  if (clearBtn) clearBtn.style.display = kw ? 'flex' : 'none';
  applyTabDetailSearch(tabId, kw);
}

/**
 * 标签页文章内搜索键盘事件
 */
function onTabDetailSearchKeydown(e, tabId) {
  const dropdown = document.getElementById(`tab-detail-search-dropdown-${tabId}`);
  const search = tabDetailSearch[tabId] || { matches: [] };
  const count = search.matches.length;
  const maxCount = Math.min(count, 50);

  if (e.key === 'Enter') {
    e.preventDefault();
    if (dropdown && dropdown.style.display !== 'none' && count > 0) {
      const active = search.activeDropdownItem >= 0 ? search.activeDropdownItem : 0;
      jumpToTabDetailDropdownItem(tabId, active);
    } else {
      tabDetailSearch[tabId] = tabDetailSearch[tabId] || { current: 0, matches: [], activeDropdownItem: -1 };
      tabDetailSearch[tabId].current = (tabDetailSearch[tabId].current + 1) % (count || 1);
      scrollToTabDetailMatch(tabId);
    }
  } else if (e.key === 'ArrowDown') {
    e.preventDefault();
    if (dropdown && count > 0) {
      dropdown.style.display = 'block';
      search.activeDropdownItem = Math.min((search.activeDropdownItem || -1) + 1, maxCount - 1);
      tabDetailSearch[tabId].activeDropdownItem = search.activeDropdownItem;
      updateTabDetailDropdownHighlight(tabId);
    }
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    if (dropdown && dropdown.style.display !== 'none') {
      search.activeDropdownItem = Math.max((search.activeDropdownItem || 0) - 1, 0);
      tabDetailSearch[tabId].activeDropdownItem = search.activeDropdownItem;
      updateTabDetailDropdownHighlight(tabId);
    }
  } else if (e.key === 'Escape') {
    clearTabDetailSearch(tabId);
  }
}

/**
 * 清除标签页文章搜索
 */
function clearTabDetailSearch(tabId) {
  const input = document.getElementById(`tab-detail-search-input-${tabId}`);
  if (input) input.value = '';
  const clearBtn = document.querySelector(`#${tabId} .detail-search-clear`);
  if (clearBtn) clearBtn.style.display = 'none';
  const dropdown = document.getElementById(`tab-detail-search-dropdown-${tabId}`);
  if (dropdown) dropdown.style.display = 'none';
  applyTabDetailSearch(tabId, '');
}

/**
 * 应用标签页搜索
 */
function applyTabDetailSearch(tabId, keyword) {
  try {
  const bodyEl = document.getElementById(`tab-detail-body-${tabId}`);
  if (!bodyEl) return;
  
  // 清除之前的高亮
  unwrapDetailSearchMarks(bodyEl);
  
  const dropdown = document.getElementById(`tab-detail-search-dropdown-${tabId}`);
  if (dropdown) dropdown.style.display = 'none';
  tabDetailSearch[tabId] = { matches: [], current: -1, activeDropdownItem: -1 };

  if (!keyword) return;
  
  const matches = highlightVisibleText(bodyEl, keyword, '正文');
  
  tabDetailSearch[tabId] = { matches, current: -1, activeDropdownItem: -1 };
  if (matches.length > 0) {
    tabDetailSearch[tabId].current = 0;
    matches[0].classList.add('scroll-anchor');
    matches[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
    // 渲染下拉列表
    renderTabDetailSearchDropdown(tabId, keyword, Math.min(matches.length, 50));
    if (dropdown) dropdown.style.display = 'block';
  } else if (dropdown) {
    dropdown.innerHTML = '<div class="detail-search-dropdown-empty">未找到匹配内容</div>';
    dropdown.style.display = 'block';
  }
  } catch(e) { console.error('[TabSearch]', e); }
}

/* 渲染标签页搜索结果下拉列表 */
function renderTabDetailSearchDropdown(tabId, keyword, maxCount) {
  const dropdown = document.getElementById(`tab-detail-search-dropdown-${tabId}`);
  if (!dropdown) return;
  const search = tabDetailSearch[tabId] || { matches: [] };
  const total = search.matches.length;
  const items = [];

  for (let i = 0; i < maxCount; i++) {
    const mk = search.matches[i];
    const ctx = mk._searchCtx || { before: '…', after: '…', section: '正文' };
    const beforeEsc = escapeHtml(ctx.before || '');
    const afterEsc = escapeHtml(ctx.after || '');
    const termEsc = escapeHtml(keyword);
    items.push(
      `<div class="detail-search-dropdown-item" data-idx="${i}" onclick="onTabDetailDropdownClick('${tabId}', ${i})" onmouseenter="onTabDetailDropdownHover('${tabId}', ${i})">` +
        `<span class="result-index">${i + 1}.</span>` +
        `<span class="result-context">${beforeEsc}<mark>${termEsc}</mark>${afterEsc}</span>` +
        `<span class="result-section">${escapeHtml(ctx.section)}</span>` +
      `</div>`
    );
  }

  let html = items.join('');
  if (total > maxCount) {
    html += `<div class="detail-search-dropdown-footer">共 ${total} 条结果，已显示前 ${maxCount} 条</div>`;
  }
  dropdown.innerHTML = html;
  dropdown.scrollTop = 0;
}

function onTabDetailDropdownClick(tabId, idx) {
  jumpToTabDetailDropdownItem(tabId, idx);
}

function onTabDetailDropdownHover(tabId, idx) {
  const search = tabDetailSearch[tabId];
  if (search) {
    search.activeDropdownItem = idx;
    updateTabDetailDropdownHighlight(tabId);
  }
}

function updateTabDetailDropdownHighlight(tabId) {
  const dropdown = document.getElementById(`tab-detail-search-dropdown-${tabId}`);
  if (!dropdown) return;
  const search = tabDetailSearch[tabId];
  if (!search) return;
  dropdown.querySelectorAll('.detail-search-dropdown-item').forEach((item, i) => {
    item.classList.toggle('active', i === search.activeDropdownItem);
    if (i === search.activeDropdownItem) {
      item.scrollIntoView({ block: 'nearest' });
    }
  });
}

function jumpToTabDetailDropdownItem(tabId, idx) {
  const dropdown = document.getElementById(`tab-detail-search-dropdown-${tabId}`);
  if (dropdown) dropdown.style.display = 'none';
  const search = tabDetailSearch[tabId];
  if (!search) return;
  search.current = idx;
  search.activeDropdownItem = idx;
  if (search.matches[idx]) {
    search.matches.forEach(m => m.classList.remove('scroll-anchor'));
    search.matches[idx].classList.add('scroll-anchor');
    search.matches[idx].scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
  updateTabDetailDropdownHighlight(tabId);
}

/**
 * 滚动到当前匹配项
 */
function scrollToTabDetailMatch(tabId) {
  const search = tabDetailSearch[tabId];
  if (!search || search.current < 0 || !search.matches[search.current]) return;
  search.matches.forEach(m => m.classList.remove('scroll-anchor'));
  search.matches[search.current].classList.add('scroll-anchor');
  search.matches[search.current].scrollIntoView({ behavior: 'smooth', block: 'center' });
}

/**
 * 设置标签页文本选中功能
 */
function setupTabTextSelection(tabId) {
  const bodyEl = $(`tab-detail-body-${tabId}`);
  if (!bodyEl) return;
  
  // 清除旧的监听器
  bodyEl.onmouseup = null;
  
  bodyEl.onmouseup = () => {
    const selection = window.getSelection();
    const selectedText = selection.toString().trim();
    const noteInput = $(`tab-note-input-${tabId}`);
    if (selectedText) {
      // 保存选中文本到 state
      state.noteSelectedText = selectedText;
      state.noteSelectedTextsByTab.set(tabId, selectedText);
      state.noteSelectionAnchorsByTab.set(tabId, captureNoteSelectionAnchor(bodyEl, selection));
      // 选中文字后，之前点击的 PDF 页面笔记锚点让位于文字锚点
      if (state.pendingPdfPageNoteByTab) state.pendingPdfPageNoteByTab.delete(tabId);
      if (noteInput) {
        noteInput.placeholder = `引用: "${selectedText.substring(0, 50)}${selectedText.length > 50 ? '...' : ''}"`;
      }
    } else {
      state.noteSelectedText = '';
      state.noteSelectedTextsByTab.delete(tabId);
      state.noteSelectionAnchorsByTab.delete(tabId);
      if (noteInput) {
        noteInput.placeholder = '添加笔记...';
      }
    }
    _showReaderSelectionMenu(bodyEl, { articleId: Number(tabState.tabs.find(tab => tab.id === tabId)?.data?.articleId || 0), tabId });
  };
}

/* ─────────────────────────────────────────────
   阅读态正文：选区快捷格式
───────────────────────────────────────────── */
let _readerSelectionContext = null;
let _readerFormatSaving = false;
const _readerFormatHistory = new Map();

function _getReaderSelectionMenu() {
  let menu = $('reader-selection-menu');
  if (menu) return menu;
  menu = document.createElement('div');
  menu.id = 'reader-selection-menu';
  menu.className = 'reader-selection-menu';
  menu.hidden = true;
  menu.setAttribute('role', 'toolbar');
  menu.setAttribute('aria-label', '选中文字格式');
  menu.innerHTML = `
    <button type="button" data-reader-format="bold" title="加粗"><strong>B</strong></button>
    <button type="button" data-reader-format="highlight" title="高亮显示"><span class="reader-format-highlight">H</span></button>
    <button type="button" data-reader-format="red" title="标红"><span class="reader-format-red">A</span></button>
    <button type="button" data-reader-format="underline" title="加下划线"><u>U</u></button>
    <button type="button" data-reader-format="italic" title="倾斜"><em>I</em></button>`;
  // 防止点击工具栏让浏览器清空阅读区的原始选区。
  menu.addEventListener('pointerdown', event => event.preventDefault());
  menu.addEventListener('click', event => {
    const button = event.target.closest('[data-reader-format]');
    if (button) _applyReaderSelectionFormat(button.dataset.readerFormat);
  });
  document.body.appendChild(menu);
  return menu;
}

function _hideReaderSelectionMenu() {
  const menu = $('reader-selection-menu');
  if (menu) menu.hidden = true;
}

function _readerSelectionHasColor(value, expected, property) {
  if (!value || String(value).toLowerCase() === 'transparent') return false;
  const probe = document.createElement('span');
  probe.style[property] = value;
  document.body.appendChild(probe);
  const actual = getComputedStyle(probe)[property];
  probe.style[property] = expected;
  const target = getComputedStyle(probe)[property];
  probe.remove();
  return actual === target;
}

function _readerSelectionFormatIsApplied(format) {
  if (format === 'bold' || format === 'underline' || format === 'italic') {
    return document.queryCommandState(format);
  }
  if (format === 'highlight') {
    return _readerSelectionHasColor(document.queryCommandValue('hiliteColor'), '#fff2a8', 'backgroundColor');
  }
  if (format === 'red') {
    return _readerSelectionHasColor(document.queryCommandValue('foreColor'), '#c62828', 'color');
  }
  return false;
}

function _showReaderSelectionMenu(root, context) {
  // mouseup 事件早于部分浏览器完成选区更新，延后一帧读取最终范围。
  requestAnimationFrame(() => {
    const selection = window.getSelection();
    if (!root || !selection?.rangeCount || selection.isCollapsed || !root.contains(selection.anchorNode)) {
      _hideReaderSelectionMenu();
      return;
    }
    const range = selection.getRangeAt(0);
    const rect = range.getBoundingClientRect();
    if (!selection.toString().trim() || !(rect.width || rect.height)) {
      _hideReaderSelectionMenu();
      return;
    }
    _readerSelectionContext = { ...context, root, range: range.cloneRange() };
    const menu = _getReaderSelectionMenu();
    menu.hidden = false;
    requestAnimationFrame(() => {
      const margin = 10;
      const width = menu.offsetWidth || 190;
      const height = menu.offsetHeight || 38;
      const left = Math.max(margin, Math.min(window.innerWidth - width - margin, rect.left + rect.width / 2 - width / 2));
      const top = rect.top - height - 10 >= margin ? rect.top - height - 10 : rect.bottom + 10;
      menu.style.left = `${left}px`;
      menu.style.top = `${Math.min(window.innerHeight - height - margin, top)}px`;
    });
  });
}

async function _applyReaderSelectionFormat(format) {
  const context = _readerSelectionContext;
  const root = context?.root;
  if (_readerFormatSaving || !root?.isConnected || !context.range || !context.articleId) return;
  const beforeHtml = root.innerHTML;
  const selection = window.getSelection();
  selection.removeAllRanges();
  selection.addRange(context.range);
  // execCommand 可准确处理跨标签的文字范围；仅在执行这一瞬间开放编辑能力，
  // 阅读页面不会进入可输入状态。
  root.contentEditable = 'true';
  root.focus({ preventScroll: true });
  const wasApplied = _readerSelectionFormatIsApplied(format);
  const commands = {
    bold: ['bold', null],
    highlight: ['hiliteColor', wasApplied ? 'transparent' : '#fff2a8'],
    // 使用 inherit 而不是写死深色文字，深色模式下也能恢复为正文默认颜色。
    red: ['foreColor', wasApplied ? 'inherit' : '#c62828'],
    underline: ['underline', null],
    italic: ['italic', null],
  };
  const [command, value] = commands[format] || [];
  const applied = command && document.execCommand(command, false, value);
  root.contentEditable = 'false';
  _hideReaderSelectionMenu();
  selection.removeAllRanges();
  if (!applied || root.innerHTML === beforeHtml) return;

  // 阅读页包含运行时生成的目录；页面保留它以免编辑后目录闪烁，保存时才移除。
  const afterHtml = root.innerHTML;
  const cleanHtml = sanitizeBodyHtml(afterHtml);
  _readerSelectionContext = null;
  _readerFormatSaving = true;
  try {
    await _saveArticleBodyWithRetry(context.articleId, cleanHtml);
    _syncReaderArticleContent(context.articleId, cleanHtml);
    const history = _readerFormatHistory.get(context.articleId) || { undo: [], redo: [] };
    history.undo.push({ beforeHtml, afterHtml });
    history.redo = [];
    _readerFormatHistory.set(context.articleId, history);
    showToast(wasApplied ? '已取消格式并保存' : '格式已保存');
  } catch (error) {
    root.innerHTML = beforeHtml;
    showToast('格式保存失败，已恢复原文', 'error');
  } finally {
    _readerFormatSaving = false;
  }
}

function _syncReaderArticleContent(articleId, html) {
  state.bodyCache.delete(articleId);
  if (state.currentArticle && Number(state.currentArticle.id) === Number(articleId)) state.currentArticle.content = html;
  const articleTab = tabState.tabs.find(tab => tab.type === TAB_TYPES.ARTICLE && Number(tab.data?.articleId) === Number(articleId));
  if (articleTab?.data?.article) articleTab.data.article.content = html;
}

function _activeReaderSurface() {
  const activeTab = tabState.tabs.find(tab => tab.id === tabState.activeTabId && tab.type === TAB_TYPES.ARTICLE);
  if (activeTab) {
    return {
      articleId: Number(activeTab.data?.articleId || 0),
      root: $(`tab-detail-body-${activeTab.id}`),
    };
  }
  const detailBody = $('detail-body');
  if (detailBody?.offsetParent) {
    return { articleId: Number(currentArticleId || state.currentArticle?.id || 0), root: detailBody };
  }
  return { articleId: 0, root: null };
}

async function _undoReaderFormat() {
  if (_readerFormatSaving) return;
  const { articleId, root } = _activeReaderSurface();
  const history = _readerFormatHistory.get(articleId);
  const entry = history?.undo.at(-1);
  // 阅读页被重新渲染或正文被其他入口保存后，旧记录不再能安全回放。
  if (!root || !entry || root.innerHTML !== entry.afterHtml) {
    if (history) _readerFormatHistory.delete(articleId);
    return;
  }
  history.undo.pop();
  root.innerHTML = entry.beforeHtml;
  _readerFormatSaving = true;
  try {
    const cleanHtml = sanitizeBodyHtml(entry.beforeHtml);
    await _saveArticleBodyWithRetry(articleId, cleanHtml);
    _syncReaderArticleContent(articleId, cleanHtml);
    history.redo.push(entry);
    showToast('已撤销格式操作');
  } catch (error) {
    root.innerHTML = entry.afterHtml;
    history.undo.push(entry);
    showToast('撤销保存失败，已恢复格式', 'error');
  } finally {
    _readerFormatSaving = false;
  }
}

/**
 * 切换标签页笔记面板显示
 */
function toggleTabNotesPanel(tabId) {
  const notesEl = $(`tab-detail-notes-${tabId}`);
  if (notesEl) {
    notesEl.classList.toggle('hidden');
    scheduleTabNoteSync(tabId);
  }
}

/**
 * 从标签页删除文章
 */
async function deleteArticleFromTab(tabId, articleId) {
  if (!await confirmArticleTrashAction('移入回收站？', '文章及其笔记将保留30天，期间可从侧边栏回收站恢复。', '移入回收站')) return;
  try {
    await apiFetch(`/api/articles/${articleId}`, { method: 'DELETE' });
    closeTab(tabId, true);
    loadArticles();
    loadStats();
    loadDomains();
    loadAuthors();
    showToast('文章已移入回收站，可在30天内恢复');
  } catch (e) {
    showToast('移入回收站失败：' + e.message, 'error');
  }
}

/**
 * 从标签页添加笔记
 */
async function addNoteFromTab(tabId, articleId) {
  const input = $(`tab-note-input-${tabId}`);
  if (!input || !input.value.trim()) return;
  
  try {
    const form = new FormData();
    form.append('article_id', articleId);
    form.append('content', input.value.trim());
    const selectedText = state.noteSelectedTextsByTab.get(tabId) || '';
    const selectionAnchor = state.noteSelectionAnchorsByTab.get(tabId);
    const pendingPage = (state.pendingPdfPageNoteByTab && state.pendingPdfPageNoteByTab.get(tabId)) || 0;
    if (selectedText && selectionAnchor) {
      form.append('selected_text', selectedText);
      form.append('selection_anchor', JSON.stringify(selectionAnchor));
    } else if (pendingPage > 0) {
      // PDF 页面笔记：锚点指向具体某一页
      form.append('selected_text', '');
      form.append('selection_anchor', JSON.stringify({ version: 2, pdf_page: pendingPage }));
    } else {
      form.append('selected_text', '');
    }
    
    await apiFetch('/api/notes', {
      method: 'POST',
      body: form
    });
    input.value = '';
    state.noteSelectedText = '';
    state.noteSelectedTextsByTab.delete(tabId);
    state.noteSelectionAnchorsByTab.delete(tabId);
    if (state.pendingPdfPageNoteByTab) state.pendingPdfPageNoteByTab.delete(tabId);
    // 重置 placeholder
    if (input) {
      input.placeholder = '添加笔记...';
    }
    await loadNotesForTab(tabId, articleId);
  } catch (e) {
    alert('保存笔记失败：' + e.message);
  }
}

/**
 * 从标签页删除笔记
 */
async function deleteNoteFromTab(tabId, noteId) {
  if (!confirm('确定要删除这条笔记吗？')) return;
  const tab = tabState.tabs.find(item => item.id === tabId && item.type === TAB_TYPES.ARTICLE);
  const articleId = Number(tab?.data?.articleId || state.currentArticle?.id || currentArticleId || 0);
  try {
    await apiFetch(`/api/notes/${noteId}`, { method: 'DELETE' });
    await loadNotesForTab(tabId, articleId);
  } catch (e) {
    alert('删除笔记失败：' + e.message);
  }
}

function startEditNoteFromTab(tabId, noteId, articleId, event) {
  if (event) event.stopPropagation();
  const noteEl = event?.target?.closest('.note-item');
  if (!noteEl) return;
  const contentEl = noteEl.querySelector('.note-content');
  const currentContent = contentEl ? contentEl.textContent.trim() : '';
  noteEl.classList.add('editing');
  if (contentEl) {
    contentEl.innerHTML = `
      <textarea class="note-edit-textarea">${escapeHtml(currentContent)}</textarea>
      <div class="note-edit-actions">
        <button class="note-edit-save" onclick="saveEditedNoteFromTab('${tabId}', ${noteId}, ${articleId}, event)">保存</button>
        <button class="note-edit-cancel" onclick="cancelEditNoteFromTab('${tabId}', ${articleId}, event)">取消</button>
      </div>
    `;
    const textarea = contentEl.querySelector('.note-edit-textarea');
    if (textarea) {
      textarea.focus();
      textarea.setSelectionRange(textarea.value.length, textarea.value.length);
    }
  }
}

function cancelEditNoteFromTab(tabId, articleId, event) {
  if (event) event.stopPropagation();
  loadNotesForTab(tabId, articleId);
}

async function saveEditedNoteFromTab(tabId, noteId, articleId, event) {
  if (event) event.stopPropagation();
  const noteEl = event?.target?.closest('.note-item');
  const textarea = noteEl?.querySelector('.note-edit-textarea');
  const content = textarea?.value.trim() || '';
  if (!content) {
    alert('笔记内容不能为空');
    return;
  }
  try {
    await apiFetch(`/api/notes/${noteId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content })
    });
    await loadNotesForTab(tabId, articleId);
    showToast('笔记已更新');
  } catch (e) {
    alert('保存修改失败：' + e.message);
  }
}

/**
 * 加载标签页笔记
 */
async function loadNotesForTab(tabId, articleId) {
  try {
    const notes = await apiFetch(`/api/notes/${articleId}`);
    const listEl = $(`tab-notes-list-${tabId}`);
    if (!listEl) return;
    const displayNotes = (await renderArticleNoteAnchorsInTab(tabId, notes)) || notes || [];
    
    if (!displayNotes || displayNotes.length === 0) {
      listEl.innerHTML = '<div class="notes-empty">暂无笔记</div>';
      scheduleTabNoteSync(tabId);
      return;
    }
    
    listEl.innerHTML = displayNotes.map((n, index) => {
      const pdfPage = pdfPageFromNote(n);
      const hasSelectedText = n.selected_text && n.selected_text.trim() !== '';
      const hasQuote = hasSelectedText || pdfPage > 0;
      const quoteLabel = pdfPage > 0 ? pdfPageNoteQuoteLabel(n) : (n.selected_text || '');
      const clickAttr = hasQuote ? `onclick="jumpToNoteInTab('${tabId}', ${n.id})"` : '';
      const noteIndex = index + 1;
      return `
        <div class="note-item ${hasQuote ? 'clickable' : ''}" data-note-id="${escapeHtml(n.id)}" data-note-index="${noteIndex}" ${clickAttr}>
          <div class="note-card-index">笔记 ${noteIndex}</div>
          <div class="note-content">${escapeHtml(n.content)}</div>
          ${hasQuote ? `<div class="note-selected-text">${escapeHtml(quoteLabel)}</div>` : ''}
          <div class="note-time">
            <span>${formatDate(n.created_at)}</span>
            <button class="note-edit-btn" onclick="event.stopPropagation(); startEditNoteFromTab('${tabId}', ${n.id}, ${articleId}, event)" title="编辑笔记">
              <svg viewBox="0 0 16 16"><path d="M3 11.5l.6-2.6L10.8 1.7a1.2 1.2 0 011.7 0l1.8 1.8a1.2 1.2 0 010 1.7L7.1 12.4 4.5 13 3 11.5z" stroke="currentColor" stroke-width="1.3" fill="none" stroke-linejoin="round"/><path d="M9.8 2.8l3.4 3.4" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg>
            </button>
            <button class="note-delete-btn" onclick="event.stopPropagation(); deleteNoteFromTab('${tabId}', ${n.id})" title="删除笔记">
              <svg viewBox="0 0 16 16"><path d="M2 4h12M5 4V2.5h6V4M6 7v5M10 7v5M3 4l1 9.5a1 1 0 001 1h6a1 1 0 001-1L13 4" stroke="currentColor" stroke-width="1.4" fill="none" stroke-linecap="round"/></svg>
            </button>
          </div>
        </div>
      `;
    }).join('');
    scheduleTabNoteSync(tabId);
  } catch (e) {
    console.error('加载笔记失败:', e);
  }
}

/**
 * 标签页中跳转笔记到正文对应位置
 */
function findNoteById(notes, noteId) {
  const targetId = String(noteId);
  return (notes || []).find(n => String(n.id) === targetId);
}

function getNotesWithSelectedText(notes) {
  return (notes || []).filter(note => note.selected_text && note.selected_text.trim());
}

function sortNotesByArticlePosition(notes, bodyEl) {
  const sourceNotes = notes || [];
  const locator = buildNoteTextLocator(bodyEl);
  const nextSearchStartByText = new Map();
  const missingPosition = Number.MAX_SAFE_INTEGER;
  const pdfPagePositions = collectPdfPageTextPositions(bodyEl, locator);

  return sourceNotes
    .map((note, originalIndex) => {
      const selectedText = (note.selected_text || '').trim();
      let position = missingPosition;
      let hasPosition = false;

      if (selectedText && locator.normalized) {
        const key = normalizeNoteLocatorText(selectedText);
        const start = nextSearchStartByText.get(key) || 0;
        const match = findNoteLocatorMatchForNote(locator, note, start, bodyEl);
        if (match) {
          position = match.startIndex;
          hasPosition = true;
          nextSearchStartByText.set(key, match.startIndex + Math.max(1, match.needle.length));
        }
      }

      const pdfPage = pdfPageFromNote(note);
      if (!hasPosition && pdfPage > 0) {
        const pagePosition = pdfPagePositions.get(pdfPage);
        if (pagePosition != null) {
          position = pagePosition;
          hasPosition = true;
        }
      }

      return { note, originalIndex, position, hasPosition };
    })
    .sort((a, b) => {
      if (a.hasPosition !== b.hasPosition) return a.hasPosition ? -1 : 1;
      if (a.position !== b.position) return a.position - b.position;
      return a.originalIndex - b.originalIndex;
    })
    .map(item => item.note);
}

/** 计算每个 PDF 页面对应的正文字符位置（取该页文字层第一个字符），用于笔记按页排序。 */
function collectPdfPageTextPositions(bodyEl, locator) {
  const positions = new Map();
  if (!bodyEl) return positions;
  const nodeIndex = new Map();
  (locator.map || []).forEach((entry, index) => {
    if (entry && entry.node && !nodeIndex.has(entry.node)) nodeIndex.set(entry.node, index);
  });
  bodyEl.querySelectorAll('figure.pdf-page').forEach(figure => {
    const pageNo = Number(figure.dataset.pdfPage);
    if (!pageNo || positions.has(pageNo)) return;
    const walker = document.createTreeWalker(figure, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      if (node.parentElement && node.parentElement.closest('.pdf-page-text-layer')) {
        const index = nodeIndex.get(node);
        if (index != null) {
          positions.set(pageNo, index);
          break;
        }
      }
    }
  });
  return positions;
}

function getNoteElementById(container, noteId) {
  if (!container) return null;
  return Array.from(container.querySelectorAll('.note-item'))
    .find(el => String(el.dataset.noteId) === String(noteId));
}

function resetArticleBodyElement(bodyEl) {
  if (!bodyEl || !state.currentArticle) return false;
  bodyEl.innerHTML = renderBodyContent(state.currentArticle.content);
  return true;
}

function normalizeNoteLocatorText(text) {
  return String(text || '')
    .replace(/[\s\u00a0\u200b\u200c\u200d\ufeff]/g, '');
}

function buildNoteSearchCandidates(searchText) {
  const raw = String(searchText || '').trim();
  const candidates = [];
  const pushCandidate = value => {
    const normalized = normalizeNoteLocatorText(value);
    if (!normalized) return;
    if (normalized.length < 8 && normalizeNoteLocatorText(raw).length >= 8) return;
    if (!candidates.includes(normalized)) candidates.push(normalized);
  };

  pushCandidate(raw);
  pushCandidate(raw.replace(/^[\[【（(].{1,80}[\]】）)]\s*/, ''));

  const compact = normalizeNoteLocatorText(raw);
  const addWindows = value => {
    if (value.length <= 80) return;
    const windowSize = Math.min(80, Math.max(32, Math.floor(value.length / 3)));
    pushCandidate(value.slice(0, windowSize));
    const middleStart = Math.max(0, Math.floor(value.length / 2) - Math.floor(windowSize / 2));
    pushCandidate(value.slice(middleStart, middleStart + windowSize));
    pushCandidate(value.slice(-windowSize));
  };

  addWindows(compact);
  const afterBracket = normalizeNoteLocatorText(raw.replace(/^[\[【（(].{1,80}[\]】）)]\s*/, ''));
  addWindows(afterBracket);

  return candidates;
}

function collectNoteTextNodes(root) {
  if (!root) return [];
  const nodes = [];
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement;
      if (!parent) return NodeFilter.FILTER_REJECT;
      if (parent.closest('.note-anchor-badge, mark, script, style, .pdf-source-text, .pdf-page-note-btn, .pdf-page-note-badge')) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });

  let node;
  while ((node = walker.nextNode())) nodes.push(node);
  return nodes;
}

function buildNoteTextLocator(root) {
  const nodes = collectNoteTextNodes(root);
  const chars = [];
  const map = [];

  nodes.forEach(node => {
    const text = node.textContent || '';
    for (let offset = 0; offset < text.length; offset++) {
      const normalized = normalizeNoteLocatorText(text[offset]);
      if (!normalized) continue;
      chars.push(normalized);
      map.push({ node, offset });
    }
  });

  return { normalized: chars.join(''), map };
}

function parseNoteSelectionAnchor(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (!value || typeof value !== 'string') return null;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch (_) {
    return null;
  }
}

function collectNoteAnchorBlocks(root) {
  if (!root) return [];
  const selector = 'p,li,blockquote,h1,h2,h3,h4,h5,h6,pre,th,td';
  return Array.from(root.querySelectorAll(selector)).filter(block => {
    const parentBlock = block.parentElement?.closest(selector);
    return !parentBlock || !root.contains(parentBlock);
  });
}

function normalizedNoteRangeContents(range) {
  if (!range) return '';
  const fragment = range.cloneContents();
  fragment.querySelectorAll?.('.note-anchor-badge, mark, script, style, .pdf-page-note-btn, .pdf-page-note-badge').forEach(node => node.remove());
  return normalizeNoteLocatorText(fragment.textContent || '');
}

/** 保存全文偏移、段落内偏移和左右上下文，精确区分重复关键词。 */
function captureNoteSelectionAnchor(root, selection = window.getSelection()) {
  if (!root || !selection?.rangeCount || selection.isCollapsed) return null;
  const range = selection.getRangeAt(0);
  if (!root.contains(range.commonAncestorContainer)) return null;
  const locator = buildNoteTextLocator(root);
  const beforeSelection = document.createRange();
  beforeSelection.selectNodeContents(root);
  try {
    beforeSelection.setEnd(range.startContainer, range.startOffset);
  } catch (_) {
    return null;
  }
  const selectedQuote = normalizedNoteRangeContents(range);
  const startIndex = normalizedNoteRangeContents(beforeSelection).length;
  const indexes = { start: startIndex, end: startIndex + selectedQuote.length };
  if (!selectedQuote || indexes.end > locator.map.length) return null;

  const startEntry = locator.map[indexes.start];
  const startElement = startEntry?.node?.parentElement;
  const blocks = collectNoteAnchorBlocks(root);
  const block = startElement?.closest('p,li,blockquote,h1,h2,h3,h4,h5,h6,pre,th,td');
  const blockIndex = block ? blocks.indexOf(block) : -1;
  let blockStart = null;
  let blockEnd = null;
  if (blockIndex >= 0 && block.contains(range.startContainer) && block.contains(range.endContainer)) {
    const beforeInBlock = document.createRange();
    beforeInBlock.selectNodeContents(block);
    beforeInBlock.setEnd(range.startContainer, range.startOffset);
    blockStart = normalizedNoteRangeContents(beforeInBlock).length;
    blockEnd = blockStart + selectedQuote.length;
  }

  const contextSize = 64;
  return {
    version: 1,
    start: indexes.start,
    end: indexes.end,
    quote: selectedQuote,
    block_index: blockIndex,
    block_start: blockStart,
    block_end: blockEnd,
    prefix: locator.normalized.slice(Math.max(0, indexes.start - contextSize), indexes.start),
    suffix: locator.normalized.slice(indexes.end, indexes.end + contextSize),
  };
}

function noteLocatorMatchFromIndexes(locator, startIndex, endIndex, expected = '') {
  const start = Number(startIndex);
  const end = Number(endIndex);
  if (!Number.isInteger(start) || !Number.isInteger(end) || start < 0 || end <= start || end > locator.map.length) return null;
  const actual = locator.normalized.slice(start, end);
  if (expected && actual !== expected) return null;
  const startPoint = locator.map[start];
  const endPoint = locator.map[end - 1];
  if (!startPoint || !endPoint) return null;
  return {
    startIndex: start,
    endIndex: end - 1,
    needle: actual,
    start: { node: startPoint.node, offset: startPoint.offset },
    end: { node: endPoint.node, offset: endPoint.offset + 1 },
  };
}

function findNoteLocatorMatchForNote(locator, note, startIndex = 0, root = null) {
  const anchor = parseNoteSelectionAnchor(note?.selection_anchor);
  const selected = normalizeNoteLocatorText(note?.selected_text || '');
  const expected = normalizeNoteLocatorText(anchor?.quote || '') || selected;
  if (anchor && expected) {
    const direct = noteLocatorMatchFromIndexes(locator, anchor.start, anchor.end, expected);
    if (direct) return direct;

    const blockIndex = Number(anchor.block_index);
    if (root && Number.isInteger(blockIndex) && blockIndex >= 0) {
      const block = collectNoteAnchorBlocks(root)[blockIndex];
      const blockLocator = buildNoteTextLocator(block);
      const local = noteLocatorMatchFromIndexes(blockLocator, anchor.block_start, anchor.block_end, expected);
      if (local) {
        const globalStart = locator.map.findIndex(point => point.node === local.start.node && point.offset === local.start.offset);
        const globalEndPoint = locator.map.findIndex(point => point.node === local.end.node && point.offset === local.end.offset - 1);
        const global = noteLocatorMatchFromIndexes(locator, globalStart, globalEndPoint + 1, expected);
        if (global) return global;
      }
    }

    const prefix = normalizeNoteLocatorText(anchor.prefix || '');
    const suffix = normalizeNoteLocatorText(anchor.suffix || '');
    const contextNeedle = `${prefix}${expected}${suffix}`;
    if (contextNeedle) {
      const contextStart = locator.normalized.indexOf(contextNeedle);
      if (contextStart >= 0) {
        const contextual = noteLocatorMatchFromIndexes(
          locator,
          contextStart + prefix.length,
          contextStart + prefix.length + expected.length,
          expected,
        );
        if (contextual) return contextual;
      }
    }
  }
  return findNoteLocatorMatch(locator, note?.selected_text || '', startIndex);
}

function findNoteLocatorMatch(locator, searchText, startIndex = 0) {
  if (!locator || !locator.normalized) return null;
  const candidates = buildNoteSearchCandidates(searchText);

  for (const needle of candidates) {
    let found = locator.normalized.indexOf(needle, startIndex);
    if (found === -1 && startIndex > 0) found = locator.normalized.indexOf(needle);
    if (found === -1) continue;

    const start = locator.map[found];
    const end = locator.map[found + needle.length - 1];
    if (!start || !end) continue;
    return {
      startIndex: found,
      endIndex: found + needle.length - 1,
      needle,
      start: { node: start.node, offset: start.offset },
      end: { node: end.node, offset: end.offset + 1 }
    };
  }

  return null;
}

function wrapNoteLocatorMatch(root, match, className) {
  if (!root || !match) return null;
  if (!match) return null;

  const nodes = collectNoteTextNodes(root);
  const rangeNodes = [];
  let collecting = false;

  for (const node of nodes) {
    if (node === match.start.node) collecting = true;
    if (collecting) rangeNodes.push(node);
    if (node === match.end.node) break;
  }

  let firstSpan = null;
  const spans = [];
  for (const node of rangeNodes) {
    if (!node.parentNode) continue;
    const text = node.textContent || '';
    const startOffset = node === match.start.node ? match.start.offset : 0;
    const endOffset = node === match.end.node ? match.end.offset : text.length;
    if (startOffset >= endOffset) continue;

    const frag = document.createDocumentFragment();
    const before = text.slice(0, startOffset);
    const matched = text.slice(startOffset, endOffset);
    const after = text.slice(endOffset);

    if (before) frag.appendChild(document.createTextNode(before));
    const span = document.createElement('span');
    span.className = className;
    span.textContent = matched;
    if (!firstSpan) firstSpan = span;
    spans.push(span);
    frag.appendChild(span);
    if (after) frag.appendChild(document.createTextNode(after));

    node.parentNode.replaceChild(frag, node);
  }

  return firstSpan ? { anchor: firstSpan, spans, match } : null;
}

function wrapFirstTextOccurrence(root, searchText, className, startIndex = 0) {
  if (!root || !searchText) return null;
  const locator = buildNoteTextLocator(root);
  return wrapNoteLocatorMatch(root, findNoteLocatorMatch(locator, searchText, startIndex), className);
}

function wrapNoteTextOccurrence(root, note, className, startIndex = 0) {
  if (!root || !note?.selected_text) return null;
  const locator = buildNoteTextLocator(root);
  return wrapNoteLocatorMatch(root, findNoteLocatorMatchForNote(locator, note, startIndex, root), className);
}

function applyArticleNoteAnchors(bodyEl, notes, options = {}) {
  const noteEntries = getNotesWithSelectedText(notes);
  const activeNoteId = options.activeNoteId;
  const onClickNote = options.onClickNote;
  const nextSearchStartByText = new Map();

  noteEntries.forEach(note => {
    const noteIndex = (notes || []).findIndex(n => String(n.id) === String(note.id)) + 1;
    const className = `note-highlight note-anchor${String(note.id) === String(activeNoteId) ? ' active' : ''}`;
    const key = normalizeNoteLocatorText(note.selected_text);
    const startIndex = nextSearchStartByText.get(key) || 0;
    const wrapped = wrapNoteTextOccurrence(bodyEl, note, className, startIndex);
    const anchor = wrapped && wrapped.anchor;
    if (!anchor) return;
    if (wrapped.match) {
      nextSearchStartByText.set(key, wrapped.match.startIndex + Math.max(1, wrapped.match.needle.length));
    }

    const activate = (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (typeof onClickNote === 'function') onClickNote(note.id);
    };

    wrapped.spans.forEach(span => {
      span.dataset.noteId = String(note.id);
      span.dataset.noteIndex = String(noteIndex);
      span.setAttribute('role', 'button');
      span.setAttribute('tabindex', '0');
      span.setAttribute('title', `查看笔记 ${noteIndex}`);
      span.addEventListener('click', activate);
      span.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') activate(event);
      });
    });

    const badge = document.createElement('sup');
    badge.className = 'note-anchor-badge';
    badge.textContent = String(noteIndex);
    badge.dataset.noteId = String(note.id);
    badge.dataset.noteIndex = String(noteIndex);
    const textLayer = anchor.closest('.pdf-page-text-layer');
    if (textLayer) {
      // PDF 文字层词框带 overflow:hidden 且按词裁切，角标放进词框会被裁掉。
      // 改为挂到文字层上，绝对定位到锚点词右上方，随文字层布局一起重定位。
      badge.classList.add('pdf-text-badge');
      badge.addEventListener('click', activate);
      textLayer.appendChild(badge);
      positionPdfTextLayerBadges(textLayer);
    } else {
      anchor.appendChild(badge);
    }
  });

  applyPdfPageNoteBadges(bodyEl, notes, options);
}

/** 定位 PDF 文字层上的笔记角标：放在锚点词右上方（上标样式）。 */
function positionPdfTextLayerBadges(layer) {
  if (!layer) return;
  layer.querySelectorAll('.pdf-text-badge').forEach(badge => {
    const anchor = layer.querySelector(`.note-anchor[data-note-id="${badge.dataset.noteId}"]`);
    if (!anchor) return;
    const word = anchor.closest('span[data-pdf-word]');
    if (!word) return;
    const left = word.offsetLeft + anchor.offsetLeft + anchor.offsetWidth;
    const top = word.offsetTop + anchor.offsetTop - badge.offsetHeight + 2;
    badge.style.position = 'absolute';
    badge.style.left = `${left}px`;
    badge.style.top = `${top}px`;
  });
}

/** 为带 PDF 页面锚点的笔记在对应页面图上挂角标（点击跳转笔记卡片）。
    同一页多条笔记时，角标自右向左依次排开，各自携带独立 noteId。 */
function applyPdfPageNoteBadges(bodyEl, notes, options = {}) {
  const onClickNote = options.onClickNote;
  (notes || []).forEach(note => {
    const pageNo = pdfPageFromNote(note);
    if (!pageNo) return;
    const figure = bodyEl?.querySelector(`figure.pdf-page[data-pdf-page="${pageNo}"]`);
    if (!figure) return;
    const existing = Array.from(figure.querySelectorAll('.pdf-page-note-badge'));
    if (existing.some(badge => String(badge.dataset.noteId) === String(note.id))) return;
    const noteIndex = (notes || []).findIndex(n => String(n.id) === String(note.id)) + 1;
    const badge = document.createElement('sup');
    badge.className = 'pdf-page-note-badge';
    badge.textContent = String(noteIndex);
    badge.dataset.noteId = String(note.id);
    badge.dataset.noteIndex = String(noteIndex);
    if (existing.length > 0) badge.style.right = `${96 + existing.length * 30}px`;
    badge.title = `查看第 ${pageNo} 页的笔记 ${noteIndex}`;
    badge.setAttribute('role', 'button');
    badge.tabIndex = 0;
    const activate = (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (typeof onClickNote === 'function') onClickNote(note.id);
    };
    badge.addEventListener('click', activate);
    badge.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') activate(event);
    });
    figure.appendChild(badge);
  });
}

async function renderArticleNoteAnchorsInTab(tabId, notes, activeNoteId = null) {
  const bodyEl = $(`tab-detail-body-${tabId}`);
  if (!resetArticleBodyElement(bodyEl)) return notes || [];
  await enhancePdfPageGalleries(bodyEl);
  const displayNotes = sortNotesByArticlePosition(notes, bodyEl);
  applyArticleNoteAnchors(bodyEl, displayNotes, {
    activeNoteId,
    onClickNote: noteId => scrollToNoteCardInTab(tabId, noteId)
  });
  return displayNotes;
}

function scrollToNoteCardInTab(tabId, noteId) {
  const notesPanel = $(`tab-detail-notes-${tabId}`);
  if (notesPanel) notesPanel.classList.remove('hidden');
  const listEl = $(`tab-notes-list-${tabId}`);
  const noteEl = getNoteElementById(listEl, noteId);
  if (!noteEl) return;

  // 程序化平滑滚动期间短暂锁定同步，避免正文驱动同步把列表拉回。
  const syncState = tabNoteSyncState[tabId];
  if (syncState) syncState.lockUntil = Date.now() + 900;

  listEl.querySelectorAll('.note-item.active').forEach(el => el.classList.remove('active'));
  noteEl.classList.add('active');
  if (syncState) syncState.currentItemEl = noteEl;
  noteEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
  scheduleTabNoteSync(tabId);
}

function scrollToBodyNoteAnchorInTab(tabId, noteId) {
  const bodyEl = $(`tab-detail-body-${tabId}`);
  const anchor = bodyEl && Array.from(bodyEl.querySelectorAll('.note-anchor'))
    .find(el => String(el.dataset.noteId) === String(noteId));
  if (!anchor) {
    showToast('未定位到对应正文片段，可能是原文格式或换行差异', 'warning');
    return;
  }

  anchor.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function jumpToNoteInTab(tabId, noteId) {
  const articleId = state.currentArticle ? state.currentArticle.id : currentArticleId;
  if (!articleId) {
    showToast('无法定位笔记，文章未加载', 'error');
    return;
  }
  
  apiFetch(`/api/notes/${articleId}`)
    .then(async notes => {
      const note = findNoteById(notes, noteId);
      if (!note) {
        showToast('笔记不存在', 'error');
        return;
      }
      const pdfPage = pdfPageFromNote(note);
      if (pdfPage > 0) {
        scrollToNoteCardInTab(tabId, noteId);
        const bodyEl = $(`tab-detail-body-${tabId}`);
        if (!scrollToPdfPageFigure(bodyEl, pdfPage)) {
          showToast('未定位到对应 PDF 页面', 'warning');
        }
        return;
      }
      if (!note.selected_text || !note.selected_text.trim()) {
        showToast('该笔记未记录选中文本，无法跳转', 'error');
        return;
      }

      await renderArticleNoteAnchorsInTab(tabId, notes, noteId);
      scrollToBodyNoteAnchorInTab(tabId, noteId);
    })
    .catch(e => {
      console.error('Failed to load note:', e);
      showToast('加载笔记失败', 'error');
    });
}

/**
 * 渲染标签栏
 */
function renderTabs() {
  const tabsContainer = $('tab-bar-tabs');
  if (!tabsContainer) return;
  document.body.classList.toggle('main-tab-active', tabState.activeTabId === 'main');
  document.body.classList.toggle('no-open-tabs', tabState.tabs.length === 0);
  const brandHomeButton = $('tab-bar-brand-home');
  if (brandHomeButton) {
    brandHomeButton.classList.toggle('active', tabState.activeTabId === 'main');
    if (tabState.activeTabId === 'main') brandHomeButton.setAttribute('aria-current', 'page');
    else brandHomeButton.removeAttribute('aria-current');
  }
  const closeAllBtn = $('tab-bar-close-all-btn');
  if (closeAllBtn) closeAllBtn.disabled = tabState.tabs.length === 0;
  
  // 构建标签 HTML（使用 data 属性而非 onclick）
  let tabsHtml = '';
  
  // 主标签（始终显示）
  const mainTabActive = tabState.activeTabId === 'main' ? 'active' : '';
  tabsHtml += `
    <div class="tab-item ${mainTabActive}" data-tab-id="main">
      <span class="tab-icon">${TAB_ICONS[TAB_TYPES.MAIN]}</span>
      <span class="tab-title">全部知识</span>
    </div>
  `;
  
  const articleTabs = sortTabsByRecentView(tabState.tabs.filter(tab => tab.type === TAB_TYPES.ARTICLE));
  const caseManagerTabs = sortTabsByRecentView(tabState.tabs.filter(tab => tab.type === TAB_TYPES.CASE_MANAGER));
  const courtOnlineTabs = sortTabsByRecentView(tabState.tabs.filter(tab => tab.type === TAB_TYPES.COURT_ONLINE));
  const activeCaseManagerTab = caseManagerTabs.find(tab => tab.id === tabState.activeTabId);
  const activeCaseManagerContextLabels = [
    activeCaseManagerTab?.data?.contextLabel,
    activeCaseManagerTab?.data?.detailLabel,
    activeCaseManagerTab?.data?.pageLabel,
  ];
  const caseManagerGroupLabel = activeCaseManagerContextLabels.includes('委托人管理')
    ? '委托人管理'
    : activeCaseManagerContextLabels.includes('对方管理')
      ? '对方管理'
      : activeCaseManagerTab?.data?.detailLabel === '委托合同及授权'
        ? '委托合同及授权'
        : '案件管理';
  const researchTabs = sortTabsByRecentView(tabState.tabs.filter(tab => tab.type === TAB_TYPES.RESEARCH_PROJECTS));
  const caseFileTabs = sortTabsByRecentView(tabState.tabs.filter(tab => tab.type === TAB_TYPES.CASE_FILES));
  const settingsTabs = sortTabsByRecentView(tabState.tabs.filter(tab => SETTINGS_TAB_TYPES.has(tab.type)));
  const knowledgeCenterTabs = sortTabsByRecentView(tabState.tabs.filter(tab => KNOWLEDGE_CENTER_TAB_TYPES.has(tab.type)));
  const toolTabs = sortTabsByRecentView(tabState.tabs.filter(tab => TOOL_TAB_TYPES.has(tab.type)));

  // 标签组顺序与“已打开页面总览”分类顺序保持一致：
  // 案件管理 → 案件文件 → 案件研究 → 已打开文章 → 知识中心 → 效率中心 → 设置
  tabsHtml += renderWorkspaceTabGroupMarkup('case-manager', caseManagerTabs, {
    label: caseManagerGroupLabel,
    icon: TAB_ICONS[TAB_TYPES.CASE_MANAGER],
    unit: '个页面'
  });

  tabsHtml += renderWorkspaceTabGroupMarkup('court-online', courtOnlineTabs, {
    label: '一张网',
    icon: TAB_ICONS[TAB_TYPES.COURT_ONLINE],
    unit: '个页面'
  });

  tabsHtml += renderWorkspaceTabGroupMarkup('case-files', caseFileTabs, {
    label: '案件文件',
    icon: TAB_ICONS[TAB_TYPES.CASE_FILES],
    unit: '个案件'
  });

  tabsHtml += renderWorkspaceTabGroupMarkup('research', researchTabs, {
    label: '案件研究',
    icon: TAB_ICONS[TAB_TYPES.RESEARCH_PROJECTS],
    unit: '个页面'
  });

  if (articleTabs.length) {
    const activeArticleTab = articleTabs.find(tab => tab.id === tabState.activeTabId) || null;
    const groupActive = activeArticleTab ? 'active' : '';

    tabsHtml += `
      <div class="tab-item article-tab-group ${groupActive}" role="button" aria-haspopup="menu" aria-expanded="false" aria-label="已打开文章，共 ${articleTabs.length} 篇" tabindex="0">
        <span class="tab-icon">${TAB_ICONS[TAB_TYPES.ARTICLE]}</span>
        <span class="tab-title" title="已打开文章">已打开文章</span>
        <span class="article-tab-count" aria-hidden="true">${articleTabs.length}</span>
        <svg class="article-tab-chevron" width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M2 3.5l3 3 3-3" stroke="currentColor" stroke-width="1.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
      </div>
    `;
  }

  tabsHtml += renderWorkspaceTabGroupMarkup('knowledge-center', knowledgeCenterTabs, {
    label: '知识中心',
    icon: TAB_ICONS[TAB_TYPES.LEGAL_KNOWLEDGE],
    unit: '个页面'
  });

  tabsHtml += renderWorkspaceTabGroupMarkup('tools', toolTabs, {
    label: '效率中心',
    icon: TOOLS_GROUP_ICON,
    unit: '个页面'
  });

  /* 设置标签组保持独立。 */
  tabsHtml += renderWorkspaceTabGroupMarkup('settings', settingsTabs, {
    label: '设置',
    icon: TAB_ICONS[TAB_TYPES.MCP_MANAGER],
    unit: '个页面'
  });

  tabsContainer.innerHTML = tabsHtml;
  syncWorkspaceTabFloatingMenu('case-manager', caseManagerTabs, {
    label: '案件管理',
    itemLabel: getCaseManagerTabDisplayName,
    itemMeta: tab => `案件管理 ${getCaseManagerTabNumber(tab) || ''}`.trim()
  });
  syncWorkspaceTabFloatingMenu('court-online', courtOnlineTabs, {
    label: '一张网',
    itemLabel: () => '一张网',
    itemMeta: () => '官网待办、消息与电子送达',
    addable: false
  });
  syncWorkspaceTabFloatingMenu('research', researchTabs, {
    label: '案件研究',
    itemLabel: tab => tab.data?.contextLabel || '未选择具体案件',
    itemMeta: () => '案件研究'
  });
  syncWorkspaceTabFloatingMenu('case-files', caseFileTabs, {
    label: '案件文件',
    itemLabel: tab => tab.data?.caseTitle || tab.title || '案件文件',
    itemMeta: () => '文件管理系统',
    addable: false
  });
  syncWorkspaceTabFloatingMenu('tools', toolTabs, {
    label: '效率中心',
    itemLabel: tab => tab.title || getOpenPageTypeLabel(tab.type),
    itemMeta: tab => getOpenPageTypeLabel(tab.type),
    addable: false
  });
  syncWorkspaceTabFloatingMenu('knowledge-center', knowledgeCenterTabs, {
    label: '知识中心',
    itemLabel: tab => tab.title || getOpenPageTypeLabel(tab.type),
    itemMeta: tab => getOpenPageTypeLabel(tab.type),
    addable: false
  });
  syncWorkspaceTabFloatingMenu('settings', settingsTabs, {
    label: '设置',
    itemLabel: tab => tab.title || getOpenPageTypeLabel(tab.type),
    itemMeta: tab => getOpenPageTypeLabel(tab.type),
    addable: false
  });
  syncArticleTabFloatingMenu(articleTabs);
  bindWorkspaceTabGroupHover('case-manager');
  bindWorkspaceTabGroupHover('court-online');
  bindWorkspaceTabGroupHover('research');
  bindWorkspaceTabGroupHover('case-files');
  bindWorkspaceTabGroupHover('knowledge-center');
  bindWorkspaceTabGroupHover('tools');
  bindWorkspaceTabGroupHover('settings');
  bindArticleTabGroupHover();
}

function renderWorkspaceTabGroupMarkup(kind, tabs, config) {
  if (!tabs.length) return '';
  const active = tabs.some(tab => tab.id === tabState.activeTabId) ? 'active' : '';
  return `
    <div class="tab-item workspace-tab-group ${kind}-tab-group ${active}" role="button" aria-haspopup="menu" aria-expanded="false" aria-label="${config.label}，共 ${tabs.length} ${config.unit}" tabindex="0" data-workspace-group="${kind}">
      <span class="tab-icon">${config.icon}</span>
      <span class="tab-title" title="${config.label}">${config.label}</span>
      <span class="article-tab-count workspace-tab-count" aria-hidden="true">${tabs.length}</span>
      <svg class="article-tab-chevron workspace-tab-chevron" width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M2 3.5l3 3 3-3" stroke="currentColor" stroke-width="1.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
    </div>
  `;
}

const workspaceTabMenuHideTimers = new Map();
const workspaceTabMenusHeldOpen = new Set();

function removeWorkspaceTabMenuHoverGuard(kind) {
  document.getElementById(`${kind}-tab-menu-hover-guard`)?.remove();
}

function ensureWorkspaceTabMenuHoverGuard(kind) {
  removeWorkspaceTabMenuHoverGuard(kind);
  const guard = document.createElement('div');
  guard.id = `${kind}-tab-menu-hover-guard`;
  guard.className = 'workspace-tab-menu-hover-guard';
  guard.setAttribute('aria-hidden', 'true');
  // 只响应用户真实移动；守卫创建时即使出现在静止指针下方，也不能自动收起菜单。
  guard.addEventListener('pointermove', () => {
    workspaceTabMenusHeldOpen.delete(kind);
    removeWorkspaceTabMenuHoverGuard(kind);
    scheduleWorkspaceTabMenuHide(kind);
  }, { once: true });
  document.body.appendChild(guard);
}

function syncWorkspaceTabFloatingMenu(kind, tabs, config) {
  const menuId = `${kind}-tab-floating-menu`;
  let menu = document.getElementById(menuId);
  const wasOpen = menu?.classList.contains('open') || false;
  if (!tabs.length) {
    removeWorkspaceTabMenuHoverGuard(kind);
    menu?.remove();
    return;
  }
  if (!menu) {
    menu = document.createElement('div');
    menu.id = menuId;
    menu.className = 'article-tab-menu workspace-tab-menu';
    menu.dataset.workspaceMenu = kind;
    menu.setAttribute('role', 'menu');
    menu.setAttribute('aria-label', config.label);
    document.body.appendChild(menu);
  }

  const items = tabs.map(tab => {
    const active = tab.id === tabState.activeTabId ? 'active' : '';
    const label = config.itemLabel(tab);
    const meta = config.itemMeta(tab);
    return `
      <div class="article-tab-menu-item workspace-tab-menu-item ${active}" role="menuitem" data-workspace-tab-id="${tab.id}" tabindex="-1">
        <span class="article-tab-menu-icon">${TAB_ICONS[tab.type] || TAB_ICONS[TAB_TYPES.MAIN]}</span>
        <span class="workspace-tab-menu-copy">
          <span class="article-tab-menu-title" title="${escapeHtml(label)}">${escapeHtml(label)}</span>
          <span class="workspace-tab-menu-meta">${escapeHtml(meta)}</span>
        </span>
        <button class="article-tab-menu-close" type="button" data-close-tab="${tab.id}" aria-label="关闭页面：${escapeHtml(label)}" title="关闭页面">
          <svg width="10" height="10" viewBox="0 0 10 10"><path d="M2 2l6 6M8 2l-6 6" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg>
        </button>
      </div>
    `;
  }).join('');

  menu.innerHTML = `
    <div class="article-tab-menu-header workspace-tab-menu-header">
      <span class="workspace-tab-menu-heading">${config.label} <span>${tabs.length}</span></span>
      <span class="workspace-tab-menu-actions">
        ${['case-manager', 'court-online', 'research', 'case-files', 'knowledge-center', 'tools', 'settings'].includes(kind) ? `
          <button class="workspace-tab-close-all-btn" type="button" data-workspace-close-all="${kind}" aria-label="关闭所有已打开的${config.label}页面" title="关闭所有${config.label}页面">
            全部关闭
          </button>
        ` : ''}
        ${config.addable === false ? '' : `<button class="workspace-tab-add-btn" type="button" data-workspace-add="${kind}" aria-label="新建${config.label}页面" title="新建${config.label}页面">+</button>`}
      </span>
    </div>
    <div class="article-tab-menu-list">${items}</div>
  `;
  if (wasOpen) {
    showWorkspaceTabMenu(kind);
  } else {
    hideWorkspaceTabMenu(kind);
  }
}

function positionWorkspaceTabMenu(kind) {
  const group = document.querySelector(`#tab-bar-tabs .${kind}-tab-group`);
  const menu = document.getElementById(`${kind}-tab-floating-menu`);
  if (!group || !menu) return;
  const rect = group.getBoundingClientRect();
  const mobile = window.matchMedia('(max-width: 760px)').matches;
  const menuWidth = mobile
    ? Math.max(0, window.innerWidth - 16)
    : Math.min(480, Math.max(300, window.innerWidth - 16));
  const left = Math.min(Math.max(8, rect.left), Math.max(8, window.innerWidth - menuWidth - 8));
  menu.style.width = `${menuWidth}px`;
  menu.style.left = `${mobile ? 8 : left}px`;
  if (mobile) {
    const tabBarTop = document.querySelector('.tab-bar')?.getBoundingClientRect().top ?? rect.top;
    menu.style.top = 'auto';
    menu.style.bottom = `${Math.max(0, window.innerHeight - tabBarTop + 4)}px`;
  } else {
    menu.style.top = `${Math.max(0, rect.bottom - 1)}px`;
    menu.style.bottom = 'auto';
  }
}

function showWorkspaceTabMenu(kind, focusFirst = false) {
  const group = document.querySelector(`#tab-bar-tabs .${kind}-tab-group`);
  const menu = document.getElementById(`${kind}-tab-floating-menu`);
  if (!group || !menu) return;
  hideAllTabGroupMenus(kind);
  const timer = workspaceTabMenuHideTimers.get(kind);
  if (timer) clearTimeout(timer);
  workspaceTabMenuHideTimers.delete(kind);
  positionWorkspaceTabMenu(kind);
  menu.classList.add('open');
  group.classList.add('menu-open');
  group.setAttribute('aria-expanded', 'true');
  if (focusFirst) menu.querySelector('.workspace-tab-menu-item')?.focus();
}

function hideWorkspaceTabMenu(kind) {
  const timer = workspaceTabMenuHideTimers.get(kind);
  if (timer) clearTimeout(timer);
  workspaceTabMenuHideTimers.delete(kind);
  workspaceTabMenusHeldOpen.delete(kind);
  removeWorkspaceTabMenuHoverGuard(kind);
  const group = document.querySelector(`#tab-bar-tabs .${kind}-tab-group`);
  const menu = document.getElementById(`${kind}-tab-floating-menu`);
  menu?.classList.remove('open');
  group?.classList.remove('menu-open');
  group?.setAttribute('aria-expanded', 'false');
}

function scheduleWorkspaceTabMenuHide(kind) {
  if (workspaceTabMenusHeldOpen.has(kind)) return;
  const timer = workspaceTabMenuHideTimers.get(kind);
  if (timer) clearTimeout(timer);
  workspaceTabMenuHideTimers.set(kind, setTimeout(() => hideWorkspaceTabMenu(kind), 140));
}

function bindWorkspaceTabGroupHover(kind) {
  const group = document.querySelector(`#tab-bar-tabs .${kind}-tab-group`);
  const menu = document.getElementById(`${kind}-tab-floating-menu`);
  if (!group || !menu) return;
  const canHover = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  if (canHover) {
    group.addEventListener('pointerenter', () => showWorkspaceTabMenu(kind));
    group.addEventListener('pointerleave', () => scheduleWorkspaceTabMenuHide(kind));
  }
  group.addEventListener('focusin', () => showWorkspaceTabMenu(kind));
  group.addEventListener('focusout', () => scheduleWorkspaceTabMenuHide(kind));
  menu.onpointerenter = canHover ? () => {
    const timer = workspaceTabMenuHideTimers.get(kind);
    if (timer) clearTimeout(timer);
  } : null;
  menu.onpointerleave = canHover ? () => {
    workspaceTabMenusHeldOpen.delete(kind);
    scheduleWorkspaceTabMenuHide(kind);
  } : null;
  menu.onfocusin = () => showWorkspaceTabMenu(kind);
  menu.onfocusout = () => scheduleWorkspaceTabMenuHide(kind);
}

let articleTabMenuHideTimer = null;
let articleTabMenuEventsInitialized = false;

function syncArticleTabFloatingMenu(articleTabs) {
  let menu = document.getElementById('article-tab-floating-menu');
  const wasOpen = menu?.classList.contains('open') || false;
  if (!articleTabs.length) {
    if (menu) menu.remove();
    return;
  }

  if (!menu) {
    menu = document.createElement('div');
    menu.id = 'article-tab-floating-menu';
    menu.className = 'article-tab-menu article-tab-floating-menu';
    menu.setAttribute('role', 'menu');
    menu.setAttribute('aria-label', '已打开文章');
    document.body.appendChild(menu);
  }

  const menuItems = articleTabs.map(tab => {
    const itemActive = tab.id === tabState.activeTabId ? 'active' : '';
    return `
      <div class="article-tab-menu-item ${itemActive}" role="menuitem" data-article-tab-id="${tab.id}" tabindex="-1">
        <span class="article-tab-menu-icon">${TAB_ICONS[TAB_TYPES.ARTICLE]}</span>
        <span class="article-tab-menu-title" title="${escapeHtml(tab.title)}">${escapeHtml(tab.title)}</span>
        <button class="article-tab-menu-close" type="button" data-close-tab="${tab.id}" aria-label="关闭文章：${escapeHtml(tab.title)}" title="关闭文章">
          <svg width="10" height="10" viewBox="0 0 10 10"><path d="M2 2l6 6M8 2l-6 6" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg>
        </button>
      </div>
    `;
  }).join('');

  menu.innerHTML = `
    <div class="article-tab-menu-header workspace-tab-menu-header">
      <span class="workspace-tab-menu-heading">已打开文章 <span>${articleTabs.length}</span></span>
      <span class="workspace-tab-menu-actions">
        <button class="workspace-tab-close-all-btn" type="button" data-article-close-all aria-label="关闭所有已打开的文章" title="关闭所有已打开的文章">
          全部关闭
        </button>
      </span>
    </div>
    <div class="article-tab-menu-list">${menuItems}</div>
  `;
  if (wasOpen) {
    showArticleTabMenu();
  } else {
    hideArticleTabMenu();
  }
}

function positionArticleTabMenu() {
  const group = document.querySelector('#tab-bar-tabs .article-tab-group');
  const menu = document.getElementById('article-tab-floating-menu');
  if (!group || !menu) return;

  const groupRect = group.getBoundingClientRect();
  const mobile = window.matchMedia('(max-width: 760px)').matches;
  const menuWidth = mobile
    ? Math.max(0, window.innerWidth - 16)
    : Math.min(480, Math.max(280, window.innerWidth - 16));
  const left = Math.min(
    Math.max(8, groupRect.left),
    Math.max(8, window.innerWidth - menuWidth - 8)
  );
  menu.style.width = `${menuWidth}px`;
  menu.style.left = `${mobile ? 8 : left}px`;
  if (mobile) {
    const tabBarTop = document.querySelector('.tab-bar')?.getBoundingClientRect().top ?? groupRect.top;
    menu.style.top = 'auto';
    menu.style.bottom = `${Math.max(0, window.innerHeight - tabBarTop + 4)}px`;
  } else {
    menu.style.top = `${Math.max(0, groupRect.bottom - 1)}px`;
    menu.style.bottom = 'auto';
  }
}

function showArticleTabMenu(focusFirst = false) {
  const group = document.querySelector('#tab-bar-tabs .article-tab-group');
  const menu = document.getElementById('article-tab-floating-menu');
  if (!group || !menu) return;
  hideAllTabGroupMenus('article');
  if (articleTabMenuHideTimer) {
    clearTimeout(articleTabMenuHideTimer);
    articleTabMenuHideTimer = null;
  }
  positionArticleTabMenu();
  menu.classList.add('open');
  group.classList.add('menu-open');
  group.setAttribute('aria-expanded', 'true');
  if (focusFirst) menu.querySelector('.article-tab-menu-item')?.focus();
}

function hideArticleTabMenu() {
  if (articleTabMenuHideTimer) {
    clearTimeout(articleTabMenuHideTimer);
    articleTabMenuHideTimer = null;
  }
  const group = document.querySelector('#tab-bar-tabs .article-tab-group');
  const menu = document.getElementById('article-tab-floating-menu');
  if (menu) menu.classList.remove('open');
  if (group) {
    group.classList.remove('menu-open');
    group.setAttribute('aria-expanded', 'false');
  }
}

function scheduleArticleTabMenuHide() {
  if (articleTabMenuHideTimer) clearTimeout(articleTabMenuHideTimer);
  articleTabMenuHideTimer = setTimeout(hideArticleTabMenu, 140);
}

function bindArticleTabGroupHover() {
  const group = document.querySelector('#tab-bar-tabs .article-tab-group');
  const menu = document.getElementById('article-tab-floating-menu');
  if (!group || !menu) return;

  const canHover = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  if (canHover) {
    group.addEventListener('pointerenter', () => showArticleTabMenu());
    group.addEventListener('pointerleave', scheduleArticleTabMenuHide);
  }
  group.addEventListener('focusin', () => showArticleTabMenu());
  group.addEventListener('focusout', scheduleArticleTabMenuHide);
  menu.onpointerenter = canHover ? () => {
    if (articleTabMenuHideTimer) clearTimeout(articleTabMenuHideTimer);
  } : null;
  menu.onpointerleave = canHover ? scheduleArticleTabMenuHide : null;
  menu.onfocusin = () => showArticleTabMenu();
  menu.onfocusout = scheduleArticleTabMenuHide;
}

function hideAllTabGroupMenus(except = '') {
  if (except !== 'article') hideArticleTabMenu();
  ['case-manager', 'court-online', 'research', 'case-files', 'knowledge-center', 'tools', 'settings'].forEach(kind => {
    if (kind !== except) hideWorkspaceTabMenu(kind);
  });
}

function hideArticleTabMenuUntilPointerLeaves() {
  hideArticleTabMenu();
}

/**
 * 切换标签页
 */
function switchTab(tabId) {
  _suspendBodyEditorForTabSwitch(tabId);
  const contentArea = $('tab-content-area');
  const previousActiveTabId = tabState.activeTabId;
  if (tabState.activeTabId === 'main' && tabId !== 'main' && contentArea) {
    if (mainTabScrollRestoreFrame !== null) {
      // 若用户在恢复动画帧执行前又离开主页，沿用尚未恢复的原位置。
      cancelAnimationFrame(mainTabScrollRestoreFrame);
      mainTabScrollRestoreFrame = null;
    } else {
      mainTabScrollTop = contentArea.scrollTop;
    }
    if (mainTabScrollRestoreTimer !== null) {
      clearTimeout(mainTabScrollRestoreTimer);
      mainTabScrollRestoreTimer = null;
    }
  }
  // 离开文章阅读页前落盘阅读位置（display:none 会把 scrollTop 压回 0）
  if (previousActiveTabId !== tabId) {
    const leavingPage = document.getElementById(previousActiveTabId);
    if (leavingPage?.dataset?.articleId) {
      flushArticleReadPositionForTab(previousActiveTabId);
    }
  }

  const switchingTab = tabState.tabs.find(tab => tab.id === tabId);
  if (switchingTab?.type === TAB_TYPES.RESEARCH_PROJECTS) {
    activateResearchStateForTab(tabId);
  }
  if (tabId !== 'main' && hibernatedTabState.has(tabId)) {
    restoreHibernatedTab(tabId);
  } else if (tabId !== 'main' && !$(tabId)) {
    const tab = tabState.tabs.find(t => t.id === tabId);
    if (tab) createTabPage(tab);
  }

  // 更新激活状态
  tabState.activeTabId = tabId;
  // 最近查看的文章优先显示在“已打开页面”的阅读文章总览中。
  // 此字段会随标签状态保存，刷新后仍可保留用户最后的阅读顺序。
  markTabAsRecentlyViewed(switchingTab);
  window.setTimeout(enforceSmartHibernation, 0);
  document.body.classList.toggle('main-tab-active', tabId === 'main');

  // “当前文章”始终跟随当前文章标签。异步加载尚未完成时保留准确的 ID，
  // 但不沿用另一标签的文章对象。
  if (switchingTab?.type === TAB_TYPES.ARTICLE) {
    currentArticleId = Number(switchingTab.data?.articleId || 0) || null;
    const tabArticle = switchingTab.data?.article;
    state.currentArticle = tabArticle && Number(tabArticle.id) === Number(currentArticleId)
      ? tabArticle
      : null;
  } else if (tabId !== 'main') {
    currentArticleId = null;
    state.currentArticle = null;
  }
  
  // 隐藏所有标签页，移除 active 类
  const allPages = document.querySelectorAll('.tab-page');
  allPages.forEach(page => {
    page.classList.remove('active');
    page.style.display = 'none';
  });
  
  // 特殊处理 'main' 标签，映射到 'tab-page-main'
  const targetId = tabId === 'main' ? 'tab-page-main' : tabId;
  
  // 显示目标标签页，添加 active 类
  const targetPage = $(targetId);
  if (targetPage) {
    targetPage.classList.add('active');
    targetPage.style.display = 'flex';
    targetPage.style.flexDirection = 'column';
    targetPage.style.flex = '1';
    targetPage.style.minHeight = '0';
    targetPage.style.overflow = 'hidden';
  }
  window.ApexPerformance?.publishPageActivity(tabId);
  
  // 切回已加载的文章阅读页时恢复上次阅读位置（display 切换会把 scrollTop 压回 0）
  if (switchingTab?.type === TAB_TYPES.ARTICLE && previousActiveTabId !== tabId) {
    const articleId = Number(switchingTab.data?.articleId || 0);
    if (articleId) {
      requestAnimationFrame(() => {
        if (tabState.activeTabId !== tabId) return;
        const scroller = document.getElementById(tabId)?.querySelector('.tab-article-body');
        if (!scroller) return;
        const max = Math.max(0, scroller.scrollHeight - scroller.clientHeight);
        const saved = getSavedArticleReadPosition(articleId);
        if (saved && max) scroller.scrollTop = Math.min(saved, max);
      });
    }
  }

  // 恢复阅读页后重绘正文-笔记连线并同步笔记栏位置。
  if (switchingTab?.type === TAB_TYPES.ARTICLE) {
    requestAnimationFrame(() => {
      if (tabState.activeTabId !== tabId) return;
      scheduleTabNoteSync(tabId);
    });
  }
  
  // 如果切换到主标签，恢复主内容区
  if (tabId === 'main') {
    // 主内容区显示
    expandSidebar();
    if (typeof loadHomeReminderCenter === 'function') loadHomeReminderCenter();
    // 恢复浮动分页按钮的显示状态
    const fpEl = document.getElementById('floating-pagination');
    if (fpEl && fpEl.dataset.fpOriginalDisplay) {
      fpEl.style.display = fpEl.dataset.fpOriginalDisplay;
    }

    // 等主页恢复布局和可滚动高度后再还原位置，避免浏览器在 display 切换时重置。
    if (mainTabScrollRestoreFrame !== null) {
      cancelAnimationFrame(mainTabScrollRestoreFrame);
    }
    mainTabScrollRestoreFrame = requestAnimationFrame(() => {
      mainTabScrollRestoreFrame = null;
      if (tabState.activeTabId === 'main' && contentArea) {
        contentArea.scrollTop = mainTabScrollTop;
      }
    });
    // 侧边栏展开会让内容区执行 0.25 秒的 left 动画，并在宽度变化时触发滚动锚定；
    // 动画结束后再校正一次，确保文章仍处在打开前的视口位置。
    if (mainTabScrollRestoreTimer !== null) {
      clearTimeout(mainTabScrollRestoreTimer);
    }
    mainTabScrollRestoreTimer = setTimeout(() => {
      mainTabScrollRestoreTimer = null;
      if (tabState.activeTabId === 'main' && contentArea) {
        contentArea.scrollTop = mainTabScrollTop;
      }
    }, 300);
  } else {
    // 折叠侧边栏
    collapseSidebar();
    // 隐藏浮动分页按钮
    const fpEl = document.getElementById('floating-pagination');
    if (fpEl) {
      fpEl.dataset.fpOriginalDisplay = fpEl.style.display || 'none';
      fpEl.style.display = 'none';
    }
  }
  
  // 更新标签栏状态
  renderTabs();
  
  // 更新主页按钮状态
  const homeBtn = $('tab-bar-home-btn');
  if (homeBtn) {
    homeBtn.classList.toggle('active', tabId !== 'main');
  }

  saveTabsState();
  _resumeBodyEditorForActiveTab();
}

/**
 * 关闭标签页
 */
function closeTab(tabId, editorDecisionResolved = false, preserveGroupMenu = false) {
  const tabIndex = tabState.tabs.findIndex(t => t.id === tabId);
  if (tabIndex === -1) return;
  const closingTab = tabState.tabs[tabIndex];
  if (closingTab.type === TAB_TYPES.ARTICLE && tabState.activeTabId === tabId
      && $('edit-body-modal')?.classList.contains('open')) _persistActiveBodyEditorSession();
  const editorSession = closingTab.type === TAB_TYPES.ARTICLE
    ? _bodyEditorSessions.get(Number(closingTab.data?.articleId || 0))
    : null;
  if (!editorDecisionResolved && editorSession?.dirty) {
    if (tabState.activeTabId === tabId) _persistActiveBodyEditorSession();
    if (confirm('这篇文章有未保存的编辑内容。是否先保存再关闭标签？')) {
      if (tabState.activeTabId !== tabId) switchTab(tabId);
      saveBody({ closeAfter: false }).then(saved => { if (saved) closeTab(tabId, true); });
      return;
    }
    if (!confirm('不保存更改并关闭该文章标签？')) return;
    _bodyEditorSessions.delete(Number(closingTab.data?.articleId || 0));
    try { localStorage.removeItem(`legal_kb_body_draft_${closingTab.data?.articleId}`); } catch (_) { /* ignore */ }
    if (tabState.activeTabId === tabId) $('edit-body-modal')?.classList.remove('open');
  }
  if (closingTab.type === TAB_TYPES.RESEARCH_PROJECTS) {
    researchStatesByTabId.delete(tabId);
  }
  const fallbackCaseManagerTab = closingTab.type === TAB_TYPES.CASE_FILES
    ? [...tabState.tabs].reverse().find(tab => tab.type === TAB_TYPES.CASE_MANAGER)?.id
    : null;
  const returnTabId = [TAB_TYPES.AI_ASK, TAB_TYPES.CASE_FILES].includes(closingTab.type)
    ? (closingTab.data?.returnTabId || fallbackCaseManagerTab)
    : null;
  if (closingTab.type === TAB_TYPES.AI_ASK) detachAskPanelFromTab();
  const askReturnState = askCitationReturnByTabId.get(tabId) || null;
  askCitationReturnByTabId.delete(tabId);
  
  // 关闭前落盘阅读位置，再次打开该文章时恢复
  if (closingTab.type === TAB_TYPES.ARTICLE) {
    flushArticleReadPositionForTab(tabId);
  }
  
  // 移除标签
  tabState.tabs.splice(tabIndex, 1);
  hibernatedTabState.delete(tabId);
  
  // 移除标签页内容
  const pageEl = $(tabId);
  if (pageEl) {
    pageEl.remove();
  }

  // 从设置页进入的 AI API / MCP 管理页被关闭时，回到设置页的管理分类
  const openedFromSettings = settingsReturnTabType === closingTab.type && !preserveGroupMenu;
  if (settingsReturnTabType === closingTab.type) settingsReturnTabType = null;

  // 如果关闭的是当前激活的标签，切换到主标签或其他标签
  if (tabState.activeTabId === tabId) {
    if (openedFromSettings) {
      const nextTab = tabState.tabs[tabState.tabs.length - 1];
      switchTab(nextTab ? nextTab.id : 'main');
      openSettingsModal('manage');
    } else if (returnTabId === 'main' || tabState.tabs.some(tab => tab.id === returnTabId)) {
      switchTab(returnTabId);
    } else if (tabState.tabs.length > 0) {
      // 切换到最后一个标签
      const lastTab = tabState.tabs[tabState.tabs.length - 1];
      switchTab(lastTab.id);
    } else {
      // 没有其他标签，切换到主标签
      switchTab('main');
    }
  } else {
    renderTabs();
  }

  saveTabsState();

  if ($('open-pages-overview')?.classList.contains('open')) {
    renderOpenPagesOverview(activeOpenPagesCategoryId);
    requestAnimationFrame(() => {
      document.querySelector('#open-pages-overview .open-page-card.active, #open-pages-overview .open-page-card')?.focus({ preventScroll: true });
    });
  }

  if (askReturnState) restoreAskCitationReturn(askReturnState);
}

let closeAllTabsConfirmEventsBound = false;

function ensureCloseAllTabsConfirmPopover() {
  let popover = document.getElementById('tab-close-all-confirm-popover');
  if (!popover) {
    popover = document.createElement('section');
    popover.id = 'tab-close-all-confirm-popover';
    popover.className = 'tab-close-all-confirm-popover';
    popover.setAttribute('role', 'dialog');
    popover.setAttribute('aria-modal', 'false');
    popover.setAttribute('aria-labelledby', 'tab-close-all-confirm-title');
    popover.hidden = true;
    popover.innerHTML = `
      <div class="tab-close-all-confirm-title" id="tab-close-all-confirm-title">关闭所有页面？</div>
      <p>将关闭 <strong data-close-all-count>0</strong> 个已打开页面。未保存的内容可能会丢失。</p>
      <div class="tab-close-all-confirm-actions">
        <button type="button" data-close-all-cancel>取消</button>
        <button type="button" class="danger" data-close-all-confirm>确认关闭</button>
      </div>
    `;
    document.body.appendChild(popover);
    popover.querySelector('[data-close-all-cancel]')?.addEventListener('click', () => hideCloseAllTabsConfirmPopover(true));
    popover.querySelector('[data-close-all-confirm]')?.addEventListener('click', confirmCloseAllOpenTabs);
  }
  if (!closeAllTabsConfirmEventsBound) {
    closeAllTabsConfirmEventsBound = true;
    document.addEventListener('pointerdown', event => {
      const target = event.target instanceof Element ? event.target : null;
      const trigger = $('tab-bar-close-all-btn');
      if (!target || !popover.classList.contains('show') || popover.contains(target) || trigger?.contains(target)) return;
      hideCloseAllTabsConfirmPopover();
    });
    document.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || !popover.classList.contains('show')) return;
      event.preventDefault();
      hideCloseAllTabsConfirmPopover(true);
    });
    window.addEventListener('resize', () => {
      if (popover.classList.contains('show')) positionCloseAllTabsConfirmPopover();
    });
  }
  return popover;
}

function positionCloseAllTabsConfirmPopover() {
  const popover = $('tab-close-all-confirm-popover');
  const trigger = $('tab-bar-close-all-btn');
  if (!popover || !trigger) return;
  const rect = trigger.getBoundingClientRect();
  const edge = 10;
  const width = popover.offsetWidth;
  const height = popover.offsetHeight;
  const left = Math.max(edge, Math.min(rect.right - width, window.innerWidth - width - edge));
  let top = rect.bottom + 9;
  if (top + height > window.innerHeight - edge) top = Math.max(edge, rect.top - height - 9);
  popover.style.left = `${Math.round(left)}px`;
  popover.style.top = `${Math.round(top)}px`;
}

function showCloseAllTabsConfirmPopover() {
  const popover = ensureCloseAllTabsConfirmPopover();
  const trigger = $('tab-bar-close-all-btn');
  popover.querySelector('[data-close-all-count]').textContent = String(tabState.tabs.length);
  popover.hidden = false;
  requestAnimationFrame(() => {
    positionCloseAllTabsConfirmPopover();
    popover.classList.add('show');
    trigger?.setAttribute('aria-expanded', 'true');
    popover.querySelector('[data-close-all-cancel]')?.focus();
  });
}

function hideCloseAllTabsConfirmPopover(restoreFocus = false) {
  const popover = $('tab-close-all-confirm-popover');
  if (!popover) return;
  popover.classList.remove('show');
  $('tab-bar-close-all-btn')?.setAttribute('aria-expanded', 'false');
  window.setTimeout(() => {
    if (!popover.classList.contains('show')) popover.hidden = true;
  }, 160);
  if (restoreFocus) $('tab-bar-close-all-btn')?.focus();
}

function closeAllOpenTabs() {
  if (!tabState.tabs.length) {
    switchTab('main');
    return;
  }
  showCloseAllTabsConfirmPopover();
}

function confirmCloseAllOpenTabs() {
  hideCloseAllTabsConfirmPopover();
  if (!tabState.tabs.length) return;

  if (tabState.tabs.some(tab => tab.type === TAB_TYPES.AI_ASK)) detachAskPanelFromTab();
  flushAllArticleReadPositions();
  tabState.tabs.forEach(tab => {
    const pageEl = $(tab.id);
    if (pageEl) pageEl.remove();
  });

  tabState.tabs = [];
  researchStatesByTabId.clear();
  askCitationReturnByTabId.clear();
  settingsReturnTabType = null;
  settingsStorageReturnPending = false;
  settingsOfflineCacheReturnPending = false;
  tabState.activeTabId = 'main';
  switchTab('main');
  saveTabsState();
  showToast('已关闭所有标签页');
}

function closeAllTabsByType(type, successMessage) {
  const matchingTabs = tabState.tabs.filter(tab => tab.type === type);
  if (!matchingTabs.length) return;

  const closingIds = new Set(matchingTabs.map(tab => tab.id));
  flushAllArticleReadPositions();
  matchingTabs.forEach(tab => {
    const pageEl = $(tab.id);
    if (pageEl) pageEl.remove();
  });
  if (type === TAB_TYPES.RESEARCH_PROJECTS) {
    closingIds.forEach(tabId => researchStatesByTabId.delete(tabId));
  }
  tabState.tabs = tabState.tabs.filter(tab => !closingIds.has(tab.id));

  if (closingIds.has(tabState.activeTabId)) {
    const nextTab = tabState.tabs[tabState.tabs.length - 1];
    switchTab(nextTab?.id || 'main');
  } else {
    renderTabs();
  }

  saveTabsState();
  showToast(successMessage);
}

function closeAllTabsByTypes(types, successMessage) {
  const typeSet = new Set(types);
  const matchingTabs = tabState.tabs.filter(tab => typeSet.has(tab.type));
  if (!matchingTabs.length) return;

  const closingIds = new Set(matchingTabs.map(tab => tab.id));
  flushAllArticleReadPositions();
  matchingTabs.forEach(tab => $(tab.id)?.remove());
  tabState.tabs = tabState.tabs.filter(tab => !closingIds.has(tab.id));
  if (settingsReturnTabType && typeSet.has(settingsReturnTabType)) settingsReturnTabType = null;

  if (closingIds.has(tabState.activeTabId)) {
    const nextTab = tabState.tabs[tabState.tabs.length - 1];
    switchTab(nextTab?.id || 'main');
  } else {
    renderTabs();
  }

  saveTabsState();
  showToast(successMessage);
}

function closeAllCaseManagerTabs() {
  closeAllTabsByType(TAB_TYPES.CASE_MANAGER, '已关闭所有案件管理页面');
}

function closeAllResearchTabs() {
  closeAllTabsByType(TAB_TYPES.RESEARCH_PROJECTS, '已关闭所有案件研究页面');
}

function closeAllCaseFileTabs() {
  closeAllTabsByType(TAB_TYPES.CASE_FILES, '已关闭所有案件文件页面');
}

function closeAllSettingsTabs() {
  closeAllTabsByTypes(SETTINGS_TAB_TYPES, '已关闭所有设置页面');
}

function closeAllToolsTabs() {
  if (tabState.tabs.some(tab => tab.type === TAB_TYPES.AI_ASK)) detachAskPanelFromTab();
  closeAllTabsByTypes(TOOL_TAB_TYPES, '已关闭所有效率中心页面');
}

function closeAllKnowledgeCenterTabs() {
  closeAllTabsByTypes(KNOWLEDGE_CENTER_TAB_TYPES, '已关闭所有知识中心页面');
}

function closeAllArticleTabs() {
  closeAllTabsByType(TAB_TYPES.ARTICLE, '已关闭所有文章');
}

