async function openCaseResearchForCase(caseId, section = 'ledger') {
  const id = Number(caseId || 0);
  if (!id) return;
  const targetSection = ['memo', 'qa'].includes(section) ? section : 'ledger';
  // 台账和备忘录已迁入案件详情；从任意旧入口都直接打开对应案件的详情工作区。
  if (targetSection !== 'qa') {
    let caseTab = tabState.tabs.find(tab => tab.id === tabState.activeTabId && tab.type === TAB_TYPES.CASE_MANAGER)
      || tabState.tabs.find(tab => tab.type === TAB_TYPES.CASE_MANAGER);
    if (!caseTab) {
      openCaseManagerTab();
      caseTab = tabState.tabs.find(tab => tab.id === tabState.activeTabId && tab.type === TAB_TYPES.CASE_MANAGER);
    } else {
      switchTab(caseTab.id);
    }
    const frame = caseTab ? document.getElementById(caseTab.id)?.querySelector('iframe') : null;
    if (!frame) return;
    const openWorkspace = () => frame.contentWindow?.postMessage({ type: 'openCaseResearchWorkspace', caseId: id, section: targetSection }, location.origin);
    openWorkspace();
    frame.addEventListener('load', openWorkspace, { once: true });
    return;
  }
  const existingTab = tabState.tabs.find(tab =>
    tab.type === TAB_TYPES.RESEARCH_PROJECTS &&
    Number(tab.data?.caseId || 0) === id
  );
  if (!existingTab) {
    openTab(TAB_TYPES.RESEARCH_PROJECTS, '案件研究', {
      caseId: id,
      section: targetSection,
      contextLabel: '正在加载案件…'
    });
    return;
  }
  switchTab(existingTab.id);
  activateResearchStateForTab(existingTab.id);
  try {
    await loadCaseResearchDetail(id);
    renderResearchProjectsPage();
    focusCaseResearchSection(targetSection);
  } catch (e) {
    renderResearchProjectsError(e);
  }
}

