function openCourtOnlineService(recordId = 0, options = {}) {
  const targetRecordId = Number(recordId || 0);
  const kind = String(options.kind || '');
  const query = String(options.query || '').trim();
  const existing = tabState.tabs.find(tab => tab.type === TAB_TYPES.COURT_ONLINE);
  if (existing) {
    switchTab(existing.id);
    const frame = document.getElementById(existing.id)?.querySelector('iframe');
    const locate = () => frame?.contentWindow?.postMessage({ type: 'courtOnlineLocate', kind, query }, location.origin);
    if (kind) { locate(); frame?.addEventListener('load', locate, { once: true }); }
    const open = () => frame?.contentWindow?.postMessage({ type: 'openCourtRecord', recordId: targetRecordId }, location.origin);
    if (targetRecordId) { open(); frame?.addEventListener('load', open, { once: true }); }
    return;
  }
  openTab(TAB_TYPES.COURT_ONLINE, '一张网', { recordId: targetRecordId, courtKind: kind, courtQuery: query });
}

