function openCaseFilesTab(caseId, caseTitle = '案件', returnTabId = '') {
  const id = Number(caseId || 0);
  if (!id) return showToast('无法识别案件信息', 'error');
  const existing = tabState.tabs.find(tab => tab.type === TAB_TYPES.CASE_FILES && Number(tab.data?.caseId || 0) === id);
  if (existing) {
    existing.data = { ...(existing.data || {}), caseId: id, caseTitle, returnTabId: returnTabId || existing.data?.returnTabId || '' };
    existing.title = `${caseTitle} · 案件文件`;
    switchTab(existing.id);
    saveTabsState();
    return;
  }
  openTab(TAB_TYPES.CASE_FILES, `${caseTitle} · 案件文件`, { caseId: id, caseTitle, returnTabId });
}

function openPrepaidExpenseEntryShortcut() {
  openCaseManagerTab();
  const activeTab = tabState.tabs.find(tab => tab.id === tabState.activeTabId);
  const frame = activeTab?.type === TAB_TYPES.CASE_MANAGER
    ? document.getElementById(activeTab.id)?.querySelector('iframe')
    : null;
  if (!frame) return false;
  const openEditor = () => {
    try {
      const child = frame.contentWindow;
      if (typeof child?.switchTab !== 'function' || typeof child?.openPrepaidEditor !== 'function') return false;
      child.switchTab('prepaidExpenses');
      child.openPrepaidEditor();
      return true;
    } catch (_) {
      return false;
    }
  };
  if (!openEditor()) frame.addEventListener('load', openEditor, { once: true });
  return true;
}

