let legalAssistantToolOrder = [];
let legalAssistantToolGroups = {};
let legalAssistantToolSubtitles = {};
let legalAssistantToolsEditing = false;
let legalAssistantToolsBeforeEdit = null;
let legalAssistantDraggedToolId = '';

function normalizedLegalAssistantToolOrder(order) {
  const knownIds = new Set(LEGAL_ASSISTANT_TOOLS.map(tool => tool.id));
  const normalized = [];
  (Array.isArray(order) ? order : []).forEach(id => {
    if (typeof id === 'string' && knownIds.has(id) && !normalized.includes(id)) normalized.push(id);
  });
  LEGAL_ASSISTANT_TOOLS.forEach(tool => {
    if (!normalized.includes(tool.id)) normalized.push(tool.id);
  });
  return normalized;
}

function orderedLegalAssistantTools() {
  const order = normalizedLegalAssistantToolOrder(legalAssistantToolOrder);
  const positions = new Map(order.map((id, index) => [id, index]));
  return [...LEGAL_ASSISTANT_TOOLS].sort((left, right) => positions.get(left.id) - positions.get(right.id));
}

function legalAssistantToolGroup(tool) {
  return legalAssistantToolGroups[tool.id] || tool.group;
}

function legalAssistantToolSubtitle(tool) {
  return Object.prototype.hasOwnProperty.call(legalAssistantToolSubtitles, tool.id)
    ? legalAssistantToolSubtitles[tool.id] : (tool.desc || '');
}

function normalizedLegalAssistantToolCustomizations(data) {
  const knownIds = new Set(LEGAL_ASSISTANT_TOOLS.map(tool => tool.id));
  const groupIds = new Set(LEGAL_ASSISTANT_GROUPS.map(group => group.id));
  const groups = {};
  const subtitles = {};
  Object.entries(data?.groups || {}).forEach(([id, group]) => {
    if (knownIds.has(id) && groupIds.has(group)) groups[id] = group;
  });
  Object.entries(data?.subtitles || {}).forEach(([id, subtitle]) => {
    if (knownIds.has(id) && typeof subtitle === 'string') subtitles[id] = subtitle.slice(0, 80);
  });
  return { groups, subtitles };
}

async function loadLegalAssistantToolOrder() {
  try {
    const response = await fetch('/api/preferences/legal-assistant-tool-order');
    if (!response.ok) throw new Error('加载失败');
    const data = await response.json();
    legalAssistantToolOrder = normalizedLegalAssistantToolOrder(data.order);
    ({ groups: legalAssistantToolGroups, subtitles: legalAssistantToolSubtitles } = normalizedLegalAssistantToolCustomizations(data));
    renderLegalAssistantTools();
  } catch (_) {
    legalAssistantToolOrder = normalizedLegalAssistantToolOrder(legalAssistantToolOrder);
  }
}

function renderLegalAssistantToolsEditActions() {
  const host = $('tools-popup-edit-actions');
  if (!host) return;
  host.innerHTML = legalAssistantToolsEditing ? `
    <button class="tools-popup-edit-text-btn" type="button" onclick="cancelLegalAssistantToolsEdit(event)">取消</button>
    <button class="tools-popup-edit-save-btn" type="button" onclick="saveLegalAssistantToolsOrder(event)">保存</button>
  ` : `
    <button class="tools-popup-edit-btn" type="button" aria-label="编辑效率中心入口" title="编辑入口" onclick="toggleLegalAssistantToolsEdit(event)">
      <svg width="16" height="16" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M4.2 14.9l.7-3.1L13.7 3a1.6 1.6 0 012.3 2.3l-8.8 8.8-3 .8z" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/><path d="M12.5 4.3l3.2 3.2" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
    </button>
  `;
}

function toggleLegalAssistantToolsEdit(event) {
  event?.preventDefault();
  event?.stopPropagation();
  legalAssistantToolOrder = normalizedLegalAssistantToolOrder(legalAssistantToolOrder);
  legalAssistantToolsBeforeEdit = {
    order: [...legalAssistantToolOrder],
    groups: { ...legalAssistantToolGroups },
    subtitles: { ...legalAssistantToolSubtitles },
  };
  legalAssistantToolsEditing = true;
  renderLegalAssistantTools();
  window.openToolsMenu?.();
}

function cancelLegalAssistantToolsEdit(event) {
  event?.preventDefault();
  event?.stopPropagation();
  legalAssistantToolOrder = [...legalAssistantToolsBeforeEdit.order];
  legalAssistantToolGroups = { ...legalAssistantToolsBeforeEdit.groups };
  legalAssistantToolSubtitles = { ...legalAssistantToolsBeforeEdit.subtitles };
  legalAssistantToolsEditing = false;
  legalAssistantDraggedToolId = '';
  renderLegalAssistantTools();
}

async function saveLegalAssistantToolsOrder(event) {
  event?.preventDefault();
  event?.stopPropagation();
  const button = event?.currentTarget;
  if (button) { button.disabled = true; button.textContent = '保存中'; }
  try {
    const order = normalizedLegalAssistantToolOrder(legalAssistantToolOrder);
    const groups = { ...legalAssistantToolGroups };
    const subtitles = { ...legalAssistantToolSubtitles };
    const response = await fetch('/api/preferences/legal-assistant-tool-order', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ order, groups, subtitles }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.detail || '保存失败');
    legalAssistantToolOrder = normalizedLegalAssistantToolOrder(data.order);
    ({ groups: legalAssistantToolGroups, subtitles: legalAssistantToolSubtitles } = normalizedLegalAssistantToolCustomizations(data));
    legalAssistantToolsEditing = false;
    legalAssistantDraggedToolId = '';
    renderLegalAssistantTools();
    showToast('效率中心设置已保存', 'success');
  } catch (error) {
    if (button) { button.disabled = false; button.textContent = '保存'; }
    showToast(error.message || '保存效率中心设置失败', 'error');
  }
}

function beginLegalAssistantToolDrag(event, toolId) {
  if (!legalAssistantToolsEditing) return;
  legalAssistantDraggedToolId = toolId;
  event.dataTransfer.effectAllowed = 'move';
  event.dataTransfer.setData('text/plain', toolId);
  event.currentTarget.closest('.tools-popup-item')?.classList.add('is-dragging');
}

function updateLegalAssistantToolSubtitle(event, toolId) {
  if (!legalAssistantToolsEditing) return;
  const tool = getLegalAssistantTool(toolId);
  if (!tool) return;
  const subtitle = event.currentTarget.value;
  if (subtitle === tool.desc) delete legalAssistantToolSubtitles[toolId];
  else legalAssistantToolSubtitles[toolId] = subtitle;
}

function moveLegalAssistantToolWithKeyboard(event, toolId) {
  if (!legalAssistantToolsEditing || !['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.key)) return;
  event.preventDefault();
  const tool = getLegalAssistantTool(toolId);
  if (!tool) return;
  const order = normalizedLegalAssistantToolOrder(legalAssistantToolOrder);
  const groupId = legalAssistantToolGroup(tool);
  const groupTools = order.filter(id => legalAssistantToolGroup(getLegalAssistantTool(id)) === groupId);
  const groupIndex = LEGAL_ASSISTANT_GROUPS.findIndex(group => group.id === groupId);
  let targetId;
  let destinationGroup = groupId;
  if (event.key === 'ArrowUp') targetId = groupTools[groupTools.indexOf(toolId) - 1];
  if (event.key === 'ArrowDown') targetId = groupTools[groupTools.indexOf(toolId) + 1];
  if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
    destinationGroup = LEGAL_ASSISTANT_GROUPS[groupIndex + (event.key === 'ArrowLeft' ? -1 : 1)]?.id;
    if (!destinationGroup) return;
    targetId = order.find(id => legalAssistantToolGroup(getLegalAssistantTool(id)) === destinationGroup);
  }
  if (!targetId && destinationGroup === groupId) return;
  order.splice(order.indexOf(toolId), 1);
  order.splice(targetId ? order.indexOf(targetId) + (event.key === 'ArrowDown' ? 1 : 0) : order.length, 0, toolId);
  legalAssistantToolOrder = order;
  if (destinationGroup === tool.group) delete legalAssistantToolGroups[toolId];
  else legalAssistantToolGroups[toolId] = destinationGroup;
  renderLegalAssistantTools();
  document.querySelector(`.tools-popup-item[data-tool-id="${CSS.escape(toolId)}"] .tools-popup-drag-handle`)?.focus();
}

function overLegalAssistantToolDrag(event, toolId) {
  if (!legalAssistantToolsEditing || !legalAssistantDraggedToolId || legalAssistantDraggedToolId === toolId) return;
  event.preventDefault();
  event.dataTransfer.dropEffect = 'move';
  event.currentTarget.closest('.tools-popup-item')?.classList.add('is-drag-over');
}

function leaveLegalAssistantToolDrag(event) {
  event.currentTarget.closest('.tools-popup-item')?.classList.remove('is-drag-over');
}

function endLegalAssistantToolDrag() {
  legalAssistantDraggedToolId = '';
  document.querySelectorAll('.tools-popup-item.is-dragging, .tools-popup-item.is-drag-over').forEach(item => item.classList.remove('is-dragging', 'is-drag-over'));
}

function dropLegalAssistantTool(event, targetId) {
  event.preventDefault();
  const sourceId = legalAssistantDraggedToolId || event.dataTransfer.getData('text/plain');
  const source = getLegalAssistantTool(sourceId);
  const target = getLegalAssistantTool(targetId);
  endLegalAssistantToolDrag();
  if (!legalAssistantToolsEditing || !source || !target || source.id === target.id) return;
  const order = normalizedLegalAssistantToolOrder(legalAssistantToolOrder);
  const targetGroup = legalAssistantToolGroup(target);
  const targetEl = event.currentTarget.closest('.tools-popup-item');
  const placeAfter = event.clientY > targetEl.getBoundingClientRect().top + targetEl.getBoundingClientRect().height / 2;
  order.splice(order.indexOf(source.id), 1);
  order.splice(order.indexOf(target.id) + (placeAfter ? 1 : 0), 0, source.id);
  legalAssistantToolOrder = order;
  if (targetGroup === source.group) delete legalAssistantToolGroups[source.id];
  else legalAssistantToolGroups[source.id] = targetGroup;
  renderLegalAssistantTools();
}

function dropLegalAssistantToolInGroup(event, groupId) {
  if (event.target.closest('.tools-popup-item')) return;
  event.preventDefault();
  const sourceId = legalAssistantDraggedToolId || event.dataTransfer.getData('text/plain');
  const source = getLegalAssistantTool(sourceId);
  endLegalAssistantToolDrag();
  if (!legalAssistantToolsEditing || !source || !LEGAL_ASSISTANT_GROUPS.some(group => group.id === groupId)) return;
  const order = normalizedLegalAssistantToolOrder(legalAssistantToolOrder);
  order.splice(order.indexOf(sourceId), 1);
  const groupIds = order.filter(id => legalAssistantToolGroup(getLegalAssistantTool(id)) === groupId);
  const lastId = groupIds[groupIds.length - 1];
  order.splice(lastId ? order.indexOf(lastId) + 1 : order.length, 0, sourceId);
  legalAssistantToolOrder = order;
  if (groupId === source.group) delete legalAssistantToolGroups[source.id];
  else legalAssistantToolGroups[source.id] = groupId;
  renderLegalAssistantTools();
}

function getLegalAssistantTool(toolId) {
  return LEGAL_ASSISTANT_TOOLS.find(tool => tool.id === toolId);
}

function openRegisteredLegalTool(toolId, closeMenu = false) {
  const tool = getLegalAssistantTool(toolId);
  if (!tool || typeof tool.action !== 'function') return;
  const launchTool = () => {
    tool.action();
    if (window.innerWidth <= 768 && document.body.classList.contains('mobile-sidebar-open')) {
      closeMobileSidebar();
    }
  };
  if (!closeMenu) {
    launchTool();
    return;
  }
  // 先使同体菜单进入收缩态，再打开目标页面，避免加载期间留下空白面板。
  window.closeToolsMenu?.();
  window.requestAnimationFrame(launchTool);
}

function installHorizontalGestureLock(el) {
  if (!el || el.dataset.horizontalGestureLockReady === '1') return;
  el.dataset.horizontalGestureLockReady = '1';
  let startX = 0;
  let startY = 0;
  let startLeft = 0;
  let axis = '';
  const threshold = 7;

  el.addEventListener('touchstart', event => {
    if (event.touches.length !== 1) return;
    const touch = event.touches[0];
    startX = touch.clientX;
    startY = touch.clientY;
    startLeft = el.scrollLeft;
    axis = '';
  }, { passive: true });

  el.addEventListener('touchmove', event => {
    if (event.touches.length !== 1) return;
    const touch = event.touches[0];
    const dx = touch.clientX - startX;
    const dy = touch.clientY - startY;
    const ax = Math.abs(dx);
    const ay = Math.abs(dy);
    if (!axis && Math.max(ax, ay) >= threshold) {
      axis = ax > ay ? 'x' : 'y';
    }
    if (axis !== 'x') return;
    event.preventDefault();
    el.scrollLeft = startLeft - dx;
  }, { passive: false });

  el.addEventListener('touchend', () => { axis = ''; }, { passive: true });
  el.addEventListener('touchcancel', () => { axis = ''; }, { passive: true });

  el.addEventListener('wheel', event => {
    if (el.scrollWidth <= el.clientWidth + 1) return;
    event.preventDefault();
    const dx = Math.abs(event.deltaX);
    const dy = Math.abs(event.deltaY);
    el.scrollLeft += event.shiftKey || dx >= dy ? event.deltaX : event.deltaY;
  }, { passive: false });
}

function renderLegalAssistantTools() {
  const visibleTools = orderedLegalAssistantTools().filter(tool => tool.id !== 'knowledge_expand');
  const popupHint = document.querySelector('.tools-popup-heading > small');
  if (popupHint) popupHint.textContent = legalAssistantToolsEditing
    ? '拖动按钮跨分类排序，点击副标题修改'
    : '案件、文书、AI、工具与邮件';
  const quickList = $('quick-tools-list');
  if (quickList) {
    const query = (($('quick-tool-search-input') && $('quick-tool-search-input').value) || '').trim().toLowerCase();
    const quickTools = visibleTools
      .filter(tool => tool.highFrequency !== false)
      .filter(tool => {
        if (!query) return true;
        return `${tool.title || ''} ${legalAssistantToolSubtitle(tool)}`.toLowerCase().includes(query);
      });
    quickList.innerHTML = quickTools.length ? quickTools.map(tool => `
      <button class="quick-tool-card" data-tool-id="${tool.id}" type="button" onclick="openRegisteredLegalTool('${tool.id}')" title="${escapeHtml(tool.title)}">
        <span class="quick-tool-icon">${tool.icon}</span>
        <span class="quick-tool-text">
          <strong>${escapeHtml(tool.title)}</strong>
          <small>${escapeHtml(legalAssistantToolSubtitle(tool))}</small>
        </span>
      </button>
    `).join('') : '<div class="quick-tool-empty">未找到工具</div>';
    installHorizontalGestureLock(quickList);
  }

  const popupList = $('tools-popup-list');
  if (popupList) {
    const groups = LEGAL_ASSISTANT_GROUPS.map(group => {
      const tools = visibleTools.filter(tool => legalAssistantToolGroup(tool) === group.id);
      return `
      <section class="tools-popup-group${legalAssistantToolsEditing ? ' is-editing' : ''}" data-tools-group="${group.id}" ${legalAssistantToolsEditing ? `ondragover="event.preventDefault()" ondrop="dropLegalAssistantToolInGroup(event, '${group.id}')"` : ''}>
        <div class="tools-popup-col-title">${escapeHtml(group.title)}</div>
        <div class="tools-popup-group-list">
          ${tools.map(tool => `
          <${legalAssistantToolsEditing ? 'div' : 'button'} class="tools-popup-item${legalAssistantToolsEditing ? ' is-editing' : ''}" data-tool-id="${tool.id}" ${legalAssistantToolsEditing ? `ondragover="overLegalAssistantToolDrag(event, '${tool.id}')" ondragleave="leaveLegalAssistantToolDrag(event)" ondrop="dropLegalAssistantTool(event, '${tool.id}')"` : `type="button" role="menuitem" onclick="openRegisteredLegalTool('${tool.id}', true)" title="${escapeHtml(legalAssistantToolSubtitle(tool) || tool.title)}"`}>
            ${legalAssistantToolsEditing ? `<span class="tools-popup-drag-handle" draggable="true" role="button" tabindex="0" aria-label="移动${escapeHtml(tool.title)}，方向键可调整位置与分类" onkeydown="moveLegalAssistantToolWithKeyboard(event, '${tool.id}')" ondragstart="beginLegalAssistantToolDrag(event, '${tool.id}')" ondragend="endLegalAssistantToolDrag()"><svg width="14" height="14" viewBox="0 0 16 16" fill="none"><circle cx="5" cy="4" r="1" fill="currentColor"/><circle cx="11" cy="4" r="1" fill="currentColor"/><circle cx="5" cy="8" r="1" fill="currentColor"/><circle cx="11" cy="8" r="1" fill="currentColor"/><circle cx="5" cy="12" r="1" fill="currentColor"/><circle cx="11" cy="12" r="1" fill="currentColor"/></svg></span>` : ''}
            <span class="tools-popup-item-icon">${tool.icon}</span>
            <span class="tools-popup-item-body">
              <strong>${escapeHtml(tool.title)}</strong>
              ${legalAssistantToolsEditing ? `<input class="tools-popup-subtitle-input" type="text" maxlength="80" aria-label="${escapeHtml(tool.title)}的副标题" placeholder="添加副标题" value="${escapeHtml(legalAssistantToolSubtitle(tool))}" oninput="updateLegalAssistantToolSubtitle(event, '${tool.id}')">` : `<small>${escapeHtml(legalAssistantToolSubtitle(tool))}</small>`}
            </span>
          </${legalAssistantToolsEditing ? 'div' : 'button'}>
          `).join('')}
        </div>
      </section>
      `;
    }).join('');
    popupList.innerHTML = `<div class="tools-popup-groups">${groups}</div>`;
    renderLegalAssistantToolsEditActions();
    window.positionToolsPopup?.();
  }
}

function toggleQuickToolSearch() {
  const wrap = $('quick-tool-search-wrap');
  const input = $('quick-tool-search-input');
  if (!wrap || !input) return;
  const open = !wrap.classList.contains('open');
  wrap.classList.toggle('open', open);
  if (open) {
    setTimeout(() => input.focus(), 0);
  } else if (input.value) {
    input.value = '';
    renderLegalAssistantTools();
  }
}

function clearQuickToolSearch() {
  const input = $('quick-tool-search-input');
  const wrap = $('quick-tool-search-wrap');
  if (!input) return;
  input.value = '';
  renderLegalAssistantTools();
  if (wrap) wrap.classList.remove('open');
}

function handleQuickToolSearchKeydown(event) {
  if (event.key === 'Escape') {
    event.preventDefault();
    clearQuickToolSearch();
  } else if (event.key === 'Enter') {
    const firstTool = document.querySelector('#quick-tools-list .quick-tool-card');
    if (firstTool) {
      event.preventDefault();
      firstTool.click();
    }
  }
}

function initMainPageWheelScroll() {
  const area = $('tab-content-area');
  if (!area || area.dataset.mainWheelScrollReady === '1') return;
  area.dataset.mainWheelScrollReady = '1';
  area.addEventListener('wheel', (e) => {
    const mainPage = $('tab-page-main');
    if (!mainPage || !mainPage.classList.contains('active')) return;
    if (document.querySelector('.modal-overlay.show, .modal.open, .ask-panel.open, .filter-drawer.show, .preview-drawer.show')) return;
    if (e.target && e.target.closest('input, textarea, select, .sidebar, .tab-iframe, .search-suggestions, .density-dropdown, .tools-popup')) return;

    const maxScroll = area.scrollHeight - area.clientHeight;
    if (maxScroll <= 0) return;
    const next = Math.max(0, Math.min(maxScroll, area.scrollTop + e.deltaY));
    if (next === area.scrollTop) return;
    e.preventDefault();
    area.scrollTop = next;
  }, { passive: false });
}

/* ─────────────────────────────────────────────
   储存管理
───────────────────────────────────────────── */
let storageDataCache = null;
let storageRequestGeneration = 0;
let storageListFilter = 'all';
let storageListSearch = '';
let articleOfflineBrowserCacheBytes = 0;

async function fetchStorageJson(url, options = {}) {
  const response = await fetch(url, {cache: 'no-store', ...options});
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(payload.detail || payload.message || '储存管理请求失败');
  }
  return payload;
}

async function measureArticleOfflineBrowserCacheBytes() {
  if (!('caches' in window)) return 0;
  try {
    const cache = await caches.open(ARTICLE_IMAGE_CACHE_NAME);
    const requests = await cache.keys();
    const sizes = await Promise.all(requests.map(async request => {
      const response = await cache.match(request);
      if (!response) return 0;
      const headerSize = Number(response.headers.get('content-length'));
      if (Number.isFinite(headerSize) && headerSize >= 0) return headerSize;
      try {
        return (await response.clone().arrayBuffer()).byteLength;
      } catch (e) {
        return 0;
      }
    }));
    return sizes.reduce((sum, size) => sum + size, 0);
  } catch (e) {
    return 0;
  }
}

function openStorageModal() {
  const overlay = document.getElementById('storage-modal-overlay');
  if (overlay) overlay.style.display = 'flex';
  const body = document.getElementById('storage-modal-body');
  if (body) body.innerHTML = '<div class="storage-loading"><span class="storage-spinner"></span><p>正在加载储存空间信息…</p></div>';
  const requestGeneration = ++storageRequestGeneration;
  fetchStorageJson('/api/storage-info')
    .then(data => {
      if (requestGeneration !== storageRequestGeneration || overlay?.style.display === 'none') return;
      storageDataCache = data;
      renderStorageInfo(data);
      measureArticleOfflineBrowserCacheBytes().then(bytes => {
        if (requestGeneration !== storageRequestGeneration || overlay?.style.display === 'none') return;
        articleOfflineBrowserCacheBytes = bytes;
        renderStorageInfo(data);
      });
    })
    .catch(error => {
      if (requestGeneration !== storageRequestGeneration) return;
      if (body) body.innerHTML = `<div class="storage-error">加载失败：${escapeHtml(error.message || '请稍后重试')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">重新加载</button></div>`;
    });
}

function closeStorageModal() {
  storageRequestGeneration += 1;
  const overlay = document.getElementById('storage-modal-overlay');
  if (overlay) overlay.style.display = 'none';
  if (settingsStorageReturnPending) {
    settingsStorageReturnPending = false;
    openSettingsModal('manage');
  }
}

function setStorageListFilter(filter) {
  storageListFilter = ['all', 'cleanable', 'optional', 'system'].includes(filter) ? filter : 'all';
  if (storageDataCache) renderStorageInfo(storageDataCache);
}

function filterStorageItems(value) {
  storageListSearch = String(value || '');
  if (storageDataCache) renderStorageInfo(storageDataCache);
  document.querySelector('#storage-modal-body .storage-search input')?.focus();
}

function refreshStorageAfterCleanup(message = '') {
  const overlay = document.getElementById('storage-modal-overlay');
  if (overlay && overlay.style.display !== 'none') {
    openStorageModal();
  } else if (message && typeof showToast === 'function') {
    showToast(message, 'success');
  }
}

function openOfflineCacheManager() {
  const overlay = document.getElementById('offline-cache-modal-overlay');
  if (!overlay) return;
  renderOfflineCacheManager();
  overlay.style.display = 'flex';
}

function closeOfflineCacheManager() {
  const overlay = document.getElementById('offline-cache-modal-overlay');
  if (overlay) overlay.style.display = 'none';
  if (settingsOfflineCacheReturnPending) {
    settingsOfflineCacheReturnPending = false;
    openSettingsModal('manage');
  }
}

function formatOfflineCacheTime(timestamp) {
  if (!timestamp) return '尚未完成缓存';
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return '时间未知';
  return date.toLocaleString('zh-CN', {
    month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false,
  });
}

function renderOfflineCacheManager(searchText = '') {
  const body = document.getElementById('offline-cache-modal-body');
  if (!body) return;
  const snapshot = articleOfflineSnapshot;
  const articles = Array.isArray(snapshot?.articles) ? snapshot.articles : [];
  const normalizedSearch = String(searchText || '').trim().toLowerCase();
  const visibleArticles = normalizedSearch
    ? articles.filter(article => `${article.title || ''} ${(article.tags || []).join(' ')} ${(article.domains || []).join(' ')}`.toLowerCase().includes(normalizedSearch))
    : articles;
  const contentBytes = articles.reduce((total, article) => total + articleOfflineContentByteLength(article?.content), 0);
  const syncedAt = offlineSnapshotSyncedAt(ARTICLE_OFFLINE_SYNCED_AT_KEY, snapshot);
  const excluded = Number(snapshot?.excluded_oversized || 0) + Number(snapshot?.client_excluded_oversized || 0);
  const online = serverConnectionOnline === true;
  const availability = articles.length
    ? '断开 Tailscale 后可继续阅读下列文章'
    : '尚未保存可离线阅读的文章；请先连接 Tailscale 并点击“立即更新”。';
  const articleRows = visibleArticles.length
    ? visibleArticles.map(article => {
      const labels = [...(Array.isArray(article.domains) ? article.domains : []), ...(Array.isArray(article.tags) ? article.tags : [])].slice(0, 3);
      return `<article class="offline-cache-article">
        <div class="offline-cache-article-copy">
          <strong>${escapeHtml(article.title || '未命名文章')}</strong>
          <span>${escapeHtml(article.summary || '已保存正文，可在离线状态阅读')}</span>
          ${labels.length ? `<div class="offline-cache-labels">${labels.map(label => `<em>${escapeHtml(label)}</em>`).join('')}</div>` : ''}
        </div>
        <time>${escapeHtml(formatOfflineCacheTime(article.created_at))}</time>
      </article>`;
    }).join('')
    : `<div class="offline-cache-empty">${articles.length ? '没有匹配的离线文章' : '当前没有可用的离线文章副本'}</div>`;
  body.innerHTML = `
    <section class="offline-cache-hero ${articles.length ? 'ready' : 'empty'}">
      <div class="offline-cache-status"><i></i>${online ? '已连接 Tailscale / Mac' : '当前未连接 Mac'}</div>
      <h3>${articles.length ? `已保存 ${articles.length} 篇离线文章` : '尚未建立文章离线缓存'}</h3>
      <p>${availability}</p>
      <div class="offline-cache-metrics">
        <span><b>${formatStorageBytes(contentBytes)}</b> 正文副本</span>
        <span><b>${formatOfflineCacheTime(syncedAt)}</b> 最近更新</span>
      </div>
      <div class="offline-cache-actions">
        <button class="btn primary" type="button" id="offline-cache-refresh-btn" onclick="refreshOfflineCacheNow()" ${online ? '' : 'disabled'}>${online ? '立即更新缓存' : '连接 Tailscale 后可更新'}</button>
        ${articles.length ? '<button class="btn" type="button" onclick="showArticleOfflineCacheCleanConfirm()">清理离线副本</button>' : ''}
      </div>
    </section>
    <section class="offline-cache-guide">
      <strong>离线可用范围</strong>
      <span>文章正文、标题、摘要、标签和已缓存图片；不包含搜索新文章、上传、编辑及需要连接 Mac 的功能。</span>
      ${excluded ? `<span>另有 ${excluded} 篇正文超过 800 KB，未写入手机离线缓存。</span>` : ''}
    </section>
    <section class="offline-cache-list-section">
      <div class="offline-cache-list-head">
        <div><h3>可离线阅读的文章</h3><span>${visibleArticles.length}${normalizedSearch ? ` / ${articles.length}` : ''} 篇</span></div>
        <label class="offline-cache-search"><span>⌕</span><input type="search" value="${escapeHtml(searchText)}" placeholder="筛选文章" oninput="filterOfflineCacheArticles(this.value)"></label>
      </div>
      <div class="offline-cache-list">${articleRows}</div>
    </section>`;
}

function filterOfflineCacheArticles(value) {
  renderOfflineCacheManager(value);
  document.querySelector('#offline-cache-modal-body .offline-cache-search input')?.focus();
}

async function refreshOfflineCacheNow() {
  const button = document.getElementById('offline-cache-refresh-btn');
  if (button) { button.disabled = true; button.textContent = '正在更新…'; }
  try {
    if (!(await isServerReachable(5000))) throw new Error('暂时无法连接 Mac，请确认 Tailscale 已连接');
    const updated = await syncArticleOfflineSnapshot(false);
    if (!updated) throw new Error('更新未完成，请稍后重试');
    renderOfflineCacheManager();
  } catch (error) {
    if (typeof showToast === 'function') showToast(error.message || '离线缓存更新失败', 'warning');
    renderOfflineCacheManager();
  }
}

function renderStorageInfo(data) {
  const body = document.getElementById('storage-modal-body');
  if (!body) return;

  // 文件类型说明
  const fileTypeNotes = {
    '后端代码': { desc: '服务器端程序代码（不含浏览器运行资料）', safe: true, note: '不可清理' },
    '浏览器运行缓存': { desc: '法院在线服务下载的 Chromium 页面、组件与模型缓存', safe: false, note: '清理前会关闭后台法院浏览器，不会退出登录' },
    '历史备份文件': { desc: '更新、迁移或维护前创建的历史回滚快照', safe: true, note: '可选择清理' },
    '前端界面': { desc: '知识库页面、工具页、样式、图标和离线静态资源', safe: true, note: '不可清理' },
    '上传文件': { desc: '文章关联的原始文件', safe: false, note: '清理后文章正文内容不受影响' },
    '文章配图': { desc: '文章插图与 PDF 逐页渲染图片（含可选中文字层），阅读页平铺展示直接引用', safe: true, note: '不可清理' },
    '临时文件': { desc: '文档渲染预览、导出测试等中间文件，不参与运行', safe: false, note: '可安全清理' },
    '测试代码': { desc: '后端功能自动化测试脚本', safe: true, note: '不可清理' },
    '桌面应用壳': { desc: 'macOS 原生应用壳与图标资源', safe: true, note: '不可清理' },
    '导出文件': { desc: '系列案件导出等业务导出产物', safe: true, note: '不可清理' },
    '本地桥接程序': { desc: '日历/通讯录桥接编译产物', safe: true, note: '不可清理' },
    '法答网数据': { desc: '法答网问答缓存数据', safe: true, note: '可重新爬取，建议保留' },
    '打包文件': { desc: '前端构建产物（可重新 build）', safe: false, note: '清理后可运行 build_mac.sh 重建' },
    'Logo 图片': { desc: '网站 Logo 图标文件', safe: true, note: '不可清理' },
    '主数据库': { desc: '当前运行中的 SQLite 数据库：文章正文、标签、笔记、索引和问答记录', safe: true, note: '不可清理' },
    '后端数据库': { desc: '后端数据库副本', safe: true, note: '不可清理' },
    '标签缓存库': { desc: '标签数据临时缓存', safe: true, note: '可安全清理，不影响文章数据' },
    '任务缓存库': { desc: '后台任务记录缓存', safe: true, note: '可安全清理' },
    '飞书配置': { desc: '飞书集成配置', safe: true, note: '不可清理' },
    '飞书监听': { desc: '飞书消息监听脚本', safe: true, note: '不可清理' },
    '飞书机器人': { desc: '飞书 Bot 程序', safe: true, note: '不可清理' },
    '无用缓存': { desc: 'Python 缓存、临时缓存、系统索引文件', safe: false, note: '可安全清理' },
    'Node 依赖': { desc: 'MCP/本地工具运行依赖', safe: true, note: '不可清理' },
    'Node 文档/示例/测试': { desc: 'node_modules 中不参与运行的测试、示例和文档目录', safe: true, note: '可选清理' },
    'Swift 编译缓存': { desc: 'calendar_bridge.swift 编译产生的模块缓存，可自动重建', safe: false, note: '可安全清理' },
    'MCP 服务': { desc: 'WorkBuddy 知识库连接服务', safe: true, note: '不可清理' },
    '运行日志': { desc: '服务日志和运行记录，可清空日志内容', safe: true, note: '可选清理' },
    '说明文档': { desc: '安装、部署、修复和使用说明文档', safe: true, note: '不可清理' },
    '维护脚本': { desc: '启动、重启、部署、修复和数据维护脚本', safe: true, note: '不可清理' },
    '本地配置': { desc: '访问密钥、AI 配置、启动项和打包配置', safe: true, note: '不可清理' },
    '包管理文件': { desc: 'Python/Node 依赖清单和锁定文件', safe: true, note: '不可清理' },
    '部署压缩包': { desc: '部署或迁移时生成的脚本归档，不参与运行', safe: true, note: '可选清理' },
    '旧数据库占位': { desc: '非当前运行库的旧数据库或空占位文件', safe: true, note: '可选清理' },
    '其它项目文件': { desc: '未归入上述类别的项目辅助文件', safe: true, note: '不可清理' },
  };

  // 后端返回的 kind 是唯一权威来源；这里仅保留旧版本后端的兼容映射。
  const cleanableTypes = {
    'dist': '打包文件',
    'uploads': '上传文件',
    'temp_files': '临时文件',
    'safe_cache': '无用缓存',
    'swift_cache': 'Swift 编译缓存',
    'browser_runtime_cache': '浏览器运行缓存',
    'pending_tasks.db': '任务缓存库'
  };
  const optionalTypes = new Set(['node_aux', 'project_archives', 'legacy_databases', 'runtime_logs', 'history_backups']);
  const actionableTypes = new Set([
    ...Object.keys(cleanableTypes), ...optionalTypes,
  ]);

  const itemDisplayKind = item => {
    if (optionalTypes.has(item.raw) || item.kind === 'optional') return 'optional';
    if (cleanableTypes[item.raw] || item.kind === 'cleanable') return 'cleanable';
    return 'system';
  };
  const normalizedQuery = storageListSearch.trim().toLowerCase();
  const matchesQuery = item => !normalizedQuery || [item.name, item.desc, item.raw]
    .some(value => String(value || '').toLowerCase().includes(normalizedQuery));
  const filteredItems = (data.items || []).filter(item => {
    const kind = itemDisplayKind(item);
    return (storageListFilter === 'all' || storageListFilter === kind) && matchesQuery(item);
  });

  // 分类：可直接清理 / 需确认 / 核心文件。不要把可回收的历史备份混入核心文件。
  const allCleanable = [];
  const allOptional = [];
  const cleanable = [];
  const optional = [];
  const systemFiles = [];
  (data.items || []).forEach(item => {
    const kind = itemDisplayKind(item);
    const normalizedItem = {...item, _storageKind: kind};
    if (kind === 'cleanable') {
      allCleanable.push(normalizedItem);
    } else if (kind === 'optional') {
      allOptional.push(normalizedItem);
    }
    if (!filteredItems.includes(item)) return;
    if (kind === 'cleanable') cleanable.push(normalizedItem);
    else if (kind === 'optional') optional.push(normalizedItem);
    else systemFiles.push(normalizedItem);
  });

  // 项目图标（按项目 raw 覆盖，未覆盖的按 可清理/可选/系统 回落）
  const ICON_DB = '<svg viewBox="0 0 24 24"><ellipse cx="12" cy="5.4" rx="7.2" ry="2.7"/><path d="M4.8 5.4v13.2c0 1.5 3.2 2.7 7.2 2.7s7.2-1.2 7.2-2.7V5.4"/><path d="M4.8 12c0 1.5 3.2 2.7 7.2 2.7s7.2-1.2 7.2-2.7"/></svg>';
  const ICON_TRASH = '<svg viewBox="0 0 24 24"><path d="M3 6.2h18"/><path d="M8.2 6.2V4.4A1.4 1.4 0 019.6 3h4.8a1.4 1.4 0 011.4 1.4v1.8"/><path d="M18.8 6.2l-.9 13.4a2 2 0 01-2 1.9H8.1a2 2 0 01-2-1.9L5.2 6.2"/><path d="M10 11.4v5.4M14 11.4v5.4"/></svg>';
  const ICON_CLOCK = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.6"/><path d="M12 7.4V12l3.2 2"/></svg>';
  const ICON_SHIELD = '<svg viewBox="0 0 24 24"><path d="M12 3l7.2 2.4v5c0 4.6-3 8.3-7 9.8-4-1.5-7-5.2-7-9.8V5.4L12 3z"/><path d="M9 12.6l2.1 2.1 3.9-3.9"/></svg>';
  const ICON_GLOBE = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.6"/><path d="M3.4 12h17.2"/><path d="M12 3.4c2.3 2.3 3.5 5.1 3.5 8.6s-1.2 6.3-3.5 8.6c-2.3-2.3-3.5-5.1-3.5-8.6s1.2-6.3 3.5-8.6z"/></svg>';
  const STORAGE_ICON_MAP = {
    'legal_kb.db': ICON_DB,
    'history_backups': ICON_DB,
    'browser_runtime_cache': ICON_GLOBE,
    'uploads': '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 16.2V8.6"/><path d="M8.8 11.6L12 8.4l3.2 3.2"/><path d="M7.5 16.6h9"/></svg>',
    'article_images': '<svg viewBox="0 0 24 24"><rect x="3" y="4.4" width="18" height="15.2" rx="2.2"/><circle cx="9" cy="9.8" r="1.9"/><path d="M4.6 17.2l4.8-4.9 3 3 2.6-2.6 4.4 4.5"/></svg>',
    'temp_files': '<svg viewBox="0 0 24 24"><path d="M4 5.4h16l-1 13.2a1.8 1.8 0 01-1.8 1.6H6.8a1.8 1.8 0 01-1.8-1.6L4 5.4z"/><path d="M8.8 9.2v6.4M12 9.2v6.4M15.2 9.2v6.4"/></svg>',
    'runtime_logs': '<svg viewBox="0 0 24 24"><path d="M6 2.8h8.4l4.8 4.8V21.2H6z"/><path d="M14.4 2.8v4.8h4.8"/><path d="M9 11.5h6M9 15h4"/></svg>',
    'frontend': '<svg viewBox="0 0 24 24"><rect x="3" y="4.2" width="18" height="15.6" rx="2.4"/><path d="M3 9.6h18"/><path d="M7.8 9.6V19.8"/></svg>',
    'dist': '<svg viewBox="0 0 24 24"><path d="M12 2.6l8.2 4.7v9.4L12 21.4l-8.2-4.7V7.3L12 2.6z"/><path d="M12 12l8.2-4.7M12 12v9.4M12 12L3.8 7.3"/></svg>',
    'mcp-server': '<svg viewBox="0 0 24 24"><rect x="4" y="3.8" width="16" height="7" rx="1.8"/><rect x="4" y="13.2" width="16" height="7" rx="1.8"/><path d="M7.2 7.3h.01M7.2 16.7h.01M10.5 7.3H18M10.5 16.7H18"/></svg>',
    'fada-wang': '<svg viewBox="0 0 24 24"><path d="M12 3.2l1.7 4 4 1.7-4 1.7-1.7 4-1.7-4-4-1.7 4-1.7 1.7-4z"/><path d="M18.6 14.6l.8 1.9 1.9.8-1.9.8-.8 1.9-.8-1.9-1.9-.8 1.9-.8.8-1.9z"/></svg>',
    'swift_cache': '<svg viewBox="0 0 24 24"><path d="M8.5 7.5L4 12l4.5 4.5M15.5 7.5L20 12l-4.5 4.5"/><path d="M13.5 5.5l-3 13"/></svg>',
    'pending_tasks.db': '<svg viewBox="0 0 24 24"><path d="M3.5 12.3V4.2a.9.9 0 01.9-.9h8.1c.9 0 .48.1.66.26l7.4 7.4c.6.6.6 1.6 0 2.2l-6.4 6.4c-.6.6-1.6.6-2.2 0l-7.4-7.4a.9.9 0 01-.26-.64z"/><circle cx="8.4" cy="8.4" r="1.4"/></svg>',
  };

  function storageIconFor(item, isCleanable, isOptional) {
    const custom = STORAGE_ICON_MAP[item.raw];
    if (custom) return custom;
    return isCleanable ? ICON_TRASH : isOptional ? ICON_CLOCK : ICON_SHIELD;
  }

  // 生成单个项目卡片
  function renderItemRow(item) {
    const barWidth = data.total > 0 ? Math.round((item.size / data.total) * 100) : 0;
    const itemKind = item._storageKind || itemDisplayKind(item);
    const isCleanable = itemKind === 'cleanable';
    const isOptional = itemKind === 'optional';
    const isActionable = actionableTypes.has(item.raw) || isCleanable || isOptional;
    const isInspectable = item.raw === 'legal_kb.db';
    const toneCls = isOptional ? 'st-optional' : isCleanable ? 'st-clean' : 'st-system';
    const noteInfo = fileTypeNotes[item.name] || { desc: item.desc || '', safe: !isCleanable, note: isCleanable ? '可安全清理' : '不可清理' };
    const tagText = isOptional ? '可选' : isCleanable ? '可清理' : '系统';
    const actionText = item.raw === 'uploads' || item.raw === 'runtime_logs' || item.raw === 'history_backups' ? '选择清理' : '清理';
    const iconSvg = storageIconFor(item, isCleanable, isOptional);

    return `
      <div class="storage-item ${toneCls}">
        <div class="storage-item-icon">${iconSvg}</div>
        <div class="storage-item-main">
          <div class="storage-item-line">
            <span class="storage-item-name">${escapeHtml(item.name)}</span>
            <span class="storage-tag">${tagText}</span>
          </div>
          <div class="storage-item-desc">${escapeHtml(item.desc || noteInfo.desc)}${item.count ? ` · ${item.count} 个文件` : ''}</div>
          <div class="storage-item-bar"><i style="width:${barWidth}%"></i></div>
        </div>
        <div class="storage-item-side">
          <span class="storage-item-size">${escapeHtml(item.size_fmt)}</span>
          ${isInspectable ? `
            <button class="storage-action-btn" onclick="showMainDatabaseDetailsModal()">
              <svg width="12" height="12" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9.2"/><path d="M12 15.8v-4.4M12 8.2h.01"/></svg>
              查看明细
            </button>
          ` : isActionable && item.size > 0 ? `
            <button class="storage-action-btn" onclick="showCleanConfirm('${item.raw}')">
              <svg width="12" height="12" viewBox="0 0 24 24"><path d="M3 6.2h18"/><path d="M8.2 6.2V4.4A1.4 1.4 0 019.6 3h4.8a1.4 1.4 0 011.4 1.4v1.8"/><path d="M18.8 6.2l-.9 13.4a2 2 0 01-2 1.9H8.1a2 2 0 01-2-1.9L5.2 6.2"/></svg>
              ${actionText}
            </button>
          ` : `<span class="storage-note-hint">${escapeHtml(noteInfo.note)}</span>`}
        </div>
      </div>`;
  }

  const cachedOfflineArticles = articleOfflineSnapshot?.articles || [];
  const offlineContentBytes = cachedOfflineArticles.reduce(
    (sum, article) => sum + articleOfflineContentByteLength(article?.content),
    0
  );
  const offlineStoredBytes = offlineContentBytes + (Number(articleOfflineBrowserCacheBytes) || 0);
  const offlineCacheSize = offlineStoredBytes > 0 ? `约 ${formatStorageBytes(offlineStoredBytes)}` : '未载入';
  const offlineExcluded = Number(articleOfflineSnapshot?.excluded_oversized || 0)
    + Number(articleOfflineSnapshot?.client_excluded_oversized || 0);
  const offlineVisible = storageListFilter === 'all' || storageListFilter === 'cleanable';
  const offlineMatches = !normalizedQuery || '文章离线缓存 浏览器副本'.includes(normalizedQuery);
  const offlineBarWidth = offlineStoredBytes > 0
    ? Math.min(100, Math.max(2, Math.round((offlineStoredBytes / Math.max((data.total || 0) + offlineStoredBytes, 1)) * 100)))
    : 0;
  const offlineCacheRow = `
    <div class="storage-item st-clean storage-offline-item">
      <div class="storage-item-icon">${ICON_GLOBE}</div>
      <div class="storage-item-main">
        <div class="storage-item-line">
          <span class="storage-item-name">文章离线缓存</span>
          <span class="storage-tag">可清理</span>
        </div>
        <div class="storage-item-desc">浏览器端副本 · ${cachedOfflineArticles.length} 篇 · 正文及图片缓存${offlineExcluded ? ` · 已排除 ${offlineExcluded} 篇超大文章` : ''}</div>
        <div class="storage-item-bar"><i style="width:${offlineBarWidth}%"></i></div>
      </div>
      <div class="storage-item-side">
        <span class="storage-item-size">${offlineCacheSize}</span>
        <button class="storage-action-btn" onclick="showArticleOfflineCacheCleanConfirm()" ${offlineStoredBytes > 0 ? '' : 'disabled'}>
          <svg width="12" height="12" viewBox="0 0 24 24"><path d="M3 6.2h18"/><path d="M8.2 6.2V4.4A1.4 1.4 0 019.6 3h4.8a1.4 1.4 0 011.4 1.4v1.8"/><path d="M18.8 6.2l-.9 13.4a2 2 0 01-2 1.9H8.1a2 2 0 01-2-1.9L5.2 6.2"/><path d="M10 11.4v5.4M14 11.4v5.4"/></svg>
          安全清理
        </button>
      </div>
    </div>`;
  const hasOfflineCache = offlineStoredBytes > 0 || cachedOfflineArticles.length > 0;
  const renderGroup = (title, hint, items) => items.length
    ? `<div class="storage-group-head"><span>${title}</span><small>${hint}</small></div>${items.map(item => renderItemRow(item)).join('')}`
    : '';
  const allRows = [
    offlineVisible && offlineMatches && hasOfflineCache ? offlineCacheRow : '',
    renderGroup('可直接清理', '不会影响文章正文和主数据库', cleanable),
    renderGroup('需确认释放', '删除前请查看用途和影响', optional),
    renderGroup('系统文件', '应用运行所需，不提供删除', systemFiles),
  ].join('') || '<div class="storage-empty-state">没有匹配的储存项目</div>';
  const listedTotal = Number.isFinite(data.listed_total)
    ? data.listed_total
    : (data.items || []).reduce((sum, item) => sum + (item.size || 0), 0);
  const listedTotalFmt = data.listed_total_fmt || formatStorageBytes(listedTotal);
  const unclassified = Number.isFinite(data.unclassified) ? data.unclassified : Math.max((data.total || 0) - listedTotal, 0);
  const unclassifiedFmt = data.unclassified_fmt || formatStorageBytes(unclassified);
  const reconcileOk = Math.abs((data.total || 0) - listedTotal) < 2;

  // 概览统计：把需要用户判断的历史备份单独展示，避免误认为都是核心文件。
  const cleanableTotal = allCleanable.reduce((sum, item) => sum + (item.size || 0), 0);
  const optionalTotal = allOptional.reduce((sum, item) => sum + (item.size || 0), 0);
  const cleanableFmt = formatStorageBytes(cleanableTotal);
  const optionalFmt = formatStorageBytes(optionalTotal);
  const coreTotal = Math.max(listedTotal - cleanableTotal - optionalTotal, 0);
  const coreFmt = formatStorageBytes(coreTotal);
  const cleanablePct = listedTotal > 0 ? Math.min(100, Math.round((cleanableTotal / listedTotal) * 100)) : 0;
  const optionalPct = listedTotal > 0 ? Math.min(100, Math.round((optionalTotal / listedTotal) * 100)) : 0;
  const corePct = Math.max(0, 100 - cleanablePct - optionalPct);
  const itemCount = (data.items || []).length;
  const visibleItemCount = itemCount + (offlineVisible && offlineMatches && hasOfflineCache ? 1 : 0);
  const tabCounts = (kind) => (data.items || []).filter(item => itemDisplayKind(item) === kind).length;
  const backupItem = allOptional.find(item => item.raw === 'history_backups');
  const recommendation = backupItem && backupItem.size > 0 ? `
    <div class="storage-recommendation">
      <div class="storage-recommendation-icon">!</div>
      <div class="storage-recommendation-copy">
        <strong>发现 ${backupItem.count || 0} 个历史备份文件，可释放 ${escapeHtml(backupItem.size_fmt)}</strong>
        <span>备份只用于回滚，不参与当前知识库运行。确认近期不需要恢复到更新前状态后，可手动选择删除。</span>
      </div>
      <button class="storage-recommendation-btn" onclick="showHistoryBackupsModal()">查看备份</button>
    </div>` : '';

  body.innerHTML = `
    <div class="storage-hero">
      <div class="storage-hero-main">
        <span class="storage-hero-label">总占用空间</span>
        <div class="storage-hero-value">${escapeHtml(data.total_fmt)}</div>
        <div class="storage-hero-meta">${itemCount} 个本地项目 · 浏览器离线缓存另计 · 统计于 ${escapeHtml(data.generated_at)}</div>
        <span class="storage-hero-reconcile ${reconcileOk ? 'ok' : 'warn'}">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${reconcileOk ? '<path d="M20 6L9 17l-5-5"/>' : '<circle cx="12" cy="12" r="9"/><path d="M12 8v4M12 16h.01"/>'}</svg>
          分类合计 ${listedTotalFmt}${reconcileOk ? '，已与总占用对齐' : `，未分类 ${unclassifiedFmt}`}
        </span>
      </div>
      <div class="storage-hero-stats">
        <div class="storage-mini-stat clean">
          <span class="storage-mini-label"><i></i>可直接清理</span>
          <strong class="storage-mini-value">${cleanableFmt}</strong>
          <div class="storage-mini-bar"><i style="width:${cleanablePct}%"></i></div>
        </div>
        <div class="storage-mini-stat optional">
          <span class="storage-mini-label"><i></i>需确认释放</span>
          <strong class="storage-mini-value">${optionalFmt}</strong>
          <div class="storage-mini-bar"><i style="width:${optionalPct}%"></i></div>
        </div>
        <div class="storage-mini-stat core">
          <span class="storage-mini-label"><i></i>核心文件</span>
          <strong class="storage-mini-value">${coreFmt}</strong>
          <div class="storage-mini-bar"><i style="width:${corePct}%"></i></div>
        </div>
      </div>
    </div>

    ${recommendation}

    <div class="storage-legend">
      <span><i class="dot clean"></i>红色「可直接清理」不影响文章正文与数据库</span>
      <span><i class="dot optional"></i>黄色「需确认释放」删除前可查看用途和影响</span>
      <span><i class="dot system"></i>绿色「系统」为核心文件，请勿清理</span>
    </div>

    <div class="storage-toolbar">
      <div class="storage-tabs" role="tablist" aria-label="储存项目筛选">
        <button type="button" class="storage-tab ${storageListFilter === 'all' ? 'active' : ''}" onclick="setStorageListFilter('all')">全部 <b>${itemCount}</b></button>
        <button type="button" class="storage-tab ${storageListFilter === 'cleanable' ? 'active' : ''}" onclick="setStorageListFilter('cleanable')">可直接清理 <b>${tabCounts('cleanable')}</b></button>
        <button type="button" class="storage-tab ${storageListFilter === 'optional' ? 'active' : ''}" onclick="setStorageListFilter('optional')">需确认 <b>${tabCounts('optional')}</b></button>
        <button type="button" class="storage-tab ${storageListFilter === 'system' ? 'active' : ''}" onclick="setStorageListFilter('system')">系统文件 <b>${tabCounts('system')}</b></button>
      </div>
      <label class="storage-search"><span>⌕</span><input type="search" value="${escapeHtml(storageListSearch)}" placeholder="搜索项目" oninput="filterStorageItems(this.value)" aria-label="搜索储存项目"></label>
      <button type="button" class="storage-refresh-btn" onclick="openStorageModal()" aria-label="刷新储存统计">刷新</button>
    </div>

    <div class="storage-section-head">
      <h4>空间明细</h4>
      <span class="storage-section-count">${visibleItemCount} 项</span>
    </div>

    <div class="storage-list">
      ${allRows}
    </div>

    <div class="storage-footnote">本地总占用只统计应用目录和配置的数据目录；文章离线缓存保存在浏览器端，单独统计。</div>`;
}

function formatStorageBytes(b) {
  b = Number(b) || 0;
  if (b < 1024) return `${b} B`;
  if (b < 1024 ** 2) return `${(b / 1024).toFixed(1)} KB`;
  if (b < 1024 ** 3) return `${(b / 1024 ** 2).toFixed(1)} MB`;
  return `${(b / 1024 ** 3).toFixed(2)} GB`;
}

