async function clearArticleOfflineBrowserCache() {
  articleOfflineCacheGeneration += 1;
  const pendingImageCache = articleOfflineImageCachePromise;
  if (pendingImageCache) {
    await pendingImageCache.catch(() => {});
  }
  if ('indexedDB' in window) {
    const db = await openArticleOfflineDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(ARTICLE_OFFLINE_STORE, 'readwrite');
      tx.objectStore(ARTICLE_OFFLINE_STORE).clear();
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
      tx.onabort = () => { db.close(); reject(tx.error || new Error('离线缓存事务已取消')); };
    });
  }
  if ('caches' in window) {
    await caches.delete(ARTICLE_IMAGE_CACHE_NAME);
  }
  articleOfflineSnapshot = null;
  articleOfflineBrowserCacheBytes = 0;
  articleOfflineReady = false;
  articleOfflineMode = false;
  ARTICLE_OFFLINE_LEGACY_SYNCED_AT_KEYS.forEach(key => localStorage.removeItem(key));
  // 避免用户刚清理后后台立即重建；12 小时维护周期后按新规则自动恢复。
  localStorage.setItem(ARTICLE_OFFLINE_SYNCED_AT_KEY, String(Date.now()));
}

async function doClearArticleOfflineCache() {
  closeCleanConfirm();
  const body = document.getElementById('storage-modal-body');
  if (body) body.innerHTML = '<div class="storage-loading"><span class="storage-spinner"></span><p>正在安全清理文章离线缓存…</p></div>';
  try {
    await clearArticleOfflineBrowserCache();
    if (typeof showToast === 'function') showToast('文章离线缓存已安全清理，主数据库未改动');
    refreshStorageAfterCleanup('文章离线缓存已安全清理');
  } catch (error) {
    if (body) {
      body.innerHTML = `<div class="storage-error">清理失败：${escapeHtml(error.message || String(error))}</div>`;
    }
  }
}

// 清理确认弹窗（打包文件）
function showDistCleanConfirm(type) {
  const names = {
    'dist': '打包文件',
    'uploads': '上传文件',
    'temp_files': '临时文件',
    'safe_cache': '无用缓存',
    'swift_cache': 'Swift 编译缓存',
    'browser_runtime_cache': '浏览器运行缓存',
    'node_aux': 'Node 文档/示例/测试',
    'project_archives': '部署压缩包',
    'legacy_databases': '旧数据库占位',
    'pending_tasks.db': '任务缓存库',
    'runtime_logs': '运行日志',
    'history_backups': '历史备份文件'
  };
  const msg = type === 'dist'
    ? `清理后可重新运行 <code>build_mac.sh</code> 重新生成。`
    : type === 'temp_files'
      ? `仅删除 <code>.tmp</code> 目录中的渲染预览、导出测试等中间文件，保留数据库回滚快照，不影响文章、数据库和运行。`
      : type === 'safe_cache'
      ? `仅清理 Python 缓存、临时缓存和系统索引文件，不删除数据库、文章、上传文件或代码。`
        : type === 'swift_cache'
          ? `仅删除 Swift 编译缓存目录。该缓存由本地日历桥接组件编译时生成，需要时会自动重建。`
          : type === 'browser_runtime_cache'
            ? `清理前会先关闭后台法院浏览器，再删除其 Chromium 页面、组件与模型缓存。不会删除登录状态、Cookie、本地设置、已下载文书或案件数据；下次使用时部分缓存可能自动重新生成。`
        : type === 'node_aux'
          ? `仅删除 <code>node_modules</code> 中的测试、示例和文档目录，不删除 MCP 服务运行入口和依赖包主体。`
          : type === 'project_archives'
            ? `仅删除部署/迁移时生成的 <code>scripts.zip</code>，不影响知识库运行。`
            : type === 'legacy_databases'
              ? `仅删除非当前运行库的旧数据库占位/副本文件，不删除当前运行中的 <code>legal_kb.db</code> 和数据库备份。`
              : type === 'pending_tasks.db'
                ? `仅清理后台任务记录缓存，不影响文章正文、标签和主数据库。`
                : type === 'runtime_logs'
                  ? `仅清空 <code>*.log</code> 日志内容，不删除数据库、文章、上传文件或程序代码。`
                : type === 'history_backups'
                    ? `仅删除可选择的历史回滚快照，不删除当前运行中的 <code>legal_kb.db</code>、文章或上传文件。`
                    : ``;

  const overlay = document.createElement('div');
  overlay.className = 'confirm-modal-overlay';
  overlay.id = 'clean-confirm-overlay';
  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:16px;padding:28px;max-width:360px;width:90%;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.3)">
      <div style="width:56px;height:56px;margin:0 auto 16px;border-radius:50%;background:rgba(192,57,43,.1);display:flex;align-items:center;justify-content:center">
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#c0392b" stroke-width="2"><path d="M3 6h18M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2"/></svg>
      </div>
      <div style="font-size:17px;font-weight:600;margin-bottom:10px;color:var(--text)">确认清理${names[type]}</div>
      <div style="font-size:13px;color:var(--text-muted);line-height:1.6;margin-bottom:24px">
        确定要清理"${names[type]}"吗？${msg}
      </div>
      <div style="display:flex;gap:10px;justify-content:center">
        <button onclick="closeCleanConfirm()" style="flex:1;padding:11px 20px;border-radius:8px;border:1px solid var(--border);background:transparent;color:var(--text);cursor:pointer;font-size:13px;font-weight:500">取消</button>
        <button onclick="doClean('${type}')" style="flex:1;padding:11px 20px;border-radius:8px;border:none;background:#c0392b;color:white;cursor:pointer;font-size:13px;font-weight:600">确认</button>
      </div>
    </div>`;
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;z-index:10000;animation:fadeIn .2s';
  document.body.appendChild(overlay);
}

function closeCleanConfirm() {
  const overlay = document.getElementById('clean-confirm-overlay');
  if (overlay) overlay.remove();
}

async function doClean(type) {
  closeCleanConfirm();
  const body = document.getElementById('storage-modal-body');
  if (body) body.innerHTML = `
    <div class="storage-loading">
      <span class="storage-spinner"></span>
      <p>正在清理…</p>
    </div>`;

  try {
    const result = await fetchStorageJson('/api/storage/cleanup', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({type: type})
    });
    if (result.ok) {
      if (typeof showToast === 'function') showToast(result.message || '清理完成', 'success');
      refreshStorageAfterCleanup(result.message || '清理完成');
    } else {
      if (body) body.innerHTML = `<div class="storage-error">${escapeHtml(result.message || '清理失败')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
    }
  } catch (e) {
    if (body) body.innerHTML = `<div class="storage-error">清理失败：${escapeHtml(e.message || '请稍后重试')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
  }
}

