function renderHistoryBackupsModal(files, data = {}) {
  const overlay = document.createElement('div');
  overlay.className = 'upload-files-overlay';
  overlay.id = 'history-backups-overlay';

  const fileRows = files.map((f, index) => {
    const newestHint = index === 0 ? '<span style="font-size:12px;font-weight:700;color:#166534;background:rgba(34,197,94,.12);padding:2px 7px;border-radius:999px">最新</span>' : '';
    return `
      <div class="db-backup-item" data-path="${escapeHtml(f.path)}" style="display:grid;grid-template-columns:24px minmax(0,1fr) auto;gap:12px;padding:14px 16px;border-radius:10px;border:1px solid var(--border);margin-bottom:10px;background:rgba(248,250,252,.72)">
        <input type="checkbox" class="db-backup-checkbox" data-path="${escapeHtml(f.path)}" data-size="${Number(f.size) || 0}" style="width:18px;height:18px;cursor:pointer;accent-color:#8b1a1a;margin-top:3px">
        <div style="min-width:0">
          <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:5px">
            <span style="font-size:14px;font-weight:800;color:var(--text);font-family:ui-monospace,SFMono-Regular,Menlo,monospace">${escapeHtml(f.name)}</span>
            ${newestHint}
            ${f.backup_kind ? `<span style="font-size:11px;font-weight:700;color:#92400e;background:rgba(245,158,11,.12);padding:2px 7px;border-radius:999px">${escapeHtml(f.backup_kind)}</span>` : ''}
          </div>
          <div style="font-size:13px;line-height:1.55;color:var(--text-muted);margin-bottom:4px">
            <strong style="color:var(--text)">备份时间：</strong>${escapeHtml(f.modified_at || '')}
            ${f.article_count !== null && f.article_count !== undefined ? ` · <strong style="color:var(--text)">文章：</strong>${f.article_count} 篇` : ''}
            · <strong style="color:var(--text)">完整性：</strong>${escapeHtml(f.integrity || '未检查')}
          </div>
          <div style="font-size:13px;line-height:1.55;color:var(--text-muted)">
            ${f.backup_reason ? `<strong style="color:var(--text)">来源：</strong>${escapeHtml(f.backup_reason)}<br>` : ''}
            <strong style="color:var(--text)">清理影响：</strong>${escapeHtml(f.cleanup_note || '删除后不影响当前知识库运行，但会少一个回滚快照。')}
          </div>
        </div>
        <span style="font-size:13px;color:var(--text-muted);font-weight:800;white-space:nowrap">${escapeHtml(f.size_fmt || '')}</span>
      </div>`;
  }).join('');

  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:16px;max-width:820px;width:96%;max-height:86vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.35)">
      <div style="padding:20px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:16px">
        <div>
          <div style="font-size:16px;font-weight:800;color:var(--text)">选择要删除的历史备份文件</div>
          <div style="font-size:12px;color:var(--text-muted);margin-top:4px">只删除历史快照；当前运行库 legal_kb.db、文章正文、上传文件和页面功能都不会被删除。</div>
        </div>
        <button onclick="closeHistoryBackupsModal()" style="background:none;border:none;cursor:pointer;color:var(--text-muted);font-size:20px;width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center">✕</button>
      </div>
      <div style="padding:14px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap">
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;color:var(--text)">
          <input type="checkbox" id="selectAllDbBackups" onchange="toggleSelectAllDbBackups()" style="width:18px;height:18px;cursor:pointer;accent-color:#8b1a1a">
          <span style="font-weight:700">全选备份</span>
        </label>
        <span id="selectedDbBackupCount" style="font-size:13px;color:var(--text-muted)">已选 0 个备份</span>
      </div>
      <div style="padding:12px 24px;background:rgba(183,121,31,.08);border-bottom:1px solid var(--border);font-size:13px;color:#92400e;line-height:1.6">
        当前历史备份合计 ${escapeHtml(data.total_size_fmt || '0 B')}。建议至少保留最新一个备份，除非你确定近期不需要回滚。
      </div>
      <div style="flex:1;overflow-y:auto;padding:16px 20px;min-height:220px;max-height:460px">
        ${files.length > 0 ? fileRows : '<div style="padding:40px;text-align:center;color:var(--text-muted);font-size:14px">暂无历史备份文件</div>'}
      </div>
      <div style="padding:16px 24px;border-top:1px solid var(--border);display:flex;gap:12px">
        <button id="cleanSelectedDbBackupsBtn" onclick="cleanSelectedHistoryBackups()" style="flex:1;padding:12px 20px;border-radius:10px;border:none;background:#8b1a1a;color:white;cursor:pointer;font-size:14px;font-weight:800;transition:opacity .2s">删除所选备份</button>
        <button onclick="closeHistoryBackupsModal()" style="flex:1;padding:12px 20px;border-radius:10px;border:1px solid var(--border);background:transparent;color:var(--text);cursor:pointer;font-size:14px;font-weight:700">取消</button>
      </div>
    </div>`;

  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.74);display:flex;align-items:center;justify-content:center;z-index:10000;animation:fadeIn .2s';
  document.body.appendChild(overlay);

  document.querySelectorAll('.db-backup-checkbox').forEach(cb => {
    cb.addEventListener('change', updateSelectedDbBackupCount);
  });
  updateSelectedDbBackupCount();
}

function closeHistoryBackupsModal() {
  const overlay = document.getElementById('history-backups-overlay');
  if (overlay) overlay.remove();
}

function toggleSelectAllDbBackups() {
  const checked = document.getElementById('selectAllDbBackups').checked;
  document.querySelectorAll('.db-backup-checkbox').forEach(cb => cb.checked = checked);
  updateSelectedDbBackupCount();
}

function updateSelectedDbBackupCount() {
  const selected = Array.from(document.querySelectorAll('.db-backup-checkbox:checked'));
  const checked = selected.length;
  const total = document.querySelectorAll('.db-backup-checkbox').length;
  const selectedBytes = selected.reduce((sum, checkbox) => sum + (Number(checkbox.dataset.size) || 0), 0);
  const label = document.getElementById('selectedDbBackupCount');
  if (label) label.textContent = checked > 0
    ? `已选 ${checked} / ${total} 个 · 可释放 ${formatStorageBytes(selectedBytes)}`
    : `已选 0 / ${total} 个备份`;
  const btn = document.getElementById('cleanSelectedDbBackupsBtn');
  if (btn) {
    btn.textContent = checked > 0 ? `删除所选备份 · 释放 ${formatStorageBytes(selectedBytes)}` : '删除所选备份';
    btn.style.opacity = checked > 0 ? '1' : '0.5';
  }
}

async function cleanSelectedHistoryBackups() {
  const selected = Array.from(document.querySelectorAll('.db-backup-checkbox:checked'));
  const paths = selected.map(cb => cb.dataset.path);
  const selectedBytes = selected.reduce((sum, checkbox) => sum + (Number(checkbox.dataset.size) || 0), 0);
  if (paths.length === 0) return alert('请先选择要删除的历史备份文件');
  if (!confirm(`确定要删除选中的 ${paths.length} 个历史备份文件并释放约 ${formatStorageBytes(selectedBytes)} 吗？这不会影响当前知识库运行，但会失去对应回滚快照。`)) return;

  closeHistoryBackupsModal();
  const body = document.getElementById('storage-modal-body');
  if (body) body.innerHTML = `
    <div style="padding:60px 24px;text-align:center">
      <div style="width:48px;height:48px;margin:0 auto 16px;border-radius:50%;border:3px solid var(--border);border-top-color:#8b1a1a;animation:spin .8s linear infinite"></div>
      <div style="font-size:14px;color:var(--text-muted)">正在删除历史备份文件…</div>
    </div>
    <style>@keyframes spin{to{transform:rotate(360deg)}}</style>`;

  try {
    const result = await fetchStorageJson('/api/storage/cleanup', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({type: 'history_backup_files', paths})
    });
    if (result.ok) {
      if (typeof showToast === 'function') showToast(result.message || '历史备份已删除', 'success');
      refreshStorageAfterCleanup(result.message || '历史备份已删除');
    } else if (body) {
      body.innerHTML = `<div class="storage-error">${escapeHtml(result.message || '删除失败')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
    }
  } catch (e) {
    if (body) body.innerHTML = `<div class="storage-error">删除失败：${escapeHtml(e.message || '请稍后重试')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
  }
}

// 上传文件选择弹窗
let uploadFilesCache = [];

function showUploadFilesModal() {
  closeUploadFilesModal();
  const overlay = document.createElement('div');
  overlay.className = 'upload-files-overlay';
  overlay.id = 'upload-files-overlay';
  overlay.innerHTML = `<div class="storage-submodal storage-submodal-loading"><span class="storage-spinner"></span><strong>正在读取上传文件</strong><span>会同时检查文章关联，避免误删仍在使用的原件。</span></div>`;
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;z-index:10000;animation:fadeIn .2s';
  document.body.appendChild(overlay);
  fetchStorageJson('/api/storage/uploads')
    .then(data => {
      uploadFilesCache = data.files || [];
      renderUploadFilesModal(uploadFilesCache);
    })
    .catch(error => {
      const current = document.getElementById('upload-files-overlay');
      if (current) current.innerHTML = `<div class="storage-submodal storage-submodal-error"><strong>上传文件读取失败</strong><span>${escapeHtml(error.message || '请稍后重试')}</span><div><button type="button" class="btn" onclick="closeUploadFilesModal()">关闭</button><button type="button" class="btn primary" onclick="showUploadFilesModal()">重新加载</button></div></div>`;
    });
}

function renderUploadFilesModal(files) {
  closeUploadFilesModal();
  const overlay = document.createElement('div');
  overlay.className = 'upload-files-overlay';
  overlay.id = 'upload-files-overlay';

  const fileRows = files.map(f => {
    const displayName = escapeHtml(f.name);
    const folderMatch = String(f.name || '').match(/^(.*\/)([^/]+)$/);
    const folderPart = folderMatch ? escapeHtml(folderMatch[1]) : '';
    const namePart = folderMatch ? escapeHtml(folderMatch[2]) : displayName;
    const folderChip = folderPart
      ? `<span style="flex-shrink:0;font-size:11px;color:#8b1a1a;background:rgba(139,26,26,.08);padding:2px 8px;border-radius:999px" title="${folderPart}">${folderPart.length > 24 ? folderPart.slice(0, 22) + '…' : folderPart}</span>`
      : '';
    const linkedCount = Number(f.article_count) || 0;
    const linkedBadge = linkedCount
      ? `<span class="upload-linked-badge" title="${escapeHtml((f.article_titles || []).join('、'))}">已关联 ${linkedCount} 篇文章</span>`
      : '<span class="upload-unlinked-badge">未关联</span>';
    const ambiguousBadge = f.association_ambiguous ? '<span class="upload-ambiguous-badge">重名待确认</span>' : '';
    return `
    <div class="upload-file-item" data-path="${escapeHtml(f.path)}" data-name="${displayName.toLowerCase()}" style="display:flex;align-items:center;gap:12px;padding:11px 14px;border-radius:10px;cursor:pointer;transition:background .2s" onclick="if(event.target.tagName!=='INPUT') this.querySelector('.file-checkbox').click()" onmouseover="this.style.background='rgba(139,26,26,.06)'" onmouseout="this.style.background='transparent'">
      <input type="checkbox" class="file-checkbox" data-path="${escapeHtml(f.path)}" style="width:18px;height:18px;cursor:pointer;accent-color:#8b1a1a;flex-shrink:0">
      <span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px" title="${displayName}">${namePart}</span>
      ${folderChip}
      ${linkedBadge}${ambiguousBadge}
      <span style="font-size:12px;color:var(--text-muted);flex-shrink:0;margin-left:8px">${escapeHtml(f.size_fmt)}</span>
    </div>`;
  }).join('');

  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:16px;max-width:580px;width:95%;max-height:80vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.3)">
      <div style="padding:20px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-size:16px;font-weight:600;color:var(--text)">选择要清理的文件</div>
          <div style="font-size:12px;color:var(--text-muted);margin-top:2px">删除原始文件不会删除文章正文；已关联文件会同步解除原件关联</div>
        </div>
        <button onclick="closeUploadFilesModal()" style="background:none;border:none;cursor:pointer;color:var(--text-muted);font-size:20px;width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center">✕</button>
      </div>
      <div style="padding:14px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center">
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;color:var(--text)">
          <input type="checkbox" id="selectAllUploads" onchange="toggleSelectAllUploads()" style="width:18px;height:18px;cursor:pointer;accent-color:#8b1a1a">
          <span style="font-weight:500">全选可见文件</span>
        </label>
        <span id="selectedCount" style="font-size:13px;color:var(--text-muted)">已选 0 个文件</span>
      </div>
      <div class="upload-files-toolbar">
        <label class="storage-search"><span>⌕</span><input type="search" placeholder="搜索文件名或文件夹" oninput="filterUploadFiles(this.value)" aria-label="搜索上传文件"></label>
        <span class="upload-files-hint">${files.length} 个文件 · 删除前请留意“已关联”标记</span>
      </div>
      <div id="uploadFilesList" style="flex:1;overflow-y:auto;padding:12px 16px;min-height:200px;max-height:400px">
        ${files.length > 0 ? fileRows : '<div style="padding:40px;text-align:center;color:var(--text-muted);font-size:14px">暂无上传文件</div>'}
      </div>
      <div style="padding:16px 24px;border-top:1px solid var(--border);display:flex;gap:12px">
        <button id="cleanSelectedBtn" onclick="cleanSelectedUploads()" style="flex:1;padding:12px 20px;border-radius:10px;border:none;background:#8b1a1a;color:white;cursor:pointer;font-size:14px;font-weight:600;transition:opacity .2s">删除所选</button>
        <button onclick="cleanAllUploads()" style="flex:1;padding:12px 20px;border-radius:10px;border:2px solid #c0392b;background:transparent;color:#c0392b;cursor:pointer;font-size:14px;font-weight:600;transition:all .2s">一键清除全部</button>
      </div>
    </div>`;

  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;z-index:10000;animation:fadeIn .2s';
  document.body.appendChild(overlay);

  // 绑定复选框事件
  document.querySelectorAll('.file-checkbox').forEach(cb => {
    cb.addEventListener('change', updateSelectedCount);
  });

  updateSelectedCount();
}

function closeUploadFilesModal() {
  const overlay = document.getElementById('upload-files-overlay');
  if (overlay) overlay.remove();
}

function toggleSelectAllUploads() {
  const checked = document.getElementById('selectAllUploads').checked;
  document.querySelectorAll('.file-checkbox').forEach(cb => cb.checked = checked);
  updateSelectedCount();
}

function filterUploadFiles(value) {
  const query = String(value || '').trim().toLowerCase();
  document.querySelectorAll('#uploadFilesList .upload-file-item').forEach(row => {
    row.style.display = !query || String(row.dataset.name || '').includes(query) ? 'flex' : 'none';
  });
}

function updateSelectedCount() {
  const selected = Array.from(document.querySelectorAll('.file-checkbox:checked'));
  const checked = selected.length;
  const total = document.querySelectorAll('.file-checkbox').length;
  const selectedFiles = selected.map(cb => uploadFilesCache.find(file => file.path === cb.dataset.path)).filter(Boolean);
  const bytes = selectedFiles.reduce((sum, file) => sum + (Number(file.size) || 0), 0);
  const linked = selectedFiles.filter(file => Number(file.article_count) > 0).length;
  const label = document.getElementById('selectedCount');
  if (label) label.textContent = checked
    ? `已选 ${checked} / ${total} 个 · 释放 ${formatStorageBytes(bytes)}${linked ? ` · ${linked} 个有关联` : ''}`
    : `已选 0 / ${total} 个文件`;
  const btn = document.getElementById('cleanSelectedBtn');
  if (btn) {
    btn.textContent = checked > 0 ? `删除所选 (${checked})` : '删除所选';
    btn.style.opacity = checked > 0 ? '1' : '0.5';
    btn.disabled = checked === 0;
  }
}

async function cleanSelectedUploads() {
  const paths = Array.from(document.querySelectorAll('.file-checkbox:checked')).map(cb => cb.dataset.path);
  if (paths.length === 0) return alert('请先选择要删除的文件');
  const selectedFiles = paths.map(path => uploadFilesCache.find(file => file.path === path)).filter(Boolean);
  const linked = selectedFiles.filter(file => Number(file.article_count) > 0).length;
  const bytes = selectedFiles.reduce((sum, file) => sum + (Number(file.size) || 0), 0);
  if (!confirm(`确定要删除选中的 ${paths.length} 个文件并释放约 ${formatStorageBytes(bytes)} 吗？${linked ? `其中 ${linked} 个文件已关联文章，删除后会解除原件关联，但不会删除文章正文。` : '这些文件未关联文章。'}`)) return;

  closeUploadFilesModal();
  const body = document.getElementById('storage-modal-body');
  if (body) body.innerHTML = `
    <div style="padding:60px 24px;text-align:center">
      <div style="width:48px;height:48px;margin:0 auto 16px;border-radius:50%;border:3px solid var(--border);border-top-color:#8b1a1a;animation:spin .8s linear infinite"></div>
      <div style="font-size:14px;color:var(--text-muted)">正在删除…</div>
    </div>
    <style>@keyframes spin{to{transform:rotate(360deg)}}</style>`;

  try {
    const result = await fetchStorageJson('/api/storage/cleanup', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({type: 'files', paths: paths})
    });
    if (result.ok) {
      if (typeof showToast === 'function') showToast(result.message || '文件已删除', 'success');
      refreshStorageAfterCleanup(result.message || '文件已删除');
    } else {
      if (body) body.innerHTML = `<div class="storage-error">${escapeHtml(result.message || '删除失败')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
    }
  } catch (e) {
    if (body) body.innerHTML = `<div class="storage-error">删除失败：${escapeHtml(e.message || '请稍后重试')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
  }
}

async function cleanAllUploads() {
  const bytes = uploadFilesCache.reduce((sum, file) => sum + (Number(file.size) || 0), 0);
  const linked = uploadFilesCache.filter(file => Number(file.article_count) > 0).length;
  if (!confirm(`确定要删除全部 ${uploadFilesCache.length} 个上传文件并释放约 ${formatStorageBytes(bytes)} 吗？${linked ? `其中 ${linked} 个文件已关联文章，删除后会解除原件关联，但不会删除文章正文。` : '当前没有文件关联文章。'}`)) return;
  closeUploadFilesModal();
  doClean('uploads');
}

// 运行日志选择弹窗
let runtimeLogFilesCache = [];
let bridgeLogPathCache = '';

function showRuntimeLogsModal() {
  fetchStorageJson('/api/storage/logs')
    .then(data => {
      runtimeLogFilesCache = data.files || [];
      renderRuntimeLogsModal(data.files || [], data);
    })
    .catch(error => alert(`运行日志明细加载失败：${error.message || '请稍后再试'}`));
}

function renderRuntimeLogsModal(files, data = {}) {
  const overlay = document.createElement('div');
  overlay.className = 'upload-files-overlay';
  overlay.id = 'runtime-logs-overlay';

  const fileRows = files.map(f => `
    <div class="runtime-log-item" data-path="${escapeHtml(f.path)}" style="display:grid;grid-template-columns:24px minmax(0,1fr) auto;gap:12px;padding:14px 16px;border-radius:10px;border:1px solid var(--border);margin-bottom:10px;background:rgba(248,250,252,.58)">
      <input type="checkbox" class="log-checkbox" data-path="${escapeHtml(f.path)}" ${f.cleanable ? '' : 'disabled'} style="width:18px;height:18px;cursor:${f.cleanable ? 'pointer' : 'not-allowed'};accent-color:#8b1a1a;margin-top:3px;flex-shrink:0">
      <div style="min-width:0">
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:5px">
          <span style="font-size:14px;font-weight:700;color:var(--text)">${escapeHtml(f.title || f.name)}</span>
          <span style="font-size:12px;color:var(--text-muted);font-family:ui-monospace,SFMono-Regular,Menlo,monospace">${escapeHtml(f.name)}</span>
          <span style="font-size:12px;font-weight:700;color:${f.cleanable ? '#b91c1c' : '#64748b'};background:${f.cleanable ? 'rgba(239,68,68,.1)' : 'rgba(100,116,139,.1)'};padding:2px 7px;border-radius:999px">${escapeHtml(f.action || (f.cleanable ? '清空内容' : '建议保留'))}</span>
        </div>
        <div style="font-size:13px;line-height:1.55;color:var(--text-muted);margin-bottom:4px">
          <strong style="color:var(--text)">用途：</strong>${escapeHtml(f.purpose || '记录运行过程和错误信息，用于排查问题。')}
        </div>
        <div style="font-size:13px;line-height:1.55;color:var(--text-muted)">
          <strong style="color:var(--text)">清理影响：</strong>${escapeHtml(f.cleanup_note || '只清空历史日志内容，不影响知识库数据。')}
        </div>
        ${String(f.name || '').endsWith('bridge.log') ? `
          <button type="button" data-bridge-log-sections="1" onclick="showBridgeLogSectionsModal(event)" style="margin-top:10px;padding:8px 12px;border-radius:8px;border:1px solid #8b1a1a;background:rgba(139,26,26,.06);color:#8b1a1a;cursor:pointer;font-size:13px;font-weight:700">
            细分清理 bridge.log
          </button>
        ` : ''}
      </div>
      <span style="font-size:13px;color:var(--text-muted);font-weight:700;white-space:nowrap">${escapeHtml(f.size_fmt || '')}</span>
    </div>`).join('');

  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:16px;max-width:760px;width:95%;max-height:84vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.3)">
      <div style="padding:20px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:16px">
        <div>
          <div style="font-size:16px;font-weight:700;color:var(--text)">选择要清空的运行日志</div>
          <div style="font-size:12px;color:var(--text-muted);margin-top:4px">只清空日志内容，不删除日志文件；不会影响文章、数据库、上传文件和页面功能。</div>
        </div>
        <button onclick="closeRuntimeLogsModal()" style="background:none;border:none;cursor:pointer;color:var(--text-muted);font-size:20px;width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center">✕</button>
      </div>
      <div style="padding:14px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap">
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;color:var(--text)">
          <input type="checkbox" id="selectAllLogs" onchange="toggleSelectAllRuntimeLogs()" style="width:18px;height:18px;cursor:pointer;accent-color:#8b1a1a">
          <span style="font-weight:600">全选可清空日志</span>
        </label>
        <span id="selectedLogCount" style="font-size:13px;color:var(--text-muted)">已选 0 个日志</span>
      </div>
      <div style="padding:12px 24px;background:rgba(183,121,31,.08);border-bottom:1px solid var(--border);font-size:13px;color:#92400e;line-height:1.6">
        建议优先清空体积较大的 <strong>bridge.log</strong> 或 <strong>server.log</strong>。<strong>server.pid</strong> 是重启脚本使用的小文件，页面会展示用途，但不提供勾选清理。
      </div>
      <div id="runtimeLogsList" style="flex:1;overflow-y:auto;padding:16px 20px;min-height:220px;max-height:460px">
        ${files.length > 0 ? fileRows : '<div style="padding:40px;text-align:center;color:var(--text-muted);font-size:14px">暂无运行日志</div>'}
      </div>
      <div style="padding:16px 24px;border-top:1px solid var(--border);display:flex;gap:12px">
        <button id="cleanSelectedLogsBtn" onclick="cleanSelectedRuntimeLogs()" style="flex:1;padding:12px 20px;border-radius:10px;border:none;background:#8b1a1a;color:white;cursor:pointer;font-size:14px;font-weight:700;transition:opacity .2s">清空所选</button>
        <button onclick="cleanAllRuntimeLogs()" style="flex:1;padding:12px 20px;border-radius:10px;border:2px solid #c0392b;background:transparent;color:#c0392b;cursor:pointer;font-size:14px;font-weight:700;transition:all .2s">清空全部可清理日志</button>
      </div>
    </div>`;

  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;z-index:10000;animation:fadeIn .2s';
  document.body.appendChild(overlay);

  document.querySelectorAll('.log-checkbox').forEach(cb => {
    cb.addEventListener('change', updateSelectedLogCount);
  });
  updateSelectedLogCount();
}

function showBridgeLogSectionsModal(event) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }
  const bridgeFile = runtimeLogFilesCache.find(f => f.name === 'bridge.log') || null;
  bridgeLogPathCache = bridgeFile?.path || '';
  const query = bridgeFile && bridgeFile.path ? `?path=${encodeURIComponent(bridgeFile.path)}` : '';
  renderBridgeLogSectionsLoading(bridgeFile);
  fetchStorageJson(`/api/storage/logs/bridge${query}`)
    .then(data => renderBridgeLogSectionsModal(data))
    .catch(err => renderBridgeLogSectionsUnavailable(bridgeFile, err.message));
}

window.showBridgeLogSectionsModal = showBridgeLogSectionsModal;

document.addEventListener('click', function(e) {
  const btn = e.target && e.target.closest ? e.target.closest('[data-bridge-log-sections]') : null;
  if (!btn) return;
  showBridgeLogSectionsModal(e);
});

function renderBridgeLogSectionsLoading(bridgeFile) {
  closeBridgeLogSectionsModal();
  const overlay = document.createElement('div');
  overlay.className = 'upload-files-overlay';
  overlay.id = 'bridge-log-sections-overlay';
  const sizeText = bridgeFile && bridgeFile.size_fmt ? bridgeFile.size_fmt : '较大';
  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:16px;max-width:560px;width:92%;box-shadow:0 20px 60px rgba(0,0,0,.35);padding:30px 28px;text-align:center">
      <div style="width:48px;height:48px;margin:0 auto 18px;border-radius:50%;border:3px solid var(--border);border-top-color:#8b1a1a;animation:spin .8s linear infinite"></div>
      <div style="font-size:17px;font-weight:800;color:var(--text);margin-bottom:8px">正在分析 bridge.log…</div>
      <div style="font-size:13px;color:var(--text-muted);line-height:1.7">当前日志约 ${escapeHtml(sizeText)}，首次细分需要读取日志内容，请稍等片刻。</div>
      <style>@keyframes spin{to{transform:rotate(360deg)}}</style>
    </div>`;
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.74);display:flex;align-items:center;justify-content:center;z-index:10001;animation:fadeIn .2s';
  document.body.appendChild(overlay);
}

function renderBridgeLogSectionsUnavailable(bridgeFile, message = '') {
  closeBridgeLogSectionsModal();
  const overlay = document.createElement('div');
  overlay.className = 'upload-files-overlay';
  overlay.id = 'bridge-log-sections-overlay';
  const sizeText = bridgeFile && bridgeFile.size_fmt ? bridgeFile.size_fmt : '未知大小';
  const canClearWholeFile = !!(bridgeFile && bridgeFile.path && bridgeFile.size > 0);

  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:16px;max-width:720px;width:94%;max-height:84vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.35)">
      <div style="padding:20px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:16px">
        <div>
          <div style="font-size:16px;font-weight:800;color:var(--text)">细分清理 bridge.log</div>
          <div style="font-size:12px;color:var(--text-muted);margin-top:4px">当前 bridge.log 显示为 ${escapeHtml(sizeText)}。</div>
        </div>
        <button onclick="closeBridgeLogSectionsModal()" style="background:none;border:none;cursor:pointer;color:var(--text-muted);font-size:20px;width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center">✕</button>
      </div>
      <div style="padding:28px 28px 8px">
        <div style="border:1px solid rgba(183,121,31,.28);background:rgba(183,121,31,.08);border-radius:12px;padding:18px 20px;color:#92400e;line-height:1.7;font-size:14px">
          <div style="font-size:16px;font-weight:800;margin-bottom:8px;color:#7c2d12">细分接口还没有加载成功</div>
          <div>页面已经是新版，但当前后端服务还在使用旧接口，所以点进来会看不到分类内容；这不是日志已经清空。</div>
          ${message ? `<div style="margin-top:6px;color:#9a3412">接口返回：${escapeHtml(message)}</div>` : ''}
        </div>
        <div style="margin-top:16px;border:1px solid var(--border);border-radius:12px;padding:16px 18px;background:rgba(248,250,252,.72)">
          <div style="font-size:14px;font-weight:800;color:var(--text);margin-bottom:8px">你现在可以怎么做</div>
          <div style="font-size:13px;color:var(--text-muted);line-height:1.75">
            1. 双击“重启法律操作系统.command”，刷新后即可看到按用途拆分的桥接日志类别。<br>
            2. 如果只是想释放空间，也可以先清空整个 bridge.log；这不会影响文章、数据库、上传文件和页面功能。
          </div>
        </div>
      </div>
      <div style="padding:18px 24px 24px;display:flex;gap:12px">
        <button onclick="closeBridgeLogSectionsModal()" style="flex:1;padding:12px 20px;border-radius:10px;border:1px solid var(--border);background:transparent;color:var(--text);cursor:pointer;font-size:14px;font-weight:700">返回运行日志</button>
        <button onclick="cleanWholeBridgeLogFromFallback()" ${canClearWholeFile ? '' : 'disabled'} style="flex:1;padding:12px 20px;border-radius:10px;border:none;background:#8b1a1a;color:white;cursor:${canClearWholeFile ? 'pointer' : 'not-allowed'};font-size:14px;font-weight:800;opacity:${canClearWholeFile ? '1' : '.45'}">清空整个 bridge.log</button>
      </div>
    </div>`;

  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.74);display:flex;align-items:center;justify-content:center;z-index:10001;animation:fadeIn .2s';
  document.body.appendChild(overlay);
}

function renderBridgeLogSectionsModal(data) {
  closeBridgeLogSectionsModal();
  const sections = data.sections || [];
  const overlay = document.createElement('div');
  overlay.className = 'upload-files-overlay';
  overlay.id = 'bridge-log-sections-overlay';

  const rows = sections.map(s => {
    const canClean = s.cleanable && s.size > 0;
    return `
      <div class="bridge-log-section-item" style="display:grid;grid-template-columns:24px minmax(0,1fr) auto;gap:12px;padding:14px 16px;border-radius:10px;border:1px solid var(--border);margin-bottom:10px;background:${canClean ? 'rgba(248,250,252,.72)' : 'rgba(241,245,249,.58)'}">
        <input type="checkbox" class="bridge-section-checkbox" data-category="${escapeHtml(s.id)}" ${canClean ? '' : 'disabled'} style="width:18px;height:18px;cursor:${canClean ? 'pointer' : 'not-allowed'};accent-color:#8b1a1a;margin-top:3px">
        <div style="min-width:0">
          <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:5px">
            <span style="font-size:14px;font-weight:800;color:var(--text)">${escapeHtml(s.title)}</span>
            <span style="font-size:12px;font-weight:700;color:${canClean ? '#b91c1c' : '#64748b'};background:${canClean ? 'rgba(239,68,68,.1)' : 'rgba(100,116,139,.1)'};padding:2px 7px;border-radius:999px">${canClean ? '可选择清理' : '暂无内容'}</span>
            <span style="font-size:12px;color:var(--text-muted)">${s.count || 0} 段记录</span>
          </div>
          <div style="font-size:13px;line-height:1.55;color:var(--text-muted);margin-bottom:4px">
            <strong style="color:var(--text)">用途：</strong>${escapeHtml(s.purpose || '')}
          </div>
          <div style="font-size:13px;line-height:1.55;color:var(--text-muted);margin-bottom:${s.sample ? '6px' : '0'}">
            <strong style="color:var(--text)">清理影响：</strong>${escapeHtml(s.cleanup_note || '')}
          </div>
          ${s.sample ? `<div style="font-size:12px;line-height:1.45;color:var(--text-muted);background:rgba(148,163,184,.1);border-radius:8px;padding:8px 10px;overflow:hidden;text-overflow:ellipsis"><strong>示例：</strong>${escapeHtml(s.sample)}</div>` : ''}
        </div>
        <span style="font-size:13px;color:var(--text-muted);font-weight:800;white-space:nowrap">${escapeHtml(s.size_fmt || '0 B')}</span>
      </div>`;
  }).join('');

  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:16px;max-width:820px;width:96%;max-height:86vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.35)">
      <div style="padding:20px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:16px">
        <div>
          <div style="font-size:16px;font-weight:800;color:var(--text)">细分清理 bridge.log</div>
          <div style="font-size:12px;color:var(--text-muted);margin-top:4px">按日志用途清理其中某几类记录，不会删除 bridge.log 文件本身。</div>
        </div>
        <button onclick="closeBridgeLogSectionsModal()" style="background:none;border:none;cursor:pointer;color:var(--text-muted);font-size:20px;width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center">✕</button>
      </div>
      <div style="padding:14px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap">
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;color:var(--text)">
          <input type="checkbox" id="selectAllBridgeSections" onchange="toggleSelectAllBridgeSections()" style="width:18px;height:18px;cursor:pointer;accent-color:#8b1a1a">
          <span style="font-weight:700">全选有内容的类别</span>
        </label>
        <span id="selectedBridgeSectionCount" style="font-size:13px;color:var(--text-muted)">已选 0 个类别</span>
      </div>
      <div style="padding:12px 24px;background:rgba(183,121,31,.08);border-bottom:1px solid var(--border);font-size:13px;color:#92400e;line-height:1.6">
        当前 bridge.log 共 ${escapeHtml(data.total_size_fmt || '0 B')}。如仍在排查 WorkBuddy 连接问题，建议保留最新的“Node 启动失败记录”；若只是释放空间，可以清理体积最大的类别。
      </div>
      <div style="flex:1;overflow-y:auto;padding:16px 20px;min-height:240px;max-height:480px">
        ${sections.length > 0 ? rows : '<div style="padding:40px;text-align:center;color:var(--text-muted);font-size:14px">暂无桥接日志</div>'}
      </div>
      <div style="padding:16px 24px;border-top:1px solid var(--border);display:flex;gap:12px">
        <button id="cleanSelectedBridgeSectionsBtn" onclick="cleanSelectedBridgeLogSections()" style="flex:1;padding:12px 20px;border-radius:10px;border:none;background:#8b1a1a;color:white;cursor:pointer;font-size:14px;font-weight:800;transition:opacity .2s">清理所选类别</button>
        <button onclick="closeBridgeLogSectionsModal()" style="flex:1;padding:12px 20px;border-radius:10px;border:1px solid var(--border);background:transparent;color:var(--text);cursor:pointer;font-size:14px;font-weight:700">返回运行日志</button>
      </div>
    </div>`;

  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.74);display:flex;align-items:center;justify-content:center;z-index:10001;animation:fadeIn .2s';
  document.body.appendChild(overlay);

  document.querySelectorAll('.bridge-section-checkbox').forEach(cb => {
    cb.addEventListener('change', updateSelectedBridgeSectionCount);
  });
  updateSelectedBridgeSectionCount();
}

function closeBridgeLogSectionsModal() {
  const overlay = document.getElementById('bridge-log-sections-overlay');
  if (overlay) overlay.remove();
}

function toggleSelectAllBridgeSections() {
  const checked = document.getElementById('selectAllBridgeSections').checked;
  document.querySelectorAll('.bridge-section-checkbox:not(:disabled)').forEach(cb => cb.checked = checked);
  updateSelectedBridgeSectionCount();
}

function updateSelectedBridgeSectionCount() {
  const checked = document.querySelectorAll('.bridge-section-checkbox:checked').length;
  const total = document.querySelectorAll('.bridge-section-checkbox:not(:disabled)').length;
  const label = document.getElementById('selectedBridgeSectionCount');
  if (label) label.textContent = `已选 ${checked} / ${total} 个可清理类别`;
  const btn = document.getElementById('cleanSelectedBridgeSectionsBtn');
  if (btn) {
    btn.textContent = checked > 0 ? `清理所选类别 (${checked})` : '清理所选类别';
    btn.style.opacity = checked > 0 ? '1' : '0.5';
  }
}

async function cleanSelectedBridgeLogSections() {
  const categories = Array.from(document.querySelectorAll('.bridge-section-checkbox:checked')).map(cb => cb.dataset.category);
  if (categories.length === 0) return alert('请先选择要清理的桥接日志类别');
  if (!confirm(`确定要清理选中的 ${categories.length} 个桥接日志类别吗？这只会移除 bridge.log 中对应类别的历史记录。`)) return;

  closeBridgeLogSectionsModal();
  closeRuntimeLogsModal();
  const body = document.getElementById('storage-modal-body');
  if (body) body.innerHTML = `
    <div style="padding:60px 24px;text-align:center">
      <div style="width:48px;height:48px;margin:0 auto 16px;border-radius:50%;border:3px solid var(--border);border-top-color:#8b1a1a;animation:spin .8s linear infinite"></div>
      <div style="font-size:14px;color:var(--text-muted)">正在清理桥接日志…</div>
    </div>
    <style>@keyframes spin{to{transform:rotate(360deg)}}</style>`;

  try {
    const result = await fetchStorageJson('/api/storage/cleanup', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({type: 'bridge_log_sections', categories, path: bridgeLogPathCache || undefined})
    });
    if (result.ok) {
      if (typeof showToast === 'function') showToast(result.message || '桥接日志已清理', 'success');
      refreshStorageAfterCleanup(result.message || '桥接日志已清理');
    } else if (body) {
      body.innerHTML = `<div class="storage-error">${escapeHtml(result.message || '清理失败')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
    }
  } catch (e) {
    if (body) body.innerHTML = `<div class="storage-error">清理失败：${escapeHtml(e.message || '请稍后重试')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
  }
}

async function cleanWholeBridgeLogFromFallback() {
  const bridgeFile = runtimeLogFilesCache.find(f => String(f.name || '').endsWith('bridge.log'));
  if (!bridgeFile || !bridgeFile.path) return alert('没有找到 bridge.log 文件路径');
  if (!confirm('确定要清空整个 bridge.log 吗？这只会清空历史桥接日志，不影响知识库数据。')) return;

  closeBridgeLogSectionsModal();
  closeRuntimeLogsModal();
  const body = document.getElementById('storage-modal-body');
  if (body) body.innerHTML = `
    <div style="padding:60px 24px;text-align:center">
      <div style="width:48px;height:48px;margin:0 auto 16px;border-radius:50%;border:3px solid var(--border);border-top-color:#8b1a1a;animation:spin .8s linear infinite"></div>
      <div style="font-size:14px;color:var(--text-muted)">正在清空 bridge.log…</div>
    </div>
    <style>@keyframes spin{to{transform:rotate(360deg)}}</style>`;

  try {
    const result = await fetchStorageJson('/api/storage/cleanup', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({type: 'log_files', paths: [bridgeFile.path]})
    });
    if (result.ok) {
      if (typeof showToast === 'function') showToast(result.message || 'bridge.log 已清空', 'success');
      refreshStorageAfterCleanup(result.message || 'bridge.log 已清空');
    } else if (body) {
      body.innerHTML = `<div class="storage-error">${escapeHtml(result.message || result.detail || '服务器未能清空日志')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
    }
  } catch (e) {
    if (body) body.innerHTML = `<div class="storage-error">清空失败：${escapeHtml(e.message || '请稍后重试')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
  }
}

function closeRuntimeLogsModal() {
  const overlay = document.getElementById('runtime-logs-overlay');
  if (overlay) overlay.remove();
}

function toggleSelectAllRuntimeLogs() {
  const checked = document.getElementById('selectAllLogs').checked;
  document.querySelectorAll('.log-checkbox:not(:disabled)').forEach(cb => cb.checked = checked);
  updateSelectedLogCount();
}

function updateSelectedLogCount() {
  const checked = document.querySelectorAll('.log-checkbox:checked').length;
  const total = document.querySelectorAll('.log-checkbox:not(:disabled)').length;
  const label = document.getElementById('selectedLogCount');
  if (label) label.textContent = `已选 ${checked} / ${total} 个可清空日志`;
  const btn = document.getElementById('cleanSelectedLogsBtn');
  if (btn) {
    btn.textContent = checked > 0 ? `清空所选 (${checked})` : '清空所选';
    btn.style.opacity = checked > 0 ? '1' : '0.5';
  }
}

async function cleanSelectedRuntimeLogs() {
  const paths = Array.from(document.querySelectorAll('.log-checkbox:checked')).map(cb => cb.dataset.path);
  if (paths.length === 0) return alert('请先选择要清空的日志');
  if (!confirm(`确定要清空选中的 ${paths.length} 个日志吗？这只会清空历史日志内容，不影响知识库数据。`)) return;

  closeRuntimeLogsModal();
  const body = document.getElementById('storage-modal-body');
  if (body) body.innerHTML = `
    <div style="padding:60px 24px;text-align:center">
      <div style="width:48px;height:48px;margin:0 auto 16px;border-radius:50%;border:3px solid var(--border);border-top-color:#8b1a1a;animation:spin .8s linear infinite"></div>
      <div style="font-size:14px;color:var(--text-muted)">正在清空日志…</div>
    </div>
    <style>@keyframes spin{to{transform:rotate(360deg)}}</style>`;

  try {
    const result = await fetchStorageJson('/api/storage/cleanup', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({type: 'log_files', paths: paths})
    });
    if (result.ok) {
      if (typeof showToast === 'function') showToast(result.message || '日志已清空', 'success');
      refreshStorageAfterCleanup(result.message || '日志已清空');
    } else if (body) {
      body.innerHTML = `<div class="storage-error">${escapeHtml(result.message || '清空失败')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
    }
  } catch (e) {
    if (body) body.innerHTML = `<div class="storage-error">清空失败：${escapeHtml(e.message || '请稍后重试')}<button class="storage-retry-btn" type="button" onclick="openStorageModal()">刷新状态</button></div>`;
  }
}

async function cleanAllRuntimeLogs() {
  if (!confirm('确定要清空全部可清理日志吗？这只会清空 *.log 历史内容，不会清理 server.pid，也不影响知识库数据。')) return;
  closeRuntimeLogsModal();
  doClean('runtime_logs');
}

// 清理确认弹窗入口（分发到对应处理函数）
function showCleanConfirm(type) {
  if (type === 'uploads') {
    showUploadFilesModal();
  } else if (type === 'runtime_logs') {
    showRuntimeLogsModal();
  } else if (type === 'history_backups') {
    showHistoryBackupsModal();
  } else {
    showDistCleanConfirm(type);
  }
}

/* ─────────────────────────────────────────────
   统计页面 postMessage 监听（接收 iframe 内嵌页面的点击事件）
───────────────────────────────────────────── */
window.addEventListener('message', function(event) {
  const data = event.data;
  if (!data || !data.type) return;

  if (event.origin === location.origin && data.type === 'scannerInboxAsk') {
    askContext = {type: 'local_attachments', sessionId: data.sessionId, files: Array.isArray(data.files) ? data.files : []};
    askSourceMode = 'hybrid';
    openAskPanel();
    startFreshAskConversation();
    _updateAskContextBar(); updateAskSourceModeUI(); renderAskSelectedFiles(); renderAskHistory();
    showToast(`已将 ${askContext.files.length} 个扫描件交给 AI 增强`, 'success');
    return;
  }
  
  if (data.type === 'filter') {
    // 统计页面的筛选请求
    const view = data.view;
    if (view === 'all' || view === 'url' || view === 'file' || view === 'notes') {
      // 关闭统计标签页，切换到主标签页并筛选
      closeStatsAndFilter(view);
    }
  } else if (data.type === 'filterByDomain') {
    // 按领域筛选
    closeStatsAndFilterByDomain(data.domain);
  } else if (data.type === 'filterByAuthor') {
    // 按作者筛选
    closeStatsAndFilterByAuthor(data.author);
  } else if (data.type === 'openArticle') {
    if (data.source === 'recommendations') {
      openArticleInTab(data.id, data.title || '文章详情');
      return;
    }
    // 打开指定文章
    closeStatsAndOpenArticle(data.id);
  } else if (data.type === 'recommendationAskArticle') {
    askContext = { type: 'article', id: data.id, title: data.title || '当前文章' };
    openAskPanel();
  } else if (data.type === 'recommendationSetStatus') {
    setArticleStatus(data.id, data.status || 'reading');
    showToast(data.status === 'done' ? '已标为已整理' : '已标为待读');
  } else if (data.type === 'recommendationsUpdated') {
    loadHomeRecommendations(0);
  } else if (data.type === 'openCourtOnline') {
    openCourtOnlineService(0, { kind: data.kind || '', query: data.query || '' });
  }
});

/**
 * 关闭统计标签页并按来源筛选
 */
function closeStatsAndFilter(view) {
  // 1. 找到并关闭统计标签页
  const kbStatsTab = tabState.tabs.find(t => t.type === TAB_TYPES.KB_STATS);
  if (kbStatsTab) {
    closeTab(kbStatsTab.id);
  }
  
  // 2. 切换到主标签页
  switchTab('main');
  
  // 3. 延迟执行筛选，确保视图已切换
  setTimeout(() => {
    if (view === 'all' || view === 'notes') {
      switchView(view);
    } else {
      switchView('list');
      filterBySource(view);
    }
    const labels = { all: '全部知识', url: '网页来源', file: '本地文档', notes: '阅读笔记' };
    showToast(`已切换到：${labels[view] || '知识列表'}`);
  }, 100);
}

/**
 * 关闭统计标签页并按领域筛选
 */
function closeStatsAndFilterByDomain(domain) {
  // 1. 找到并关闭统计标签页
  const kbStatsTab = tabState.tabs.find(t => t.type === TAB_TYPES.KB_STATS);
  if (kbStatsTab) {
    closeTab(kbStatsTab.id);
  }
  
  // 2. 切换到主标签页
  switchTab('main');
  
  // 3. 延迟执行筛选
  setTimeout(() => {
    switchView('list');
    filterByDomain(domain);
    showToast(`已按领域筛选：${domain}`);
  }, 100);
}

/**
 * 关闭统计标签页并按作者筛选
 */
function closeStatsAndFilterByAuthor(author) {
  const kbStatsTab = tabState.tabs.find(t => t.type === TAB_TYPES.KB_STATS);
  if (kbStatsTab) {
    closeTab(kbStatsTab.id);
  }

  switchTab('main');

  setTimeout(() => {
    filterByAuthor(author);
    showToast(`已按作者筛选：${author}`);
  }, 100);
}

/**
 * 关闭统计标签页并打开文章
 */
function closeStatsAndOpenArticle(articleId) {
  // 1. 找到并关闭统计标签页
  const kbStatsTab = tabState.tabs.find(t => t.type === TAB_TYPES.KB_STATS);
  if (kbStatsTab) {
    closeTab(kbStatsTab.id);
  }
  
  // 2. 切换到主标签页并延迟打开文章
  setTimeout(() => {
    openArticleInTab(articleId, '文章详情');
  }, 100);
}

/**
 * 按来源类型筛选（url/file）
 */
function filterBySource(view) {
  // 清除其他筛选条件
  state.q = '';
  state.domain = '';
  state.author = '';
  state.customTag = '';
  state.currentTagGroupId = null;
  state.customCategoryTags = [];
  
  // 设置来源筛选
  if (view === 'url' || view === 'file') {
    state.view = view;
  } else {
    state.view = 'list';
  }
  
  state.page = 1;
  loadArticles();
}

/**
 * 按领域筛选
 */
function filterByDomain(domain) {
  // 清除其他筛选条件
  state.q = '';
  state.author = '';
  state.customTag = '';
  state.currentTagGroupId = null;
  state.customCategoryTags = [];
  state.view = 'list';
  
  // 设置领域筛选
  state.domain = domain;
  state.page = 1;
  loadArticles();
}

/**
 * 按作者筛选
 */
function filterByAuthor(author) {
  state.q = '';
  state.domain = null;
  state.customTag = null;
  state.currentTagGroupId = null;
  state.customCategory = null;
  state.customCategoryTags = null;
  state.view = 'all';
  state.author = author || '';
  state.page = 1;

  document.querySelectorAll('.nav-item').forEach(e => e.classList.remove('active'));
  document.querySelectorAll('#domain-list .domain-item').forEach(e => e.classList.remove('active'));
  document.querySelectorAll('#tag-groups-container .tag-group-item').forEach(e => e.classList.remove('active'));
  document.querySelectorAll('#author-list .domain-item').forEach(e => {
    const text = e.textContent.trim();
    e.classList.toggle('active', !!author && (text === author || text.includes(author)));
  });

  const title = author ? `作者：${author}` : '全部知识';
  $('page-title').textContent = title;
  loadArticles();
}

/* ─────────────────────────────────────────────
   工具函数
───────────────────────────────────────────── */
const $ = id => document.getElementById(id);

function formatDate(iso) {
  const d = new Date(iso);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
}

function escapeHtml(str) {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const FINDER_TAG_COLORS = new Set(['red', 'orange', 'blue', 'yellow', 'green', 'purple', 'gray']);

function renderFinderTagDots(tags) {
  const list = Array.isArray(tags)
    ? tags.map(tag => ({ color: String(tag?.color || ''), name: String(tag?.name || '') }))
      .filter(tag => FINDER_TAG_COLORS.has(tag.color))
    : [];
  if (!list.length) return '';
  const label = list.map(tag => tag.name).filter(Boolean).join('、');
  const accessible = label ? ` title="访达标签：${escapeHtml(label)}" aria-label="访达标签：${escapeHtml(label)}"` : '';
  return `<span class="finder-tags"${accessible}>${list.map(tag => `<span class="finder-tag-dot ${tag.color}" aria-hidden="true"></span>`).join('')}</span>`;
}

const FINDER_FOLDER_ICON_COLORS = {
  red: '#ff3b30', orange: '#ff9500', blue: '#0a84ff', yellow: '#ffcc00',
  green: '#34c759', purple: '#af52de', gray: '#8e8e93',
};

function renderFinderFolderIcon(tags) {
  const color = Array.isArray(tags)
    ? tags.map(tag => FINDER_FOLDER_ICON_COLORS[String(tag?.color || '')]).find(Boolean)
    : '';
  const fill = color || '#52a9ff';
  return `<svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M1.5 4A1.5 1.5 0 0 1 3 2.5h3.1c.4 0 .78.16 1.06.44L8.2 4H13a1.5 1.5 0 0 1 1.5 1.5v6A1.5 1.5 0 0 1 13 13H3a1.5 1.5 0 0 1-1.5-1.5z" fill="${fill}" stroke="${fill}" stroke-width="1.3" stroke-linejoin="round"/><path d="M2 5.4h12" stroke="#fff" stroke-opacity=".48" stroke-width=".8"/></svg>`;
}

function highlightText(text, keyword) {
  if (!keyword || !state.fuzzy) return escapeHtml(text);
  const escaped = keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return escapeHtml(text).replace(
    new RegExp(escaped, 'gi'),
    m => `<mark>${m}</mark>`
  );
}

function truncate(str, len) {
  if (!str) return '';
  return str.length > len ? str.slice(0, len) + '…' : str;
}

/**
 * 将图片URL转换为代理URL，绕过防盗链
 */
function getProxyImageUrl(url) {
  if (!url) return url;
  let originalUrl = String(url).trim();
  // 历史数据中可能已经保存了一层或多层本地代理地址。先逐层解开，
  // 再按当前规则只包装一次，避免 /proxy/image?url=/proxy/image?...。
  for (let depth = 0; depth < 5; depth += 1) {
    const match = originalUrl.match(/(?:^|\/proxy\/image\?)url=([^&]+)/i);
    if (!match) break;
    try {
      const decoded = decodeURIComponent(match[1]);
      if (!decoded || decoded === originalUrl) break;
      originalUrl = decoded;
    } catch (e) {
      break;
    }
  }
  if (originalUrl.startsWith('data:') || originalUrl.startsWith('blob:')) return originalUrl;
  // 微信图片，使用代理
  if (originalUrl.includes('mmbiz.qpic.cn')) {
    return `${API_BASE}/proxy/image?url=${encodeURIComponent(originalUrl)}`;
  }
  // 今日头条图片，使用代理（带正确Referer）
  if (originalUrl.includes('toutiaoimg.com') || originalUrl.includes('byteimg.com') || originalUrl.includes('p3-sign.toutiaoimg') || originalUrl.includes('p6-sign.toutiaoimg') || originalUrl.includes('p9-sign.toutiaoimg')) {
    return `${API_BASE}/proxy/image?url=${encodeURIComponent(originalUrl)}`;
  }
  if (/^https?:\/\//i.test(originalUrl) && !originalUrl.startsWith(location.origin)) {
    return `${API_BASE}/proxy/image?url=${encodeURIComponent(originalUrl)}`;
  }
  // 其他图片直接返回原URL
  return originalUrl;
}

/**
 * 正文内容渲染函数 —— 统一 HTML 存储格式。
 *
 * 存储格式分三类：
 *  A) 新格式：以 "<" 开头的 HTML 字符串，直接净化后渲染。
 *  B) Markdown：识别常用块级/行内语法，转换并净化后渲染。
 *  C) 旧格式：纯文本（\n 分段，<b>/<i>/<u> 内联标记），自动升级为 HTML。
 *
 * 升级规则（仅旧格式）：
 *  - 双空行分段 → <p>…</p>
 *  - 单行且符合标题特征 → <p class="body-heading"> 或 body-heading-secondary
 *  - [图片: URL] → 图片链接
 *  - <b>/<i>/<u> 行内标记保留
 */
function renderBodyContent(raw) {
  return renderBodyContentWithToc(raw).html;
}

/**
 * 渲染正文并返回 { html, toc }，toc 供左侧智能目录栏使用。
 * 系统自动生成的目录不会出现在 html 中。
 */
function renderBodyContentWithToc(raw) {
  if (!raw) return { html: '<p class="body-empty">暂无正文</p>', toc: [] };

  // 每次都重新渲染以应用最新的图片处理逻辑
  let html;

  // ── 判断是否已经是 HTML 格式 ──
  const source = String(raw);
  const isHtml = /^\s*<(p|div|h[1-6]|ul|ol|blockquote|pre|table|hr|br)\b/i.test(source.trimStart());

  if (isHtml) {
    // 新格式：直接净化渲染
    html = sanitizeBodyHtml(source);
  } else if (isLikelyMarkdown(source)) {
    html = sanitizeBodyHtml(markdownBodyToHtml(source));
  } else {
    // 旧格式：转换为 HTML
    html = legacyTextToHtml(source);
  }

  return enhanceArticleTocHtml(html);
}

