/** 识别 PDF 文字层错序产生的乱码标题（中英碎片穿插、随机字母串），与后端规则一致。 */
function pdfTitleIsNoise(title) {
  const raw = String(title || '');
  const compact = raw.replace(/\s+/g, '');
  if (!compact) return false;
  const frags = raw.match(/[A-Za-z]+/g) || [];
  if (!frags.length) return false;
  const cjk = (compact.match(/[\u4e00-\u9fff]/g) || []).length;
  if (cjk === 0) {
    return !frags.some(f => f.length >= 4 && _PDF_TITLE_COMMON_WORDS.has(f.toLowerCase()));
  }
  let score = 0;
  for (const frag of frags) {
    if (_PDF_TITLE_ABBR.has(frag.toLowerCase())) continue;
    score += 4;
  }
  if (frags.length >= 3) score += 2;
  if ((compact.match(/[\u4e00-\u9fff][A-Za-z]|[A-Za-z][\u4e00-\u9fff]/g) || []).length >= 4) score += 2;
  if (compact.length > 30) score += 1;
  if (cjk >= 4) score += 1;
  return score >= 5;
}

/** 为正文中的 PDF 页面图构建透明可选中文字层（文字仅供拖动选中作笔记）。 */
async function enhancePdfPageGalleries(rootEl) {
  if (!rootEl) return;
  const pages = Array.from(rootEl.querySelectorAll('figure.pdf-page'));
  if (!pages.length) return;
  ensurePdfOverlayResizeHandler();
  await Promise.all(pages.map(figure => enhancePdfPage(figure)));
}

async function enhancePdfPage(figure) {
  const img = figure.querySelector('img.pdf-page-image');
  if (!img || figure.querySelector('.pdf-page-text-layer')) return;
  const src = img.getAttribute('src') || '';
  if (!/\/api\/article-pdf\//.test(src)) return;
  const pageMatch = src.match(/page-(\d+)\.(?:png|jpe?g)$/);
  const pageNo = pageMatch ? Number(pageMatch[1]) : 0;
  if (pageNo > 0) figure.dataset.pdfPage = String(pageNo);
  appendPdfPageNoteButton(figure, pageNo);
  appendPdfPageNumber(figure, pageNo);
  const wordsUrl = src.replace(/\.(?:png|jpe?g)$/, '.words.json');
  let layer = _pdfLayerCache.get(wordsUrl);
  if (!layer) {
    try {
      const res = await fetch(wordsUrl, { headers: { Accept: 'application/json' } });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      layer = await res.json();
      _pdfLayerCache.set(wordsUrl, layer);
    } catch (e) {
      console.warn('PDF 文字层加载失败:', wordsUrl, e);
      return;
    }
  }
  const words = Array.isArray(layer?.words) ? layer.words : [];
  const overlay = document.createElement('span');
  overlay.className = 'pdf-page-text-layer';
  words.forEach((item, index) => {
    const text = String(item[4] ?? item?.['text'] ?? '');
    if (!text) return;
    const next = words[index + 1];
    const nextText = String(next ? (next[4] ?? next?.['text'] ?? '') : '');
    const needSpace = /[A-Za-z0-9)]$/.test(text) && /^[A-Za-z0-9(]/.test(nextText);
    const span = document.createElement('span');
    span.textContent = text + (needSpace ? ' ' : '');
    span.dataset.pdfWord = JSON.stringify([Number(item[0]), Number(item[1]), Number(item[2]), Number(item[3])]);
    overlay.appendChild(span);
  });
  figure.appendChild(overlay);
  observePdfPageLayout(figure);
  if (img.complete && img.naturalWidth > 0) {
    layoutPdfPageOverlay(figure);
  } else {
    img.addEventListener('load', () => layoutPdfPageOverlay(figure), { once: true });
  }
}

/** 每页右上角悬浮「在此页添加笔记」按钮（悬停页面时出现）。 */
function appendPdfPageNoteButton(figure, pageNo) {
  if (!pageNo || figure.querySelector('.pdf-page-note-btn')) return;
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'pdf-page-note-btn';
  button.title = `在第 ${pageNo} 页添加笔记`;
  button.setAttribute('aria-label', `在第 ${pageNo} 页添加笔记`);
  button.innerHTML =
    '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true">' +
    '<path d="M7 1v12M1 7h12" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>' +
    '<span>笔记</span>';
  button.addEventListener('click', event => {
    event.preventDefault();
    event.stopPropagation();
    startPdfPageNote(figure, pageNo);
  });
  figure.appendChild(button);
}

/** 每页右下角显示小的页码标识。 */
function appendPdfPageNumber(figure, pageNo) {
  if (!pageNo || figure.querySelector('.pdf-page-number')) return;
  const badge = document.createElement('span');
  badge.className = 'pdf-page-number';
  badge.textContent = `第 ${pageNo} 页`;
  badge.setAttribute('aria-hidden', 'true');
  figure.appendChild(badge);
}

/** 解析笔记中的 PDF 页面锚点（selection_anchor = {version:2, pdf_page:N}）。 */
function pdfPageFromNote(note) {
  const anchor = parseNoteSelectionAnchor(note?.selection_anchor);
  const page = Number(anchor?.pdf_page);
  return Number.isInteger(page) && page > 0 ? page : 0;
}

function pdfPageNoteQuoteLabel(note) {
  const page = pdfPageFromNote(note);
  return page > 0 ? `第 ${page} 页` : '';
}

/** 点击「在此页添加笔记」：打开笔记面板并记录待保存的页面锚点。 */
function startPdfPageNote(figure, pageNo) {
  const tabPage = figure.closest('.tab-page');
  if (tabPage && tabPage.id && tabPage.id !== 'main') {
    const tabId = tabPage.id;
    if (!state.pendingPdfPageNoteByTab) state.pendingPdfPageNoteByTab = new Map();
    state.pendingPdfPageNoteByTab.set(tabId, pageNo);
    const notesPanel = $(`tab-detail-notes-${tabId}`);
    if (notesPanel) notesPanel.classList.remove('hidden');
    const input = $(`tab-note-input-${tabId}`);
    if (input) {
      input.placeholder = `引用: 第 ${pageNo} 页（PDF 页面笔记）`;
      input.focus();
    }
    showToast(`已定位到第 ${pageNo} 页，输入内容后点击「保存笔记」`);
  } else {
    state.pendingPdfPageNote = pageNo;
    const panel = $('notes-panel');
    if (panel) panel.classList.remove('hidden');
    const input = $('note-input');
    if (input) {
      input.placeholder = `引用: 第 ${pageNo} 页（PDF 页面笔记）`;
      input.focus();
    }
    showToast(`已定位到第 ${pageNo} 页，输入内容后点击「保存笔记」`);
  }
}

/** 滚动到指定 PDF 页面并闪烁提示。 */
function scrollToPdfPageFigure(bodyEl, pageNo) {
  const figure = bodyEl?.querySelector(`figure.pdf-page[data-pdf-page="${pageNo}"]`);
  if (!figure) return null;
  figure.scrollIntoView({ behavior: 'smooth', block: 'start' });
  figure.classList.remove('pdf-page-note-flash');
  void figure.offsetWidth;
  figure.classList.add('pdf-page-note-flash');
  setTimeout(() => figure.classList.remove('pdf-page-note-flash'), 2400);
  return figure;
}

/** 监听每个页面图的尺寸变化（标签页切换显示、侧栏开合、窗口缩放都会触发重新定位）。 */
function observePdfPageLayout(figure) {
  if (typeof ResizeObserver === 'undefined') return;
  try {
    const observer = new ResizeObserver(() => layoutPdfPageOverlay(figure));
    observer.observe(figure);
    figure._pdfResizeObserver = observer;
  } catch (_) { /* 忽略 */ }
}

/** 按图片当前显示尺寸缩放定位文字层（词坐标为全分辨率渲染图像素坐标）。 */
function layoutPdfPageOverlay(figure, attempts = 0) {
  const img = figure.querySelector('img.pdf-page-image');
  const overlay = figure.querySelector('.pdf-page-text-layer');
  if (!img || !overlay) return;
  const naturalWidth = img.naturalWidth || 1;
  const naturalHeight = img.naturalHeight || 1;
  const displayWidth = img.clientWidth || img.getBoundingClientRect().width;
  if (!naturalWidth || !displayWidth) {
    // 标签页尚未显示（display:none 时宽度为 0）：等待布局完成后重试
    if (attempts < 240) {
      requestAnimationFrame(() => layoutPdfPageOverlay(figure, attempts + 1));
    }
    return;
  }
  const scale = displayWidth / naturalWidth;
  const displayHeight = displayWidth * naturalHeight / naturalWidth;
  overlay.style.left = `${img.offsetLeft}px`;
  overlay.style.top = `${img.offsetTop}px`;
  overlay.style.width = `${displayWidth}px`;
  overlay.style.height = `${displayHeight}px`;
  overlay.querySelectorAll('span[data-pdf-word]').forEach(span => {
    let box;
    try { box = JSON.parse(span.dataset.pdfWord); } catch (_) { return; }
    const x0 = Number(box[0]), y0 = Number(box[1]), x1 = Number(box[2]), y1 = Number(box[3]);
    if (!Number.isFinite(x0) || !Number.isFinite(y0)) return;
    // 文字层框与图像墨迹框一一对应：行高框高度即词框高度，保证选中高亮与原文完全重合。
    // 外扩 padding 仅扩大可拖选热区，文字位置用负偏移补偿，不改变视觉对齐。
    const pad = 3;
    const fontSize = Math.max(4, (y1 - y0) * scale);
    span.style.left = `${(x0 * scale - pad).toFixed(1)}px`;
    span.style.top = `${(y0 * scale - pad).toFixed(1)}px`;
    span.style.fontSize = `${fontSize.toFixed(1)}px`;
    span.style.lineHeight = '1';
    span.style.padding = `${pad}px`;
    // 关键对齐：把 span 命中区与选中高亮严格限制在词框内。系统字体宽度与
    // PDF 实际字形不一致时，长句若不限制宽度会溢出词框，选中高亮盖到相邻
    // 文字甚至空白区域，造成“文字层与页面错位”。
    span.style.width = `${Math.max(1, (x1 - x0) * scale).toFixed(1)}px`;
    span.style.height = `${Math.max(1, (y1 - y0) * scale).toFixed(1)}px`;
    span.style.overflow = 'hidden';
  });
  // 词框重新定位后，同步重定位挂在本页文字层上的笔记角标。
  positionPdfTextLayerBadges(overlay);
}

function ensurePdfOverlayResizeHandler() {
  if (_pdfOverlayResizeBound) return;
  _pdfOverlayResizeBound = true;
  window.addEventListener('resize', () => {
    document.querySelectorAll('figure.pdf-page').forEach(layoutPdfPageOverlay);
  });
}

/** 保守识别 Markdown，避免改变历史纯文本文章的既有排版。 */
function isLikelyMarkdown(value) {
  const source = String(value || '').replace(/\r\n?/g, '\n');
  return /^(?: {0,3})(?:#{1,6}\s+|```|~~~|>\s?|[-*+]\s+|\d+[.)]\s+)/m.test(source)
    || /^(?: {0,3})(?:-{3,}|\*{3,}|_{3,})\s*$/m.test(source)
    || /^\s*\|?.+\|.+\n\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$/m.test(source)
    || /!?\[[^\]\n]+\]\((?:https?:\/\/|mailto:|\/|#)[^)\s]+(?:\s+['"][^'"]*['"])?\)/i.test(source)
    || /(?:^|[^*])\*\*[^*\n]+\*\*|(?:^|[^_])__[^_\n]+__|~~[^~\n]+~~|`[^`\n]+`/.test(source);
}

function markdownSafeUrl(value, image = false) {
  const url = String(value || '').trim().replace(/^<|>$/g, '');
  if (image) {
    if (/^(?:https?:\/\/|\/|data:image\/(?:png|gif|jpe?g|webp);base64,|blob:)/i.test(url)) return url;
    return '';
  }
  return /^(?:https?:\/\/|mailto:|\/|#)/i.test(url) ? url : '';
}

/** 将 Markdown 行内语法转换为受控 HTML；占位符可避免代码内容被二次解析。 */
function markdownInlineToHtml(value) {
  const tokens = [];
  const stash = html => {
    const index = tokens.push(html) - 1;
    return `\u0000MD${index}\u0000`;
  };
  let source = String(value || '');

  source = source.replace(/`([^`\n]+)`/g, (_, code) => stash(`<code>${escapeHtml(code)}</code>`));
  source = source.replace(/!\[([^\]\n]*)\]\(([^\s)]+)(?:\s+['"]([^'"]*)['"])?\)/g, (_, alt, rawUrl, title) => {
    const safeUrl = markdownSafeUrl(rawUrl, true);
    if (!safeUrl) return escapeHtml(alt);
    const displayUrl = /^https?:\/\//i.test(safeUrl) ? getProxyImageUrl(safeUrl) : safeUrl;
    const titleAttr = title ? ` title="${escapeAttr(title)}"` : '';
    return stash(`<img src="${escapeAttr(displayUrl)}" data-original="${escapeAttr(safeUrl)}" alt="${escapeAttr(alt)}"${titleAttr}>`);
  });
  source = source.replace(/\[([^\]\n]+)\]\(([^\s)]+)(?:\s+['"]([^'"]*)['"])?\)/g, (_, label, rawUrl, title) => {
    const safeUrl = markdownSafeUrl(rawUrl, false);
    if (!safeUrl) return label;
    const external = /^https?:\/\//i.test(safeUrl);
    const titleAttr = title ? ` title="${escapeAttr(title)}"` : '';
    return stash(`<a href="${escapeAttr(safeUrl)}"${external ? ' target="_blank"' : ''} rel="noopener noreferrer"${titleAttr}>${escapeHtml(label)}</a>`);
  });

  source = escapeHtml(source)
    .replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
    .replace(/__([^_\n]+)__/g, '<strong>$1</strong>')
    .replace(/~~([^~\n]+)~~/g, '<del>$1</del>')
    .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>')
    .replace(/(^|[^_])_([^_\n]+)_/g, '$1<em>$2</em>');

  return source.replace(/\u0000MD(\d+)\u0000/g, (_, index) => tokens[Number(index)] || '');
}

function markdownTableCells(line) {
  let value = String(line || '').trim();
  if (value.startsWith('|')) value = value.slice(1);
  if (value.endsWith('|')) value = value.slice(0, -1);
  return value.split(/(?<!\\)\|/).map(cell => cell.trim().replace(/\\\|/g, '|'));
}

function markdownBodyToHtml(markdown) {
  const lines = String(markdown || '').replace(/\r\n?/g, '\n').split('\n');
  const output = [];
  const isFence = line => /^\s*(```|~~~)/.test(line);
  const isTableDivider = line => /^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line);
  const isBlockStart = (line, index) => /^\s*(?:#{1,6}\s+|>|[-*+]\s+|\d+[.)]\s+|```|~~~)/.test(line)
    || /^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line)
    || (index + 1 < lines.length && line.includes('|') && isTableDivider(lines[index + 1]));

  for (let i = 0; i < lines.length;) {
    const line = lines[i];
    if (!line.trim()) { i += 1; continue; }

    const fence = line.match(/^\s*(```|~~~)\s*([\w+-]*)\s*$/);
    if (fence) {
      const code = [];
      i += 1;
      while (i < lines.length && !new RegExp(`^\\s*${fence[1]}`).test(lines[i])) code.push(lines[i++]);
      if (i < lines.length) i += 1;
      const language = fence[2] ? ` class="language-${escapeAttr(fence[2])}"` : '';
      output.push(`<pre><code${language}>${escapeHtml(code.join('\n'))}</code></pre>`);
      continue;
    }

    const heading = line.match(/^\s*(#{1,6})\s+(.+?)\s*#*\s*$/);
    if (heading) {
      const level = heading[1].length;
      output.push(`<h${level}>${markdownInlineToHtml(heading[2])}</h${level}>`);
      i += 1;
      continue;
    }
    if (/^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line)) {
      output.push('<hr>');
      i += 1;
      continue;
    }

    if (i + 1 < lines.length && line.includes('|') && isTableDivider(lines[i + 1])) {
      const headers = markdownTableCells(line);
      const alignments = markdownTableCells(lines[i + 1]).map(cell => {
        const left = cell.startsWith(':');
        const right = cell.endsWith(':');
        return left && right ? 'center' : (right ? 'right' : (left ? 'left' : ''));
      });
      i += 2;
      const rows = [];
      while (i < lines.length && lines[i].includes('|') && lines[i].trim()) rows.push(markdownTableCells(lines[i++]));
      const cells = (values, tag) => values.map((cell, index) => {
        const align = alignments[index] ? ` style="text-align:${alignments[index]}"` : '';
        return `<${tag}${align}>${markdownInlineToHtml(cell)}</${tag}>`;
      }).join('');
      output.push(`<div class="markdown-table-wrap"><table><thead><tr>${cells(headers, 'th')}</tr></thead><tbody>${rows.map(row => `<tr>${cells(row, 'td')}</tr>`).join('')}</tbody></table></div>`);
      continue;
    }

    if (/^\s*>/.test(line)) {
      const quote = [];
      while (i < lines.length && /^\s*>/.test(lines[i])) quote.push(lines[i++].replace(/^\s*>\s?/, ''));
      output.push(`<blockquote>${markdownBodyToHtml(quote.join('\n'))}</blockquote>`);
      continue;
    }

    const listMatch = line.match(/^\s*([-*+]|\d+[.)])\s+(.+)$/);
    if (listMatch) {
      const ordered = /^\d/.test(listMatch[1]);
      const tag = ordered ? 'ol' : 'ul';
      const items = [];
      while (i < lines.length) {
        const item = lines[i].match(/^\s*([-*+]|\d+[.)])\s+(.+)$/);
        if (!item || /^\d/.test(item[1]) !== ordered) break;
        let content = item[2];
        const task = content.match(/^\[([ xX])\]\s+(.+)$/);
        if (task) content = `<input type="checkbox" disabled${task[1].toLowerCase() === 'x' ? ' checked' : ''}> ${markdownInlineToHtml(task[2])}`;
        else content = markdownInlineToHtml(content);
        // 保留原始编号，供智能目录识别“1.”层级标题。
        const numberAttr = ordered ? ` data-article-list-number="${escapeAttr(item[1].replace(/[.)]$/, ''))}"` : '';
        items.push(`<li${numberAttr}>${content}</li>`);
        i += 1;
      }
      output.push(`<${tag}>${items.join('')}</${tag}>`);
      continue;
    }

    const paragraph = [line.replace(/^\s+/, '')];
    i += 1;
    while (i < lines.length && lines[i].trim() && !isFence(lines[i]) && !isBlockStart(lines[i], i)) paragraph.push(lines[i++].replace(/^\s+/, ''));
    const paragraphHtml = paragraph.map(part => markdownInlineToHtml(part.replace(/\s{2}$/, '')))
      .map((rendered, index) => `${index ? (/\s{2}$/.test(paragraph[index - 1]) ? '<br>' : ' ') : ''}${rendered}`)
      .join('');
    output.push(`<p>${paragraphHtml}</p>`);
  }
  return output.join('\n');
}

/**
 * 将法规正文中的语义目录项与后续同名章节标题建立跳转关系。
 *
 * 同一部法规内可能多次出现“第一章 一般规定”等同名标题，因此按正文
 * 出现顺序依次匹配，而不是只查找第一个同名节点。
 *
 * 返回 { html, toc }：html 为不含“系统自动生成目录”的正文；
 * toc 为侧栏智能目录条目（含原文自带目录与系统生成的目录）。
 */
function enhanceArticleTocHtml(html) {
  const root = document.createElement('div');
  root.innerHTML = html;

  // 兼容历史入库数据：旧版会把法条列举项、案号和裁判文书中的句子残片
  // 标成标题。只在显示层修复明确错误，不改写数据库中的原始正文。
  repairExistingArticleTocEntries(root);
  repairArticleBodyStructure(root);

  // 网页抓取和富文本粘贴通常只保留普通 <p>/<h*>，不会带 Word 导入时
  // 生成的 body-toc-* 语义类。先从“目录 + 后续重复章节标题”中恢复结构；
  // 若原文没有目录，但包含足够多的章/节或 HTML 标题，则自动生成目录。
  prepareArticleTocStructure(root);

  const tocEntries = Array.from(root.querySelectorAll('p.body-toc-entry, li.body-toc-entry'));
  const toc = [];

  if (tocEntries.length) {
    const lastTocEntry = tocEntries[tocEntries.length - 1];
    const headingCandidates = Array.from(root.querySelectorAll(
      'p.body-heading, p.body-heading-secondary, p.body-centered, li.body-heading, li.body-heading-secondary, h1, h2, h3, h4, h5, h6'
    )).filter(node => (
      lastTocEntry.compareDocumentPosition(node) & Node.DOCUMENT_POSITION_FOLLOWING
    ));

    const headingsByText = new Map();
    headingCandidates.forEach(heading => {
      const key = normalizeArticleHeadingText(articleTocText(heading));
      if (!key) return;
      if (!headingsByText.has(key)) headingsByText.set(key, []);
      headingsByText.get(key).push(heading);
    });

    let anchorIndex = 0;
    tocEntries.forEach(entry => {
      const entryText = articleTocText(entry);
      const key = normalizeArticleHeadingText(entryText);
      // 条文目录等生成器在条目上预置了 data-article-toc-target 锚点，
      // 直接沿用，无需再与同名标题匹配。
      const presetTarget = entry.getAttribute ? entry.getAttribute('data-article-toc-target') : null;
      const matches = presetTarget ? null : headingsByText.get(key);
      let targetKey = null;

      if (presetTarget) {
        targetKey = presetTarget;
      } else if (matches && matches.length) {
        const target = matches.shift();
        targetKey = String(anchorIndex++);
        target.setAttribute('data-article-toc-anchor', targetKey);

        const link = document.createElement('a');
        link.className = 'body-toc-link';
        link.href = '#';
        link.setAttribute('data-article-toc-target', targetKey);
        link.setAttribute('aria-label', `跳转到${entryText}`);
        link.setAttribute('title', '点击跳转到正文');
        link.setAttribute('onclick', 'return jumpToArticleToc(this);');
        while (entry.firstChild) link.appendChild(entry.firstChild);
        entry.appendChild(link);
      }

      // 空文本条目（如图片构成的目录行）不进入侧栏智能目录
      if (!entryText) return;
      // 层级优先按当前文本重新识别（编-章-节、一-（一）-1-（1）），
      // 历史入库数据没有层级属性或属性过旧时以此为准。预置锚点的条文
      // 目录条目固定按自身层级属性显示。
      const entryLevel = presetTarget
        ? (Number(entry.getAttribute('data-article-toc-level')) || 2)
        : (articleTocLevel(entry)
          || Number(entry.getAttribute('data-article-toc-level'))
          || 1);
      toc.push({
        text: entryText,
        level: entryLevel,
        targetKey,
      });
    });
  }

  // 「PDF 不解析为文本」页面版：按页生成智能目录（页面N：页面左上角小标题）。
  // 条目由后端以隐藏段落 pdf-page-toc-entry 存入正文，渲染时转为侧栏目录，
  // 点击滚动到对应页面图片并短暂高亮；隐藏段落不显示在正文中。
  const pdfTocEntries = Array.from(root.querySelectorAll('p.pdf-page-toc-entry'));
  if (pdfTocEntries.length) {
    const figureByPage = new Map();
    root.querySelectorAll('figure.pdf-page').forEach(figure => {
      const imgSrc = figure.querySelector('img.pdf-page-image')?.getAttribute('src') || '';
      const match = imgSrc.match(/page-(\d{3,4})\.(?:png|jpe?g)$/);
      if (match) figureByPage.set(Number(match[1]), figure);
    });
    pdfTocEntries.forEach(entry => {
      const text = String(entry.textContent || '').trim();
      const match = text.match(/^页面(\d{1,4})[：:]\s*(.*)$/);
      const pageNo = match ? Number(match[1]) : 0;
      const pageTitle = match ? String(match[2] || '').trim() : '';
      const figure = figureByPage.get(pageNo);
      if (!figure) return;
      const targetKey = `pdf-page-${pageNo}`;
      figure.setAttribute('data-article-toc-anchor', targetKey);
      const cleanTitle = pdfTitleIsNoise(pageTitle) ? '' : pageTitle;
      toc.push({
        text: cleanTitle ? `页面${pageNo}：${cleanTitle}` : `页面${pageNo}`,
        level: 2,
        targetKey,
      });
    });
    pdfTocEntries.forEach(entry => entry.remove());
  }

  // 系统自动生成的目录只显示在左侧智能目录栏，不再插入正文。
  // 原文自带的目录（如 Word 导入）保持原样。
  root.querySelectorAll('p.body-toc-generated').forEach(node => node.remove());

  return { html: root.innerHTML, toc };
}

function normalizeArticleHeadingText(value) {
  return String(value || '')
    .replace(/[\s\u00a0\u3000]+/g, '')
    .replace(/[：:]+$/g, '')
    .trim();
}

function isMajorNumberedArticleHeading(value) {
  const text = String(value || '').replace(/[\s\u00a0\u3000]+/g, '').trim();
  if (text.length > 50 || !/^[一二三四五六七八九十百千零〇两\d]{1,3}[、.．]/.test(text)) return false;
  // 仅允许逗号作为标题内部的分隔符；分号、句号和问叹号仍表示正文。
  if (/[；;。！？?!]/.test(text)) return false;
  // “一、二审”“一、二次”等是固定并列表达，不是章节标题。
  return !/^[一二三四五六七八九十百千零〇两\d]{1,3}、[一二三四五六七八九十百千零〇两\d]{1,3}(?:审|次|项|条|款|人|个|级|类|方|部分|阶段|年度|月份|方面)/.test(text);
}

function articleHeadingLevel(node) {
  const text = String(node && node.textContent || '').replace(/[\s\u00a0\u3000]+/g, ' ').trim();
  if (!text || text.length > 100) return 0;

  const tag = String(node.tagName || '').toLowerCase();
  // 编辑器生成的有序提纲列表项（带编号标签），是用户明确设置的提纲层级，
  // 句末句号不影响其标题身份。
  if (tag === 'li' && node.getAttribute && node.getAttribute('data-list-label')) {
    const liLevel = Number(node.getAttribute('data-list-level')) || 1;
    return Math.min(3, liLevel);
  }
  if (/[。！？?!]$/.test(text)) return 0;

  if (/^h[1-6]$/.test(tag)) return Math.min(parseInt(tag.slice(1), 10), 3);
  // 网页和 Word 转换结果经常会丢失“章/节”后的空格，例如“第三章管理人”。
  if (/^第[一二三四五六七八九十百千零〇两\d]+(?:编|部分)/.test(text)) return 1;
  if (/^第[一二三四五六七八九十百千零〇两\d]+章/.test(text)) return 1;
  if (/^(?:第[一二三四五六七八九十百千零〇两\d]+节|附则|附录)/.test(text)) return 2;

  if (isMajorNumberedArticleHeading(text)) return 1;

  // 培训讲义、PPT 等文章用（一）/1、/问题N 作提纲编号。这类编号在法条和
  // 判决中通常是正文列举，只有短小且无句读的才按提纲层级纳入目录：
  // （一）→ 二级，1、→ 三级，问题N → 二级。
  const outlineLike = text.length <= 50 && !/[，,；;。！？?!]/.test(text);
  if (outlineLike && /^[（(][一二三四五六七八九十百千零〇两\d]{1,3}[）)]/.test(text)) return 2;
  if (outlineLike && /^\d{1,3}[、.．)）]/.test(text)) return 3;
  if (outlineLike && /^问题[一二三四五六七八九十百千零〇两\d]{1,3}[、.．:：]?/.test(text)) return 2;

  // 非法规文章（案例汇编、专业文章）没有“章/节”编号，使用已经过
  // 保守分类器确认的语义标题层级生成目录。
  if (node.classList && node.classList.contains('body-heading')) return 1;
  if (node.classList && (
    node.classList.contains('body-heading-secondary')
    || node.classList.contains('body-label-heading')
  )) return 2;
  return 0;
}

/**
 * 目录条目展示文本。Markdown 有序列表会把“1.”编号剥进
 * data-article-list-number，这里还原出“1. 标题”形式的完整文本。
 */
function articleTocText(node) {
  if (!node) return '';
  const text = String(node.textContent || '').trim();
  const number = node.getAttribute ? node.getAttribute('data-article-list-number') : null;
  if (number) return `${number}. ${text}`;
  const label = node.getAttribute ? node.getAttribute('data-list-label') : null;
  if (label) return `${label} ${text}`;
  return text;
}

/**
 * 智能目录用细粒度层级（1-4）。与 articleHeadingLevel 不同，这里把
 * “编-章-节”区分开（1/2/3），并识别“一、（一）1.（1）”多级编号
 * （1/2/3/4），供侧栏目录按字号/颜色区分等级。
 */
function articleTocLevel(node) {
  const text = String(node && node.textContent || '').replace(/[\s\u00a0\u3000]+/g, ' ').trim();
  if (!text || text.length > 100) return 0;

  const compact = text.replace(/\s+/g, '');
  const tag = String(node.tagName || '').toLowerCase();
  // 编辑器有序提纲列表项：按列表层级（1-3）显示。
  if (tag === 'li' && node.getAttribute && node.getAttribute('data-list-label')) {
    return Math.min(4, Number(node.getAttribute('data-list-level')) || 1);
  }
  if (/[。！？?!]$/.test(text)) return 0;

  if (/^h[1-4]$/.test(tag)) return parseInt(tag.slice(1), 10);
  if (/^h[5-6]$/.test(tag)) return 4;

  // 编-章-节：民法典等法规的稳定层级。
  if (/^第[一二三四五六七八九十百千零〇两\d]+(?:分编|编|部分)/.test(compact)) return 1;
  if (/^第[一二三四五六七八九十百千零〇两\d]+章/.test(compact)) return 2;
  if (/^第[一二三四五六七八九十百千零〇两\d]+节/.test(compact)) return 3;
  if (/^(?:附则|附录)/.test(compact)) return 2;

  // 一、（一）1.（1）多级编号标题。含句子标点或过长的行视为正文列举。
  if (!/[，,；;。！？?!]/.test(text)) {
    if (/^[（(][一二三四五六七八九十百千零〇两]{1,3}[）)]/.test(compact)) return 2;
    if (/^[（(]\d{1,3}[）)]/.test(compact)) return 4;
    if (/^\d{1,3}[.．、)）]/.test(compact) && !/^\d{1,3}[.．]\d/.test(compact)) return 3;
    if (/^[一二三四五六七八九十百千零〇两]{1,3}[、.．]/.test(compact)) return 1;
    if (/^问题[一二三四五六七八九十百千零〇两\d]{1,3}[、.．:：]?/.test(compact)) return 2;
  }
  if (isMajorNumberedArticleHeading(text)) return 1;

  // Markdown 有序列表项（编号剥入 data-article-list-number）。
  if (tag === 'li' && /^\d{1,3}$/.test(node.getAttribute('data-article-list-number') || '')) return 3;

  // 语义标题类作为兜底。
  if (node.classList && node.classList.contains('body-heading')) return 1;
  if (node.classList && (
    node.classList.contains('body-heading-secondary')
    || node.classList.contains('body-label-heading')
  )) return 2;
  return 0;
}

/** 深层编号标题（（一）/1./（1））层级，供“一、（一）1.（1）”体例文章使用。 */
function minorNumberedHeadingLevel(node) {
  const text = String(node && node.textContent || '').replace(/[\s\u00a0\u3000]+/g, ' ').trim();
  if (!text || text.length > 30 || /[，,；;。！？?!]/.test(text)) return 0;
  const compact = text.replace(/\s+/g, '');
  if (/^[（(][一二三四五六七八九十百千零〇两]{1,3}[）)]/.test(compact)) return 2;
  if (/^[（(]\d{1,3}[）)]/.test(compact)) return 4;
  if (/^\d{1,3}[.．、)）]/.test(compact) && !/^\d{1,3}[.．]\d/.test(compact)) return 3;
  if (String(node.tagName || '').toLowerCase() === 'li'
      && /^\d{1,3}$/.test(node.getAttribute('data-article-list-number') || '')) return 3;
  return 0;
}

/**
 * 修复法规来源中常见的两个粘连排版问题：
 *  1. “目　录第一章　总则”被放在同一段；
 *  2. “第三章　管理人第二十二条……”的章节标题与首条正文粘在同一段。
 *
 * 这里只拆分明确的法律结构标记，不对普通自然段做主观断句。
 */
function splitMergedLegalStructureBlocks(root) {
  const cnNumber = '[一二三四五六七八九十百千零〇两\\d]+';
  const blocks = Array.from(root.querySelectorAll('p, h1, h2, h3, h4, h5, h6'));

  blocks.forEach(node => {
    const rawText = String(node.textContent || '').trim();
    const tocMatch = rawText.match(/^目[\s\u00a0\u3000]*录[\s\u00a0\u3000]*(.+)$/);
    if (!tocMatch) return;

    const remainder = tocMatch[1].trim();
    const probe = document.createElement('p');
    probe.textContent = remainder;
    if (!articleHeadingLevel(probe)) return;

    const tocHeading = document.createElement('p');
    tocHeading.className = 'body-toc-heading';
    tocHeading.textContent = '目录';
    node.parentNode.insertBefore(tocHeading, node);
    node.textContent = remainder;
  });

  Array.from(root.querySelectorAll('p')).forEach(node => {
    if (node.classList.contains('body-toc-heading')) return;
    const rawText = String(node.textContent || '').trim();
    const mergedHeading = rawText.match(new RegExp(
      `^((?:第${cnNumber}章|第${cnNumber}节)[\\s\\u00a0\\u3000]*[\\u4e00-\\u9fffA-Za-z0-9、·]{1,30}?)(?=第${cnNumber}条)`
    ));
    if (!mergedHeading) return;

    const headingText = mergedHeading[1].trim();
    const bodyText = rawText.slice(mergedHeading[1].length).trim();
    if (!bodyText) return;

    const headingProbe = document.createElement('p');
    headingProbe.textContent = headingText;
    const heading = document.createElement('p');
    heading.className = articleHeadingLevel(headingProbe) === 1
      ? 'body-heading'
      : 'body-heading-secondary';
    heading.textContent = headingText;
    node.parentNode.insertBefore(heading, node);
    node.classList.remove('body-heading', 'body-heading-secondary');
    node.textContent = bodyText;
  });
}

/**
 * 为网页抓取、直接粘贴和旧纯文本恢复/生成正文目录结构。
 * 仅在至少两个目录项能与后文同名标题配对时认定为目录，避免把普通列表
 * 误识别为导航；自动生成目录时要求至少三个结构标题。
 */
function prepareArticleTocStructure(root) {
  // 「PDF 不解析为文本」页面版正文由逐页图片 + 隐藏文字层组成，目录
  // 由专门的 pdf-page-toc-entry 规则按页面顺序生成。跳过通用标题识别，
  // 避免隐藏文字层中的零散标题混入目录、打乱页面顺序。
  if (root.querySelector('.pdf-page-gallery')) return;

  splitMergedLegalStructureBlocks(root);

  // 兼容历史入库数据：空目录占位段（段落还在、文字已删空）和存进正文的
  // “系统生成目录”都会让下方判定提前退出，先清理再决定是否生成目录。
  Array.from(root.querySelectorAll('p.body-toc-heading, p.body-toc-entry')).forEach(node => {
    const empty = !String(node.textContent || '').replace(/[\s\u00a0\u3000]/g, '');
    if (empty || node.classList.contains('body-toc-generated')) node.remove();
  });

  const blocks = Array.from(root.querySelectorAll('p, h1, h2, h3, h4, h5, h6, li'));
  if (!blocks.length || root.querySelector('p.body-toc-entry')) return;

  const tocTitleIndex = blocks.findIndex(node => (
    /^目录(?:[：:]|$)/.test(normalizeArticleHeadingText(node.textContent))
  ));
  if (tocTitleIndex >= 0) {
    const tocTitle = blocks[tocTitleIndex];
    const possibleEntries = [];
    const seen = new Set();

    for (let i = tocTitleIndex + 1; i < blocks.length; i += 1) {
      const node = blocks[i];
      const text = String(node.textContent || '').trim();
      if (!text) continue;
      const key = normalizeArticleHeadingText(text);
      const level = articleHeadingLevel(node);

      // 目录后的首个重复标题通常就是正文开始处。
      if (possibleEntries.length && seen.has(key)) break;
      // 目录条目可含编/章/节等多级结构（“第一编 总则 / 第一章 / 第一节”），
      // 只要是标题就继续收集，直到正文开始；条目显示层级由 articleTocLevel
      // 细分，培训提纲等（一）/1、编号项组成的目录同样保留三级结构。
      // 目录页内偶有排版残片（换行拆断的标题残段）与目录后的正文段落，
      // 一律跳过而非终止收集，避免第三编之后的章节条目全部丢失。
      if (level <= 0) continue;
      possibleEntries.push({ node, key, level, index: i });
      seen.add(key);
    }

    const matchedEntries = [];
    possibleEntries.forEach(entry => {
      const target = blocks.slice(entry.index + 1).find(node => (
        normalizeArticleHeadingText(articleTocText(node)) === entry.key
      ));
      if (target) matchedEntries.push({ ...entry, target });
    });

    // 目录页条目须与正文标题高度对应（≥75%）才视为完整的原文目录；
    // 否则回退自动生成，避免 PPT 等“目录页只列部分内容”的文章只得到
    // 残缺目录（此前只凭 >=2 条即采用，曾把培训 PPT 目录截断）。
    if (matchedEntries.length >= 2
        && matchedEntries.length * 4 >= possibleEntries.length * 3) {
      tocTitle.classList.add('body-toc-heading');
      matchedEntries.forEach(({ node, target, level }) => {
        node.classList.add('body-toc-entry');
        node.setAttribute('data-article-toc-level', String(level));
        if (!target.matches('h1, h2, h3, h4, h5, h6')) {
          target.classList.add(level === 1 ? 'body-heading' : 'body-heading-secondary');
        }
      });
      return;
    }
  }

  // 没有现成目录时，根据明确的章/节标题或 HTML 标题自动生成。
  let headingCandidates = blocks.filter(node => {
    if (node.closest('.body-toc-heading, .body-toc-entry')) return false;
    return articleHeadingLevel(node) > 0;
  });
  // 同一标题常同时出现在文章开头的提纲与正文中，目录只保留同一大标题
  // 下的首次出现项。案例汇编会在每个大标题下重复“裁判要旨 / 基本案情 /
  // 裁判结果”等栏目名，不能再用全局去重，否则第二部分起的小标题会全部丢失。
  {
    const seenHeadingKeys = new Set();
    let currentMajorKey = '';
    headingCandidates = headingCandidates.filter(node => {
      const key = normalizeArticleHeadingText(String(node.textContent || ''));
      if (!key) return false;
      if (articleTocLevel(node) === 1) currentMajorKey = key;
      const scopedKey = `${currentMajorKey}\u0000${key}`;
      if (seenHeadingKeys.has(scopedKey)) return false;
      seenHeadingKeys.add(scopedKey);
      return true;
    });
  }
  // “一、（一）1.（1）”多级编号：只有文章确实采用“一、二、”这种大标题
  // 编号体系时，才把深层编号行作为子标题纳入目录，避免普通列举项误入目录。
  const majorNumberedCount = headingCandidates.filter(node => (
    /^[一二三四五六七八九十百千零〇两]{1,3}[、.．]/
      .test(String(node.textContent || '').replace(/[\s\u00a0\u3000]+/g, ''))
  )).length;
  if (majorNumberedCount >= 2) {
    const usedMinorKeys = new Set(headingCandidates.map(node => (
      normalizeArticleHeadingText(String(node.textContent || ''))
    )));
    const minorBlocks = blocks.filter(node => {
      if (headingCandidates.includes(node)) return false;
      if (node.closest && node.closest('.body-toc-heading, .body-toc-entry')) return false;
      if (minorNumberedHeadingLevel(node) <= 0) return false;
      const key = normalizeArticleHeadingText(String(node.textContent || ''));
      if (!key || usedMinorKeys.has(key)) return false;
      usedMinorKeys.add(key);
      return true;
    });
    if (minorBlocks.length) {
      headingCandidates = headingCandidates.concat(minorBlocks)
        .sort((a, b) => blocks.indexOf(a) - blocks.indexOf(b));
    }
  }
  // 超大型汇编若把数百个小标题全部铺进目录，反而无法使用。此时只保留
  // “编/章/部分”顶层结构；没有足够顶层结构则不自动生成目录。
  if (headingCandidates.length > 150) {
    headingCandidates = headingCandidates.filter(node => (
      /^第[一二三四五六七八九十百千零〇两\d]+(?:分编|编|章|部分)/
        .test(String(node.textContent || '').replace(/[\s\u00a0\u3000]+/g, ''))
    ));
  }
  if (headingCandidates.length > 120) headingCandidates = [];
  if (headingCandidates.length < 3) {
    // 未分章节的法律法规（全文只有具体条款、没有任何编/章/节或提纲
    // 标题）按“条文序号 + 该条文前十字 + 省略号”生成条文目录。
    if (!headingCandidates.length) buildUnchaptersedStatuteToc(root, blocks);
    return;
  }

  const tocHeading = document.createElement('p');
  tocHeading.className = 'body-toc-heading body-toc-generated';
  tocHeading.textContent = '目录';
  const fragment = document.createDocumentFragment();
  fragment.appendChild(tocHeading);

  headingCandidates.forEach(heading => {
    const level = articleTocLevel(heading);
    const entry = document.createElement('p');
    entry.className = 'body-toc-entry body-toc-generated';
    entry.setAttribute('data-article-toc-level', String(level));
    entry.textContent = articleTocText(heading);
    fragment.appendChild(entry);

    // 文章开头提纲页的条目在正文中通常有同名段落：跳转目标指向正文那一处，
    // 提纲页本身保持原样；没有同名段落时以条目自身为目标。
    const entryKey = normalizeArticleHeadingText(articleTocText(heading));
    const headingIndex = blocks.indexOf(heading);
    const target = headingIndex >= 0
      ? blocks.slice(headingIndex + 1).find(node => (
        normalizeArticleHeadingText(articleTocText(node)) === entryKey
      ))
      : null;
    const anchorNode = target || heading;
    if (anchorNode && !anchorNode.matches('h1, h2, h3, h4, h5, h6')) {
      anchorNode.classList.add(level === 1 ? 'body-heading' : 'body-heading-secondary');
    }
  });

  let tocAnchor = headingCandidates[0];
  while (tocAnchor && tocAnchor.parentNode && tocAnchor.parentNode !== root) tocAnchor = tocAnchor.parentNode;
  if (tocAnchor && tocAnchor.parentNode === root) root.insertBefore(fragment, tocAnchor);
  else root.appendChild(fragment);
}

/**
 * 中文条文序号转数值（“二十一”→21，“一〇三”→103），纯数字直接返回。
 * 无法解析时返回 null。
 */
function cnArticleNumberToInt(raw) {
  const s = String(raw || '').replace(/[\s\u00a0\u3000]+/g, '');
  if (!s) return null;
  if (/^\d+$/.test(s)) return Number(s);
  const DIGIT = { 零: 0, 〇: 0, 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 };
  let total = 0;
  let section = 0;
  let number = 0;
  for (const ch of s) {
    if (ch === '十' || ch === '百' || ch === '千') {
      const base = ch === '十' ? 10 : ch === '百' ? 100 : 1000;
      section += (number || 1) * base;
      number = 0;
    } else if (ch === '万' || ch === '亿') {
      total = (total + section + number) * (ch === '万' ? 10000 : 100000000);
      section = 0;
      number = 0;
    } else {
      const digit = DIGIT[ch];
      if (digit === undefined) return null;
      number = digit;
    }
  }
  return total + section + number;
}

/**
 * 未分章节的法律法规智能目录：条文序号 + 该条文前十字 + 省略号。
 *
 * 支持“第X条”与“1.”两种条文编号（含序号独占一段、正文紧随其后的
 * 排版）；仅当全文没有任何编/章/节结构标题、条文数不少于 3 条、序号
 * 严格递增且条文覆盖正文主体时生成，避免普通文章中的法条引用和
 * “1.”列举被误生成为目录。
 */
function buildUnchaptersedStatuteToc(root, blocks) {
  // 有编/章/节/附则/附录结构标题的文章不适用条文目录规则。
  const hasStructuralHeading = blocks.some(node => {
    const compact = String(node.textContent || '').replace(/[\s\u00a0\u3000]+/g, '');
    return /^第[一二三四五六七八九十百千零〇两\d]+(?:分编|编|章|节|部分)/.test(compact)
      || /^(?:附则|附录)/.test(compact);
  });
  if (hasStructuralHeading) return false;

  const CN_SEQ_RE = /^第([一二三四五六七八九十百千零〇两\d]+)条([\s\u00a0\u3000]*)([\s\S]*)$/;
  const NUM_SEQ_RE = /^(\d{1,3})[.．]([\s\u00a0\u3000]*)([\s\S]*)$/;

  const findNextBodyBlock = from => {
    for (let j = from + 1; j < blocks.length; j += 1) {
      const cand = blocks[j];
      const cls = String(cand.className || '');
      if (cls.includes('body-toc') || cls.includes('body-image') || cls.includes('pdf-source-text')) continue;
      const t = String(cand.textContent || '').replace(/[\s\u00a0\u3000]+/g, '');
      if (!t) continue;
      if (CN_SEQ_RE.test(t) || NUM_SEQ_RE.test(t)) continue;
      return cand;
    }
    return null;
  };

  const items = [];
  blocks.forEach((node, index) => {
    const cls = String(node.className || '');
    if (cls.includes('body-toc') || cls.includes('body-image') || cls.includes('pdf-source-text')) return;
    const fullText = String(node.textContent || '').replace(/[\s\u00a0\u3000]+/g, ' ').trim();
    if (!fullText) return;

    const cnMatch = fullText.match(CN_SEQ_RE);
    if (cnMatch) {
      const number = cnArticleNumberToInt(cnMatch[1]);
      if (number === null) return;
      let bodyNode = node;
      let bodyText = String(cnMatch[3] || '').replace(/[\s\u00a0\u3000]+/g, '');
      if (!bodyText) {
        const next = findNextBodyBlock(index);
        if (!next) return;
        bodyNode = next;
        bodyText = String(next.textContent || '').replace(/[\s\u00a0\u3000]+/g, '');
      }
      items.push({ node, seqText: `第${cnMatch[1]}条`, number, bodyNode, bodyText, style: 'cn' });
      return;
    }

    if (/^\d{1,3}[.．]\d/.test(fullText)) return;
    const numMatch = fullText.match(NUM_SEQ_RE);
    if (numMatch) {
      let bodyNode = node;
      let bodyText = String(numMatch[3] || '').replace(/[\s\u00a0\u3000]+/g, '');
      if (!bodyText) {
        const next = findNextBodyBlock(index);
        if (!next) return;
        bodyNode = next;
        bodyText = String(next.textContent || '').replace(/[\s\u00a0\u3000]+/g, '');
      }
      items.push({ node, seqText: `${numMatch[1]}.`, number: Number(numMatch[1]), bodyNode, bodyText, style: 'num' });
    }
  });

  if (items.length < 3) return false;
  // 同一篇法规只使用一种条文编号，混用两种编号视为普通文章。
  const cnCount = items.filter(item => item.style === 'cn').length;
  if (cnCount > 0 && cnCount < items.length) return false;

  // 条文序号必须严格递增；正文不足 8 字的块不是有效条文。
  let prevNumber = null;
  const validItems = [];
  items.forEach(item => {
    if (item.bodyText.length < 8) return;
    if (prevNumber !== null && item.number <= prevNumber) return;
    prevNumber = item.number;
    validItems.push(item);
  });
  if (validItems.length < 3) return false;
  // “1.”条文编号必须从 1 开始；“第X条”允许从任意一条开始（节选）。
  if (validItems[0].style === 'num' && validItems[0].number !== 1) return false;

  // 条文序列（序号块 + 条文正文）至少覆盖正文三成，才认定全文由条款构成。
  const meaningfulBlocks = blocks.filter(node => {
    const cls = String(node.className || '');
    if (cls.includes('body-toc') || cls.includes('body-image') || cls.includes('pdf-source-text')) return false;
    return Boolean(String(node.textContent || '').replace(/[\s\u00a0\u3000]+/g, ''));
  }).length;
  if (meaningfulBlocks > 0 && validItems.length * 2 < meaningfulBlocks * 0.3) return false;

  const tocHeading = document.createElement('p');
  tocHeading.className = 'body-toc-heading body-toc-generated';
  tocHeading.textContent = '目录';
  const fragment = document.createDocumentFragment();
  fragment.appendChild(tocHeading);

  validItems.forEach((item, index) => {
    const excerpt = item.bodyText.slice(0, 10);
    const entry = document.createElement('p');
    entry.className = 'body-toc-entry body-toc-generated';
    entry.setAttribute('data-article-toc-level', '2');
    const targetKey = `statute-${index}`;
    entry.setAttribute('data-article-toc-target', targetKey);
    entry.textContent = `${item.seqText}${item.style === 'cn' ? ' ' : ''}${excerpt}${excerpt ? '…' : ''}`;
    fragment.appendChild(entry);
    item.node.setAttribute('data-article-toc-anchor', targetKey);
  });

  let tocAnchor = blocks[0];
  while (tocAnchor && tocAnchor.parentNode && tocAnchor.parentNode !== root) tocAnchor = tocAnchor.parentNode;
  if (tocAnchor && tocAnchor.parentNode === root) root.insertBefore(fragment, tocAnchor);
  else root.appendChild(fragment);
  return true;
}

/** 点击法规目录项后，在当前文章内滚动到对应章节并短暂高亮。 */
function jumpToArticleToc(link) {
  const articleRoot = link && link.closest('.tab-article-body-text, .detail-body, .tab-page-body');
  if (!articleRoot) return false;

  const targetKey = link.getAttribute('data-article-toc-target');
  if (targetKey === null) return false;
  const target = articleRoot.querySelector(`[data-article-toc-anchor="${targetKey}"]`);
  if (!target) return false;

  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  target.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });

  if (target._articleTocHighlightTimer) clearTimeout(target._articleTocHighlightTimer);
  target.classList.remove('body-toc-target-flash');
  void target.offsetWidth;
  target.classList.add('body-toc-target-flash');
  target._articleTocHighlightTimer = setTimeout(() => {
    target.classList.remove('body-toc-target-flash');
    target._articleTocHighlightTimer = null;
  }, 1800);

  return false;
}

/**
 * 渲染左侧智能目录栏的目录项。targetKey 存在时可点击跳转到正文。
 * bodyElId 为目标正文容器（detail-body 或 tab-detail-body-*）的 id。
 */
function renderSidebarTocHtml(toc, bodyElId) {
  if (!Array.isArray(toc) || !toc.length) {
    return '<div class="sidebar-toc-empty">本文暂无目录</div>';
  }
  // 只有一个层级时，目录是平铺的章节列表，不需要用一级标题样式强调。
  // “前言/引言”等文章前置标题有时会被语义分类器标成二级，但在目录结构中
  // 与“一、二、三……”同属顶层，不能因此把平铺目录误判为多层目录。
  const tocLevels = new Set(toc.map(item => {
    const level = Number(item && item.level) || 1;
    const normalizedText = String(item && item.text || '').replace(/[\s\u00a0\u3000]+/g, '');
    return level > 1 && /^(?:前言|引言|序言|导言)$/.test(normalizedText) ? 1 : level;
  }));
  const isSingleLevel = tocLevels.size === 1;
  return toc.map(item => {
    const text = escapeHtml(String(item.text || ''));
    const level = Number(item.level) || 1;
    const levelCls = level >= 4 ? 'level-4' : (level === 3 ? 'level-3' : (level === 2 ? 'level-2' : 'level-1'));
    const singleLevelCls = isSingleLevel ? ' single-level' : '';
    if (item.targetKey !== null && item.targetKey !== undefined && item.targetKey !== '') {
      return `<a class="sidebar-toc-link ${levelCls}${singleLevelCls}" href="#" data-article-toc-target="${escapeHtml(String(item.targetKey))}"
        onclick="return jumpToSidebarToc(this, '${escapeHtml(String(bodyElId))}')" title="点击跳转到正文">${text}</a>`;
    }
    return `<span class="sidebar-toc-item ${levelCls}${singleLevelCls}">${text}</span>`;
  }).join('');
}

/** 点击侧栏智能目录项后，在正文容器内滚动到对应章节并短暂高亮。 */
function jumpToSidebarToc(link, bodyElId) {
  const targetKey = link && link.getAttribute('data-article-toc-target');
  if (targetKey === null) return false;

  let body = null;
  if (bodyElId) body = document.getElementById(bodyElId);
  if (!body) {
    const modalRoot = link && link.closest('.modal-detail');
    body = modalRoot ? modalRoot.querySelector('.detail-body') : null;
  }
  if (!body) return false;

  const target = body.querySelector(`[data-article-toc-anchor="${targetKey}"]`);
  if (!target) return false;

  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  target.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });

  if (target._articleTocHighlightTimer) clearTimeout(target._articleTocHighlightTimer);
  target.classList.remove('body-toc-target-flash');
  void target.offsetWidth;
  target.classList.add('body-toc-target-flash');
  target._articleTocHighlightTimer = setTimeout(() => {
    target.classList.remove('body-toc-target-flash');
    target._articleTocHighlightTimer = null;
  }, 1800);

  return false;
}

/**
 * 渲染弹窗模式下左侧摘要栏（上半：摘要，下半：智能目录）。
 * 鼠标悬停某一区域时该区域自动展开占满整个侧栏。
 */
function renderModalDetailSidebar(summary, toc) {
  const el = $('detail-summary');
  if (!el) return;

  const hasSummary = Boolean(String(summary || '').trim());
  const hasToc = Array.isArray(toc) && toc.length > 0;
  el.classList.toggle('has-content', hasSummary || hasToc);

  el.innerHTML = `
    <div class="sidebar-panes" data-toc-empty="${hasToc ? 'false' : 'true'}">
      <section class="sidebar-pane pane-toc"
        onmouseenter="if(this.parentNode.dataset.tocEmpty!=='true') this.parentNode.dataset.expand='toc'"
        onmouseleave="if(this.parentNode.dataset.tocEmpty!=='true'&&this.parentNode.dataset.expand==='toc') delete this.parentNode.dataset.expand">
        <header class="sidebar-pane-header"><span class="sidebar-pane-title">智能目录</span></header>
        <div class="sidebar-pane-body sidebar-toc-list">${renderSidebarTocHtml(toc, 'detail-body')}</div>
      </section>
      <section class="sidebar-pane pane-summary"
        onmouseenter="if(this.parentNode.dataset.tocEmpty!=='true') this.parentNode.dataset.expand='summary'"
        onmouseleave="if(this.parentNode.dataset.tocEmpty!=='true'&&this.parentNode.dataset.expand==='summary') delete this.parentNode.dataset.expand">
        <header class="sidebar-pane-header">
          <span class="sidebar-pane-title">摘要</span>
          <button class="btn-edit-summary sidebar-summary-edit" id="summary-edit-btn" type="button" title="编辑摘要" onclick="enableEditSummary()">
            <svg width="13" height="13" viewBox="0 0 14 14"><path d="M3 10l8-8 3 3-8 8z" stroke="currentColor" stroke-width="1.4" fill="none"/><path d="M11 2v3M11 5h3" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>
            编辑
          </button>
        </header>
        <div class="sidebar-pane-body markdown-summary detail-summary-text">${
          hasSummary ? renderSummaryMarkdown(summary) : '<p class="sidebar-empty-hint">暂无摘要</p>'
        }</div>
      </section>
    </div>
  `;
}

/** 目录是否为空发生变化时复位悬停展开状态，并同步折叠标记。 */
function setSidebarTocEmptyState(panes, hasToc) {
  if (!panes) return;
  const isEmpty = !hasToc;
  if ((panes.dataset.tocEmpty === 'true') !== isEmpty) delete panes.dataset.expand;
  panes.dataset.tocEmpty = isEmpty ? 'true' : 'false';
}

/** 更新弹窗模式侧栏中的摘要区，保留智能目录与展开状态。 */
function renderLegacyDetailSummary(element, summary) {
  if (!element) return;
  const textEl = element.querySelector('.detail-summary-text');
  const hasSummary = Boolean(String(summary || '').trim());
  if (textEl) {
    textEl.innerHTML = hasSummary ? renderSummaryMarkdown(summary) : '<p class="sidebar-empty-hint">暂无摘要</p>';
  } else {
    element.innerHTML = `<div class="markdown-summary">${renderSummaryMarkdown(summary)}</div>`;
  }
  const hasToc = Boolean(element.querySelector('.sidebar-toc-link, .sidebar-toc-item'));
  element.classList.toggle('has-content', hasSummary || hasToc);
  setSidebarTocEmptyState(element.querySelector('.sidebar-panes'), hasToc);
}

/** 正文保存/更新后，仅刷新弹窗模式侧栏的智能目录，保留摘要与展开状态。 */
function refreshModalSidebarToc(toc) {
  const el = $('detail-summary');
  if (!el) return;
  const tocList = el.querySelector('.sidebar-toc-list');
  if (!tocList) return;
  tocList.innerHTML = renderSidebarTocHtml(toc, 'detail-body');
  setSidebarTocEmptyState(el.querySelector('.sidebar-panes'), Array.isArray(toc) && toc.length > 0);
  const hasSummary = Boolean(String(state.currentArticle?.summary || '').trim());
  el.classList.toggle('has-content', hasSummary || (Array.isArray(toc) && toc.length > 0));
}

/** 正文保存/更新后，仅刷新标签页侧栏的智能目录，保留摘要与展开状态。 */
function refreshTabSidebarToc(tabId, toc) {
  if (!tabId) return;
  const pageEl = document.getElementById(tabId);
  const tocList = pageEl?.querySelector('.sidebar-toc-list');
  if (!tocList) return;
  tocList.innerHTML = renderSidebarTocHtml(toc, `tab-detail-body-${tabId}`);
  setSidebarTocEmptyState(pageEl.querySelector('.sidebar-panes'), Array.isArray(toc) && toc.length > 0);
}

/**
 * 将旧版纯文本（含 <b>/<i>/<u> 标记）转为 HTML。
 *
 * 修复的问题：
 *  1. CRLF 换行（\r\n\r\n）无法被 \n{2,} 分段 → 改用通用正则
 *  2. \xa0（不换行空格）保留在文字中显示乱 → 统一替换为普通空格
 *  3. 段落内单换行被 join('') 丢弃 → 改用 join(' ') 保留间隔
 *  4. 极短纯字段名（≤10字、无标点）误入普通段落 → 额外识别为小标题
 *  5. 尊重后端/源文给出的双换行，避免前端再次合并标题、署名和目录项
 */
function legacyTextToHtml(text) {
  // ── 预处理 ──────────────────────────────────────────
  // 1. 统一换行：\r\n → \n，单独 \r → \n
  text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  // 2. 替换不换行空格 \xa0 为普通空格
  text = text.replace(/\xa0/g, ' ');
  // 3. 只清理同一物理行内的完整图片标记。旧规则允许跨行查找右括号，
  // 当微信图片标记本身缺少“]”时，会一直吞到后文脚注的“]”，造成整段正文丢失。
  text = text.replace(/\[图片:[^\]\r\n]*\]/g, m => m.replace(/[\r\n]+/g, ' '));

  // 修正图片标记正则：支持不完整的标记（缺少右括号的情况）
  const IMAGE_FULL_RE  = /^\[图片:\s*(https?:[^\]\s]+(?:[^\]\s]*))/;
  const IMAGE_INLINE_RE = /\[图片:\s*(https?:[^\]\s]+(?:[^\]\s]*))/g;

  // ── 分段：双换行为段边界 ────────────────────────────
  const originalBlocks = text.split(/\n{2,}/);
  const blocks = [];
  originalBlocks.forEach(block => {
    const singleLines = block.split('\n').map(line => line.trim()).filter(Boolean);
    const hasTocTitle = singleLines.some(line => /^目录(?:\s*[：:]\s*)?$/.test(line.replace(/<[^>]+>/g, '').trim()));
    const structuralLineCount = singleLines.filter(line => {
      const type = classifyLegacyTextBlock(line);
      return type === 'body-heading' || type === 'body-heading-secondary';
    }).length;
    // 直接粘贴的纯文本有时只有单换行。遇到明确的目录结构时保留每一行，
    // 否则继续沿用旧逻辑，将网页硬换行合并为一个自然段。
    if (hasTocTitle && structuralLineCount >= 2) blocks.push(...singleLines);
    else blocks.push(block);
  });

  const parts = blocks.map(block => {
    // 去除行首尾空白；保留非空行
    const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
    if (!lines.length) return '';

    // 独立图片块
    const imgMatch = lines[0].match(IMAGE_FULL_RE);
    if (lines.length === 1 && imgMatch) {
      const url = imgMatch[1];
      const proxyUrl = getProxyImageUrl(url);
      const referrerPolicy = url.includes('mmbiz.qpic.cn') ? 'referrerPolicy="no-referrer"' : '';
      return `<p class="body-image"><img src="${escapeAttr(proxyUrl)}" data-original="${escapeAttr(url)}" alt="图片" class="body-image-img" ${referrerPolicy} onclick="event.stopPropagation();showImagePreview('${escapeAttr(url)}');return false;" style="max-width:100%;height:auto;display:block;margin:10px auto;"></p>`;
    }

    // ── 标题识别（单行段落） ────────────────────────────
    if (lines.length === 1) {
      const line = lines[0];
      const blockType = classifyLegacyTextBlock(line);
      if (blockType) {
        return `<p class="${blockType}">${inlineToHtml(line)}</p>`;
      }
    }

    // ── 普通段落：多行用空格连接（保留行间隔感） ──────────
    const rawText = lines.join(' ');
    const processed = rawText.replace(IMAGE_INLINE_RE, (_, url) => {
      const proxyUrl = getProxyImageUrl(url);
      const referrerPolicy = url.includes('mmbiz.qpic.cn') ? 'referrerPolicy="no-referrer"' : '';
      return `<img src="${escapeAttr(proxyUrl)}" data-original="${escapeAttr(url)}" alt="图片" class="inline-image" ${referrerPolicy} onclick="event.stopPropagation();showImagePreview('${escapeAttr(url)}');return false;" style="max-width:100%;height:auto;max-height:300px;display:inline-block;vertical-align:middle;">`;
    });
    const finalHtml = processTextWithInlineImages(rawText, processed);
    return `<p>${finalHtml}</p>`;
  });

  // 双换行是明确的段落边界。文本已在入库时完成一次排版，
  // 渲染层不再根据长度猜测并合并，避免同一内容被二次排版。
  return parts.filter(Boolean).join('\n');
}

function classifyLegacyTextBlock(line) {
  return classifyArticleBlockText(line);
}

/**
 * 统一的正文块分类器。原则是保守升格：列举项默认是正文，只有明确的
 * 篇章结构、栏目名和短小完整的编号短语才作为标题。
 */
function classifyArticleBlockText(line, options = {}) {
  const plain = String(line || '')
    .replace(/<[^>]+>/g, '')
    .replace(/[\u00a0\u3000]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!plain) return '';
  const compact = plain.replace(/\s+/g, '');
  const tag = String(options.sourceTag || '').toLowerCase();
  const explicit = Boolean(options.explicitHeading || /^h[1-6]$/.test(tag));
  const hasSentencePunctuation = /[，,；;。！？?!]/.test(plain);

  // 来源、发布时间、作者等元信息是辅助信息，不应被渲染成大标题。
  if (/^(?:发布时间|发布日期|来源|文章来源|作者|编辑|责任编辑|字号|浏览次数|点击数|阅读量)\s*[：:]/.test(plain) && plain.length <= 60) {
    return 'body-meta-line';
  }

  // 裁判文书案号、法规沿革日期是文档元信息，而不是括号编号标题。
  if (/^[（(]\d{4}[）)][^。！？]{0,50}(?:法|民|刑|行|执|商|知|赔|仲)[^。！？]{0,20}号$/.test(compact)
      || /^[（(][^）)]{0,100}(?:通过|修正|修订|公布|施行|发布|批准)[^）)]{0,100}[）)]$/.test(compact)) {
    return 'body-document-meta';
  }
  if (/^(?:中华人民共和国)?(?:最高人民法院|最高人民检察院|.+人民法院|.+人民检察院)$/.test(compact)
      || /^(?:民事|刑事|行政)?(?:判决书|裁定书|决定书|调解书)$/.test(compact)) {
    return 'body-document-meta';
  }

  // 法律/案例文本中常见的结构标签。
  const label = plain.replace(/^[【[]|[】]]$/g, '').replace(/[：:]$/, '').replace(/\s+/g, '');
  if (/^【(?:关键词|关键字|要\s*旨|裁判要旨|基本案情|裁判理由|裁判结果|典型意义|检察履职情况|争议焦点|法院观点|律师提示|实务要点|相关法条|法条链接|案例索引)】/.test(plain)
      || /^(?:摘要|内容提要|关键词|关键字|前言|引言|序言|编者按|结语|结论|总结|作者简介|裁判要旨|法院观点|本院认为|基本案情|裁判理由|裁判结果|典型意义|争议焦点|案件焦点|检察履职情况|律师提示|实务要点|相关法条|法条链接|案例索引|参考文献|致谢)$/.test(label)) {
    return 'body-label-heading';
  }

  if (/^(?:目录|目次)$/.test(compact)) return 'body-toc-heading';

  // 编、章、节、部分是跨来源最稳定的层级标记。
  const structural = plain.match(/^第[一二三四五六七八九十百千零〇两\d]+(分编|编|章|节|部分)(?:[\s\u3000　]*[^，；。！？]{0,60})?$/);
  if (structural) return /^(?:分编|编|章|部分)$/.test(structural[1]) ? 'body-heading' : 'body-heading-secondary';

  // "案例一刘某某、邹某某非国家工作人员受贿案"：顿号是案名组成部分，不能因为含顿号就降为正文。
  if (/^案例[一二三四五六七八九十百千\d]+[\u4e00-\u9fffA-Za-z0-9、，（）()《》“”""：:\s-]{4,80}(?:案|案例|纠纷|争议)$/.test(plain)) {
    return 'body-heading-secondary';
  }
  if (/^\d{1,3}[.．、]\s*.{4,145}(?:案|纠纷案|争议案)$/.test(plain)) {
    return 'body-heading-secondary';
  }

  // “一、二审”“一、二次”等是固定并列表达，不是“一、”编号标题。
  if (/^[一二三四五六七八九十百千零〇两\d]{1,3}、[一二三四五六七八九十百千零〇两\d]{1,3}(?:审|次|项|条|款|人|个|级|类|方|部分|阶段|年度|月份|方面)/.test(compact)) return '';
  if (/^第[一二三四五六七八九十百千零〇两\d]+条(?:\s|　|$)/.test(plain)) return '';

  const parenthesized = /^[（(][一二三四五六七八九十百千零〇两\d]{1,3}[）)]/.test(plain);
  const decimal = /^\d{1,3}(?:[.．、)）]|\.\d+)/.test(plain);
  const major = /^[一二三四五六七八九十百千零〇两\d]+[、.．]\s*/.test(plain);
  if (parenthesized || decimal) {
    if (explicit && plain.length <= 45 && !hasSentencePunctuation) return 'body-heading-secondary';
    return 'body-list-item';
  }
  if (major) {
    // 逗号是标题内部常见的分隔符；句末标点仍然表示普通正文。
    if (isMajorNumberedArticleHeading(plain)) return 'body-heading';
    return '';
  }

  if (explicit && plain.length <= 80 && !hasSentencePunctuation) {
    return /^(?:h4|h5|h6)$/.test(tag) ? 'body-heading-secondary' : 'body-heading';
  }
  if (options.bold && plain.length <= 45 && !hasSentencePunctuation) return 'body-heading';

  if (plain.length >= 4 && plain.length <= 28 && !hasSentencePunctuation
      && /(?:问题|规则|标准|条件|情形|关系|效力|责任|权利|义务|观点|要点|分析|认定|处理|程序|范围|主体|意见|建议|方法|路径|方案|意义|背景|焦点|争议|概述|解读|说明)$/.test(plain)) {
    return 'body-heading-secondary';
  }

  if (plain.length <= 20 && /^[\u4e00-\u9fa5A-Za-z]{2,12}[：:]$/.test(plain)) return 'body-label-heading';

  return '';
}

/**
 * 修复旧版已保存 HTML 中确定性的误分类和断句残片。
 * 规则只合并有明确续接信号的相邻段落，避免主观重写文章结构。
 */
function repairArticleBodyStructure(root) {
  Array.from(root.querySelectorAll('h1, h2, h3, h4, h5, h6')).forEach(node => {
    const blockClass = classifyArticleBlockText(node.textContent, {
      sourceTag: node.tagName,
      explicitHeading: true,
    });
    const paragraph = document.createElement('p');
    if (blockClass && blockClass !== 'body-toc-heading') paragraph.className = blockClass;
    while (node.firstChild) paragraph.appendChild(node.firstChild);
    node.replaceWith(paragraph);
  });

  const headingSelector = 'p.body-heading, p.body-heading-secondary, p.body-label-heading';
  Array.from(root.querySelectorAll(headingSelector)).forEach(node => {
    // root 是用于净化正文的离屏容器，节点不会连接到 document；只需确认
    // 它尚未被前一次合并移除。
    if (!root.contains(node) || node.classList.contains('body-toc-entry')) return;
    const next = node.nextElementSibling;
    if (!next || next.tagName !== 'P' || /body-(?:heading|toc|image)/.test(next.className || '')) return;

    const currentText = String(node.textContent || '').trim();
    const nextText = String(next.textContent || '').trim();
    const compound = /^[一二三四五六七八九十百千零〇两\d]{1,3}、[一二三四五六七八九十百千零〇两\d]{1,3}(?:审|次|项|条|款|人|个|级|类|方|部分|阶段|方面)/.test(currentText.replace(/\s+/g, ''));
    const punctuationContinuation = /^[，,；;。！？?!、]/.test(nextText);
    const predicateContinuation = /(?:认定|认为|指出|主张|规定|称|载明|包括|如下|权利|义务|原则)$/.test(currentText)
      && /^(?:《|“|「|被|由|并|且|而|但|故|即|系|是|未|应|可|将|其|该|本|对|存在|错误|合法|无效|有效)/.test(nextText);

    if (compound || punctuationContinuation || predicateContinuation) {
      node.textContent = `${currentText}${nextText}`;
      next.remove();
    }
  });

  // 标点被单独放到下一段，是确定性的软换行错误；不限于旧标题节点。
  Array.from(root.querySelectorAll('p')).forEach(node => {
    if (!root.contains(node) || !/^[，,；;。！？?!、]/.test(String(node.textContent || '').trim())) return;
    const previous = node.previousElementSibling;
    if (!previous || previous.tagName !== 'P' || /body-(?:toc|image)/.test(previous.className || '')) return;
    previous.textContent = `${String(previous.textContent || '').trim()}${String(node.textContent || '').trim()}`;
    node.remove();
  });

  Array.from(root.querySelectorAll('p')).forEach(node => {
    if (/body-(?:toc|image)/.test(node.className || '')) return;
    const wasHeading = node.matches('p.body-heading')
      ? 'body-heading'
      : node.matches('p.body-heading-secondary')
        ? 'body-heading-secondary'
        : node.matches('p.body-label-heading')
          ? 'body-label-heading'
          : '';
    const blockClass = classifyArticleBlockText(node.textContent, { bold: Boolean(wasHeading) });
    node.classList.remove(
      'body-heading', 'body-heading-secondary', 'body-label-heading',
      'body-list-item', 'body-document-meta', 'body-meta-line'
    );
    if (blockClass && blockClass !== 'body-toc-heading') {
      node.classList.add(blockClass);
    } else if (wasHeading) {
      // 分类器对“第1条对照”“问题3、……的界定”等无编号标题返回空，但
      // 已保存的标题类代表此前的人工/导入确认。只有明确是句子、超长或
      // 法条列举（第X条）的才降级为正文，避免整篇标题被抹掉。
      const plain = String(node.textContent || '').replace(/[\s\u00a0\u3000]+/g, ' ').trim();
      const keepable = plain.length <= 80
        && !/[，,；;。！？?!]/.test(plain)
        && !/^第[一二三四五六七八九十百千零〇两\d]+条(?:\s|　|$)/.test(plain);
      if (keepable) node.classList.add(wasHeading);
    }
    if (blockClass === 'body-list-item') {
      node.style.textIndent = '';
      node.style.paddingLeft = '';
    }
  });
}

/** 纠正旧 Word 导入中“目录状态未结束，整篇正文都变成目录项”的问题。 */
function repairExistingArticleTocEntries(root) {
  const tocHeading = root.querySelector('p.body-toc-heading');
  if (!tocHeading) return;
  const entries = [];
  let cursor = tocHeading.nextElementSibling;
  while (cursor && cursor.matches('p.body-toc-entry')) {
    entries.push(cursor);
    cursor = cursor.nextElementSibling;
  }
  if (entries.length < 3) return;

  let validCount = 0;
  let bodyStart = -1;
  entries.forEach((entry, index) => {
    if (bodyStart >= 0) return;
    const predicted = classifyArticleBlockText(entry.textContent);
    const structural = predicted === 'body-heading'
      || predicted === 'body-heading-secondary'
      || predicted === 'body-label-heading';
    if (structural && String(entry.textContent || '').trim().length <= 100) {
      validCount += 1;
    } else if (validCount >= 2) {
      bodyStart = index;
    }
  });
  if (bodyStart < 0) return;

  entries.slice(bodyStart).forEach(entry => {
    entry.classList.remove('body-toc-entry');
    entry.removeAttribute('data-article-toc-level');
  });
}

/**
 * 处理混有内联图片的文本段：转义普通文字，保留图片链接和 b/i/u 标签。
 */
function processTextWithInlineImages(rawText, processedText) {
  // 如果没有图片标记，直接转义并恢复格式标签
  if (!rawText.includes('[图片:')) return inlineToHtml(rawText);
  // 已经处理过图片，直接返回
  return processedText;
}

/**
 * 将行内的 <b>/<i>/<u> 标记与纯文字混合内容转为安全 HTML。
 */
function inlineToHtml(text) {
  // 按 <b>/<i>/<u> 及其闭合标签分割，分别处理文字节点
  const INLINE_TAG = /(<\/?(?:b|i|u)>)/gi;
  return text.split(INLINE_TAG).map((seg, idx) => {
    // 奇数段是标签本身（原样保留），偶数段是纯文字（需转义）
    if (INLINE_TAG.test(seg)) return seg;
    INLINE_TAG.lastIndex = 0;
    return escapeHtml(seg);
  }).join('');
}

/** 转义 HTML 属性中的特殊字符 */
function escapeAttr(str) {
  return String(str || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#039;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

/**
 * 净化编辑器输出的 HTML，只保留安全的内联/块级格式标签。
 * 去除 script/style/事件属性等危险内容。
 */
function sanitizeBodyHtml(html) {
  const tmp = document.createElement('div');
  tmp.innerHTML = html;

  // 阅读页的笔记高亮、序号角标和连线都只是运行时 UI，绝不能随正文保存。
  // 过去这里将不在白名单中的 <sup> 仅“脱标签”处理，导致角标数字留在
  // .note-anchor 内；再次打开文章后又生成一枚角标，于是显示为重复序号。
  // 先完整移除角标/连线，再拆掉高亮包装，既保留原文，也避免任何笔记 UI 回写。
  tmp.querySelectorAll('.note-anchor-badge, .pdf-page-note-badge, .pdf-text-badge, .note-connector-layer')
    .forEach(node => node.remove());
  tmp.querySelectorAll('.note-anchor, .note-highlight').forEach(node => {
    const parent = node.parentNode;
    if (!parent) return;
    while (node.firstChild) parent.insertBefore(node.firstChild, node);
    node.remove();
  });

  // 清理目录占位残留：历史上会把“系统生成目录”连文带段存进正文，或只剩
  // 文字已删空的目录段落。这类残留会阻止智能目录自动生成，这里统一剔除，
  // 渲染时会按当前标题重新生成目录。原文自带的目录（有文字、无
  // body-toc-generated 类）不受影响。
  Array.from(tmp.querySelectorAll('p.body-toc-heading, p.body-toc-entry')).forEach(node => {
    const empty = !String(node.textContent || '').replace(/[\s\u00a0\u3000]/g, '');
    if (empty || node.classList.contains('body-toc-generated')) node.remove();
  });

  // 允许的标签白名单
  const ALLOWED_TAGS = new Set(['p','b','strong','i','em','u','s','del','br','span','font','a','ul','ol','li','blockquote','h1','h2','h3','h4','h5','h6','img','pre','code','hr','table','thead','tbody','tr','th','td','input','figure']);
  // 允许的属性白名单
  const ALLOWED_ATTRS = {
    font: ['face','color'],
    a: ['href','target','rel','class','onclick','title'],
    img: ['src','alt','class','style','onclick','referrerPolicy','data-original','title'],
    input: ['type','checked','disabled'],
    code: ['class'],
    ol: ['class','data-list-series'],
    ul: ['class','data-list-series'],
    li: ['data-list-level','data-list-label','data-article-list-number'],
    th: ['style'],
    td: ['style'],
  };

  function clean(node) {
    const toRemove = [];
    node.childNodes.forEach(child => {
      // 处理文本节点: 转换[图片: URL]标记
      if (child.nodeType === Node.TEXT_NODE) {
        const text = child.textContent;
        // 修正正则：支持不完整的标记（缺少右括号的情况）
        const imgRegex = /\[图片:\s*(https?:[^\]\s]+(?:[^\]\s]*))/g;
        const matches = [...text.matchAll(imgRegex)];
        if (matches.length > 0) {
          // 将文本节点分割为多个片段
          let lastIndex = 0;
          const fragments = [];
          for (const match of matches) {
            const [fullMatch, url] = match;
            const beforeText = text.slice(lastIndex, match.index);
            if (beforeText) {
              fragments.push(document.createTextNode(beforeText));
            }
            // 创建img标签
            const img = document.createElement('img');
            img.src = url;
            img.alt = '图片';
            img.className = 'body-image-img';
            const referrerPolicy = url.includes('mmbiz.qpic.cn') ? 'no-referrer' : '';
            if (referrerPolicy) img.referrerPolicy = referrerPolicy;
            img.style.cssText = 'max-width:100%;height:auto;display:block;margin:10px auto;cursor:pointer;';
            const escapedUrl = url.replace(/'/g, "\\'");
            img.onclick = function(e) {
              e.stopPropagation();
              showImagePreview(escapedUrl);
              return false;
            };
            fragments.push(img);
            lastIndex = match.index + fullMatch.length;
          }
          // 添加剩余文本
          const afterText = text.slice(lastIndex);
          if (afterText) {
            fragments.push(document.createTextNode(afterText));
          }
          // 替换原文本节点
          if (fragments.length > 0) {
            const frag = document.createDocumentFragment();
            fragments.forEach(f => frag.appendChild(f));
            toRemove.push({ node: child, frag, replaceWith: frag });
          }
        }
        return;
      }

      if (child.nodeType === Node.ELEMENT_NODE) {
        const tag = child.tagName.toLowerCase();
        let allowedStructuralDiv = false;
        if (tag === 'div') {
          const hasBlockChildren = Array.from(child.children).some(el => (
            /^(P|DIV|H[1-6]|UL|OL|BLOCKQUOTE|FIGURE)$/.test(el.tagName)
          ));
          if (!hasBlockChildren) {
            // Safari/Chromium 把粘贴到 contenteditable 的每一行保存成 div。
            // 将叶子 div 转为语义段落，保留目录和章节之间的行边界。
            const paragraph = document.createElement('p');
            if (child.className) paragraph.className = child.className;
            if (child.getAttribute('style')) paragraph.setAttribute('style', child.getAttribute('style'));
            child.childNodes.forEach(c => paragraph.appendChild(c.cloneNode(true)));
            clean(paragraph);
            toRemove.push({ node: child, frag: null, replaceWith: paragraph });
            return;
          }
          allowedStructuralDiv = child.classList.contains('markdown-table-wrap')
            || child.classList.contains('pdf-page-gallery');
          if (allowedStructuralDiv) {
            if (child.classList.contains('markdown-table-wrap')) {
              child.className = 'markdown-table-wrap';
              child.removeAttribute('style');
            } else {
              child.className = 'pdf-page-gallery';
            }
          }
        }
        if (!ALLOWED_TAGS.has(tag) && !allowedStructuralDiv) {
          // 保留文字内容，移除标签包装
          const frag = document.createDocumentFragment();
          child.childNodes.forEach(c => frag.appendChild(c.cloneNode(true)));
          toRemove.push({ node: child, frag });
          return;
        }
        // 移除不允许的属性（按标签类型分别处理）
        const attrs = Array.from(child.attributes);
        const globalAllowed = ['class', 'style'];
        const tagAllowed = ALLOWED_ATTRS[tag] || [];
        attrs.forEach(attr => {
          const name = attr.name.toLowerCase();
          // on* 事件属性：只有 a 和 img（onclick用于预览）才保留
          if (/^on/i.test(name) && tag !== 'a' && tag !== 'img') {
            child.removeAttribute(attr.name);
          } else if (!globalAllowed.includes(name) && !tagAllowed.includes(name)) {
            child.removeAttribute(attr.name);
          }
        });
        // 将旧的图片链接转换为img标签
        if (tag === 'a' && child.classList.contains('image-link')) {
          const href = child.getAttribute('href') || '';
          if (href) {
            const img = document.createElement('img');
            img.src = href;
            img.alt = '图片';
            img.className = 'body-image-img';
            const referrerPolicy = href.includes('mmbiz.qpic.cn') ? 'no-referrer' : '';
            if (referrerPolicy) img.referrerPolicy = referrerPolicy;
            img.style.cssText = 'max-width:100%;height:auto;display:block;margin:10px auto;cursor:pointer;';
            const escapedHref = href.replace(/'/g, "\\'");
            img.onclick = function(e) {
              e.stopPropagation();
              showImagePreview(escapedHref);
              return false;
            };
            toRemove.push({ node: child, frag: null, replaceWith: img });
            return;
          }
        }
        // 限制 a 标签的 onclick 只能调用 showImagePreview
        if (tag === 'a') {
          child.removeAttribute('onclick');
          const href = child.getAttribute('href') || '';
          if (href && !markdownSafeUrl(href, false)) child.removeAttribute('href');
          child.setAttribute('rel', 'noopener');
        }
        // 为微信图片添加 referrerPolicy 并使用代理URL
        if (tag === 'img') {
          const src = child.getAttribute('src') || '';
          if (src && !markdownSafeUrl(src, true)) {
            child.remove();
            return;
          }
          // 如果是微信图片，使用代理URL
          if (src.includes('mmbiz.qpic.cn')) {
            const proxyUrl = getProxyImageUrl(src);
            child.setAttribute('src', proxyUrl);
            // 保存原始URL用于预览
            child.setAttribute('data-original', src);
            if (!child.hasAttribute('referrerPolicy')) {
              child.setAttribute('referrerPolicy', 'no-referrer');
            }
          }
          // 添加默认样式
          if (!child.hasAttribute('style')) {
            child.setAttribute('style', 'max-width:100%;height:auto;display:block;margin:10px auto;');
          }
          // 添加点击预览功能；不复用正文中已有的事件属性。
          const original = child.getAttribute('data-original') || '';
          const previewSrc = markdownSafeUrl(original, true) || src;
          child.setAttribute('data-original', previewSrc);
          child.setAttribute('onclick', `event.stopPropagation();showImagePreview(${JSON.stringify(previewSrc)});return false;`);
          child.style.cursor = 'pointer';
        }
        if (tag === 'input') {
          if (child.getAttribute('type') !== 'checkbox') {
            child.remove();
            return;
          }
          child.setAttribute('disabled', '');
        }
        clean(child);
      } else {
        toRemove.push({ node: child, frag: null });
      }
    });
    toRemove.forEach(({ node: n, frag, replaceWith }) => {
      if (replaceWith) {
        n.parentNode.replaceChild(replaceWith, n);
      } else if (frag) {
        n.parentNode.replaceChild(frag, n);
      } else {
        n.parentNode.removeChild(n);
      }
    });
  }

  clean(tmp);
  return tmp.innerHTML;
}

/* ─────────────────────────────────────────────
   API 请求
───────────────────────────────────────────── */
const API_BASE = '';
const CLIENT_VERSION = '2026.08.21-web-import-timeout';

function fetchWithTimeout(url, options = {}, timeoutMs = 0) {
  if (!timeoutMs || typeof AbortController === 'undefined') return fetch(url, options);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  return fetch(url, { ...options, signal: controller.signal }).finally(() => clearTimeout(timer));
}

function apiTimeoutFor(method, articleRead, caseResearchRead = false) {
  if (method !== 'GET') return 30000;
  if (caseResearchRead) return caseResearchOfflineMode && caseResearchOfflineReady ? 5000 : 30000;
  if (!articleRead) return 15000;
  if (articleOfflineMode && articleOfflineReady) return 5000;
  return articleOfflineReady ? 15000 : 30000;
}

const ARTICLE_OFFLINE_DB_NAME = 'legal-kb-articles-offline';
const ARTICLE_OFFLINE_DB_VERSION = 1;
const ARTICLE_OFFLINE_STORE = 'snapshots';
const ARTICLE_OFFLINE_KEY = 'recent100-max800kb-v2';
const ARTICLE_OFFLINE_LEGACY_KEYS = ['recent100'];
const ARTICLE_OFFLINE_SYNCED_AT_KEY = 'legal_kb_articles_offline_synced_at_v2';
const ARTICLE_OFFLINE_LEGACY_SYNCED_AT_KEYS = ['legal_kb_articles_offline_synced_at'];
const ARTICLE_OFFLINE_MAX_CONTENT_BYTES = 800 * 1024;
const ARTICLE_IMAGE_CACHE_NAME = 'legal-kb-article-images-v1';
const ARTICLE_OFFLINE_REFRESH_AGE = 12 * 60 * 60 * 1000;
let articleOfflineSnapshot = null;
let articleOfflineReady = false;
let articleOfflineMode = false;
let articleOfflineToastShown = false;
let articleLastOnlineProbeAt = 0;
let articleOfflineCacheGeneration = 0;
let articleOfflineImageCachePromise = null;
const PENDING_KNOWLEDGE_LINKS_KEY = 'legal_kb_pending_knowledge_links';
const CASE_RESEARCH_OFFLINE_DB_NAME = 'legal-kb-case-research-offline';
const CASE_RESEARCH_OFFLINE_DB_VERSION = 1;
const CASE_RESEARCH_OFFLINE_STORE = 'snapshots';
const CASE_RESEARCH_OFFLINE_KEY = 'all';
const CASE_RESEARCH_OFFLINE_SYNCED_AT_KEY = 'legal_kb_case_research_offline_synced_at';
const CASE_RESEARCH_OFFLINE_REFRESH_AGE = 60 * 60 * 1000;
let caseResearchOfflineSnapshot = null;
let caseResearchOfflineReady = false;
let caseResearchOfflineMode = false;
let caseResearchOfflineToastShown = false;
let caseResearchLastOnlineProbeAt = 0;
const CASE_RESEARCH_PENDING_KEY = 'legal_kb_case_research_pending_ops';
let offlineSnapshotRefreshTimer = null;
let offlineSnapshotRefreshRunning = false;
let forceArticleSnapshotRefresh = false;
let forceResearchSnapshotRefresh = false;
let lastOfflineCacheUserActivityAt = Date.now();

function noteOfflineCacheUserActivity() {
  lastOfflineCacheUserActivityAt = Date.now();
}

['pointerdown', 'touchstart', 'keydown', 'scroll'].forEach(eventName => {
  document.addEventListener(eventName, noteOfflineCacheUserActivity, { passive: true, capture: true });
});

function offlineSnapshotSyncedAt(key, snapshot) {
  const stored = Number(localStorage.getItem(key) || 0);
  if (stored) return stored;
  const generated = Date.parse(snapshot?.generated_at || '');
  return Number.isFinite(generated) ? generated : 0;
}

function offlineSnapshotNeedsRefresh(key, snapshot, maxAge) {
  const syncedAt = offlineSnapshotSyncedAt(key, snapshot);
  return !syncedAt || Date.now() - syncedAt >= maxAge;
}

function scheduleOfflineSnapshotRefresh({ forceArticle = false, forceResearch = false, delay = 30000 } = {}) {
  forceArticleSnapshotRefresh ||= forceArticle;
  forceResearchSnapshotRefresh ||= forceResearch;
  if ((forceArticle || forceResearch) && offlineSnapshotRefreshTimer) {
    clearTimeout(offlineSnapshotRefreshTimer);
    offlineSnapshotRefreshTimer = null;
  }
  if (offlineSnapshotRefreshTimer || offlineSnapshotRefreshRunning) return;
  offlineSnapshotRefreshTimer = window.setTimeout(async () => {
    offlineSnapshotRefreshTimer = null;
    const userIsActive = Date.now() - lastOfflineCacheUserActivityAt < 15000;
    if (document.hidden || serverConnectionOnline !== true || userIsActive) {
      scheduleOfflineSnapshotRefresh({ delay: 15000 });
      return;
    }
    offlineSnapshotRefreshRunning = true;
    const refreshArticle = forceArticleSnapshotRefresh || offlineSnapshotNeedsRefresh(
      ARTICLE_OFFLINE_SYNCED_AT_KEY, articleOfflineSnapshot, ARTICLE_OFFLINE_REFRESH_AGE
    );
    const refreshResearch = forceResearchSnapshotRefresh || offlineSnapshotNeedsRefresh(
      CASE_RESEARCH_OFFLINE_SYNCED_AT_KEY, caseResearchOfflineSnapshot, CASE_RESEARCH_OFFLINE_REFRESH_AGE
    );
    forceArticleSnapshotRefresh = false;
    forceResearchSnapshotRefresh = false;
    try {
      if (refreshResearch) await syncCaseResearchOfflineSnapshot(true);
      if (refreshArticle) await syncArticleOfflineSnapshot(true);
    } finally {
      offlineSnapshotRefreshRunning = false;
      if (forceArticleSnapshotRefresh || forceResearchSnapshotRefresh) {
        scheduleOfflineSnapshotRefresh({ delay: 5000 });
      }
    }
  }, Math.max(0, delay));
}

function openArticleOfflineDb() {
  return new Promise((resolve, reject) => {
    if (!('indexedDB' in window)) return reject(new Error('当前浏览器不支持文章离线缓存'));
    const req = indexedDB.open(ARTICLE_OFFLINE_DB_NAME, ARTICLE_OFFLINE_DB_VERSION);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(ARTICLE_OFFLINE_STORE)) {
        req.result.createObjectStore(ARTICLE_OFFLINE_STORE);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function readArticleOfflineSnapshot() {
  const db = await openArticleOfflineDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(ARTICLE_OFFLINE_STORE, 'readonly');
    const req = tx.objectStore(ARTICLE_OFFLINE_STORE).get(ARTICLE_OFFLINE_KEY);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
  });
}

async function writeArticleOfflineSnapshot(snapshot) {
  const db = await openArticleOfflineDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(ARTICLE_OFFLINE_STORE, 'readwrite');
    const store = tx.objectStore(ARTICLE_OFFLINE_STORE);
    store.put(snapshot, ARTICLE_OFFLINE_KEY);
    ARTICLE_OFFLINE_LEGACY_KEYS.forEach(key => store.delete(key));
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); reject(tx.error); };
  });
}

function articleOfflineContentByteLength(value) {
  const text = String(value || '');
  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(text).byteLength;
  return unescape(encodeURIComponent(text)).length;
}

function enforceArticleOfflineSizeLimit(snapshot) {
  if (!snapshot || !Array.isArray(snapshot.articles)) return snapshot;
  const articles = snapshot.articles.filter(article =>
    articleOfflineContentByteLength(article?.content) <= ARTICLE_OFFLINE_MAX_CONTENT_BYTES
  );
  return {
    ...snapshot,
    version: Math.max(Number(snapshot.version || 0), 2),
    max_content_bytes: ARTICLE_OFFLINE_MAX_CONTENT_BYTES,
    client_excluded_oversized: snapshot.articles.length - articles.length,
    articles,
  };
}

async function initArticleOfflineSupport() {
  try {
    const snapshot = await readArticleOfflineSnapshot();
    if (snapshot) {
      articleOfflineSnapshot = enforceArticleOfflineSizeLimit(snapshot);
      articleOfflineReady = true;
    }
  } catch (e) {
    console.warn('读取文章离线缓存失败:', e);
  }
}

async function syncArticleOfflineSnapshot(silent = true) {
  const cacheGeneration = articleOfflineCacheGeneration;
  try {
    const timeout = articleOfflineReady ? 120000 : 180000;
    const res = await fetchWithTimeout('/api/articles/offline-snapshot?limit=100', { cache: 'no-store' }, timeout);
    if (!res.ok) throw new Error('文章离线快照更新失败');
    const snapshot = enforceArticleOfflineSizeLimit(await res.json());
    if (cacheGeneration !== articleOfflineCacheGeneration) return false;
    await writeArticleOfflineSnapshot(snapshot);
    if (cacheGeneration !== articleOfflineCacheGeneration) return false;
    const imageCachePromise = cacheArticleSnapshotImages(snapshot, cacheGeneration);
    articleOfflineImageCachePromise = imageCachePromise;
    try {
      await imageCachePromise;
    } finally {
      if (articleOfflineImageCachePromise === imageCachePromise) articleOfflineImageCachePromise = null;
    }
    if (cacheGeneration !== articleOfflineCacheGeneration) return false;
    articleOfflineSnapshot = snapshot;
    articleOfflineReady = true;
    articleOfflineMode = false;
    ARTICLE_OFFLINE_LEGACY_SYNCED_AT_KEYS.forEach(key => localStorage.removeItem(key));
    localStorage.setItem(ARTICLE_OFFLINE_SYNCED_AT_KEY, String(Date.now()));
    if (!silent && typeof showToast === 'function') showToast('最近100篇文章已缓存');
    return true;
  } catch (e) {
    if (!silent && articleOfflineReady && typeof showToast === 'function') showToast('当前使用上次文章离线缓存');
    return false;
  }
}

function pendingKnowledgeLinks() {
  try {
    const links = JSON.parse(localStorage.getItem(PENDING_KNOWLEDGE_LINKS_KEY) || '[]');
    return Array.isArray(links) ? links : [];
  } catch (e) {
    return [];
  }
}

function savePendingKnowledgeLinks(links) {
  localStorage.setItem(PENDING_KNOWLEDGE_LINKS_KEY, JSON.stringify(links || []));
  renderPendingKnowledgeQueue();
}

function makePendingKnowledgeId() {
  return `link-${Date.now()}-${Math.floor(Math.random() * 1000000)}`;
}

function normalizeKnowledgeUrl(url) {
  return String(url || '').trim();
}

function enqueuePendingKnowledgeLink(url) {
  const normalized = normalizeKnowledgeUrl(url);
  const links = pendingKnowledgeLinks();
  const existing = links.find(item => normalizeKnowledgeUrl(item.url) === normalized);
  if (existing) {
    existing.status = 'pending';
    existing.last_error = '';
    existing.updated_at = new Date().toISOString();
    savePendingKnowledgeLinks(links);
    return existing;
  }
  const item = {
    id: makePendingKnowledgeId(),
    url: normalized,
    status: 'pending',
    attempts: 0,
    queued_at: new Date().toISOString(),
    last_error: '',
  };
  links.unshift(item);
  savePendingKnowledgeLinks(links);
  return item;
}

function removePendingKnowledgeLink(id) {
  savePendingKnowledgeLinks(pendingKnowledgeLinks().filter(item => item.id !== id));
}

function pendingKnowledgeHostname(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch (e) {
    return '网页链接';
  }
}

function renderPendingKnowledgeQueue() {
  const box = typeof $ === 'function' ? $('pending-knowledge-queue') : null;
  if (!box) return;
  const links = pendingKnowledgeLinks();
  if (!links.length) {
    box.style.display = 'none';
    box.innerHTML = '';
    return;
  }
  box.style.display = 'block';
  const pendingCount = links.filter(item => item.status !== 'syncing').length;
  box.innerHTML = `
    <div class="pending-knowledge-head">
      <div>
        <strong>待上传知识队列</strong>
        <span>${pendingCount} 条链接等待恢复 Tailscale 后收录</span>
      </div>
      <button type="button" class="btn-secondary pending-knowledge-sync" onclick="syncPendingKnowledgeLinks(false)">立即同步</button>
    </div>
    <div class="pending-knowledge-list">
      ${links.map(item => `
        <div class="pending-knowledge-item">
          <div class="pending-knowledge-main">
            <div class="pending-knowledge-title">${escapeHtml(pendingKnowledgeHostname(item.url))}</div>
            <div class="pending-knowledge-url">${escapeHtml(item.url)}</div>
            ${item.last_error ? `<div class="pending-knowledge-error">${escapeHtml(item.last_error)}</div>` : ''}
          </div>
          <button type="button" class="btn-icon pending-knowledge-remove" aria-label="移除" onclick="removePendingKnowledgeLink('${escapeAttr(item.id)}')">×</button>
        </div>
      `).join('')}
    </div>
  `;
}

async function submitKnowledgeLinkDirect(url) {
  const form = new FormData();
  form.append('url', url);
  const res = await fetchWithTimeout('/api/submit/url', { method: 'POST', body: form }, 90000);
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.detail || data.message || res.statusText || '知识链接上传失败');
  return data;
}

let pendingKnowledgeSyncing = false;
async function syncPendingKnowledgeLinks(silent = true) {
  const links = pendingKnowledgeLinks();
  if (pendingKnowledgeSyncing || !links.length) return false;
  if (!(await isServerReachable(2500))) {
    if (!silent && typeof showToast === 'function') showToast('当前无法连接 Mac，待上传队列会继续保留', 'warning');
    renderPendingKnowledgeQueue();
    return false;
  }
  pendingKnowledgeSyncing = true;
  let changed = false;
  let completed = 0;
  const remaining = [];
  try {
    for (const item of links) {
      const next = { ...item, status: 'syncing', attempts: Number(item.attempts || 0) + 1 };
      try {
        savePendingKnowledgeLinks([...remaining, next, ...links.slice(links.indexOf(item) + 1)]);
        const data = await submitKnowledgeLinkDirect(item.url);
        if (data?.duplicate || data?.success) {
          completed += 1;
          changed = true;
        } else {
          remaining.push({ ...next, status: 'pending', last_error: data?.message || '上传未完成，稍后会重试' });
        }
      } catch (e) {
        remaining.push({ ...next, status: 'pending', last_error: e.message || '上传失败，稍后会重试' });
      }
    }
  } finally {
    pendingKnowledgeSyncing = false;
  }
  savePendingKnowledgeLinks(remaining);
  if (changed) {
    scheduleOfflineSnapshotRefresh({ forceArticle: true, delay: 5000 });
    loadArticles().catch(() => {});
    loadStats().catch(() => {});
    loadDomains().catch(() => {});
    loadAuthors().catch(() => {});
  }
  if (completed && typeof showToast === 'function') {
    showToast(`待上传知识已同步 ${completed} 条`);
  } else if (!silent && remaining.length && typeof showToast === 'function') {
    showToast('暂未同步成功，队列会继续保留', 'warning');
  }
  return completed > 0 && remaining.length === 0;
}

function openCaseResearchOfflineDb() {
  return new Promise((resolve, reject) => {
    if (!('indexedDB' in window)) return reject(new Error('当前浏览器不支持案件研究离线缓存'));
    const req = indexedDB.open(CASE_RESEARCH_OFFLINE_DB_NAME, CASE_RESEARCH_OFFLINE_DB_VERSION);
    req.onupgradeneeded = () => req.result.createObjectStore(CASE_RESEARCH_OFFLINE_STORE);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function readCaseResearchOfflineSnapshot() {
  const db = await openCaseResearchOfflineDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(CASE_RESEARCH_OFFLINE_STORE, 'readonly');
    const req = tx.objectStore(CASE_RESEARCH_OFFLINE_STORE).get(CASE_RESEARCH_OFFLINE_KEY);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
  });
}

async function writeCaseResearchOfflineSnapshot(snapshot) {
  const db = await openCaseResearchOfflineDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(CASE_RESEARCH_OFFLINE_STORE, 'readwrite');
    tx.objectStore(CASE_RESEARCH_OFFLINE_STORE).put(snapshot, CASE_RESEARCH_OFFLINE_KEY);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); reject(tx.error); };
  });
}

async function initCaseResearchOfflineSupport() {
  try {
    const snapshot = await readCaseResearchOfflineSnapshot();
    if (snapshot) {
      caseResearchOfflineSnapshot = snapshot;
      caseResearchOfflineReady = true;
    }
  } catch (e) {
    console.warn('读取案件研究离线缓存失败:', e);
  }
}

async function syncCaseResearchOfflineSnapshot(silent = true) {
  try {
    const timeout = caseResearchOfflineReady ? 60000 : 120000;
    const res = await fetchWithTimeout('/api/case-research/offline-snapshot?limit=500', { cache: 'no-store' }, timeout);
    if (!res.ok) throw new Error('案件研究离线快照更新失败');
    const snapshot = await res.json();
    await writeCaseResearchOfflineSnapshot(snapshot);
    caseResearchOfflineSnapshot = snapshot;
    caseResearchOfflineReady = true;
    caseResearchOfflineMode = false;
    localStorage.setItem(CASE_RESEARCH_OFFLINE_SYNCED_AT_KEY, String(Date.now()));
    if (!silent && typeof showToast === 'function') showToast('案件研究已缓存到本机');
    return true;
  } catch (e) {
    if (!silent && caseResearchOfflineReady && typeof showToast === 'function') showToast('当前使用上次案件研究离线缓存');
    return false;
  }
}

function pendingResearchOps() {
  try {
    return JSON.parse(localStorage.getItem(CASE_RESEARCH_PENDING_KEY) || '[]');
  } catch (e) {
    return [];
  }
}

function savePendingResearchOps(ops) {
  localStorage.setItem(CASE_RESEARCH_PENDING_KEY, JSON.stringify(ops || []));
}

function makeTempId() {
  return -Math.floor(Date.now() + Math.random() * 1000000);
}

function timelineArrayByType(detail, type) {
  return type === 'ledger' ? (detail.ledgers || (detail.ledgers = [])) : (detail.memo_entries || (detail.memo_entries = []));
}

function applyCaseResearchTimelineLocal(op) {
  if (!caseResearchOfflineSnapshot || !researchState.activeCaseId) return;
  const detail = caseResearchOfflineSnapshot.details?.[String(researchState.activeCaseId)];
  if (!detail) return;
  const list = timelineArrayByType(detail, op.type);
  const now = new Date().toISOString();
  if (op.action === 'delete') {
    const idx = list.findIndex(item => Number(item.id) === Number(op.id));
    if (idx >= 0) list.splice(idx, 1);
  } else if (op.action === 'upsert') {
    const item = {
      id: op.id,
      project_id: op.project_id,
      title: op.payload.title || '',
      content: op.payload.content || '',
      happened_at: op.payload.happened_at || '',
      created_at: op.created_at || now,
      updated_at: now,
      offline_pending: true,
    };
    const idx = list.findIndex(x => Number(x.id) === Number(op.id));
    if (idx >= 0) list[idx] = { ...list[idx], ...item };
    else list.unshift(item);
  }
  if (op.type === 'ledger') researchState.ledgers = [...list];
  else researchState.memoEntries = [...list];
  writeCaseResearchOfflineSnapshot(caseResearchOfflineSnapshot).catch(() => {});
}

function enqueueCaseResearchTimelineOp(op) {
  const ops = pendingResearchOps();
  ops.push({ ...op, queued_at: new Date().toISOString() });
  savePendingResearchOps(ops);
  applyCaseResearchTimelineLocal(op);
}

async function syncPendingCaseResearchOps() {
  const ops = pendingResearchOps();
  if (!ops.length || !(await isServerReachable(3000))) return false;
  const remaining = [];
  const idMap = {};
  for (const op of ops) {
    try {
      const endpoint = op.type === 'ledger' ? 'ledgers' : 'memo-entries';
      let id = idMap[op.id] || op.id;
      if (op.action === 'delete') {
        if (Number(id) > 0) await apiFetch(`/api/case-research/${endpoint}/${id}`, { method: 'DELETE' });
      } else if (op.action === 'upsert') {
        if (Number(id) > 0) {
          await apiFetch(`/api/case-research/${endpoint}/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(op.payload)
          });
        } else {
          const data = await apiFetch(`/api/case-research/projects/${op.project_id}/${endpoint}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(op.payload)
          });
          if (data?.id) idMap[op.id] = data.id;
        }
      }
    } catch (e) {
      remaining.push(op);
    }
  }
  savePendingResearchOps(remaining);
  if (remaining.length !== ops.length) {
    scheduleOfflineSnapshotRefresh({ forceResearch: true, delay: 3000 });
    if (researchState.activeCaseId) await loadCaseResearchDetail(researchState.activeCaseId);
    renderResearchProjectsPage();
    if (!remaining.length && typeof showToast === 'function') showToast('案件研究离线修改已同步');
  }
  return remaining.length === 0;
}

function extractArticleImageUrls(snapshot) {
  const urls = new Set();
  const parser = new DOMParser();
  (snapshot?.articles || []).forEach(article => {
    const html = String(article.content || '');
    if (!html.includes('<img')) return;
    const doc = parser.parseFromString(html, 'text/html');
    doc.querySelectorAll('img[src]').forEach(img => {
      const raw = img.getAttribute('src') || '';
      if (!raw || raw.startsWith('data:') || raw.startsWith('blob:')) return;
      let url = getProxyImageUrl(raw);
      try {
        url = new URL(url, location.origin).toString();
        urls.add(url);
      } catch (e) {}
    });
  });
  return [...urls];
}

async function cacheArticleSnapshotImages(snapshot, expectedGeneration = articleOfflineCacheGeneration) {
  if (!('caches' in window)) return;
  if (expectedGeneration !== articleOfflineCacheGeneration) return false;
  const urls = extractArticleImageUrls(snapshot);
  if (!urls.length) return true;
  const cache = await caches.open(ARTICLE_IMAGE_CACHE_NAME);
  await Promise.allSettled(urls.map(async url => {
    if (expectedGeneration !== articleOfflineCacheGeneration) return;
    const req = new Request(url, { mode: 'same-origin', credentials: 'same-origin' });
    const cached = await cache.match(req);
    if (cached) return;
    const resp = await fetchWithTimeout(url, { cache: 'force-cache' }, 12000);
    if (expectedGeneration !== articleOfflineCacheGeneration) return;
    if (resp && resp.ok) await cache.put(req, resp.clone());
  }));
  return expectedGeneration === articleOfflineCacheGeneration;
}

function articlePlainText(value) {
  const tmp = document.createElement('div');
  tmp.innerHTML = String(value || '');
  return (tmp.textContent || tmp.innerText || '').replace(/\s+/g, ' ').trim();
}

function articleSearchText(article, scope = 'all') {
  const tags = (article.tags || []).join(' ');
  const domains = (article.domains || []).join(' ');
  const fields = {
    title: [article.title],
    summary: [article.summary],
    content: [articlePlainText(article.content)],
    tags: [tags, domains],
    author: [tags],
    all: [article.title, article.summary, articlePlainText(article.content), tags, domains],
  };
  return String((fields[scope] || fields.all).join(' ')).toLowerCase();
}

function articleMatchesOffline(article, params) {
  const q = String(params.get('q') || '').trim().toLowerCase();
  const scope = params.get('search_scope') || 'all';
  if (q && !articleSearchText(article, scope).includes(q)) return false;
  const domain = params.get('domain');
  if (domain && !(article.domains || []).includes(domain)) return false;
  const author = params.get('author');
  if (author && !(article.tags || []).includes(`作者:${author}`)) return false;
  const customTag = params.get('custom_tag');
  if (customTag && !(article.tags || []).includes(customTag)) return false;
  const customTags = String(params.get('custom_tags') || '').split(',').map(x => x.trim()).filter(Boolean);
  if (customTags.length && !customTags.some(tag => (article.tags || []).includes(tag))) return false;
  const sourceType = params.get('source_type');
  if (sourceType && article.source_type !== sourceType) return false;
  return true;
}

function offlineContentSnippets(article, keyword, scope) {
  if (!keyword || !['all', 'content'].includes(scope || 'all')) return [];
  const plain = articlePlainText(article.content);
  const lower = plain.toLowerCase();
  const q = keyword.toLowerCase();
  const snippets = [];
  let start = 0;
  while (snippets.length < 5) {
    const idx = lower.indexOf(q, start);
    if (idx < 0) break;
    const s = Math.max(0, idx - 60);
    const e = Math.min(plain.length, idx + keyword.length + 60);
    snippets.push({
      text: `${s > 0 ? '…' : ''}${plain.slice(s, e)}${e < plain.length ? '…' : ''}`,
      offset: idx,
    });
    start = idx + keyword.length;
  }
  return snippets;
}

function offlineArticleList(url) {
  if (!articleOfflineSnapshot) throw new Error('没有可用的文章离线缓存，请联网打开知识库完成缓存');
  const parsed = new URL(url, location.origin);
  const params = parsed.searchParams;
  const page = Math.max(1, Number(params.get('page') || 1));
  const pageSize = Math.max(1, Number(params.get('page_size') || 10));
  const q = String(params.get('q') || '').trim();
  const scope = params.get('search_scope') || 'all';
  const matched = (articleOfflineSnapshot.articles || []).filter(article => articleMatchesOffline(article, params));
  const start = (page - 1) * pageSize;
  const articles = matched.slice(start, start + pageSize).map(article => {
    const item = { ...article };
    item.content_snippets = offlineContentSnippets(article, q, scope);
    delete item.content;
    return item;
  });
  return { total: matched.length, page, page_size: pageSize, articles };
}

function offlineArticleDetail(url) {
  const match = String(url).match(/^\/api\/articles\/(\d+)(?:$|\?)/);
  const id = match ? Number(match[1]) : 0;
  const article = (articleOfflineSnapshot?.articles || []).find(item => Number(item.id) === id)
    || offlineCaseResearchArticle(id);
  if (!article) throw new Error('该文章不在最近100篇或案件研究离线缓存中');
  return { ...article };
}

function isArticleOfflineRead(url, method) {
  const text = String(url);
  return method === 'GET' && (
    /^\/api\/articles(?:\?|$)/.test(text) ||
    /^\/api\/articles\/\d+(?:$|\?)/.test(text)
  );
}

function articleOfflineApi(url) {
  if (/^\/api\/articles\/\d+(?:$|\?)/.test(String(url))) return offlineArticleDetail(url);
  return offlineArticleList(url);
}

function caseResearchText(value) {
  return String(value ?? '').toLowerCase();
}

function caseResearchCaseMatches(item, query) {
  const q = caseResearchText(query).trim();
  if (!q) return true;
  return caseResearchText([
    item.title,
    item.case_type,
    item.memo,
    item.client_names,
    item.court_contact,
    item.party_contact,
  ].join(' ')).includes(q);
}

function requireCaseResearchSnapshot() {
  if (!caseResearchOfflineSnapshot) throw new Error('没有可用的案件研究离线缓存，请联网打开案件研究完成缓存');
  return caseResearchOfflineSnapshot;
}

function offlineCaseResearchCases(url) {
  const snapshot = requireCaseResearchSnapshot();
  const parsed = new URL(url, location.origin);
  const q = parsed.searchParams.get('q') || '';
  const limit = Number(parsed.searchParams.get('limit') || 500);
  const cases = (snapshot.cases || []).filter(item => caseResearchCaseMatches(item, q)).slice(0, limit);
  return { cases };
}

function offlineCaseResearchDetailByCaseId(caseId) {
  const snapshot = requireCaseResearchSnapshot();
  const detail = snapshot.details?.[String(caseId)];
  if (!detail) throw new Error('案件研究离线缓存中未找到该案件');
  return {
    ...detail,
    questions: detail.questions || [],
  };
}

function offlineCaseResearchDetailByProjectId(projectId) {
  const snapshot = requireCaseResearchSnapshot();
  const caseId = snapshot.project_to_case?.[String(projectId)];
  if (!caseId) throw new Error('案件研究离线缓存中未找到该项目');
  return offlineCaseResearchDetailByCaseId(caseId);
}

function offlineResearchQuestions(projectId) {
  const detail = offlineCaseResearchDetailByProjectId(projectId);
  return { questions: detail.questions || [] };
}

function offlineResearchMemo(memoId) {
  const snapshot = requireCaseResearchSnapshot();
  const caseId = snapshot.memo_to_case?.[String(memoId)];
  if (!caseId) throw new Error('案件研究离线缓存中未找到该备忘录');
  const detail = offlineCaseResearchDetailByCaseId(caseId);
  const memo = (detail.memos || []).find(item => Number(item.id) === Number(memoId));
  if (!memo) throw new Error('案件研究离线缓存中未找到该备忘录');
  return { ...memo };
}

function offlineCaseResearchArticle(articleId) {
  const snapshot = caseResearchOfflineSnapshot;
  const article = snapshot?.linked_articles?.[String(articleId)];
  return article ? { ...article } : null;
}

function isCaseResearchOfflineRead(url, method) {
  const text = String(url);
  return method === 'GET' && (
    /^\/api\/case-research\/cases(?:\?|$)/.test(text) ||
    /^\/api\/case-research\/cases\/\d+(?:$|\?)/.test(text) ||
    /^\/api\/research-projects\/\d+(?:$|\?)/.test(text) ||
    /^\/api\/research-projects\/\d+\/questions(?:$|\?)/.test(text) ||
    /^\/api\/research-memos\/\d+(?:$|\?)/.test(text)
  );
}

function caseResearchOfflineApi(url) {
  const text = String(url);
  let match = text.match(/^\/api\/case-research\/cases\/(\d+)(?:$|\?)/);
  if (match) return offlineCaseResearchDetailByCaseId(Number(match[1]));
  match = text.match(/^\/api\/research-projects\/(\d+)\/questions(?:$|\?)/);
  if (match) return offlineResearchQuestions(Number(match[1]));
  match = text.match(/^\/api\/research-projects\/(\d+)(?:$|\?)/);
  if (match) return offlineCaseResearchDetailByProjectId(Number(match[1]));
  match = text.match(/^\/api\/research-memos\/(\d+)(?:$|\?)/);
  if (match) return offlineResearchMemo(Number(match[1]));
  return offlineCaseResearchCases(url);
}

async function apiFetch(path, options = {}) {
  const url = path.startsWith('http') ? path : `${API_BASE}${path}`;
  console.log('apiFetch:', url, options);
  const method = String(options.method || 'GET').toUpperCase();
  // 单次调用可通过 options.timeoutMs 覆盖默认超时（如扫描版 PDF 需逐页 OCR，解析耗时可达数分钟）
  const timeoutOverride = Number(options.timeoutMs) > 0 ? Number(options.timeoutMs) : 0;
  const fetchOptions = { ...options };
  delete fetchOptions.timeoutMs;
  const articleRead = isArticleOfflineRead(url, method);
  const caseResearchRead = isCaseResearchOfflineRead(url, method);
  if (articleRead && articleOfflineMode && articleOfflineReady) {
    const now = Date.now();
    if (now - articleLastOnlineProbeAt < 8000) return articleOfflineApi(url);
    articleLastOnlineProbeAt = now;
  }
  if (caseResearchRead && caseResearchOfflineMode && caseResearchOfflineReady) {
    const now = Date.now();
    if (now - caseResearchLastOnlineProbeAt < 8000) return caseResearchOfflineApi(url);
    caseResearchLastOnlineProbeAt = now;
  }
  let res;
  try {
    res = await fetchWithTimeout(url, fetchOptions, timeoutOverride || apiTimeoutFor(method, articleRead, caseResearchRead));
  } catch (e) {
    if (articleRead) {
      if (await isServerReachable(5000)) {
        res = await fetchWithTimeout(url, fetchOptions, 30000);
      } else {
      const data = articleOfflineApi(url);
      articleOfflineMode = true;
      if (!articleOfflineToastShown && typeof showToast === 'function') {
        showToast('已切换到最近100篇文章离线缓存');
        articleOfflineToastShown = true;
      }
      return data;
      }
    } else if (caseResearchRead) {
      if (await isServerReachable(5000)) {
        res = await fetchWithTimeout(url, fetchOptions, 30000);
      } else {
        const data = caseResearchOfflineApi(url);
        caseResearchOfflineMode = true;
        if (!caseResearchOfflineToastShown && typeof showToast === 'function') {
          showToast('已切换到案件研究离线缓存');
          caseResearchOfflineToastShown = true;
        }
        return data;
      }
    } else {
      throw e;
    }
  }
  console.log('apiFetch response:', res.status, res.statusText);
  if (!res.ok) {
    const err = await res.json().catch(() => ({ detail: res.statusText }));
    let message = err.detail || err.message || res.statusText || '请求失败';
    if (Array.isArray(message)) {
      message = message.map(item => {
        if (typeof item === 'string') return item;
        const loc = Array.isArray(item.loc) ? item.loc.join('.') : '';
        return [loc, item.msg].filter(Boolean).join(': ') || JSON.stringify(item);
      }).join('\n');
    } else if (message && typeof message === 'object') {
      message = JSON.stringify(message);
    }
    throw new Error(message);
  }
  noteServerSuccess();
  if (articleRead) {
    articleOfflineMode = false;
    articleOfflineToastShown = false;
  }
  if (caseResearchRead) {
    caseResearchOfflineMode = false;
    caseResearchOfflineToastShown = false;
  }
  return res.json();
}

function hasCaseManagerOfflineSnapshot(timeoutMs = 400) {
  return new Promise(resolve => {
    if (!('indexedDB' in window)) return resolve(false);
    const timer = setTimeout(() => resolve(false), timeoutMs);
    const req = indexedDB.open('legal-kb-case-manager', 1);
    req.onerror = () => { clearTimeout(timer); resolve(false); };
    req.onupgradeneeded = () => {
      req.transaction.abort();
      clearTimeout(timer);
      resolve(false);
    };
    req.onsuccess = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains('snapshots')) {
        db.close();
        clearTimeout(timer);
        resolve(false);
        return;
      }
      const tx = db.transaction('snapshots', 'readonly');
      const getReq = tx.objectStore('snapshots').get('latest');
      getReq.onsuccess = () => {
        clearTimeout(timer);
        resolve(!!getReq.result);
      };
      getReq.onerror = () => {
        clearTimeout(timer);
        resolve(false);
      };
      tx.oncomplete = () => db.close();
    };
  });
}

async function isServerReachable(timeoutMs = 3500) {
  try {
    const res = await fetchWithTimeout(`/api/server-status?_=${Date.now()}`, { cache: 'no-store' }, timeoutMs);
    return !!res && res.ok;
  } catch (e) {
    return false;
  }
}

let connectivityMonitorTimer = null;
let connectivityProbeFailures = 0;
let connectivityProbeRunning = false;
let serverConnectionOnline = null;
let serverLastSuccessAt = 0;
let serverFailedProbeCount = 0;

function applyServerConnectionState(online, force = false) {
  if (!online && !force) {
    serverFailedProbeCount += 1;
    const recentlySucceeded = serverLastSuccessAt && Date.now() - serverLastSuccessAt < 15000;
    if (recentlySucceeded || (serverConnectionOnline === true && serverFailedProbeCount < 2)) {
      return serverConnectionOnline;
    }
  }
  if (online) {
    serverLastSuccessAt = Date.now();
    serverFailedProbeCount = 0;
  }
  serverConnectionOnline = online;
  if (articleOfflineReady) articleOfflineMode = !online;
  if (caseResearchOfflineReady) caseResearchOfflineMode = !online;
  applyHomeOfflineLayout();
  if (online) {
    articleOfflineToastShown = false;
    caseResearchOfflineToastShown = false;
  }
  return online;
}

function noteServerSuccess() {
  applyServerConnectionState(true);
}

function refreshAfterOnlineTransition() {
  recoverArticleOnlineIfPossible(true);
  recoverCaseResearchOnlineIfPossible(true);
  Promise.allSettled([loadStats(), loadDomains(), loadAuthors(), loadCustomTags()]);
}

function handleServerProbeResult(online, refresh = true) {
  const previous = serverConnectionOnline;
  const effectiveOnline = applyServerConnectionState(online);
  connectivityProbeFailures = effectiveOnline ? 0 : Math.min(connectivityProbeFailures + 1, 6);
  if (effectiveOnline && previous !== true && refresh) refreshAfterOnlineTransition();
  return effectiveOnline;
}

async function probeServerConnection({ refresh = true, timeoutMs } = {}) {
  if (connectivityProbeRunning) return null;
  connectivityProbeRunning = true;
  try {
    const baseTimeout = timeoutMs || (serverConnectionOnline === false ? 10000 : 5000);
    let online = await isServerReachable(baseTimeout);
    // 单次探测失败不足以定性：立即用短超时复核一次。
    // Tailscale 中继切换/移动网络抖动常造成秒级停顿，双确认可大幅减少误判离线。
    if (!online && serverConnectionOnline !== false) {
      online = await isServerReachable(3000);
    }
    return handleServerProbeResult(online, refresh);
  } finally {
    connectivityProbeRunning = false;
  }
}

function startConnectivityMonitor() {
  if (connectivityMonitorTimer) return;
  const schedule = () => {
    const onlineDelay = 30000;
    const offlineDelay = Math.min(300000, 30000 * Math.pow(2, Math.max(0, connectivityProbeFailures - 1)));
    const delay = document.hidden ? 300000 : (serverConnectionOnline === false ? offlineDelay : onlineDelay);
    connectivityMonitorTimer = window.setTimeout(async () => {
      connectivityMonitorTimer = null;
      if (!document.hidden) await probeServerConnection();
      schedule();
    }, delay);
  };
  schedule();
}

let articleRecoveringOnline = false;
async function recoverArticleOnlineIfPossible(confirmedOnline = false) {
  if (articleRecoveringOnline || (!confirmedOnline && !articleOfflineReady && !pendingKnowledgeLinks().length)) return;
  articleRecoveringOnline = true;
  articleLastOnlineProbeAt = 0;
  try {
    const online = confirmedOnline || await isServerReachable(5000);
    if (!online) return;
    articleOfflineMode = false;
    articleOfflineToastShown = false;
    await syncPendingKnowledgeLinks(true);
    scheduleOfflineSnapshotRefresh({ delay: 30000 });
    if (typeof loadArticles === 'function') {
      loadArticles().catch(e => console.warn('恢复在线文章列表失败:', e));
    }
  } finally {
    articleRecoveringOnline = false;
  }
}

window.addEventListener('pageshow', () => probeServerConnection());
window.addEventListener('focus', () => probeServerConnection());
document.addEventListener('visibilitychange', () => {
  if (!document.hidden) probeServerConnection();
});

let caseResearchRecoveringOnline = false;
async function recoverCaseResearchOnlineIfPossible(confirmedOnline = false) {
  if (caseResearchRecoveringOnline || !caseResearchOfflineReady) return;
  caseResearchRecoveringOnline = true;
  caseResearchLastOnlineProbeAt = 0;
  try {
    const online = confirmedOnline || await isServerReachable(5000);
    if (!online) return;
    caseResearchOfflineMode = false;
    caseResearchOfflineToastShown = false;
    await syncPendingCaseResearchOps();
    scheduleOfflineSnapshotRefresh({ delay: 30000 });
  } finally {
    caseResearchRecoveringOnline = false;
  }
}

window.addEventListener('online', () => probeServerConnection());
// iOS 在后台挂起或切换网络时会触发并不可靠的 offline 事件（Tailscale 仍在路由）。
// 离线状态一律以服务器探针结果为准，这里只触发重新探测，不再强制切换。
window.addEventListener('offline', () => {
  if (!document.hidden) probeServerConnection();
});

