/* ─────────────────────────────────────────────
   文章列表密度
───────────────────────────────────────────── */
const ARTICLE_DENSITY_KEY = 'legal_kb_article_density';
const ARTICLE_DENSITY_OPTIONS = new Set(['compact', 'standard', 'comfortable']);
const ARTICLE_DENSITY_LABELS = { compact: '紧凑', standard: '标准', comfortable: '舒适' };

const SEARCH_SCOPE_KEY = 'legal_kb_search_scope';
const SEARCH_SCOPE_DIRTY_KEY = 'legal_kb_search_scope_dirty';
const SEARCH_SCOPE_API = '/api/preferences/default-search-scope';
const SEARCH_SCOPE_OPTIONS = new Set(['all', 'title', 'summary', 'content', 'tags', 'notes', 'author']);
const SEARCH_SCOPE_LABELS = { all: '全部', title: '标题', summary: '摘要', content: '正文', tags: '标签', notes: '笔记', author: '作者' };
let searchScopeSyncTimer = null;

function loadSearchScopePreference() {
  try {
    const saved = localStorage.getItem(SEARCH_SCOPE_KEY);
    return SEARCH_SCOPE_OPTIONS.has(saved) ? saved : 'all';
  } catch (e) {
    return 'all';
  }
}

function saveSearchScopePreference(scope) {
  try {
    localStorage.setItem(SEARCH_SCOPE_KEY, scope);
    localStorage.setItem(SEARCH_SCOPE_DIRTY_KEY, '1');
  } catch (e) { /* ignore */ }
  scheduleSearchScopeSync();
}

function scheduleSearchScopeSync() {
  clearTimeout(searchScopeSyncTimer);
  searchScopeSyncTimer = setTimeout(() => pushSearchScopeToServer(), 150);
}

async function pushSearchScopeToServer() {
  const scope = loadSearchScopePreference();
  try {
    const response = await fetchWithTimeout(SEARCH_SCOPE_API, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ scope })
    }, 10000);
    if (response.ok) {
      try { localStorage.removeItem(SEARCH_SCOPE_DIRTY_KEY); } catch (e) { /* ignore */ }
    }
  } catch (error) {
    // 本地副本已保存；网络恢复或下次启动时会再次同步。
    console.warn('默认搜索范围同步失败，将保留本地设置:', error);
  }
}

async function syncSearchScopeFromServer() {
  const localScope = loadSearchScopePreference();
  const hasPendingLocalChanges = localStorage.getItem(SEARCH_SCOPE_DIRTY_KEY) === '1';
  try {
    const response = await fetchWithTimeout(`${SEARCH_SCOPE_API}?_=${Date.now()}`, {
      cache: 'no-store'
    }, 10000);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    const serverScope = SEARCH_SCOPE_OPTIONS.has(data.scope) ? data.scope : 'all';
    if (hasPendingLocalChanges) {
      await pushSearchScopeToServer();
    } else if (data.updated_at) {
      // 服务端已有数据时以服务端为准，保证各设备一致。
      if (serverScope !== localScope) {
        try { localStorage.setItem(SEARCH_SCOPE_KEY, serverScope); } catch (e) { /* ignore */ }
      }
    } else if (localScope !== 'all') {
      // 升级后的首次启动：把原来仅存在本地浏览器里的设置迁移到服务端。
      await pushSearchScopeToServer();
    }
    applySearchScopePreference();
  } catch (error) {
    console.warn('读取默认搜索范围失败，继续使用本地设置:', error);
  }
}

function applySearchScopePreference() {
  const scope = loadSearchScopePreference();
  state.searchScope = scope;
  const scopeSelect = $('search-scope');
  if (scopeSelect) scopeSelect.value = scope;
  const settingSelect = $('settings-search-scope-select');
  if (settingSelect) settingSelect.value = scope;
}

function renderSearchScopeSetting() {
  const settingSelect = $('settings-search-scope-select');
  if (settingSelect) settingSelect.value = SEARCH_SCOPE_OPTIONS.has(state.searchScope) ? state.searchScope : loadSearchScopePreference();
}

function setSearchScopePreference(scope) {
  if (!SEARCH_SCOPE_OPTIONS.has(scope)) return;
  state.searchScope = scope;
  saveSearchScopePreference(scope);
  const scopeSelect = $('search-scope');
  if (scopeSelect) scopeSelect.value = scope;
  showToast(`默认搜索范围：${SEARCH_SCOPE_LABELS[scope]}`);
  onSearchInput();
}

function loadArticleDensityPreference() {
  try {
    const saved = localStorage.getItem(ARTICLE_DENSITY_KEY);
    return ARTICLE_DENSITY_OPTIONS.has(saved) ? saved : 'standard';
  } catch (e) {
    return 'standard';
  }
}

function saveArticleDensityPreference(mode) {
  try {
    localStorage.setItem(ARTICLE_DENSITY_KEY, mode);
  } catch (e) { /* ignore */ }
}

function applyArticleDensity() {
  const mode = ARTICLE_DENSITY_OPTIONS.has(state.articleDensity) ? state.articleDensity : 'standard';
  document.body.classList.remove('density-compact', 'density-standard', 'density-comfortable');
  document.body.classList.add(`density-${mode}`);
  renderArticleDensityControl();
}

function setArticleDensity(mode) {
  if (!ARTICLE_DENSITY_OPTIONS.has(mode)) return;
  state.articleDensity = mode;
  applyArticleDensity();
  saveArticleDensityPreference(mode);
  closeDensityMenu();

  showToast(`文章列表密度：${ARTICLE_DENSITY_LABELS[mode]}`);
}

function renderArticleDensityControl() {
  const mode = ARTICLE_DENSITY_OPTIONS.has(state.articleDensity) ? state.articleDensity : 'standard';
  const currentLabel = $('density-current-label');
  if (currentLabel) currentLabel.textContent = ARTICLE_DENSITY_LABELS[mode] || '标准';

  document.querySelectorAll('.density-option').forEach(btn => {
    const active = btn.dataset.density === mode;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
}

function toggleDensityMenu(event) {
  if (event) event.stopPropagation();
  const menu = $('density-menu');
  const trigger = $('density-trigger');
  if (!menu) return;
  const willOpen = !menu.classList.contains('open');
  menu.classList.toggle('open', willOpen);
  if (trigger) trigger.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
}

function closeDensityMenu() {
  const menu = $('density-menu');
  const trigger = $('density-trigger');
  if (!menu) return;
  menu.classList.remove('open');
  if (trigger) trigger.setAttribute('aria-expanded', 'false');
}

document.addEventListener('click', (event) => {
  const menu = $('density-menu');
  if (menu && !menu.contains(event.target)) closeDensityMenu();
});

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') closeDensityMenu();
});

/* ─────────────────────────────────────────────
   首页工作流增强：状态、视图、批量、健康提示
───────────────────────────────────────────── */
const ARTICLE_STATUS_KEY = 'legal_kb_article_status';
const SAVED_VIEWS_KEY = 'legal_kb_saved_views';
const SAVED_VIEWS_BACKUP_KEY = 'legal_kb_saved_views_backup';
const SAVED_VIEWS_DIRTY_KEY = 'legal_kb_saved_views_dirty';
const SAVED_VIEWS_API = '/api/preferences/saved-views';
const RECENT_WORKSPACE_KEY = 'legal_kb_recent_workspace';
const HEALTH_FILTER_KEY = 'legal_kb_health_filter';
let savedViewsExpanded = false;
let savedViewsEditMode = false;
let savedViewSearchQuery = '';
let pendingSavedViewDeleteId = null;
let draggedSavedViewId = null;
let savedViewsSyncReady = false;
let savedViewsSyncTimer = null;

function readJsonStore(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch (e) {
    return fallback;
  }
}

function writeJsonStore(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) { /* ignore */ }
}

function readSavedViewsStore() {
  let views = readJsonStore(SAVED_VIEWS_KEY, null);
  if (!Array.isArray(views)) {
    views = readJsonStore(SAVED_VIEWS_BACKUP_KEY, []);
    if (Array.isArray(views) && views.length) writeSavedViewsStore(views);
  }
  return Array.isArray(views) ? views : [];
}

function writeSavedViewsStore(views, { sync = true } = {}) {
  writeJsonStore(SAVED_VIEWS_KEY, views);
  writeJsonStore(SAVED_VIEWS_BACKUP_KEY, views);
  if (sync) {
    localStorage.setItem(SAVED_VIEWS_DIRTY_KEY, '1');
    if (savedViewsSyncReady) scheduleSavedViewsSync();
  }
}

function scheduleSavedViewsSync() {
  clearTimeout(savedViewsSyncTimer);
  savedViewsSyncTimer = setTimeout(() => pushSavedViewsToServer(), 150);
}

async function pushSavedViewsToServer() {
  const views = readSavedViewsStore();
  const serializedViews = JSON.stringify(views);
  try {
    const response = await fetchWithTimeout(SAVED_VIEWS_API, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ views })
    }, 10000);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    if (JSON.stringify(readSavedViewsStore()) === serializedViews) {
      localStorage.removeItem(SAVED_VIEWS_DIRTY_KEY);
    } else {
      scheduleSavedViewsSync();
    }
  } catch (error) {
    // 本地副本已经保存；网络恢复或下次启动时会再次同步。
    console.warn('保存视图同步失败，将保留本地副本:', error);
  }
}

async function syncSavedViewsFromServer() {
  const localViews = readSavedViewsStore();
  const hasPendingLocalChanges = localStorage.getItem(SAVED_VIEWS_DIRTY_KEY) === '1';
  try {
    const response = await fetchWithTimeout(`${SAVED_VIEWS_API}?_=${Date.now()}`, {
      cache: 'no-store'
    }, 10000);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    const serverViews = Array.isArray(data.views) ? data.views : [];
    if (hasPendingLocalChanges) {
      await pushSavedViewsToServer();
    } else if (data.updated_at) {
      // 服务端已有数据时以服务端为准，保证各设备一致。
      writeSavedViewsStore(serverViews, { sync: false });
    } else if (localViews.length) {
      // 升级后的首次启动：把原来仅存在桌面浏览器里的视图迁移到服务端。
      await fetchWithTimeout(SAVED_VIEWS_API, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ views: localViews })
      }, 10000).then(response => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        localStorage.removeItem(SAVED_VIEWS_DIRTY_KEY);
      });
    }
  } catch (error) {
    console.warn('读取共享保存视图失败，继续使用本地副本:', error);
  } finally {
    savedViewsSyncReady = true;
    renderSavedViews();
  }
}

function clearActiveSavedView() {
  if (!state.activeSavedViewId && !state.activeSavedViewName) return;
  state.activeSavedViewId = null;
  state.activeSavedViewName = null;
  renderSavedViews();
}

function getArticleStatus(articleId) {
  return readJsonStore(ARTICLE_STATUS_KEY, {})[articleId] || 'new';
}

function setArticleStatus(articleId, status) {
  const store = readJsonStore(ARTICLE_STATUS_KEY, {});
  if (status === 'new') delete store[articleId];
  else store[articleId] = status;
  writeJsonStore(ARTICLE_STATUS_KEY, store);
  renderArticles(state.articles || []);
}

function getStatusLabel(status) {
  return ({ new: '未读', reading: '待读', todo: '待整理', done: '已整理' })[status] || '未读';
}

function recordRecentArticle(article) {
  if (!article || !article.id) return;
  const list = readJsonStore(RECENT_WORKSPACE_KEY, []);
  const next = [
    {
      id: article.id,
      title: article.title || '未命名文章',
      source: article.source_url || article.source_filename || article.source_localpath || '',
      summary: article.summary || '',
      status: getArticleStatus(article.id),
      ts: Date.now()
    },
    ...list.filter(item => item.id !== article.id)
  ].slice(0, 30);
  writeJsonStore(RECENT_WORKSPACE_KEY, next);
}

function getCurrentViewPayload() {
  return {
    name: $('page-title')?.textContent || '当前视图',
    view: state.view,
    q: state.q,
    searchScope: state.searchScope,
    fuzzy: state.fuzzy,
    domain: state.domain,
    author: state.author,
    customTag: state.customTag,
    currentTagGroupId: state.currentTagGroupId,
    customCategory: state.customCategory,
    customCategoryTags: state.customCategoryTags,
    sortMode: state.sortMode,
    articleDensity: state.articleDensity,
    savedAt: Date.now()
  };
}

function saveCurrentView() {
  const payload = getCurrentViewPayload();
  const suffix = state.q ? ` · ${state.q}` : '';
  const name = prompt('保存当前视图为：', `${payload.name}${suffix}`);
  if (!name) return;
  const list = readSavedViewsStore();
  const next = [{ ...payload, name, id: `view_${Date.now()}`, pinned: false }, ...list];
  writeSavedViewsStore(next);
  renderSavedViews();
  showToast('当前视图已保存');
}

function restoreSavedView(id) {
  const view = readSavedViewsStore().find(item => item.id === id);
  if (!view) return;
  const restoredView = ['all', 'url', 'file', 'notes'].includes(view.view) ? view.view : 'all';
  closeSavedViewsDropdown();
  Object.assign(state, {
    view: restoredView,
    q: view.q || '',
    searchScope: view.searchScope || 'all',
    fuzzy: view.fuzzy !== false,
    domain: view.domain || null,
    author: view.author || null,
    customTag: view.customTag || null,
    currentTagGroupId: view.currentTagGroupId || null,
    customCategory: view.customCategory || null,
    customCategoryTags: view.customCategoryTags || null,
    sortMode: view.sortMode || 'time',
    articleDensity: view.articleDensity || 'standard',
    activeSavedViewId: view.id,
    activeSavedViewName: view.name || '',
    page: 1
  });
  const searchInput = $('search-input');
  if (searchInput) searchInput.value = state.q;
  const fuzzyToggle = $('fuzzy-toggle');
  if (fuzzyToggle) fuzzyToggle.checked = state.fuzzy;
  const scopeSelect = $('search-scope');
  if (scopeSelect) scopeSelect.value = state.searchScope;
  applyArticleDensity();
  renderSortModeToggle();
  renderSavedViews();
  loadArticles();
  showToast(`已恢复视图：${view.name}`);
}

function deleteSavedView(id, event) {
  if (event) event.stopPropagation();
  if (!savedViewsEditMode) return;
  if (pendingSavedViewDeleteId !== id) {
    pendingSavedViewDeleteId = id;
    renderSavedViewDropdownList();
    return;
  }
  const next = readSavedViewsStore().filter(item => item.id !== id);
  writeSavedViewsStore(next);
  pendingSavedViewDeleteId = null;
  if (state.activeSavedViewId === id) {
    state.activeSavedViewId = null;
    state.activeSavedViewName = null;
  }
  renderSavedViews();
  showToast('已删除保存视图');
}

function cancelDeleteSavedView(event) {
  if (event) event.stopPropagation();
  pendingSavedViewDeleteId = null;
  renderSavedViewDropdownList();
}

function toggleSavedViewsExpanded() {
  if (savedViewsExpanded) closeSavedViewsDropdown();
  else openSavedViewsDropdown();
}

function openSavedViewsDropdown() {
  savedViewsExpanded = true;
  const shell = $('saved-view-shell');
  const dropdown = $('saved-view-dropdown');
  if (dropdown && dropdown.parentElement !== document.body) {
    document.body.appendChild(dropdown);
    dropdown.classList.add('saved-view-dropdown-portal');
  }
  if (shell) {
    shell.classList.add('open');
  }
  updateSavedViewsToggle();
  positionSavedViewsDropdown();
  requestAnimationFrame(() => dropdown?.classList.add('open'));
  setTimeout(() => $('saved-view-search')?.focus(), 120);
}

function closeSavedViewsDropdown(resetSearch = true) {
  savedViewsExpanded = false;
  savedViewsEditMode = false;
  pendingSavedViewDeleteId = null;
  if (resetSearch) savedViewSearchQuery = '';
  const shell = $('saved-view-shell');
  const dropdown = $('saved-view-dropdown');
  if (shell) {
    shell.classList.remove('open', 'editing');
  }
  dropdown?.classList.remove('open');
  const search = $('saved-view-search');
  if (search && resetSearch) search.value = '';
  updateSavedViewsToggle();
  renderSavedViewDropdownList();
}

function positionSavedViewsDropdown() {
  if (!savedViewsExpanded) return;
  const anchor = $('saved-view-toggle');
  const dropdown = $('saved-view-dropdown');
  if (!anchor || !dropdown) return;
  const rect = anchor.getBoundingClientRect();
  const visualViewport = window.visualViewport;
  const viewportLeft = visualViewport?.offsetLeft || 0;
  const viewportTop = visualViewport?.offsetTop || 0;
  const viewportWidth = visualViewport?.width || window.innerWidth;
  const viewportHeight = visualViewport?.height || window.innerHeight;
  const viewportPad = 12;
  const gap = 8;
  const width = Math.min(540, viewportWidth - viewportPad * 2);
  const left = Math.max(viewportLeft + viewportPad, Math.min(rect.right - width, viewportLeft + viewportWidth - width - viewportPad));
  const spaceBelow = viewportTop + viewportHeight - rect.bottom - gap - viewportPad;
  const spaceAbove = rect.top - viewportTop - gap - viewportPad;
  const desiredHeight = Math.min(560, Math.max(280, dropdown.scrollHeight || 0));
  const openUpward = spaceBelow < Math.min(300, desiredHeight) && spaceAbove > spaceBelow;
  const availableHeight = Math.max(220, openUpward ? spaceAbove : spaceBelow);
  dropdown.classList.toggle('opens-up', openUpward);
  dropdown.style.width = `${width}px`;
  dropdown.style.left = `${left}px`;
  dropdown.style.maxHeight = `${Math.min(560, availableHeight)}px`;
  dropdown.style.top = openUpward
    ? `${Math.max(viewportTop + viewportPad, rect.top - Math.min(desiredHeight, availableHeight) - gap)}px`
    : `${rect.bottom + gap}px`;
}

function updateSavedViewsToggle() {
  const shell = $('saved-view-shell');
  const toggle = $('saved-view-toggle');
  const dropdown = $('saved-view-dropdown');
  if (!shell || !toggle || !dropdown) return;
  shell.classList.toggle('open', savedViewsExpanded);
  toggle.textContent = savedViewsExpanded ? '收起视图' : `全部 ${readSavedViewsStore().length}`;
  toggle.setAttribute('aria-expanded', String(savedViewsExpanded));
  toggle.setAttribute('aria-label', savedViewsExpanded ? '收起已保存视图菜单' : '展开全部已保存视图');
  dropdown.setAttribute('aria-hidden', String(!savedViewsExpanded));
}

function toggleSavedViewEditMode() {
  savedViewsEditMode = !savedViewsEditMode;
  pendingSavedViewDeleteId = null;
  $('saved-view-shell')?.classList.toggle('editing', savedViewsEditMode);
  renderSavedViewDropdownList();
}

function setSavedViewSearch(value) {
  savedViewSearchQuery = String(value || '').trim().toLowerCase();
  pendingSavedViewDeleteId = null;
  renderSavedViewDropdownList();
}

function getOrderedSavedViews() {
  return readSavedViewsStore()
    .map((view, index) => ({ ...view, _savedIndex: index }))
    .sort((a, b) => Number(Boolean(b.pinned)) - Number(Boolean(a.pinned)) || a._savedIndex - b._savedIndex);
}

function togglePinSavedView(id, event) {
  if (event) event.stopPropagation();
  if (!savedViewsEditMode) return;
  const views = readSavedViewsStore();
  const target = views.find(item => item.id === id);
  if (!target) return;
  target.pinned = !target.pinned;
  const normalized = views
    .map((view, index) => ({ view, index }))
    .sort((a, b) => Number(Boolean(b.view.pinned)) - Number(Boolean(a.view.pinned)) || a.index - b.index)
    .map(item => item.view);
  writeSavedViewsStore(normalized);
  renderSavedViews();
  showToast(target.pinned ? '视图已置顶' : '已取消置顶');
}

function reorderSavedViews(sourceId, targetId, sourceElement = null, targetElement = null) {
  if (!sourceId || !targetId || sourceId === targetId) return;
  const views = readSavedViewsStore();
  const sourceIndex = views.findIndex(item => item.id === sourceId);
  const targetIndex = views.findIndex(item => item.id === targetId);
  if (sourceIndex < 0 || targetIndex < 0) return;
  if (Boolean(views[sourceIndex].pinned) !== Boolean(views[targetIndex].pinned)) {
    showToast('置顶视图与普通视图请分别排序');
    renderSavedViewDropdownList();
    return;
  }
  const listEl = targetElement?.parentElement;
  const beforeRects = listEl ? captureApexReorderRects(listEl, ':scope > .saved-view-dropdown-item') : null;
  const [moved] = views.splice(sourceIndex, 1);
  views.splice(targetIndex, 0, moved);
  if (sourceElement && targetElement && listEl) {
    const reference = sourceIndex < targetIndex ? targetElement.nextElementSibling : targetElement;
    if (reference !== sourceElement && sourceElement.nextElementSibling !== reference) {
      listEl.insertBefore(sourceElement, reference);
      animateApexReorder(listEl, beforeRects, { skip: sourceElement });
      markApexReorderCommitted(sourceElement);
    }
  }
  writeSavedViewsStore(views);
  renderSavedViewPreviewStrip();
  showToast('视图顺序已更新');
}

function bindSavedViewInteractions(el) {
  el.querySelectorAll('.saved-view-dropdown-item[draggable="true"]').forEach(chip => {
    chip.addEventListener('dragstart', event => {
      draggedSavedViewId = chip.dataset.viewId;
      chip.classList.add('dragging');
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', draggedSavedViewId);
    });
    chip.addEventListener('dragover', event => {
      event.preventDefault();
      if (draggedSavedViewId && draggedSavedViewId !== chip.dataset.viewId) {
        chip.classList.add('drag-over');
      }
    });
    chip.addEventListener('dragleave', () => chip.classList.remove('drag-over'));
    chip.addEventListener('drop', event => {
      event.preventDefault();
      const sourceId = draggedSavedViewId || event.dataTransfer.getData('text/plain');
      chip.classList.remove('drag-over');
      const sourceElement = sourceId
        ? el.querySelector(`.saved-view-dropdown-item[data-view-id="${CSS.escape(sourceId)}"]`)
        : null;
      reorderSavedViews(sourceId, chip.dataset.viewId, sourceElement, chip);
    });
    chip.addEventListener('dragend', () => {
      draggedSavedViewId = null;
      el.querySelectorAll('.saved-view-dropdown-item').forEach(item => item.classList.remove('dragging', 'drag-over'));
    });
  });
}

function renderSavedViewDropdownList() {
  const listEl = $('saved-view-dropdown-list');
  if (!listEl) return;
  const allViews = getOrderedSavedViews();
  const views = savedViewSearchQuery
    ? allViews.filter(view => String(view.name || '').toLowerCase().includes(savedViewSearchQuery))
    : allViews;
  const count = $('saved-view-count');
  const editToggle = $('saved-view-edit-toggle');
  if (count) count.textContent = savedViewSearchQuery ? `${views.length} / ${allViews.length} 个视图` : `${allViews.length} 个视图`;
  if (editToggle) {
    editToggle.textContent = savedViewsEditMode ? '完成' : '编辑';
    editToggle.classList.toggle('active', savedViewsEditMode);
  }
  if (!views.length) {
    listEl.innerHTML = `<div class="saved-view-search-empty">${allViews.length ? '未找到匹配的视图' : '暂无保存视图'}</div>`;
    return;
  }
  listEl.innerHTML = views.map(v => {
    const isPendingDelete = pendingSavedViewDeleteId === v.id;
    return `
      <div class="saved-view-dropdown-item ${v.pinned ? 'pinned' : ''} ${state.activeSavedViewId === v.id ? 'active' : ''} ${isPendingDelete ? 'confirming-delete' : ''}"
           data-view-id="${v.id}" role="listitem" draggable="${savedViewsEditMode && !isPendingDelete}">
        ${savedViewsEditMode ? '<span class="saved-view-drag-handle" title="拖动调整顺序" aria-label="拖动调整顺序">${SIDEBAR_ICONS.dragHandle}</span>' : ''}
        <button type="button" class="saved-view-item-main" onclick="restoreSavedView('${v.id}')" title="${escapeHtml(v.name)}">
          <span class="saved-view-pin-mark" aria-hidden="true">${v.pinned ? '◆' : ''}</span>
          <span class="saved-view-item-name">${escapeHtml(v.name)}</span>
          ${v.pinned ? '<small>置顶</small>' : ''}
        </button>
        ${savedViewsEditMode ? (isPendingDelete ? `
          <div class="saved-view-item-actions delete-confirm-actions">
            <span>确认删除？</span>
            <button type="button" class="saved-view-confirm-btn" onclick="deleteSavedView('${v.id}', event)">删除</button>
            <button type="button" class="saved-view-cancel-btn" onclick="cancelDeleteSavedView(event)">取消</button>
          </div>` : `
          <div class="saved-view-item-actions">
            <button type="button" class="saved-view-pin-btn" onclick="togglePinSavedView('${v.id}', event)">${v.pinned ? '取消置顶' : '置顶'}</button>
            <button type="button" class="saved-view-delete" onclick="deleteSavedView('${v.id}', event)" aria-label="删除视图 ${escapeHtml(v.name)}" title="删除">×</button>
          </div>`) : ''}
      </div>`;
  }).join('');
  if (savedViewsEditMode) bindSavedViewInteractions(listEl);
}

function renderSavedViewPreviewStrip() {
  const el = $('saved-view-strip');
  const toggle = $('saved-view-toggle');
  if (!el || !toggle) return;
  const views = getOrderedSavedViews();
  if (!views.length) {
    el.innerHTML = '<span class="saved-view-empty">暂无保存视图</span>';
    toggle.hidden = true;
    closeSavedViewsDropdown();
    return;
  }
  toggle.hidden = false;
  el.innerHTML = views.map(v => `
    <button type="button" class="saved-view-chip saved-view-preview-chip ${v.pinned ? 'pinned' : ''} ${state.activeSavedViewId === v.id ? 'active' : ''}"
            onclick="restoreSavedView('${v.id}')" title="${escapeHtml(v.name)}">
      ${v.pinned ? '<span class="saved-view-preview-pin" aria-hidden="true">◆</span>' : ''}${escapeHtml(v.name)}
    </button>`).join('');
}

function renderSavedViews() {
  const el = $('saved-view-strip');
  const toggle = $('saved-view-toggle');
  if (!el || !toggle) return;
  renderSavedViewPreviewStrip();
  renderSavedViewDropdownList();
  requestAnimationFrame(updateSavedViewsToggle);
}

document.addEventListener('click', event => {
  const shell = $('saved-view-shell');
  const dropdown = $('saved-view-dropdown');
  if (savedViewsExpanded && shell && !shell.contains(event.target) && !dropdown?.contains(event.target)) {
    closeSavedViewsDropdown();
  }
});

document.addEventListener('keydown', event => {
  if (event.key === 'Escape' && savedViewsExpanded) closeSavedViewsDropdown();
});

window.addEventListener('resize', positionSavedViewsDropdown);
document.addEventListener('scroll', positionSavedViewsDropdown, true);
window.visualViewport?.addEventListener('resize', positionSavedViewsDropdown);
window.visualViewport?.addEventListener('scroll', positionSavedViewsDropdown);

function getArticleQuality(article) {
  let score = 0;
  if (article.summary && article.summary.trim().length >= 20) score += 35;
  if (article.domains && article.domains.length) score += 25;
  if ((article.tags || []).filter(t => !String(t).startsWith('作者:')).length) score += 20;
  if (article.source_url || article.source_filename || article.source_localpath) score += 20;
  return Math.min(100, score);
}

function renderHealthStrip() {
  const el = $('kb-health-strip');
  if (!el) return;
  const articles = state.articles || [];
  const missingSummary = articles.filter(a => !a.summary).length;
  const uncategorized = articles.filter(a => !(a.domains || []).length).length;
  const todo = articles.filter(a => ['todo', 'reading'].includes(getArticleStatus(a.id))).length;
  const hints = [];
  if (missingSummary) hints.push({ type: 'missingSummary', label: `${missingSummary} 篇缺摘要` });
  if (uncategorized) hints.push({ type: 'uncategorized', label: `${uncategorized} 篇未分类` });
  if (todo) hints.push({ type: 'todo', label: `${todo} 篇待处理` });
  el.innerHTML = hints.length
    ? hints.map(h => `<button class="health-chip" onclick="applyHealthFilter('${h.type}')">${escapeHtml(h.label)}</button>`).join('')
    : '<span class="health-chip ok">当前页状态良好</span>';
}

function articleMatchesHealthFilter(article, type) {
  if (!type) return true;
  if (type === 'missingSummary') return !article.summary;
  if (type === 'uncategorized') return !(article.domains || []).length;
  if (type === 'todo') return ['todo', 'reading'].includes(getArticleStatus(article.id));
  return true;
}

function applyHealthFilter(type) {
  state.healthFilter = type;
  try { sessionStorage.setItem(HEALTH_FILTER_KEY, type || ''); } catch (e) {}
  renderArticles(state.articles || []);
  const labels = { missingSummary: '缺摘要文章', uncategorized: '未分类文章', todo: '待处理文章' };
  showToast(`已筛选：${labels[type] || '全部文章'}`);
}

function clearHealthFilter() {
  state.healthFilter = null;
  try { sessionStorage.removeItem(HEALTH_FILTER_KEY); } catch (e) {}
  renderArticles(state.articles || []);
}

function findSimilarArticles(article, articles) {
  const title = (article.title || '').replace(/[，。、《》（）()\s]/g, '');
  if (!title || title.length < 8) return [];
  return articles.filter(other => {
    if (other.id === article.id) return false;
    const otherTitle = (other.title || '').replace(/[，。、《》（）()\s]/g, '');
    if (!otherTitle) return false;
    const common = [...new Set(title)].filter(ch => otherTitle.includes(ch)).length;
    return common / Math.max(1, Math.min(title.length, otherTitle.length)) > 0.62;
  });
}

function buildMatchBadges(article) {
  if (!state.q) return '';
  const q = state.q.toLowerCase();
  const badges = [];
  if ((article.title || '').toLowerCase().includes(q)) badges.push('标题命中');
  if ((article.summary || '').toLowerCase().includes(q)) badges.push('摘要命中');
  if ((article.tags || []).some(t => String(t).toLowerCase().includes(q))) badges.push('标签命中');
  if ((article.content_snippets || []).length) badges.push('正文命中');
  return badges.map(b => `<span class="card-insight-chip match">${b}</span>`).join('');
}

function buildArticleInsightBadges(article, allArticles) {
  const quality = getArticleQuality(article);
  const status = getArticleStatus(article.id);
  const similarCount = findSimilarArticles(article, allArticles).length;
  const badges = [
    `<span class="card-insight-chip status-${status}">${getStatusLabel(status)}</span>`,
    `<span class="card-insight-chip quality-${quality >= 80 ? 'good' : quality >= 55 ? 'mid' : 'low'}">质量 ${quality}</span>`
  ];
  if (similarCount) badges.push(`<span class="card-insight-chip warning">相似 ${similarCount}</span>`);
  return badges.join('') + buildMatchBadges(article);
}

function toggleArticleSelection(articleId, checked) {
  if (checked) state.selectedArticleIds.add(articleId);
  else state.selectedArticleIds.delete(articleId);
  renderBulkActionBar();
}

function clearArticleSelection() {
  state.selectedArticleIds.clear();
  renderArticles(state.articles || []);
}

function renderBulkActionBar() {
  const bar = $('bulk-action-bar');
  const countEl = $('bulk-selected-count');
  if (!bar || !countEl) return;
  const count = state.selectedArticleIds.size;
  bar.style.display = count ? 'flex' : 'none';
  document.body.classList.toggle('has-bulk-selection', !!count);
  countEl.textContent = `已选择 ${count} 篇`;
}

function bulkSetStatus(status) {
  [...state.selectedArticleIds].forEach(id => {
    const store = readJsonStore(ARTICLE_STATUS_KEY, {});
    if (status === 'new') delete store[id];
    else store[id] = status;
    writeJsonStore(ARTICLE_STATUS_KEY, store);
  });
  renderArticles(state.articles || []);
  showToast('已更新处理状态');
}

let bulkEditingTags = [];

async function openBulkTagsModal() {
  const count = state.selectedArticleIds.size;
  if (!count) {
    showToast('请先选择文章', 'warning');
    return;
  }

  bulkEditingTags = [];
  $('bulk-tags-description').textContent = `将标签添加到已选择的 ${count} 篇文章，文章原有标签会保留。`;
  $('bulk-new-tag-input').value = '';
  renderBulkSelectedTags();
  renderBulkCommonTags();
  $('bulk-tags-modal').classList.add('open');

  // 标签目录尚未加载时，主动获取一次，保证候选项完整。
  if (!_tagGroupsCache.length) {
    try {
      const cats = await apiFetch('/api/tag-categories');
      _tagCategoriesCache = cats;
      _tagGroupsCache = cats.flatMap(cat => cat.tags || []);
      renderBulkCommonTags();
    } catch (error) {
      console.warn('Failed to load tags for bulk editor:', error);
    }
  }
}

function closeBulkTagsModal() {
  $('bulk-tags-modal').classList.remove('open');
  bulkEditingTags = [];
}

function renderBulkSelectedTags() {
  const container = $('bulk-selected-tags');
  if (!bulkEditingTags.length) {
    container.innerHTML = '<div class="tags-empty">尚未选择标签</div>';
    return;
  }
  container.innerHTML = bulkEditingTags.map((tag, index) => `
    <span class="tag-item custom">
      ${SIDEBAR_ICONS.tag} ${escapeHtml(tag)}
      <button class="tag-remove" type="button" data-bulk-tag-index="${index}" aria-label="移除 ${escapeHtml(tag)}">×</button>
    </span>
  `).join('');
  container.querySelectorAll('[data-bulk-tag-index]').forEach(button => {
    button.addEventListener('click', () => removeBulkTag(Number(button.dataset.bulkTagIndex)));
  });
}

function renderBulkCommonTags() {
  const container = $('bulk-common-tags');
  const names = [...new Set((_tagGroupsCache || [])
    .map(tag => String(tag.name || '').trim())
    .filter(name => name && !name.startsWith('作者:')))]
    .filter(name => !bulkEditingTags.includes(name));
  if (!names.length) {
    container.innerHTML = '<div class="tags-empty">暂无其他已有标签</div>';
    return;
  }
  container.innerHTML = names.map((tag, index) => `
    <button class="tag-item common" type="button" data-bulk-common-index="${index}">${SIDEBAR_ICONS.tag} ${escapeHtml(tag)}</button>
  `).join('');
  container.querySelectorAll('[data-bulk-common-index]').forEach(button => {
    button.addEventListener('click', () => addBulkTag(names[Number(button.dataset.bulkCommonIndex)]));
  });
}

function addBulkTag(tagName) {
  const tag = String(tagName || '').trim();
  if (!tag || bulkEditingTags.includes(tag)) return;
  if (tag.startsWith('作者:')) {
    showToast('作者标签由系统自动生成，不能手动添加', 'warning');
    return;
  }
  bulkEditingTags.push(tag);
  renderBulkSelectedTags();
  renderBulkCommonTags();
}

function addBulkTagsFromInput() {
  const input = $('bulk-new-tag-input');
  const tags = input.value.split(/[,，]/).map(tag => tag.trim()).filter(Boolean);
  if (!tags.length) return;
  tags.forEach(addBulkTag);
  input.value = '';
  input.focus();
}

function removeBulkTag(index) {
  bulkEditingTags.splice(index, 1);
  renderBulkSelectedTags();
  renderBulkCommonTags();
}

async function saveBulkTags() {
  const articleIds = [...state.selectedArticleIds];
  if (!articleIds.length) {
    closeBulkTagsModal();
    showToast('所选文章已取消', 'warning');
    return;
  }
  if (!bulkEditingTags.length) {
    showToast('请至少添加一个标签', 'warning');
    return;
  }

  const button = $('confirm-bulk-tags-btn');
  button.disabled = true;
  button.textContent = '正在添加…';
  try {
    const result = await apiFetch('/api/articles/bulk/tags', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ article_ids: articleIds, tags: bulkEditingTags })
    });
    closeBulkTagsModal();
    state.selectedArticleIds.clear();
    await Promise.all([loadArticles(), loadCustomTags(), loadStats()]);
    const message = result.updated_articles
      ? `已为 ${result.updated_articles} 篇文章添加标签`
      : '所选文章已包含这些标签';
    showToast(message);
  } catch (error) {
    console.error('Bulk add tags error:', error);
    showToast(error.message || '批量添加标签失败', 'error');
  } finally {
    button.disabled = false;
    button.textContent = '添加到所选文章';
  }
}

function bulkExportSelected() {
  const selected = (state.articles || []).filter(a => state.selectedArticleIds.has(a.id));
  const lines = ['标题,来源,日期,状态,摘要'].concat(selected.map(a =>
    [a.title, a.source_url || a.source_filename || '', formatDate(a.created_at), getStatusLabel(getArticleStatus(a.id)), a.summary || '']
      .map(v => `"${String(v).replace(/"/g, '""')}"`).join(',')
  ));
  const blob = new Blob([lines.join('\n')], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `知识库文章清单_${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  recordApexDownload(a.download, 'export', '知识库');
  URL.revokeObjectURL(url);
}

async function bulkDeleteSelected() {
  const articleIds = [...state.selectedArticleIds];
  const count = articleIds.length;
  if (!count) {
    showToast('请先选择文章', 'warning');
    return;
  }
  if (!await confirmArticleTrashAction('移入回收站？', `所选 ${count} 篇文章及其笔记将保留30天，期间可恢复。`, '移入回收站')) return;

  try {
    const result = await apiFetch('/api/articles/bulk', {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ article_ids: articleIds })
    });
    state.selectedArticleIds.clear();
    // 删除当前页最后几篇时，回退到仍有内容的上一页，避免停留在空页。
    if (state.page > 1 && (state.articles || []).length <= count) state.page -= 1;
    await Promise.all([loadArticles(), loadStats(), loadDomains(), loadAuthors(), loadCustomTags()]);
    showToast(`已将 ${result.deleted_count} 篇文章移入回收站`);
  } catch (error) {
    console.error('Bulk delete articles error:', error);
    showToast(error.message || '批量删除失败', 'error');
  }
}

const ARTICLE_TRASH_PAGE_SIZE = 100;
const articleTrashState = { items: [], total: 0, selected: new Set(), loading: false, opener: null };

function confirmArticleTrashAction(title, message, confirmLabel = '确认', danger = false) {
  return new Promise(resolve => {
    const previousFocus = document.activeElement;
    const overlay = document.createElement('div');
    overlay.className = 'article-trash-confirm-overlay';
    overlay.innerHTML = `
      <section class="article-trash-confirm" role="alertdialog" aria-modal="true" aria-labelledby="article-trash-confirm-title" aria-describedby="article-trash-confirm-message">
        <h3 id="article-trash-confirm-title"></h3>
        <p id="article-trash-confirm-message"></p>
        <div class="article-trash-confirm-actions">
          <button type="button" data-confirm="cancel">取消</button>
          <button type="button" class="${danger ? 'danger' : 'primary'}" data-confirm="accept"></button>
        </div>
      </section>`;
    overlay.querySelector('#article-trash-confirm-title').textContent = title;
    overlay.querySelector('#article-trash-confirm-message').textContent = message;
    overlay.querySelector('[data-confirm="accept"]').textContent = confirmLabel;
    const finish = accepted => {
      document.removeEventListener('keydown', onKey);
      overlay.remove();
      previousFocus?.focus?.({ preventScroll: true });
      resolve(accepted);
    };
    const onKey = event => {
      if (event.key === 'Escape') { event.preventDefault(); finish(false); }
    };
    overlay.addEventListener('click', event => {
      if (event.target === overlay || event.target.closest('[data-confirm="cancel"]')) finish(false);
      else if (event.target.closest('[data-confirm="accept"]')) finish(true);
    });
    document.body.appendChild(overlay);
    document.addEventListener('keydown', onKey);
    overlay.querySelector('[data-confirm="cancel"]').focus();
  });
}

function ensureArticleTrashModal() {
  let overlay = $('article-trash-overlay');
  if (overlay) return overlay;
  overlay = document.createElement('div');
  overlay.id = 'article-trash-overlay';
  overlay.className = 'article-trash-overlay';
  overlay.hidden = true;
  overlay.innerHTML = `
    <section class="article-trash-dialog" role="dialog" aria-modal="true" aria-labelledby="article-trash-title" tabindex="-1">
      <header class="article-trash-head">
        <div><h2 id="article-trash-title">知识库回收站</h2><p>每篇文章从删除时起保留30天，到期自动清理。原始上传文件不受影响。</p></div>
        <button type="button" class="article-trash-close" data-trash-action="close" aria-label="关闭回收站">×</button>
      </header>
      <div class="article-trash-toolbar">
        <label class="article-trash-select-all"><input type="checkbox" id="article-trash-select-all">选择已加载</label>
        <span id="article-trash-count">正在加载…</span>
        <button type="button" data-trash-action="restore-selected" disabled>恢复所选</button>
        <button type="button" data-trash-action="purge-selected" class="danger" disabled>彻底删除所选</button>
        <button type="button" data-trash-action="clear-all" class="danger" disabled>清空回收站</button>
      </div>
      <div class="article-trash-list" id="article-trash-list"></div>
      <footer class="article-trash-footer"><span id="article-trash-footnote">删除后的文章不会出现在搜索和知识列表中。</span><button type="button" data-trash-action="more" hidden>加载更多</button></footer>
    </section>`;
  overlay.addEventListener('click', async event => {
    if (event.target === overlay) { closeArticleTrash(); return; }
    const button = event.target.closest('[data-trash-action]');
    if (!button || articleTrashState.loading) return;
    const action = button.dataset.trashAction;
    const id = Number(button.dataset.trashId || 0);
    if (action === 'close') closeArticleTrash();
    else if (action === 'more') await loadArticleTrash(false);
    else if (action === 'restore-one') await restoreArticleTrashItems([id]);
    else if (action === 'purge-one') await purgeArticleTrashItems([id]);
    else if (action === 'restore-selected') await restoreArticleTrashItems([...articleTrashState.selected]);
    else if (action === 'purge-selected') await purgeArticleTrashItems([...articleTrashState.selected]);
    else if (action === 'clear-all') await purgeArticleTrashItems(null);
  });
  overlay.addEventListener('change', event => {
    if (event.target.id === 'article-trash-select-all') {
      articleTrashState.items.forEach(item => {
        if (event.target.checked) articleTrashState.selected.add(item.id);
        else articleTrashState.selected.delete(item.id);
      });
      overlay.querySelectorAll('[data-trash-select]').forEach(input => { input.checked = event.target.checked; });
    } else if (event.target.matches('[data-trash-select]')) {
      const id = Number(event.target.dataset.trashSelect);
      if (event.target.checked) articleTrashState.selected.add(id);
      else articleTrashState.selected.delete(id);
    }
    updateArticleTrashActions();
  });
  overlay.addEventListener('keydown', event => {
    if (event.key === 'Escape' && !document.querySelector('.article-trash-confirm-overlay')) {
      event.preventDefault();
      closeArticleTrash();
    }
  });
  document.body.appendChild(overlay);
  return overlay;
}

function formatArticleTrashDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '时间未知' : date.toLocaleString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
}

function renderArticleTrash() {
  const overlay = $('article-trash-overlay');
  if (!overlay) return;
  const list = $('article-trash-list');
  list.innerHTML = articleTrashState.items.length ? articleTrashState.items.map(item => `
    <article class="article-trash-row">
      <label class="article-trash-check"><input type="checkbox" data-trash-select="${item.id}" aria-label="选择${escapeHtml(item.title)}" ${articleTrashState.selected.has(item.id) ? 'checked' : ''}></label>
      <div class="article-trash-main"><strong title="${escapeHtml(item.title)}">${escapeHtml(item.title)}</strong><small>删除于 ${formatArticleTrashDate(item.deleted_at)} · ${formatArticleTrashDate(item.expires_at)} 自动清理</small></div>
      <div class="article-trash-row-actions"><button type="button" data-trash-action="restore-one" data-trash-id="${item.id}">恢复</button><button type="button" class="danger" data-trash-action="purge-one" data-trash-id="${item.id}">彻底删除</button></div>
    </article>`).join('') : '<div class="article-trash-empty">回收站是空的。误删的文章会在这里保留30天。</div>';
  $('article-trash-count').textContent = `共 ${articleTrashState.total} 篇`;
  overlay.querySelector('[data-trash-action="more"]').hidden = articleTrashState.items.length >= articleTrashState.total;
  updateArticleTrashActions();
}

function updateArticleTrashActions() {
  const overlay = $('article-trash-overlay');
  if (!overlay) return;
  const selectedCount = articleTrashState.selected.size;
  overlay.querySelector('[data-trash-action="restore-selected"]').disabled = !selectedCount || articleTrashState.loading;
  overlay.querySelector('[data-trash-action="purge-selected"]').disabled = !selectedCount || articleTrashState.loading;
  overlay.querySelector('[data-trash-action="clear-all"]').disabled = !articleTrashState.total || articleTrashState.loading;
  const selectAll = $('article-trash-select-all');
  selectAll.disabled = !articleTrashState.items.length || articleTrashState.loading;
  selectAll.checked = Boolean(articleTrashState.items.length && articleTrashState.items.every(item => articleTrashState.selected.has(item.id)));
  selectAll.indeterminate = Boolean(!selectAll.checked && articleTrashState.items.some(item => articleTrashState.selected.has(item.id)));
}

async function loadArticleTrash(reset = true) {
  if (articleTrashState.loading) return;
  articleTrashState.loading = true;
  if (reset) {
    articleTrashState.items = [];
    articleTrashState.selected.clear();
    $('article-trash-list').innerHTML = '<div class="article-trash-empty">正在读取回收站…</div>';
  }
  updateArticleTrashActions();
  try {
    const offset = reset ? 0 : articleTrashState.items.length;
    const result = await apiFetch(`/api/articles/trash?limit=${ARTICLE_TRASH_PAGE_SIZE}&offset=${offset}`);
    articleTrashState.items = reset ? result.items : articleTrashState.items.concat(result.items || []);
    articleTrashState.total = Number(result.total || 0);
    renderArticleTrash();
  } catch (error) {
    $('article-trash-list').innerHTML = `<div class="article-trash-empty">${escapeHtml(error.message || '加载失败')}</div>`;
  } finally {
    articleTrashState.loading = false;
    updateArticleTrashActions();
  }
}

function openArticleTrash() {
  const overlay = ensureArticleTrashModal();
  articleTrashState.opener = document.activeElement;
  overlay.hidden = false;
  overlay.querySelector('.article-trash-dialog').focus();
  loadArticleTrash(true);
}

function closeArticleTrash() {
  const overlay = $('article-trash-overlay');
  if (!overlay) return;
  overlay.hidden = true;
  articleTrashState.opener?.focus?.({ preventScroll: true });
}

async function restoreArticleTrashItems(ids) {
  if (!ids.length) return;
  if (ids.length > 500) { showToast('每次最多恢复500篇文章', 'warning'); return; }
  articleTrashState.loading = true;
  updateArticleTrashActions();
  try {
    const result = await apiFetch('/api/articles/trash/restore', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ trash_ids: ids })
    });
    showToast(result.restored_count
      ? `已恢复 ${result.restored_count} 篇文章${result.skipped_related_rows ? `；${result.skipped_related_rows} 条失效关联未恢复` : ''}`
      : '所选文章已到期或不在回收站中', result.restored_count ? 'success' : 'warning');
    await Promise.allSettled([loadArticles(), loadStats(), loadDomains(), loadAuthors(), loadCustomTags()]);
  } catch (error) {
    showToast(error.message || '恢复失败', 'error');
  } finally {
    articleTrashState.loading = false;
    await loadArticleTrash(true);
  }
}

async function purgeArticleTrashItems(ids) {
  const count = ids === null ? articleTrashState.total : ids.length;
  if (!count) return;
  if (ids && ids.length > 500) { showToast('每次最多彻底删除500篇文章，也可清空整个回收站', 'warning'); return; }
  const accepted = await confirmArticleTrashAction('彻底删除回收站文章？', `将永久删除 ${count} 篇文章的恢复快照，此操作无法撤销。原始上传文件不受影响。`, '彻底删除', true);
  if (!accepted) return;
  articleTrashState.loading = true;
  updateArticleTrashActions();
  try {
    const result = await apiFetch('/api/articles/trash', {
      method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(ids === null ? { clear_all: true } : { trash_ids: ids })
    });
    showToast(`已彻底删除 ${result.deleted_count} 篇文章`);
  } catch (error) {
    showToast(error.message || '彻底删除失败', 'error');
  } finally {
    articleTrashState.loading = false;
    await loadArticleTrash(true);
  }
}

function showRecentWorkspace() {
  const recent = readJsonStore(RECENT_WORKSPACE_KEY, []);
  const modal = $('recent-workspace-modal');
  const body = $('recent-workspace-body');
  if (!modal || !body) return;
  if (!recent.length) {
    body.innerHTML = `
      <div class="recent-empty">
        <span class="recent-empty-mark" aria-hidden="true">⌁</span>
        <strong>暂时没有阅读记录</strong>
        <span>打开一篇知识库文章后，会自动保留在这里。</span>
      </div>`;
  } else {
    const statusCount = recent.reduce((counts, item) => {
      const status = getArticleStatus(item.id);
      counts[status] = (counts[status] || 0) + 1;
      return counts;
    }, {});
    body.innerHTML = `
      <div class="recent-summary">
        <div class="recent-summary-copy">
          <span class="recent-summary-label">最近 ${recent.length} 篇</span>
          <span>点击文章即可继续阅读</span>
        </div>
        <div class="recent-summary-stats" aria-label="阅读状态汇总">
          ${statusCount.reading ? `<span><b>${statusCount.reading}</b> 待读</span>` : ''}
          ${statusCount.todo ? `<span><b>${statusCount.todo}</b> 待整理</span>` : ''}
          ${statusCount.done ? `<span><b>${statusCount.done}</b> 已整理</span>` : ''}
          ${!statusCount.reading && !statusCount.todo && !statusCount.done ? '<span>均为未读</span>' : ''}
        </div>
      </div>
      <div class="recent-list">
        ${recent.map(item => {
          const status = getArticleStatus(item.id);
          const id = JSON.stringify(item.id);
          return `
          <article class="recent-item status-${status}">
            <button type="button" class="recent-main" onclick="openRecentArticle(${id})" title="继续阅读：${escapeHtml(item.title)}">
              <div class="recent-item-topline">
                <div class="recent-title">${escapeHtml(item.title)}</div>
                <span class="recent-status-pill ${status}">${getStatusLabel(status)}</span>
              </div>
              <div class="recent-meta">
                <span class="recent-source">${escapeHtml(formatRecentSource(item.source))}</span>
                <span>${formatRecentTime(item.ts)}</span>
              </div>
              <div class="recent-summary-text">${escapeHtml(truncate(item.summary || '暂无摘要', 150))}</div>
            </button>
            <div class="recent-actions">
              <button type="button" class="recent-status-action ${status === 'reading' ? 'is-active' : ''}" aria-pressed="${status === 'reading'}" onclick="setRecentArticleStatus(${id}, 'reading')">待读</button>
              <button type="button" class="recent-status-action done ${status === 'done' ? 'is-active' : ''}" aria-pressed="${status === 'done'}" onclick="setRecentArticleStatus(${id}, 'done')">已整理</button>
              <button type="button" class="recent-remove" onclick="removeRecentArticle(${id})" aria-label="从最近阅读中移除">移除</button>
            </div>
          </article>`;
        }).join('')}
      </div>`;
  }
  modal.classList.add('open');
}

function closeRecentWorkspace() {
  const modal = $('recent-workspace-modal');
  if (modal) modal.classList.remove('open');
}

function refreshRecentWorkspace() {
  showRecentWorkspace();
}

function setRecentArticleStatus(id, status) {
  setArticleStatus(id, status);
  refreshRecentWorkspace();
}

function formatRecentTime(ts) {
  if (!ts) return '未知时间';
  const diff = Date.now() - ts;
  if (diff < 60_000) return '刚刚';
  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)} 分钟前`;
  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)} 小时前`;
  return `${Math.floor(diff / 86_400_000)} 天前`;
}

function formatRecentSource(source) {
  const value = String(source || '').trim();
  if (!value) return '知识库文章';
  try {
    const url = new URL(value);
    return url.hostname.replace(/^www\./, '') || '网页来源';
  } catch (e) {
    const filename = value.split(/[\\/]/).pop() || value;
    return truncate(filename, 42);
  }
}

function openRecentArticle(id) {
  closeRecentWorkspace();
  const recent = readJsonStore(RECENT_WORKSPACE_KEY, []);
  const item = recent.find(r => r.id === id);
  openArticleInTab(id, item ? item.title : '文章详情');
}

function removeRecentArticle(id) {
  const next = readJsonStore(RECENT_WORKSPACE_KEY, []).filter(item => item.id !== id);
  writeJsonStore(RECENT_WORKSPACE_KEY, next);
  showRecentWorkspace();
}

function clearRecentWorkspace() {
  writeJsonStore(RECENT_WORKSPACE_KEY, []);
  showRecentWorkspace();
}

function getCurrentResultsAskTitle() {
  if (state.activeSavedViewName) return state.activeSavedViewName;
  if (state.domain) return state.domain;
  if (state.author) return state.author;
  if (state.customTag) return state.customTag;

  if (state.customCategory) {
    const cat = _tagCategoriesCache.find(item => item.id === state.customCategory);
    if (cat?.name) return cat.name;
    const catEl = document.querySelector(`.tag-category[data-cat-id="${state.customCategory}"]`);
    if (catEl?.dataset?.catName) return catEl.dataset.catName;
  }

  const viewTitles = { all: '全部知识', url: '网页来源', file: '本地文档', notes: '笔记视图' };
  const baseTitle = $('page-title')?.textContent?.trim() || viewTitles[state.view] || '当前结果';
  if (state.q) return `${baseTitle} · 搜索「${state.q}」`;
  return baseTitle;
}

function openCurrentResultsAskPanel() {
  const articles = (state.articles || []).slice(0, 10);
  if (!articles.length) {
    showToast('当前结果为空，无法发起问答', 'warning');
    return;
  }
  askContext = {
    type: 'results',
    title: getCurrentResultsAskTitle(),
    ids: articles.map(a => a.id),
    titles: articles.map(a => a.title)
  };
  openAskPanel();
}

/* ─────────────────────────────────────────────
   今日推荐
───────────────────────────────────────────── */
const HOME_RECOMMEND_VISIBLE_KEY = 'legal_kb_home_recommend_visible';
let homeRecommendationRefresh = 0;
let homeRecommendationItems = [];
let homeRecommendationExcludedIds = new Set();

function isHomeRecommendationsVisible() {
  try {
    return localStorage.getItem(HOME_RECOMMEND_VISIBLE_KEY) !== '0';
  } catch (e) {
    return true;
  }
}

function isMobileHomeLayout() {
  return window.matchMedia?.('(max-width: 760px)').matches === true;
}

function applyHomeOfflineLayout() {
  const mobileOffline = serverConnectionOnline === false && isMobileHomeLayout();
  const mainPage = $('tab-page-main');
  if (mainPage) mainPage.classList.toggle('home-offline-mode', mobileOffline);
  document.querySelectorAll('#tab-page-main .kb-home-hero, #tab-page-main .kb-home-overview').forEach(card => {
    card.hidden = mobileOffline;
  });
  const recommendationPanel = $('home-recommend-panel');
  if (recommendationPanel) recommendationPanel.hidden = mobileOffline;
  document.querySelectorAll('#tab-page-main #home-recommend-toggle, #tab-page-main [onclick="openRecommendationsTab()"]')
    .forEach(control => { control.disabled = mobileOffline; });
  if (!mobileOffline) applyHomeRecommendationVisibility();
  else updateHomeRecommendationOffset();
}

function applyHomeRecommendationVisibility() {
  const visible = isHomeRecommendationsVisible();
  const panel = $('home-recommend-panel');
  const btn = $('home-recommend-toggle');
  if (panel) panel.style.display = visible ? '' : 'none';
  if (btn) btn.textContent = visible ? '隐藏今日推荐' : '显示今日推荐';
  updateHomeRecommendationOffset();
  if (visible && !homeRecommendationItems.length) loadHomeRecommendations(0);
}

function updateHomeRecommendationOffset() {
  const mainPage = $('tab-page-main');
  const panel = $('home-recommend-panel');
  if (!mainPage) return;
  const visible = panel && !panel.hidden && panel.style.display !== 'none';
  const height = visible ? Math.ceil(panel.getBoundingClientRect().height) : 0;
  mainPage.style.setProperty('--home-recommend-offset', `${height}px`);
}

function toggleHomeRecommendations() {
  const nextVisible = !isHomeRecommendationsVisible();
  try {
    localStorage.setItem(HOME_RECOMMEND_VISIBLE_KEY, nextVisible ? '1' : '0');
  } catch (e) {}
  applyHomeRecommendationVisibility();
}

async function recordRecommendationFeedback(articleId, action, extra = {}) {
  try {
    await apiFetch('/api/recommendations/feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        article_id: articleId,
        action,
        context: 'home',
        extra
      })
    });
  } catch (e) {
    console.warn('recommendation feedback failed', e);
  }
}

async function loadHomeRecommendations(refreshDelta = 0) {
  if (!isHomeRecommendationsVisible()) return;
  const list = $('home-recommend-list');
  const subtitle = $('home-recommend-subtitle');
  if (!list) return;
  if (refreshDelta) {
    homeRecommendationItems.slice(0, 3).forEach(item => homeRecommendationExcludedIds.add(item.id));
    homeRecommendationRefresh += 1;
  }
  list.innerHTML = '<div class="recommend-loading">正在挑选今日推荐...</div>';
  try {
    const params = new URLSearchParams({
      limit: '12',
      refresh: String(homeRecommendationRefresh),
    });
    if (homeRecommendationExcludedIds.size) {
      params.set('exclude_ids', [...homeRecommendationExcludedIds].join(','));
    }
    const data = await apiFetch(`/api/recommendations/today?${params}`);
    homeRecommendationItems = data.items || [];
    if (refreshDelta && homeRecommendationItems.length < 3) {
      homeRecommendationExcludedIds.clear();
      return loadHomeRecommendations(0);
    }
    if (subtitle) subtitle.textContent = `${data.date || ''} · 从知识库里挑 3 条值得打开的内容`;
    renderHomeRecommendations();
  } catch (e) {
    list.innerHTML = `<div class="recommend-error">今日推荐加载失败：${escapeHtml(e.message)}</div>`;
    requestAnimationFrame(updateHomeRecommendationOffset);
  }
}

function renderHomeRecommendations() {
  const list = $('home-recommend-list');
  if (!list) return;
  const visibleItems = homeRecommendationItems.slice(0, 3);
  if (!visibleItems.length) {
    list.innerHTML = '<div class="recommend-empty">暂时没有可推荐内容</div>';
    requestAnimationFrame(updateHomeRecommendationOffset);
    return;
  }
  list.innerHTML = visibleItems.map(item => renderHomeRecommendationCard(item)).join('');
  requestAnimationFrame(updateHomeRecommendationOffset);
}

function renderHomeRecommendationCard(item) {
  const domains = (item.domains || []).slice(0, 2).map(d => `<span>${escapeHtml(d)}</span>`).join('');
  const status = getArticleStatus(item.id);
  return `
    <article class="home-recommend-card" data-recommend-id="${item.id}">
      <div class="home-recommend-main" onclick="openHomeRecommendation(${item.id})">
        <div class="home-recommend-title">${escapeHtml(item.title || '未命名文章')}</div>
        <div class="home-recommend-reason">${escapeHtml(item.reason || '适合今日回看')}</div>
        <div class="home-recommend-summary">${escapeHtml(truncate(item.summary || '暂无摘要', 92))}</div>
        <div class="home-recommend-meta">
          ${domains}
          <span>${escapeHtml(item.source_label || '知识库')}</span>
          <span>${escapeHtml(item.reading_load || '中等')}</span>
          <span>${escapeHtml(getStatusLabel(status))}</span>
        </div>
      </div>
      <div class="home-recommend-card-actions">
        <button onclick="event.stopPropagation(); markHomeRecommendation(${item.id}, 'reading')">待读</button>
        <button onclick="event.stopPropagation(); skipHomeRecommendation(${item.id})">换一篇</button>
      </div>
    </article>
  `;
}

function openHomeRecommendation(articleId) {
  const item = homeRecommendationItems.find(x => x.id === articleId);
  if (item) {
    recordRecentArticle(item);
    recordRecommendationFeedback(articleId, 'opened', { title: item.title || '' });
  }
  openArticleInTab(articleId, item ? item.title : '文章详情');
}

async function markHomeRecommendation(articleId, status) {
  setArticleStatus(articleId, status);
  await recordRecommendationFeedback(articleId, status === 'done' ? 'done' : 'read');
  renderHomeRecommendations();
}

async function skipHomeRecommendation(articleId) {
  await recordRecommendationFeedback(articleId, 'skipped');
  homeRecommendationItems = homeRecommendationItems.filter(item => item.id !== articleId);
  if (homeRecommendationItems.length < 3) {
    homeRecommendationRefresh += 1;
    await loadHomeRecommendations(0);
  } else {
    renderHomeRecommendations();
  }
}

/* ─────────────────────────────────────────────
   案件研究工作台
───────────────────────────────────────────── */
function createResearchState(tabId = null) {
  return {
  tabId,
  cases: [],
  activeCaseId: null,
  activeCase: null,
  projects: [],
  activeProjectId: null,
  activeProject: null,
  articles: [],
  questions: [],
  memos: [],
  ledgers: [],
  memoEntries: [],
  ledgerQuery: '',
  memoEntryQuery: '',
  qaQuery: '',
  qaLoading: false,
  qaLoadingStartedAt: 0,
  qaLoadingModel: '',
  expandedQuestionIds: new Set(),
  watchTasks: [],
  watchResults: [],
  caseListScrollTop: 0,
  pendingCaseId: null,
  pendingSection: 'ledger',
  };
}

const researchStatesByTabId = new Map();
let researchState = createResearchState();

function activateResearchStateForTab(tabId) {
  if (!tabId) return researchState;
  let tabResearchState = researchStatesByTabId.get(tabId);
  if (!tabResearchState) {
    const tab = tabState.tabs.find(item => item.id === tabId);
    tabResearchState = createResearchState(tabId);
    tabResearchState.pendingCaseId = Number(tab?.data?.caseId || 0) || null;
    tabResearchState.pendingSection = ['memo', 'qa'].includes(tab?.data?.section) ? tab.data.section : 'ledger';
    researchStatesByTabId.set(tabId, tabResearchState);
  }
  researchState = tabResearchState;
  return tabResearchState;
}

function updateResearchTabContext(tabId = researchState.tabId) {
  const tab = tabState.tabs.find(item => item.id === tabId && item.type === TAB_TYPES.RESEARCH_PROJECTS);
  if (!tab) return;
  const tabResearchState = researchStatesByTabId.get(tabId) || researchState;
  const activeCase = tabResearchState.activeCase;
  const fallbackCase = tabResearchState.cases?.find(item => Number(item.id) === Number(tabResearchState.activeCaseId));
  const contextLabel = activeCase?.title || fallbackCase?.title || '未选择具体案件';
  tab.data = {
    ...(tab.data || {}),
    caseId: Number(activeCase?.id || fallbackCase?.id || tabResearchState.activeCaseId || 0) || null,
    contextLabel
  };
  renderTabs();
  saveTabsState();
}

