function handleOverlayClick(e) {
  if (e.target === $('submit-modal')) closeSubmitModal();
  if (e.target === $('tag-group-name-modal')) closeTagGroupNameModal();
  if (e.target === $('tag-list-editor-modal')) closeTagListEditorModal();
  if (e.target === $('delete-tag-group-modal')) closeDeleteTagGroupModal();
  if (e.target === $('facet-delete-modal')) closeFacetDeleteModal();
  if (e.target === $('bulk-tags-modal')) closeBulkTagsModal();
}

document.addEventListener('keydown', event => {
  const tab = event.target.closest?.('.tle-tab');
  if (tab && (event.key === 'ArrowRight' || event.key === 'ArrowDown' || event.key === 'ArrowLeft' || event.key === 'ArrowUp')) {
    const tabs = Array.from(tab.closest('.tle-tabs')?.querySelectorAll('.tle-tab') || []);
    const offset = event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : -1;
    const next = tabs[(tabs.indexOf(tab) + offset + tabs.length) % tabs.length];
    if (next) {
      event.preventDefault();
      setTagEditorTab(next.dataset.tleTab);
      next.focus();
    }
    return;
  }
  if (event.key !== 'Escape') return;
  const tagNameModal = $('tag-group-name-modal');
  const deleteModal = $('delete-tag-group-modal');
  const facetDeleteModal = $('facet-delete-modal');
  const editor = $('tag-list-editor-modal');
  if (tagNameModal?.style.display === 'flex') closeTagGroupNameModal();
  else if (deleteModal?.style.display === 'flex') closeDeleteTagGroupModal();
  else if (facetDeleteModal?.style.display === 'flex') closeFacetDeleteModal();
  else if (editor?.style.display === 'flex') closeTagListEditorModal();
});

function switchSubmitModalTab(tab) {
  currentTab = tab;
  ['url', 'file', 'localpath', 'blank', 'national-law', 'recording'].forEach(t => {
    const active = t === tab;
    $(`tab-${t}`).classList.toggle('active', active);
    $(`tab-${t}`).setAttribute('aria-selected', String(active));
    $(`tab-${t}`).tabIndex = active ? 0 : -1;
    $(`panel-${t}`).classList.toggle('active', active);
  });
  $('submit-modal-card')?.classList.toggle('submit-national-law', tab === 'national-law');
  if (tab === 'national-law') {
    loadNationalLawStatus();
    resumeNationalLawScan();
  }
  const focusTarget = {
    url: 'url-input', localpath: 'localpath-input', blank: 'blank-article-title', 'national-law': 'national-law-query'
  }[tab];
  if (focusTarget) window.setTimeout(() => $(focusTarget)?.focus({ preventScroll: true }), 80);
}

async function createBlankArticle() {
  const button = $('btn-create-blank');
  const title = ($('blank-article-title')?.value || '').trim() || '未命名知识';
  try {
    if (button) { button.disabled = true; button.textContent = '正在创建…'; }
    const result = await apiFetch('/api/articles/blank', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
    });
    closeSubmitModal();
    openArticleInTab(result.id, result.title);
    loadArticles().catch(() => { /* the open article remains usable if list refresh is temporarily unavailable */ });
    const tab = tabState.tabs.find(item => item.type === TAB_TYPES.ARTICLE && Number(item.data?.articleId) === Number(result.id));
    const startEditing = () => {
      if (!tab) return;
      const article = tab.data?.article;
      if (article) { state.currentArticle = article; openEditBodyModalInTab(tab.id); }
      else window.setTimeout(startEditing, 80);
    };
    startEditing();
  } catch (error) {
    alert(`创建空白知识失败：${error.message || '请稍后重试'}`);
  } finally {
    if (button) { button.disabled = false; button.textContent = '创建并开始编辑'; }
  }
}

/* ─────────────────────────────────────────────
   文件拖拽
───────────────────────────────────────────── */
function handleDragOver(e) {
  e.preventDefault();
  $('file-drop-zone').classList.add('drag-over');
}

function handleDragLeave(e) {
  $('file-drop-zone').classList.remove('drag-over');
}

function handleDrop(e) {
  e.preventDefault();
  $('file-drop-zone').classList.remove('drag-over');
  const file = e.dataTransfer.files[0];
  if (file) {
    $('file-input').files = e.dataTransfer.files;
    onFileSelected();
  }
}

function onFileSelected() {
  const file = $('file-input').files[0];
  if (file) {
    $('file-selected').style.display = 'inline-block';
    $('file-selected').textContent = `✓  ${file.name}  (${(file.size / 1024).toFixed(0)} KB)`;
  }
  onPdfImageModeToggle(true);
}

function onPdfImageModeToggle(silent = false) {
  const checkbox = $('pdf-image-mode');
  if (!checkbox) return;
  const file = $('file-input')?.files?.[0];
  if (checkbox.checked && file && !/\.pdf$/i.test(file.name) && !silent) {
    showToast('「PDF 不解析为文本」仅对 PDF 文件生效，当前文件将按普通方式解析', 'warning');
  }
}

/* ─────────────────────────────────────────────
   提交逻辑
───────────────────────────────────────────── */
function showProgress(text) {
  $('submit-progress').style.display = 'flex';
  $('progress-text').textContent = text;
  $('submit-result').style.display = 'none';
  $(`btn-submit-${currentTab}`).disabled = true;
}

function showResult(success, html) {
  $('submit-progress').style.display = 'none';
  const el = $('submit-result');
  el.style.display = 'block';
  el.className = `submit-result ${success ? 'success' : 'error'}`;
  el.innerHTML = html;
  $(`btn-submit-${currentTab}`).disabled = false;
}

async function submitUrl() {
  const url = $('url-input').value.trim();
  if (!url) { $('url-input').focus(); return; }
  if (!/^https?:\/\/.+/.test(url)) {
    showResult(false, '请输入有效的网页链接（以 http:// 或 https:// 开头）');
    return;
  }
  if (!(await isServerReachable(2500))) {
    enqueuePendingKnowledgeLink(url);
    $('url-input').value = '';
    showResult(true, `
      <strong>已加入待上传知识队列</strong><br>
      <span style="font-size:12px;color:#166534">恢复 Tailscale 连接后会自动解析并收录。</span>
    `);
    showToast('链接已保存到待上传知识队列');
    return;
  }
  showProgress('正在抓取网页内容…');
  try {
    const form = new FormData();
    form.append('url', url);
    // 网页收录可能需要等待动态页面渲染（如今日头条、公众号）并提取正文。
    // 不应沿用普通写请求的 30 秒上限，否则浏览器会先取消请求，后端尚未
    // 完成抓取时前端便显示 “Fetch is aborted”。
    const res = await apiFetch('/api/submit/url', {
      method: 'POST',
      body: form,
      timeoutMs: 120000,
    });

    // 检查是否是重复文章
    if (res.duplicate) {
      showResult(false, `<strong>⚠️ ${escapeHtml(res.message)}</strong>`);
      return;
    }

    const aiTag = res.ai_summary_pending
      ? `<span style="display:inline-block;background:#e0f2fe;color:#0369a1;border-radius:20px;padding:1px 8px;font-size:11px;margin-top:2px">✨ AI 摘要正在后台生成</span>`
      : (res.ai_summary
        ? `<span style="display:inline-block;background:#e0f2fe;color:#0369a1;border-radius:20px;padding:1px 8px;font-size:11px;margin-top:2px">✨ AI 摘要</span>`
        : '');
    showResult(true, `
      <strong>✓ 收录成功</strong><br>
      <span style="font-weight:600">${escapeHtml(res.title)}</span><br>
      <span style="font-size:12px;color:#166534">领域：${(res.domains || []).join('、') || '综合法律'}</span>
      ${aiTag}<br>
      <span style="font-size:12px;color:#166534;margin-top:4px;display:block">${escapeHtml(truncate(res.summary, 120))}</span>
    `);
    loadArticles();
    loadStats();
    loadDomains();
    loadAuthors();
  } catch (e) {
    if (!(await isServerReachable(1500))) {
      enqueuePendingKnowledgeLink(url);
      $('url-input').value = '';
      showResult(true, `
        <strong>已加入待上传知识队列</strong><br>
        <span style="font-size:12px;color:#166534">当前无法连接 Mac，恢复 Tailscale 后会自动收录。</span>
      `);
      showToast('链接已保存到待上传知识队列');
      return;
    }
    const aborted = e?.name === 'AbortError'
      || /fetch is aborted|aborted|aborterror/i.test(String(e?.message || ''));
    const message = aborted
      ? '网页解析超过 2 分钟仍未完成，请检查链接是否可访问后重试'
      : (e.message || '请稍后重试');
    showResult(false, `<strong>✗ 失败</strong><br>${escapeHtml(message)}`);
  }
}

async function toggleFeishuArticleSettings() {
  const panel = $('feishu-article-settings');
  if (!panel) return;
  const opening = panel.style.display === 'none';
  panel.style.display = opening ? 'block' : 'none';
  if (!opening) return;
  const hint = $('feishu-article-settings-result');
  if (hint) hint.textContent = '正在读取已保存的设置…';
  try {
    const settings = await apiFetch('/api/articles/feishu-settings');
    $('feishu-article-app-id').value = settings.app_id || '';
    $('feishu-article-base-url').value = settings.base_url || '';
    $('feishu-article-form-url').value = settings.form_url || '';
    $('feishu-article-app-secret').placeholder = settings.app_secret_configured
      ? `已保存：${settings.app_secret_masked}（留空则不修改）`
      : '请输入 App Secret';
    if (hint) hint.textContent = settings.configured ? '已配置；系统启动后会自动同步。' : '请填写飞书应用和多维表格信息。';
  } catch (error) {
    if (hint) hint.textContent = `无法读取设置：${error.message}`;
  }
}

async function saveFeishuArticleSettings() {
  const hint = $('feishu-article-settings-result');
  if (hint) hint.textContent = '正在连接飞书并检查表单字段…';
  try {
    const result = await apiFetch('/api/articles/feishu-settings', {
      method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({
        app_id: $('feishu-article-app-id').value.trim(),
        app_secret: $('feishu-article-app-secret').value.trim(),
        base_url: $('feishu-article-base-url').value.trim(),
        form_url: $('feishu-article-form-url').value.trim(), verify: true,
      }),
    });
    $('feishu-article-app-secret').value = '';
    if (hint) hint.textContent = result.verification?.message || '设置已保存。';
    showToast('飞书离线收录设置已保存');
  } catch (error) {
    if (hint) hint.textContent = `保存失败：${error.message}`;
  }
}

async function syncFeishuArticles() {
  const hint = $('feishu-article-settings-result');
  if (hint) hint.textContent = '正在同步飞书表单中的文章链接…';
  try {
    const result = await apiFetch('/api/articles/feishu-sync', { method: 'POST' });
    if (!result.ok) throw new Error(result.message || '同步未完成');
    if (hint) hint.textContent = `同步完成：新增 ${Number(result.imported || 0)} 篇，重复 ${Number(result.duplicate || 0)} 篇。`;
    showToast(`飞书文章同步完成：新增 ${Number(result.imported || 0)} 篇`);
    loadArticles(); loadStats(); loadDomains(); loadAuthors();
  } catch (error) {
    if (hint) hint.textContent = `同步失败：${error.message}`;
  }
}

async function openFeishuArticleForm() {
  try {
    const settings = await apiFetch('/api/articles/feishu-settings');
    const url = settings.form_url || settings.base_url;
    if (!url) { showToast('请先保存飞书表单链接', 'warning'); return; }
    window.open(url, '_blank', 'noopener');
  } catch (error) {
    showToast(error.message || '无法打开飞书表单', 'error');
  }
}

async function submitFile() {
  const file = $('file-input').files[0];
  if (!file) { alert('请先选择文件'); return; }
  const pdfImageMode = !!(($('pdf-image-mode')?.checked)) && /\.pdf$/i.test(file.name);
  showProgress(pdfImageMode
    ? `正在渲染 PDF 页面「${file.name}」…（保留原始排版，逐页生成可选中文字层，扫描件需 OCR，请耐心等待）`
    : `正在解析文档「${file.name}」…（扫描版 PDF 需逐页 OCR 识别，可能需要几分钟，请耐心等待）`);
  try {
    const form = new FormData();
    form.append('file', file);
    if (pdfImageMode) form.append('pdf_image_mode', '1');
    // 文档解析（尤其扫描件 OCR）耗时较长，超时时间放宽到 10 分钟
    const res = await apiFetch('/api/submit/file', { method: 'POST', body: form, timeoutMs: 600000 });

    // 检查是否是重复文章
    if (res.duplicate) {
      showResult(false, `<strong>⚠️ ${escapeHtml(res.message)}</strong>`);
      return;
    }

    const aiTag = res.ai_summary_pending
      ? `<span style="display:inline-block;background:#e0f2fe;color:#0369a1;border-radius:20px;padding:1px 8px;font-size:11px;margin-top:2px">✨ AI 摘要正在后台生成</span>`
      : (res.ai_summary
        ? `<span style="display:inline-block;background:#e0f2fe;color:#0369a1;border-radius:20px;padding:1px 8px;font-size:11px;margin-top:2px">✨ AI 摘要</span>`
        : '');
    const ocrTag = res.ocr_used
      ? `<span style="display:inline-block;background:#fef3c7;color:#92400e;border-radius:20px;padding:1px 8px;font-size:11px;margin-top:2px;margin-left:4px">📷 扫描件 OCR</span>`
      : '';
    const pdfPagesTag = res.pdf_pages
      ? `<span style="display:inline-block;background:#ede9fe;color:#5b21b6;border-radius:20px;padding:1px 8px;font-size:11px;margin-top:2px;margin-left:4px">🖼 页面图片版</span>`
      : '';
    showResult(true, `
      <strong>✓ 收录成功</strong><br>
      <span style="font-weight:600">${escapeHtml(res.title)}</span><br>
      <span style="font-size:12px;color:#166534">领域：${(res.domains || []).join('、') || '综合法律'}</span>
      ${aiTag}${ocrTag}${pdfPagesTag}<br>
      <span style="font-size:12px;color:#166534;margin-top:4px;display:block">${escapeHtml(truncate(res.summary, 120))}</span>
    `);
    loadArticles();
    loadStats();
    loadDomains();
    loadAuthors();
  } catch (e) {
    showResult(false, `<strong>✗ 失败</strong><br>${escapeHtml(e.message)}`);
  }
}

