/* ─────────────────────────────────────────────
   国家法律法规数据库
───────────────────────────────────────────── */
let nationalLawScanId = null;
let nationalLawScanTimer = null;

async function loadNationalLawStatus() {
  const el = $('national-law-status');
  if (!el || el.dataset.loaded === '1') return;
  el.textContent = '正在检查国家法律法规数据库连接…';
  try {
    const data = await apiFetch('/api/national-laws/status');
    el.dataset.loaded = '1';
    el.textContent = data.connected ? '已连接 · 默认检索有效及尚未生效法规' : '暂未连接';
  } catch (e) {
    el.textContent = `连接检查失败：${e.message}`;
  }
}

function nationalLawMeta(law) {
  return [law.status_label, law.category, law.issuer, law.published_at ? `公布 ${law.published_at}` : '', law.effective_at ? `施行 ${law.effective_at}` : '']
    .filter(Boolean).map(value => `<span>${escapeHtml(value)}</span>`).join('');
}

async function searchNationalLaws() {
  const query = $('national-law-query').value.trim();
  if (!query) { $('national-law-query').focus(); return; }
  const button = $('btn-national-law-search');
  const list = $('national-law-search-results');
  button.disabled = true;
  list.innerHTML = '<div class="national-law-card">正在检索国家法律法规数据库…</div>';
  try {
    const data = await apiFetch('/api/national-laws/search', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      // Official fuzzy title search tokenizes long Chinese titles too broadly; use phrase matching
      // here so the candidate list stays centered on the law name entered by the user.
      body: JSON.stringify({ query, search_scope: 'title', exact: true, statuses: [3, 4], limit: 12 }),
    });
    const rows = data.results || [];
    if (!rows.length) {
      list.innerHTML = '<div class="national-law-card">未找到有效或尚未生效的匹配法规。</div>';
      return;
    }
    list.innerHTML = rows.map(law => `
      <div class="national-law-card">
        <div class="national-law-card-head">
          <div class="national-law-card-title">${escapeHtml(law.title)}</div>
          <span class="national-law-badge">${escapeHtml(law.status_label || '未知')}</span>
        </div>
        <div class="national-law-card-meta">${nationalLawMeta(law)}</div>
        <div class="national-law-item-actions">
          <a class="btn-secondary" href="${escapeHtml(law.source_url)}" target="_blank" rel="noopener">查看官方原文</a>
          <button class="btn-primary" onclick="importNationalLaw('${escapeHtml(law.bbbs)}', this)">收录到知识库</button>
        </div>
      </div>`).join('');
  } catch (e) {
    list.innerHTML = `<div class="national-law-card"><span class="national-law-badge error">检索失败</span>${escapeHtml(e.message)}</div>`;
  } finally {
    button.disabled = false;
  }
}

async function importNationalLaw(bbbs, button) {
  button.disabled = true;
  button.textContent = '正在下载并解析…';
  try {
    let data = await apiFetch('/api/national-laws/import', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ bbbs, conflict_action: 'confirm' }),
    });
    if (data.requires_confirmation) {
      const conflict = (data.conflicts || [])[0];
      const replace = window.confirm(
        `知识库中已有同名文章《${conflict?.title || data.law?.title || ''}》。\n\n` +
        '点击“确定”覆盖原文章并保留笔记、收藏和标签；点击“取消”另存为新版本。'
      );
      data = await apiFetch('/api/national-laws/import', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bbbs, conflict_action: replace ? 'replace' : 'new_version',
          article_id: replace ? conflict.id : null,
        }),
      });
    }
    button.textContent = data.duplicate ? '已收录' : '收录成功';
    showToast(data.duplicate ? '该法规已在知识库中' : '国家法规已收录');
    loadArticles(); loadStats(); loadDomains(); loadAuthors();
  } catch (e) {
    button.disabled = false;
    button.textContent = '重新收录';
    showToast(e.message || '法规收录失败', 'error');
  }
}

async function startNationalLawUpdateScan() {
  const button = $('btn-national-law-scan');
  button.disabled = true;
  try {
    const data = await apiFetch('/api/national-laws/update-scans', { method: 'POST' });
    nationalLawScanId = data.scan_id;
    localStorage.setItem('nationalLawScanId', String(nationalLawScanId));
    $('national-law-scan').style.display = 'block';
    pollNationalLawScan();
  } catch (e) {
    showToast(e.message || '无法启动法规检测', 'error');
    button.disabled = false;
  }
}

async function resumeNationalLawScan() {
  const saved = Number(localStorage.getItem('nationalLawScanId') || 0);
  if (saved) {
    if (nationalLawScanId === saved) return;
    nationalLawScanId = saved;
    $('national-law-scan').style.display = 'block';
    pollNationalLawScan();
    return;
  }
  try {
    const data = await apiFetch('/api/national-laws/update-scans/latest');
    if (!data.scan) return;
    nationalLawScanId = data.scan.id;
    localStorage.setItem('nationalLawScanId', String(nationalLawScanId));
    $('national-law-scan').style.display = 'block';
    renderNationalLawScan(data);
    if (['queued', 'running'].includes(data.scan.status)) pollNationalLawScan();
  } catch (_) {
    // The tab remains usable even when no persisted reminder can be restored.
  }
}

async function pollNationalLawScan() {
  if (!nationalLawScanId) return;
  clearTimeout(nationalLawScanTimer);
  try {
    const data = await apiFetch(`/api/national-laws/update-scans/${nationalLawScanId}`);
    renderNationalLawScan(data);
    if (['queued', 'running'].includes(data.scan.status)) {
      nationalLawScanTimer = setTimeout(pollNationalLawScan, 1500);
    } else {
      $('btn-national-law-scan').disabled = false;
    }
  } catch (e) {
    $('national-law-scan-summary').innerHTML = `<div class="national-law-card">检测状态读取失败：${escapeHtml(e.message)}</div>`;
    $('btn-national-law-scan').disabled = false;
  }
}

function nationalLawItemLabel(status) {
  return {
    pending_match: ['待确认对应关系', ''], update_available: ['发现更新', 'update'],
    current: ['已是最新', 'current'], unmatched: ['未找到对应法规', 'error'],
    failed: ['检测失败', 'error'], applied: ['已更新', 'current'],
  }[status] || [status, ''];
}

function renderNationalLawScan(data) {
  const scan = data.scan || {};
  const total = Number(scan.total || 0), processed = Number(scan.processed || 0);
  const pct = total ? Math.min(100, Math.round(processed / total * 100)) : (scan.status === 'completed' ? 100 : 0);
  $('national-law-scan-summary').innerHTML = `
    <div class="national-law-scan-summary">
      <div class="national-law-stat"><strong>${processed}/${total}</strong>已检测</div>
      <div class="national-law-stat"><strong>${scan.pending_matches || 0}</strong>待确认</div>
      <div class="national-law-stat"><strong>${scan.updates_found || 0}</strong>可更新</div>
      <div class="national-law-stat"><strong>${scan.current_count || 0}</strong>已是最新</div>
      <div class="national-law-stat"><strong>${scan.failed_count || 0}</strong>未匹配/失败</div>
    </div>
    <div class="national-law-progress"><span style="width:${pct}%"></span></div>
    <div class="national-law-status">${scan.status === 'completed' ? '检测完成。所有未绑定法规均需逐项确认。' : `正在检测… ${pct}%`}</div>`;
  const items = data.items || [];
  $('national-law-scan-items').innerHTML = items.map(item => {
    const [label, badge] = nationalLawItemLabel(item.status);
    const candidates = item.candidates || [];
    const target = item.detail?.target || item.detail?.preferred || item.detail?.current || {};
    const candidateControl = item.status === 'pending_match' ? `
      ${candidates.length ? `<select class="national-law-candidate-select" id="national-law-candidate-${item.id}">
        <option value="">请选择官方对应法规</option>
        ${candidates.map(c => `<option value="${escapeHtml(c.bbbs)}">${escapeHtml(c.title)}｜${escapeHtml(c.status_label)}｜${escapeHtml(c.published_at || '')}</option>`).join('')}
      </select><button class="btn-primary" onclick="confirmNationalLawMatch(${item.id})">确认对应关系</button>` : '<span>未找到候选法规</span>'}
    ` : '';
    const updateControl = item.status === 'update_available' ? `
      <label><input type="checkbox" class="national-law-update-checkbox" data-item-id="${item.id}">选择更新</label>
      <select class="national-law-action" data-item-id="${item.id}">
        <option value="replace">更新原文章（保留笔记）</option><option value="new_version">另存为新版本</option>
      </select>` : '';
    const rollback = item.status === 'applied' ? `<button class="btn-secondary" onclick="rollbackNationalLawUpdate(${item.id})">撤销本次更新</button>` : '';
    return `<div class="national-law-card">
      <div class="national-law-card-head"><div class="national-law-card-title">${escapeHtml(item.local_title)}</div><span class="national-law-badge ${badge}">${escapeHtml(label)}</span></div>
      ${target.title ? `<div class="national-law-card-meta"><span>官方：${escapeHtml(target.title)}</span>${nationalLawMeta(target)}</div>` : ''}
      ${item.detail?.new_version_available ? '<div class="national-law-card-meta"><span>发现同名现行新版本</span></div>' : ''}
      ${item.detail?.content_changed ? '<div class="national-law-card-meta"><span>官方正文与本地正文不同</span></div>' : ''}
      ${item.error ? `<div class="national-law-card-meta"><span>${escapeHtml(item.error)}</span></div>` : ''}
      <div class="national-law-item-actions">${candidateControl}${updateControl}${rollback}</div>
    </div>`;
  }).join('') || '<div class="national-law-card">尚无检测结果。</div>';
  $('national-law-apply-bar').style.display = items.some(item => item.status === 'update_available') ? 'flex' : 'none';
}

async function confirmNationalLawMatch(itemId) {
  const select = $(`national-law-candidate-${itemId}`);
  if (!select?.value) { showToast('请先选择官方对应法规', 'warning'); return; }
  try {
    const data = await apiFetch(`/api/national-laws/update-scans/${nationalLawScanId}/confirm-matches`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: [{ item_id: itemId, bbbs: select.value }] }),
    });
    const result = data.results?.[0];
    if (!result?.success) throw new Error(result?.error || '确认失败');
    showToast('已确认官方对应关系');
    pollNationalLawScan();
  } catch (e) { showToast(e.message || '确认失败', 'error'); }
}

function selectAllNationalLawUpdates(checked) {
  document.querySelectorAll('.national-law-update-checkbox').forEach(el => { el.checked = checked; });
}

async function applySelectedNationalLawUpdates() {
  const items = Array.from(document.querySelectorAll('.national-law-update-checkbox:checked')).map(el => {
    const id = Number(el.dataset.itemId);
    const action = document.querySelector(`.national-law-action[data-item-id="${id}"]`)?.value || 'replace';
    return { item_id: id, action };
  });
  if (!items.length) { showToast('请先勾选需要更新的法规', 'warning'); return; }
  if (!window.confirm(`将更新选中的 ${items.length} 部法规。覆盖前会自动保存可撤销快照，是否继续？`)) return;
  const button = $('btn-national-law-apply');
  button.disabled = true; button.textContent = '正在更新…';
  try {
    const data = await apiFetch(`/api/national-laws/update-scans/${nationalLawScanId}/apply`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ items }),
    });
    const success = (data.results || []).filter(item => item.success).length;
    const failed = items.length - success;
    showToast(`法规更新完成：成功 ${success}，失败 ${failed}`, failed ? 'warning' : 'success');
    loadArticles(); loadStats(); loadDomains(); pollNationalLawScan();
  } catch (e) { showToast(e.message || '批量更新失败', 'error'); }
  finally { button.disabled = false; button.textContent = '更新选中项'; }
}

async function rollbackNationalLawUpdate(itemId) {
  if (!window.confirm('确认撤销本次法规更新并恢复更新前正文吗？')) return;
  try {
    await apiFetch(`/api/national-laws/updates/${itemId}/rollback`, { method: 'POST' });
    showToast('已恢复更新前版本');
    loadArticles(); pollNationalLawScan();
  } catch (e) { showToast(e.message || '撤销失败', 'error'); }
}


