/* ─────────────────────────────────────────────
   标题栏滚动隐藏/显示
───────────────────────────────────────────── */
let lastScrollTop = 0;
let isHeaderHidden = false;
let scrollTimeout = null;

function setupHeaderScroll() {
  const modal = $('detail-modal-content');
  const header = modal?.querySelector('.modal-header');
  if (!header) return;

  // 重置状态
  lastScrollTop = 0;
  isHeaderHidden = false;
  header.classList.remove('hidden');

  // 清理旧的事件监听器
  if (scrollTimeout) {
    clearTimeout(scrollTimeout);
    scrollTimeout = null;
  }

  let ticking = false;

  const scrollHandler = () => {
    if (!ticking) {
      window.requestAnimationFrame(() => {
        const currentScrollTop = modal.scrollTop;

        // 添加阈值,避免微小滚动导致的闪烁
        const scrollDelta = Math.abs(currentScrollTop - lastScrollTop);

        // 只有滚动距离超过5px才触发状态改变
        if (scrollDelta > 5) {
          // 向下滚动且当前未隐藏,隐藏标题栏
          if (currentScrollTop > lastScrollTop && !isHeaderHidden) {
            header.classList.add('hidden');
            isHeaderHidden = true;
          }
          // 向上滚动且当前已隐藏,显示标题栏
          else if (currentScrollTop < lastScrollTop && isHeaderHidden) {
            header.classList.remove('hidden');
            isHeaderHidden = false;
          }

          lastScrollTop = currentScrollTop;
        }

        ticking = false;
      });
      ticking = true;
    }
  };

  // 使用passive选项提高滚动性能
  modal.addEventListener('scroll', scrollHandler, { passive: true });
  modal.dataset.scrollHandler = 'true';
}

function cleanupHeaderScroll() {
  const modal = $('detail-modal-content');
  if (modal && modal.dataset.scrollHandler) {
    const header = modal.querySelector('.modal-header');
    if (header) {
      header.classList.remove('hidden');
      isHeaderHidden = false;
    }
    // 清理滚动超时
    if (scrollTimeout) {
      clearTimeout(scrollTimeout);
      scrollTimeout = null;
    }
    // 移除所有滚动事件监听器
    const newModal = modal.cloneNode(true);
    newModal.dataset.scrollHandler = '';
    modal.parentNode.replaceChild(newModal, modal);
  }
}

/**
 * 滚动正文到指定字符偏移位置，并短暂高亮关键词所在片段
 * @param {number} charOffset - 关键词在原始正文中的字符偏移（来自后端 content_snippets）
 * @param {string} keyword - 用于高亮的关键词
 */
function scrollBodyToOffset(charOffset, keyword) {
  const bodyEl = $('detail-body');
  if (!bodyEl) return;

  // 遍历所有文本节点，累计字符数直到找到目标位置
  const walker = document.createTreeWalker(bodyEl, NodeFilter.SHOW_TEXT, null, false);
  let accumulated = 0;
  let targetNode = null;
  let nodeOffset = 0;

  while (walker.nextNode()) {
    const node = walker.currentNode;
    const len = node.textContent.length;
    if (accumulated + len > charOffset) {
      targetNode = node;
      nodeOffset = charOffset - accumulated;
      break;
    }
    accumulated += len;
  }

  const quoteMatch = findCitationQuoteNode(bodyEl, keyword);
  if (quoteMatch) targetNode = quoteMatch;
  if (!targetNode) return;
  highlightCitationTarget(targetNode, bodyEl);

  // 短暂高亮（包裹一个 mark 元素，3s 后移除）
  if (keyword && !quoteMatch) {
    try {
      const range = document.createRange();
      const kwLen = Math.min(keyword.length, targetNode.textContent.length - nodeOffset);
      range.setStart(targetNode, nodeOffset);
      range.setEnd(targetNode, nodeOffset + kwLen);
      const mark = document.createElement('mark');
      mark.className = 'search-highlight scroll-anchor';
      range.surroundContents(mark);
      setTimeout(() => {
        if (mark.parentNode) {
          const parent = mark.parentNode;
          while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
          mark.remove();
        }
      }, 3000);
  } catch (_) { /* 跨节点时忽略 */ }
}

/**
 * 在文章正文中高亮并滚动到关键词
 */
function highlightAndScrollToKeyword(keyword) {
  const bodyEl = $('detail-body');
  if (!bodyEl || !keyword || keyword.length < 2) {
    console.log('highlightAndScrollToKeyword: 缺少必要参数', { bodyEl, keyword });
    return;
  }

  const searchTerm = keyword.trim();
  console.log('highlightAndScrollToKeyword: 开始搜索', { searchTerm });
  
  // 方法1：直接DOM搜索（更可靠）
  const match = findFirstTextNodeContainingKeyword(bodyEl, searchTerm);
  
  if (match) {
    console.log('DOM搜索成功:', { nodeText: match.node.textContent.substring(0, 50), offset: match.offset, keyword: searchTerm });
    scrollAndHighlightNode(match.node, match.offset, searchTerm);
    return;
  }
  
  // 方法2：备用模糊搜索
  console.log('精确匹配失败，尝试模糊匹配:', searchTerm);
  const words = searchTerm.split(/\s+/).filter(w => w.length > 1);
  console.log('分割后的词:', words);
  
  for (const word of words) {
    const fuzzyMatch = findFirstTextNodeContainingKeyword(bodyEl, word);
    if (fuzzyMatch) {
      console.log('模糊匹配成功:', word, '位置:', fuzzyMatch.offset);
      scrollAndHighlightNode(fuzzyMatch.node, fuzzyMatch.offset, word);
      return;
    }
  }
  
  console.log('未在正文中找到关键词:', searchTerm);
}

/**
 * 在DOM树中查找包含关键词的第一个文本节点
 */
function findFirstTextNodeContainingKeyword(root, keyword) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
  const normalizedKeyword = keyword.toLowerCase();
  
  while (walker.nextNode()) {
    const node = walker.currentNode;
    const text = node.textContent.toLowerCase();
    const index = text.indexOf(normalizedKeyword);
    
    if (index !== -1) {
      return { node, offset: index, keywordLength: keyword.length };
    }
  }
  
  return null;
}

/**
 * 滚动并高亮指定文本节点中的关键词
 */
function scrollAndHighlightNode(targetNode, nodeOffset, keyword) {
  if (!targetNode) return;
  
  // 将目标文本节点的父元素滚动到视图
  const el = targetNode.parentElement || $('detail-body');
  el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  
  // 短暂高亮（包裹一个 mark 元素，3s 后移除）
  try {
    const range = document.createRange();
    const kwLen = Math.min(keyword.length, targetNode.textContent.length - nodeOffset);
    range.setStart(targetNode, nodeOffset);
    range.setEnd(targetNode, nodeOffset + kwLen);
    const mark = document.createElement('mark');
    mark.className = 'search-highlight scroll-anchor';
    range.surroundContents(mark);
    setTimeout(() => {
      if (mark.parentNode) {
        const parent = mark.parentNode;
        while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
        mark.remove();
      }
    }, 3000);
  } catch (_) { 
    console.log('高亮操作失败，可能是跨节点边界');
  }
}
}

async function openDetail(id) {
  if (shouldUseTabbedArticleReader()) {
    openArticleInTab(id, '文章详情');
    return;
  }
  console.log('openDetail called with id:', id);
  currentArticleId = id;
  notesVisible = true;
  $('detail-modal').classList.add('open');
  document.getElementById('relations-panel')?.classList.add('hidden');
  // 隐藏列表翻页按钮，避免其透过文章阅读弹窗显示
  const fpEl = document.getElementById('floating-pagination');
  if (fpEl) fpEl.dataset.hiddenByDetail = fpEl.style.display || 'none';
  if (fpEl && fpEl.style.display !== 'none') fpEl.style.display = 'none';
  $('detail-title').textContent = '加载中…';
  $('detail-meta').innerHTML = '';
  const detailSummaryEl = $('detail-summary');
  detailSummaryEl.textContent = '';
  detailSummaryEl.classList.remove('has-content');
  detailSummaryEl.style.display = '';
  $('detail-body').textContent = '';
  $('notes-list').innerHTML = '';
  $('note-input').value = '';
  // btn-edit-summary 已移到摘要浮动窗口内部，不需要单独处理

  try {
    console.log('Fetching article details...');
    const a = await apiFetch(`/api/articles/${id}`);
    state.currentArticle = a;
    const title = a.title;
    $('detail-title').textContent = title;

    // 为全屏模式设置标题
    $('detail-modal-content').setAttribute('data-title', title);

    const domains = (a.domains || []).map(d =>
      `<span class="meta-tag domain">${escapeHtml(d)}</span>`
    ).join('');

    const sourceTag = `<span class="meta-tag source">${
      a.source_type === 'url' ? '网页' : '本地文件'
    }</span>`;
    const dateTag = `<span class="meta-tag date">${formatDate(a.created_at)}</span>`;

    // 提取作者标签
    const tags = a.tags || [];
    const authorTag = tags
      .filter(t => t.startsWith('作者:'))
      .map(t => {
        const author = t.replace('作者:', '');
        return `<span class="meta-tag author" onclick="openEditAuthorModal('${escapeHtml(author)}')">${ARTICLE_META_PERSON_ICON}<span>${escapeHtml(author)}</span></span>`;
      })
      .join('');

    // 提取非作者标签
    const customTags = tags
      .filter(t => !t.startsWith('作者:'))
      .map(t => `<span class="meta-tag tag">${ARTICLE_META_TAG_ICON}<span>${escapeHtml(t)}</span></span>`)
      .join('');

    // 编辑标签按钮
    const editTagsBtn = `<button class="btn-secondary article-meta-edit-btn" onclick="openEditTagsModal()">${ARTICLE_META_EDIT_ICON}<span>编辑标签</span></button>`;

    const sourceLink = a.source_url
      ? `<a class="meta-link" href="${escapeHtml(a.source_url)}" target="_blank" rel="noopener">${escapeHtml(truncate(a.source_url, 60))}</a>`
      : a.source_localpath
        ? `<span class="meta-localpath" title="点击在原路径打开文件" onclick="openLocalPath('${escapeHtml(a.source_localpath)}')">
             <svg width="13" height="13" viewBox="0 0 13 13" style="margin-right:4px;vertical-align:-2px"><path d="M1.5 3H5l1 1.5h5.5a.5.5 0 01.5.5v5a.5.5 0 01-.5.5h-10a.5.5 0 01-.5-.5V3.5a.5.5 0 01.5-.5z" stroke="currentColor" stroke-width="1.2" fill="none"/></svg>${escapeHtml(a.source_localpath)}</span>`
        : (a.source_filename
          ? `<span class="meta-tag date" style="cursor:pointer" onclick="openLocalFile('${escapeHtml(a.source_filename)}')">${ARTICLE_META_FILE_ICON}<span>${escapeHtml(a.source_filename)}</span></span>`
          : '');

    $('detail-meta').innerHTML = `${domains}${sourceTag}${authorTag}${customTags}${editTagsBtn}${dateTag}${sourceLink}`;
    // 正文与智能目录一起渲染：系统生成的目录不再插入正文，改由左侧侧栏展示
    const renderedBody = renderBodyContentWithToc(a.content);
    renderModalDetailSidebar(a.summary || '', renderedBody.toc);

    $('detail-body').innerHTML = renderedBody.html;
    enhancePdfPageGalleries($('detail-body'));

    // 重新设置文本选中功能（因为innerHTML会重置DOM）
    setupTextSelection();

    $('btn-edit-title').style.display = 'inline-flex';

    $('detail-delete-btn').onclick = () => deleteArticle(id);

    // 显示笔记面板
    $('notes-panel').classList.remove('hidden');

    // 加载笔记
    await loadNotes(id);
    await registerArticleRelationOpen(id);
    await loadArticleRelations(id);

    // 处理正文字符偏移定位（从列表搜索结果点击进入）
    if (state.pendingScrollOffset !== null) {
      const offset = state.pendingScrollOffset;
      const citationQuote = state.pendingCitationQuote;
      state.pendingScrollOffset = null;
      state.pendingCitationQuote = null;
      setTimeout(() => scrollBodyToOffset(offset, citationQuote), 150);
    }

    // 处理 AI 引用来源关键词高亮定位（点击引用来源卡片进入）
    if (state.pendingHighlight) {
      const kw = state.pendingHighlight;
      console.log('openDetail: 处理pendingHighlight', { kw });
      state.pendingHighlight = null;
      setTimeout(() => {
        // 清理关键词：去除标点符号和过长的内容
        const cleanedKw = kw.replace(/[…（）【】《》「」\"'.,;:?!()]/g, '').trim();
        console.log('清理后的关键词:', cleanedKw);
        // 提取前20-40个字符的关键部分
        let searchKw = cleanedKw;
        if (searchKw.length > 40) {
          // 尝试提取中间部分，避免开头可能包含多余描述
          const midStart = Math.max(0, Math.floor(searchKw.length / 2) - 20);
          searchKw = searchKw.substring(midStart, midStart + 40);
        } else if (searchKw.length > 20) {
          searchKw = searchKw.substring(0, 20);
        }
        console.log('最终搜索词:', searchKw);
        
        if (searchKw) {
          // 直接高亮定位，不填入搜索框
          highlightAndScrollToKeyword(searchKw);
        } else {
          console.log('搜索词为空');
        }
      }, 200);
    }

    // 设置标题栏滚动隐藏/显示
    setupHeaderScroll();
  } catch (e) {
    console.error('openDetail error:', e);
    $('detail-title').textContent = '加载失败';
    $('detail-body').innerHTML = `<p style="color:var(--danger)">${escapeHtml(e.message)}</p>`;
  }
}

/* ─────────────────────────────────────────────
   文章内搜索（正文 + 摘要 + 笔记）
───────────────────────────────────────────── */
const detailSearch = {
  matches: [],   // 所有命中的 mark 元素
  current: -1,   // 当前高亮索引
  timer: null,
  dropdownIndex: -1,  // 下拉列表高亮索引
  activeDropdownItem: -1,  // 当前激活的下拉项（鼠标悬停）
};

function onDetailSearchInput() {
  clearTimeout(detailSearch.timer);
  detailSearch.timer = setTimeout(() => {
    const kw = $('detail-search-input').value.trim();
    $('detail-search-clear').style.display = kw ? 'flex' : 'none';
    applyDetailSearch(kw);
  }, 200);
}

function onDetailSearchKeydown(e) {
  const dropdown = $('detail-search-dropdown');
  const count = detailSearch.matches.length;
  if (e.key === 'Enter') {
    e.preventDefault();
    if (dropdown && dropdown.style.display !== 'none' && count > 0) {
      // 下拉列表打开时，Enter 跳转到当前悬停项或第0项
      const targetIdx = detailSearch.activeDropdownItem >= 0 ? detailSearch.activeDropdownItem : 0;
      jumpToDetailDropdownItem(targetIdx);
    } else {
      detailSearchNav(e.shiftKey ? -1 : 1);
    }
  } else if (e.key === 'ArrowDown') {
    e.preventDefault();
    if (dropdown && count > 0) {
      dropdown.style.display = 'block';
      detailSearch.activeDropdownItem = Math.min(detailSearch.activeDropdownItem + 1, Math.min(count, 50) - 1);
      updateDetailDropdownHighlight();
    }
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    if (dropdown && dropdown.style.display !== 'none') {
      detailSearch.activeDropdownItem = Math.max(detailSearch.activeDropdownItem - 1, 0);
      updateDetailDropdownHighlight();
    }
  } else if (e.key === 'Escape') {
    clearDetailSearch();
  }
}

function clearDetailSearch() {
  $('detail-search-input').value = '';
  $('detail-search-clear').style.display = 'none';
  const dropdown = $('detail-search-dropdown');
  if (dropdown) dropdown.style.display = 'none';
  applyDetailSearch('');
}

function applyDetailSearch(keyword) {
  // 先清除之前的高亮
  _clearDetailHighlights();
  const dropdown = $('detail-search-dropdown');
  if (dropdown) dropdown.style.display = 'none';
  detailSearch.dropdownIndex = -1;
  detailSearch.activeDropdownItem = -1;

  if (!keyword) {
    $('detail-search-count').style.display = 'none';
    $('detail-search-nav').style.display = 'none';
    return;
  }

  // 搜索范围：正文 + 摘要 + 笔记面板
  const searchRoots = [
    { el: $('detail-body'), name: '正文' },
    { el: $('detail-summary'), name: '摘要' },
    { el: $('notes-list'), name: '笔记' },
  ].filter(r => r.el);

  detailSearch.matches = [];

  for (const { el, name } of searchRoots) {
    _highlightInNode(el, keyword, name);
  }

  const count = detailSearch.matches.length;
  const countEl = $('detail-search-count');
  const navEl = $('detail-search-nav');

  if (count === 0) {
    countEl.textContent = '无结果';
    countEl.style.display = 'inline';
    navEl.style.display = 'none';
    // 显示空下拉
    if (dropdown) {
      dropdown.innerHTML = '<div class="detail-search-dropdown-empty">未找到匹配内容</div>';
      dropdown.style.display = 'block';
    }
  } else {
    detailSearch.current = 0;
    _activateMatch(0);
    countEl.style.display = 'inline';
    navEl.style.display = 'flex';
    // 渲染下拉列表（最多50条）
    renderDetailSearchDropdown(keyword, Math.min(count, 50));
    if (dropdown) dropdown.style.display = 'block';
  }
}

/* 渲染搜索结果下拉列表 */
function renderDetailSearchDropdown(keyword, maxCount) {
  const dropdown = $('detail-search-dropdown');
  if (!dropdown) return;

  const total = detailSearch.matches.length;
  const items = [];

  for (let i = 0; i < maxCount; i++) {
    const mk = detailSearch.matches[i];
    const ctx = mk._searchCtx || { before: '…', after: '…', section: '正文' };
    const beforeEsc = escapeHtml(ctx.before || '');
    const afterEsc = escapeHtml(ctx.after || '');
    const termEsc = escapeHtml(keyword);
    items.push(
      `<div class="detail-search-dropdown-item" data-idx="${i}" onclick="onDetailDropdownClick(${i})" onmouseenter="onDetailDropdownHover(${i})">` +
        `<span class="result-index">${i + 1}.</span>` +
        `<span class="result-context">${beforeEsc}<mark>${termEsc}</mark>${afterEsc}</span>` +
        `<span class="result-section">${escapeHtml(ctx.section)}</span>` +
      `</div>`
    );
  }

  let html = items.join('');
  if (total > maxCount) {
    html += `<div class="detail-search-dropdown-footer">共 ${total} 条结果，已显示前 ${maxCount} 条</div>`;
  }

  dropdown.innerHTML = html;
  dropdown.scrollTop = 0;
}

function onDetailDropdownClick(idx) {
  jumpToDetailDropdownItem(idx);
}

function onDetailDropdownHover(idx) {
  detailSearch.activeDropdownItem = idx;
  updateDetailDropdownHighlight();
}

function updateDetailDropdownHighlight() {
  const dropdown = $('detail-search-dropdown');
  if (!dropdown) return;
  dropdown.querySelectorAll('.detail-search-dropdown-item').forEach((item, i) => {
    item.classList.toggle('active', i === detailSearch.activeDropdownItem);
    if (i === detailSearch.activeDropdownItem) {
      item.scrollIntoView({ block: 'nearest' });
    }
  });
}

function jumpToDetailDropdownItem(idx) {
  const dropdown = $('detail-search-dropdown');
  if (dropdown) dropdown.style.display = 'none';

  // 激活对应 mark
  detailSearch.current = idx;
  _activateMatch(idx);
  // 同时设置悬停索引一致
  detailSearch.activeDropdownItem = idx;
  updateDetailDropdownHighlight();
}

function detailSearchNav(dir) {
  const n = detailSearch.matches.length;
  if (n === 0) return;
  detailSearch.current = (detailSearch.current + dir + n) % n;
  _activateMatch(detailSearch.current);
}

function _activateMatch(idx) {
  detailSearch.matches.forEach((m, i) => {
    m.classList.toggle('detail-search-active', i === idx);
  });
  const active = detailSearch.matches[idx];
  if (active) {
    active.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
  const countEl = $('detail-search-count');
  if (countEl) countEl.textContent = `${idx + 1}/${detailSearch.matches.length}`;
}

function _clearDetailHighlights() {
  // 还原所有 detail-search-mark 节点为文本
  // 限定范围：只清除弹窗模式的 detail-modal 内，避免误清标签页内的高亮
  const scope = $('detail-modal') || document;
  unwrapDetailSearchMarks(scope);
  detailSearch.matches = [];
  detailSearch.current = -1;
  // 隐藏下拉列表
  const dropdown = $('detail-search-dropdown');
  if (dropdown) dropdown.style.display = 'none';
}

function _highlightInNode(root, keyword, sectionName) {
  if (!root) return;
  try {
  detailSearch.matches.push(...highlightVisibleText(root, keyword, sectionName || '正文'));
  } catch(e) { console.error('[Search]', e); }
}

function closeDetailModal() {
  const modalContent = $('detail-modal-content');
  const summaryEl = $('detail-summary');
  $('detail-modal').classList.remove('open');
  if (modalContent) modalContent.classList.remove('fullscreen');
  if (summaryEl) {
    summaryEl.style.display = 'flex';
    // 复位摘要/智能目录展开状态
    const panes = summaryEl.querySelector('.sidebar-panes');
    if (panes) delete panes.dataset.expand;
  }
  currentArticleId = null;

  // 恢复列表翻页按钮的显示状态
  const fpEl = document.getElementById('floating-pagination');
  if (fpEl && fpEl.dataset.hiddenByDetail) {
    fpEl.style.display = fpEl.dataset.hiddenByDetail === 'none' ? 'none' : fpEl.dataset.hiddenByDetail;
    delete fpEl.dataset.hiddenByDetail;
  }

  // 清理文章内搜索状态
  _clearDetailHighlights();
  if ($('detail-search-input')) $('detail-search-input').value = '';
  if ($('detail-search-count')) { $('detail-search-count').style.display = 'none'; }
  if ($('detail-search-nav')) { $('detail-search-nav').style.display = 'none'; }
  if ($('detail-search-clear')) { $('detail-search-clear').style.display = 'none'; }
  if ($('detail-search-dropdown')) { $('detail-search-dropdown').style.display = 'none'; }

  // 移除标题栏滚动事件
  cleanupHeaderScroll();
}

function toggleFullscreen() {
  const modalContent = $('detail-modal-content');
  const summaryEl = $('detail-summary');
  if (modalContent) {
    const isFullscreen = modalContent.classList.contains('fullscreen');

    if (isFullscreen) {
      // 退出全屏：显示摘要
      modalContent.classList.remove('fullscreen');
      if (summaryEl && summaryEl.classList.contains('has-content')) {
        summaryEl.style.display = 'flex';
      }
    } else {
      // 进入全屏：隐藏摘要
      modalContent.classList.add('fullscreen');
      if (summaryEl) summaryEl.style.display = 'none';
    }
  }
}

function handleDetailOverlayClick(e) {
  if (e.target === $('detail-modal')) closeDetailModal();
}

async function deleteArticle(id) {
  if (!await confirmArticleTrashAction('移入回收站？', '文章及其笔记将保留30天，期间可从侧边栏回收站恢复。', '移入回收站')) return;
  try {
    await apiFetch(`/api/articles/${id}`, { method: 'DELETE' });
    closeDetailModal();
    loadArticles();
    loadStats();
    loadDomains();
    loadAuthors();
    showToast('文章已移入回收站，可在30天内恢复');
  } catch (e) {
    showToast('移入回收站失败：' + e.message, 'error');
  }
}

