function applyTheme() {
  const body = document.body;
  const root = document.documentElement;
  if (state.darkMode) {
    body.classList.add('dark-mode');
    root.classList.add('dark-mode');
  } else {
    body.classList.remove('dark-mode');
    root.classList.remove('dark-mode');
  }
  const themeMeta = document.querySelector('meta[name="theme-color"]');
  if (themeMeta) {
    themeMeta.setAttribute('content', state.darkMode ? '#0f172a' : '#f7f8fc');
  }
}

function saveTheme(persist = true) {
  if (persist) localStorage.setItem('theme', state.darkMode ? 'dark' : 'light');
  // 主动设置所有 iframe 的 body 样式（直接修改 iframe 内的 DOM）
  document.querySelectorAll('iframe').forEach(iframe => {
    try {
      const iframeBody = iframe.contentDocument.body;
      if (iframeBody) {
        if (state.darkMode) {
          iframeBody.classList.add('dark-mode');
        } else {
          iframeBody.classList.remove('dark-mode');
        }
      }
      // 同时发送 postMessage（用于已在监听的 iframe）
      iframe.contentWindow.postMessage({ type: 'theme', dark: state.darkMode }, '*');
    } catch(e) {}
  });
  // 广播给其他标签页
  try {
    const channel = new BroadcastChannel('legal-kb-theme');
    channel.postMessage(state.darkMode ? 'dark' : 'light');
    channel.close();
  } catch(e) {}
}

function loadTheme() {
  state.darkMode = getPreferredDarkMode();
  applyTheme();
  // 清除 head 内联脚本打的早期标记
  document.documentElement.classList.remove('dark-mode-early');
}

let legalKbThemeSyncChannel = null;
function applyExternalTheme(value) {
  const dark = value === 'dark';
  if (state.darkMode === dark && document.body.classList.contains('dark-mode') === dark) return;
  state.darkMode = dark;
  applyTheme();
  document.querySelectorAll('iframe').forEach(iframe => {
    try {
      iframe.contentDocument?.documentElement?.classList.toggle('dark-mode', dark);
      iframe.contentDocument?.body?.classList.toggle('dark-mode', dark);
      iframe.contentWindow.postMessage({ type: 'theme', dark }, '*');
    } catch (e) {}
  });
}

function initThemeSync() {
  window.addEventListener('storage', event => {
    if (event.key === 'theme' && event.newValue) applyExternalTheme(event.newValue);
  });
  try {
    legalKbThemeSyncChannel = new BroadcastChannel('legal-kb-theme');
    legalKbThemeSyncChannel.onmessage = event => applyExternalTheme(event.data);
  } catch (e) {}

  try {
    const systemThemeMedia = window.matchMedia?.(APEX_SYSTEM_THEME_QUERY);
    const syncSystemTheme = event => {
      try { if (['dark', 'light'].includes(localStorage.getItem('theme'))) return; } catch (e) {}
      const dark = !!event.matches;
      if (state.darkMode === dark && document.body.classList.contains('dark-mode') === dark) return;
      state.darkMode = dark;
      applyTheme();
      saveTheme(false);
    };
    if (systemThemeMedia?.addEventListener) {
      systemThemeMedia.addEventListener('change', syncSystemTheme);
    } else if (systemThemeMedia?.addListener) {
      systemThemeMedia.addListener(syncSystemTheme);
    }
  } catch (e) {}
}

/* ─────────────────────────────────────────────
   标签管理
───────────────────────────────────────────── */
let currentEditingTags = [];
let currentEditingDomains = [];
let _originalEditingTags = [];  // 打开弹窗时的原始标签快照，用于计算新增标签

// 系统预定义的18个专业领域
const PREDEFINED_DOMAINS = [
  '建设工程', '强制执行', '执行异议与复议', '公司法', '商事仲裁',
  '合同法', '房地产', '知识产权', '劳动法', '刑事法律',
  '行政法', '金融证券', '破产法', '侵权责任', '婚姻家事',
  '税务', '刑民交叉', '担保合同'
];

function openEditTagsModal() {
  // 优先使用 state.currentArticle，如果为空则尝试从 state.articles 查找
  const articleId = state.currentArticle ? state.currentArticle.id : currentArticleId;
  let article = state.currentArticle;
  if (!article && articleId) {
    article = state.articles.find(a => a.id === articleId);
  }
  if (!article || !articleId) {
    console.warn('openEditTagsModal: 无法获取文章信息，currentArticleId=', currentArticleId, 'state.currentArticle=', state.currentArticle);
    showToast('无法获取文章信息，请重试', 'error');
    return;
  }

  currentEditingTags = [...(article.tags || [])];
  currentEditingDomains = [...(article.domains || [])];
  _originalEditingTags = [...(article.tags || [])];  // 保存快照
  renderCurrentDomains();
  renderCommonDomains();
  renderCurrentTags();
  renderCommonTags();

  $('edit-tags-modal').classList.add('open');
}

function closeEditTagsModal() {
  $('edit-tags-modal').classList.remove('open');
  currentEditingTags = [];
  currentEditingDomains = [];
  _originalEditingTags = [];
}

function renderCurrentDomains() {
  const container = $('current-domains-list');
  if (currentEditingDomains.length === 0) {
    container.innerHTML = '<div class="tags-empty">暂无专业领域</div>';
    return;
  }
  container.innerHTML = currentEditingDomains.map(d => {
    return `
      <span class="tag-item domain">
        <span class="domain-dot"></span> ${escapeHtml(d)}
        <button class="tag-remove" onclick="removeDomain('${escapeHtml(d)}')">×</button>
      </span>
    `;
  }).join('');
}

function renderCommonDomains(filterVal) {
  // 合并预定义领域 + 文章中出现过的领域（去重）
  const fromArticles = new Set();
  state.articles.forEach(a => {
    (a.domains || []).forEach(d => fromArticles.add(d));
  });
  const allCandidates = [...new Set([...PREDEFINED_DOMAINS, ...fromArticles])];

  // 过滤掉已选中的
  const q = (filterVal || '').trim().toLowerCase();
  let candidates = allCandidates.filter(d => !currentEditingDomains.includes(d));

  // 若有输入关键词则过滤
  if (q) {
    candidates = candidates.filter(d => d.toLowerCase().includes(q));
  }

  const container = $('common-domains');
  if (candidates.length === 0) {
    container.innerHTML = q
      ? `<div class="tags-empty">无匹配领域，回车可直接添加"${escapeHtml(q)}"</div>`
      : '<div class="tags-empty">暂无候选领域</div>';
    return;
  }
  container.innerHTML = candidates
    .map(d => `
      <span class="tag-item common" onclick="addCommonDomain('${escapeHtml(d)}')">
        <span class="domain-dot"></span> ${escapeHtml(d)}
      </span>
    `)
    .join('');
}

function filterDomainSuggestions(val) {
  renderCommonDomains(val);
}

function renderCurrentTags() {
  const container = $('current-tags-list');
  const authorTags = currentEditingTags.filter(t => t.startsWith('作者:'));
  const customTags = currentEditingTags.filter(t => !t.startsWith('作者:'));

  let html = '';
  if (authorTags.length > 0) {
    html += '<div class="tag-category"><strong>作者标签（自动）</strong></div>';
    html += authorTags.map(t => {
      const name = t.replace('作者:', '');
      return `<span class="tag-item author">👤 ${escapeHtml(name)}</span>`;
    }).join('');
  }

  if (customTags.length > 0) {
    html += '<div class="tag-category"><strong>自定义标签</strong></div>';
    html += customTags.map(t => {
      return `
        <span class="tag-item custom">
          ${SIDEBAR_ICONS.tag} ${escapeHtml(t)}
          <button class="tag-remove" onclick="removeTag('${escapeHtml(t)}')">×</button>
        </span>
      `;
    }).join('');
  } else {
    html += '<div class="tags-empty">暂无自定义标签</div>';
  }

  container.innerHTML = html;
}

function renderCommonTags() {
  const allTags = new Set();
  state.articles.forEach(a => {
    (a.tags || []).forEach(t => {
      if (!t.startsWith('作者:')) {
        allTags.add(t);
      }
    });
  });

  const container = $('common-tags');
  if (allTags.size === 0) {
    container.innerHTML = '<div class="tags-empty">暂无常用标签</div>';
  } else {
    container.innerHTML = Array.from(allTags)
      .map(t => `
        <span class="tag-item common" onclick="addCommonTag('${escapeHtml(t)}')">
          ${SIDEBAR_ICONS.tag} ${escapeHtml(t)}
        </span>
      `)
      .join('');
  }
}

function addDomain() {
  const input = $('new-domain-input');
  const domainName = input.value.trim();

  if (!domainName) return;
  if (currentEditingDomains.includes(domainName)) {
    showToast('该领域已存在', 'warning');
    return;
  }

  currentEditingDomains.push(domainName);
  input.value = '';
  renderCurrentDomains();
  renderCommonDomains();
}

function addCommonDomain(domainName) {
  if (currentEditingDomains.includes(domainName)) {
    showToast('该领域已存在', 'warning');
    return;
  }

  currentEditingDomains.push(domainName);
  // 清空输入框，刷新候选列表（排除刚加入的）
  const input = $('new-domain-input');
  if (input) input.value = '';
  renderCurrentDomains();
  renderCommonDomains();
}

function removeDomain(domainName) {
  currentEditingDomains = currentEditingDomains.filter(d => d !== domainName);
  renderCurrentDomains();
  // 刷新候选，让刚移除的领域重新出现
  const input = $('new-domain-input');
  renderCommonDomains(input ? input.value : '');
}

let _tagSuggestTimer = null;
let _tagSuggestIndex = -1;  // 当前键盘选中项

function onTagInputChange(val) {
  clearTimeout(_tagSuggestTimer);
  const q = val.trim();
  if (!q) {
    hideTagSuggestions();
    return;
  }
  _tagSuggestTimer = setTimeout(() => fetchTagSuggestions(q), 120);
}

async function fetchTagSuggestions(q) {
  try {
    const res = await fetch(`${API_BASE}/api/tag-groups/suggestions?q=${encodeURIComponent(q)}`);
    const data = await res.json();
    renderTagSuggestions(data.suggestions || []);
  } catch (e) {
    hideTagSuggestions();
  }
}

function renderTagSuggestions(suggestions) {
  const dropdown = $('tag-suggestions-dropdown');
  if (!dropdown) return;
  // 过滤掉已在 currentEditingTags 中的
  const filtered = suggestions.filter(s => !currentEditingTags.includes(s));
  if (filtered.length === 0) {
    hideTagSuggestions();
    return;
  }
  _tagSuggestIndex = -1;
  dropdown.innerHTML = filtered.map((s, i) =>
    `<div class="tag-suggest-item" data-idx="${i}" data-name="${escapeHtml(s)}"
          onmousedown="selectTagSuggestion('${escapeHtml(s)}')"
          onmouseover="_tagSuggestIndex=${i};updateTagSuggestHighlight()">
       ${SIDEBAR_ICONS.tag} ${escapeHtml(s)}
     </div>`
  ).join('');
  dropdown.style.display = 'block';
}

function hideTagSuggestions() {
  const dropdown = $('tag-suggestions-dropdown');
  if (dropdown) dropdown.style.display = 'none';
  _tagSuggestIndex = -1;
}

function selectTagSuggestion(name) {
  const input = $('new-tag-input');
  if (input) input.value = name;
  hideTagSuggestions();
  addTag();
}

function updateTagSuggestHighlight() {
  const items = document.querySelectorAll('#tag-suggestions-dropdown .tag-suggest-item');
  items.forEach((el, i) => {
    el.classList.toggle('highlighted', i === _tagSuggestIndex);
  });
}

function onTagInputKeydown(e) {
  const dropdown = $('tag-suggestions-dropdown');
  if (!dropdown || dropdown.style.display === 'none') {
    if (e.key === 'Enter') { e.preventDefault(); addTag(); }
    return;
  }
  const items = dropdown.querySelectorAll('.tag-suggest-item');
  if (e.key === 'ArrowDown') {
    e.preventDefault();
    _tagSuggestIndex = Math.min(_tagSuggestIndex + 1, items.length - 1);
    updateTagSuggestHighlight();
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    _tagSuggestIndex = Math.max(_tagSuggestIndex - 1, -1);
    updateTagSuggestHighlight();
  } else if (e.key === 'Enter') {
    e.preventDefault();
    if (_tagSuggestIndex >= 0 && items[_tagSuggestIndex]) {
      selectTagSuggestion(items[_tagSuggestIndex].dataset.name);
    } else {
      hideTagSuggestions();
      addTag();
    }
  } else if (e.key === 'Escape') {
    hideTagSuggestions();
  }
}

function addTag() {
  const input = $('new-tag-input');
  const tagName = input.value.trim();

  if (!tagName) return;
  if (tagName.startsWith('作者:')) {
    alert('作者标签会自动从文章中提取，请勿手动添加');
    return;
  }
  if (currentEditingTags.includes(tagName)) {
    alert('该标签已存在');
    return;
  }

  currentEditingTags.push(tagName);
  input.value = '';
  hideTagSuggestions();
  renderCurrentTags();
}

function addCommonTag(tagName) {
  if (currentEditingTags.includes(tagName)) {
    alert('该标签已存在');
    return;
  }

  currentEditingTags.push(tagName);
  renderCurrentTags();
}

function removeTag(tagName) {
  currentEditingTags = currentEditingTags.filter(t => t !== tagName);
  renderCurrentTags();
}

async function saveTags() {
  const articleId = state.currentArticle?.id || currentArticleId;
  if (!articleId) return;

  try {
    // 计算本次新增的自定义标签（不在原始快照里、也不是作者标签）
    const newlyAdded = currentEditingTags.filter(
      t => !t.startsWith('作者:') && !_originalEditingTags.includes(t)
    );

    const formData = new FormData();
    formData.append('tags', JSON.stringify(currentEditingTags));
    formData.append('domains', JSON.stringify(currentEditingDomains));
    if (newlyAdded.length > 0) {
      formData.append('new_tags', JSON.stringify(newlyAdded));
    }

    const response = await fetch(`${API_BASE}/api/articles/${articleId}/tags`, {
      method: 'PUT',
      body: formData
    });

    const result = await response.json();

    if (result.success) {
      // 更新本地状态
      if (state.currentArticle && state.currentArticle.id === articleId) {
        state.currentArticle.tags = currentEditingTags;
        state.currentArticle.domains = currentEditingDomains;
      }
      const article = state.articles.find(a => a.id === articleId);
      if (article) {
        article.tags = currentEditingTags;
        article.domains = currentEditingDomains;
      }
      // 原地刷新当前文章标签页，避免打开旧版无导航阅读弹窗
      await refreshCurrentArticleView(articleId);

      // 重新加载自定义标签列表和领域列表
      await loadCustomTags();
      await loadDomains();
      closeEditTagsModal();
      showToast('标签已保存');
    } else {
      showToast(result.message || '保存失败', 'error');
    }
  } catch (error) {
    console.error('Save tags error:', error);
    showToast('保存失败，请重试', 'error');
  }
}

/* ─────────────────────────────────────────────
   文章拖拽排序
───────────────────────────────────────────── */

// 文章拖拽相关的全局变量
let articleDraggedItem = null;
let articleIsDragging = false;

// 文章拖拽开始
function handleArticleDragStart(event, articleId) {
  event.stopPropagation();
  
  articleDraggedItem = event.target.closest('.article-card');
  if (!articleDraggedItem) return;
  
  articleIsDragging = true;
  
  // 设置拖拽样式
  articleDraggedItem.classList.add('dragging');
  
  // 设置拖拽数据
  event.dataTransfer.effectAllowed = 'move';
  event.dataTransfer.setData('text/plain', articleId);
  window._articleDragId = articleId; // 供标签组拖入使用
  
  // 注意：dragover/dragleave/drop 事件已在 renderArticles 中为每个卡片绑定，
  // 此处不再重复添加，避免事件监听器堆积导致 handleArticleDrop 被多次触发。
}

// 文章拖拽结束
function handleArticleDragEnd(event) {
  event.stopPropagation();
  
  if (!articleDraggedItem) return;
  
  // 移除拖拽样式
  articleDraggedItem.classList.remove('dragging');
  
  // 移除所有卡片的 drop-target 样式
  const grid = document.getElementById('article-grid');
  if (grid) {
    grid.querySelectorAll('.article-card').forEach(card => {
      card.classList.remove('drop-target');
    });
  }
  
  articleDraggedItem = null;
  articleIsDragging = false;
  window._articleDragId = null; // 清除供标签组使用的全局拖拽 ID
}

// 文章拖拽经过
function handleArticleDragOver(event) {
  event.preventDefault();
  event.stopPropagation();
  
  if (!articleDraggedItem || articleDraggedItem === event.currentTarget) return;
  
  // 移除所有卡片的drop-target样式
  const grid = document.getElementById('article-grid');
  if (grid) {
    const allCards = grid.querySelectorAll('.article-card');
    allCards.forEach(card => card.classList.remove('drop-target'));
  }
  
  // 添加drop-target样式到当前卡片
  event.currentTarget.classList.add('drop-target');
  
  // 设置拖拽效果
  event.dataTransfer.dropEffect = 'move';
}

// 文章拖拽离开
function handleArticleDragLeave(event) {
  event.preventDefault();
  event.stopPropagation();
  
  // 移除drop-target样式
  event.currentTarget.classList.remove('drop-target');
}

// 文章放置
function handleArticleDrop(event) {
  event.preventDefault();
  event.stopPropagation();
  
  if (!articleDraggedItem || articleDraggedItem === event.currentTarget) {
    return;
  }
  
  const dropTarget = event.currentTarget;
  const grid = document.getElementById('article-grid');
  
  if (!grid || !dropTarget) return;
  
  // 移除所有卡片的drop-target样式
  const allCards = grid.querySelectorAll('.article-card');
  allCards.forEach(card => card.classList.remove('drop-target'));
  
  // 获取所有文章卡片
  const articles = Array.from(grid.querySelectorAll('.article-card'));
  const draggedIndex = articles.indexOf(articleDraggedItem);
  const dropIndex = articles.indexOf(dropTarget);
  
  if (draggedIndex === -1 || dropIndex === -1) return;
  
  // 移动元素
  const beforeRects = captureApexReorderRects(grid, ':scope > .article-card');
  if (draggedIndex < dropIndex) {
    grid.insertBefore(articleDraggedItem, dropTarget.nextSibling);
  } else {
    grid.insertBefore(articleDraggedItem, dropTarget);
  }
  animateApexReorder(grid, beforeRects, { skip: articleDraggedItem });
  
  // 获取新顺序并去重
  const newOrder = Array.from(grid.querySelectorAll('.article-card')).map(card => {
    return card.getAttribute('data-article-id');
  }).filter(id => id !== null);
  
  // 调试信息
  console.log('handleArticleDrop: 获取到的顺序', {
    newOrder: newOrder,
    hasDuplicates: newOrder.length !== new Set(newOrder).size,
    duplicateIds: newOrder.filter((id, index) => newOrder.indexOf(id) !== index)
  });
  
  // 去重：确保没有重复的ID
  const uniqueOrder = [...new Set(newOrder)];
  
  console.log('handleArticleDrop: 去重后的顺序', {
    uniqueOrder: uniqueOrder,
    length: uniqueOrder.length
  });
  
  // 保存自定义排序到localStorage
  saveArticleOrder(uniqueOrder);
  
  // 拖拽完成后确保处于自定义排序模式
  if (state.sortMode !== 'custom') {
    state.sortMode = 'custom';
    saveSortModePreference('custom');
    renderSortModeToggle();
  }
  
  // 重置拖拽状态
  articleDraggedItem.classList.remove('dragging');
  markApexReorderCommitted(articleDraggedItem);
  articleDraggedItem = null;
  articleIsDragging = false;
}

// 保存文章排序顺序
function saveArticleOrder(order) {
  if (!order || order.length === 0) return;
  
  // 生成排序键，包含视图和筛选条件
  const localStorageKey = generateArticleOrderKey();
  
  // 如果当前有搜索词，不保存排序（因为搜索结果是临时的）
  if (state.q) {
    console.log('搜索状态下不保存自定义排序');
    return;
  }
  
  try {
    localStorage.setItem(localStorageKey, JSON.stringify(order));
    console.log(`保存排序顺序到键 ${localStorageKey}:`, order);
  } catch (e) {
    console.error('保存文章排序失败:', e);
  }
}

// 生成文章排序键，包含视图和筛选条件
function generateArticleOrderKey() {
  const currentView = state.view || 'all';
  const filters = [];
  
  // 添加筛选条件到键中
  if (state.domain) filters.push(`domain=${state.domain}`);
  if (state.author) filters.push(`author=${state.author}`);
  if (state.customTag) filters.push(`tag=${state.customTag}`);
  if (state.customCategory) filters.push(`cat=${state.customCategory}`);
  
  if (filters.length === 0) {
    return `articleOrder_${currentView}`;
  } else {
    return `articleOrder_${currentView}_${filters.join('_')}`;
  }
}

// 加载文章排序顺序
function loadArticleOrder() {
  // 生成排序键，包含视图和筛选条件
  const localStorageKey = generateArticleOrderKey();
  
  try {
    const order = localStorage.getItem(localStorageKey);
    if (!order) return null;
    
    const parsedOrder = JSON.parse(order);
    if (!Array.isArray(parsedOrder)) return null;
    
    // 去重：确保没有重复的ID
    const uniqueOrder = [...new Set(parsedOrder)];
    
    // 如果去重后数量减少，说明原数据有重复，修复它
    if (uniqueOrder.length !== parsedOrder.length) {
      console.warn(`发现重复的排序数据，已自动修复: ${localStorageKey}`, {
        originalLength: parsedOrder.length,
        uniqueLength: uniqueOrder.length,
        duplicates: parsedOrder.filter((id, index) => parsedOrder.indexOf(id) !== index)
      });
      
      // 保存修复后的数据回localStorage
      try {
        localStorage.setItem(localStorageKey, JSON.stringify(uniqueOrder));
      } catch (e) {
        console.error('保存修复后的排序数据失败:', e);
      }
    }
    
    return uniqueOrder;
  } catch (e) {
    console.error('加载文章排序失败:', e);
    return null;
  }
}

// 应用自定义排序到文章列表
function applyArticleOrder(articles) {
  const customOrder = loadArticleOrder();
  
  if (!customOrder || customOrder.length === 0) {
    console.log('applyArticleOrder: 无自定义排序，直接返回原文章列表');
    return articles;
  }
  
  // 如果当前有搜索词，不应用自定义排序
  if (state.q) {
    console.log('applyArticleOrder: 搜索状态下不应用自定义排序');
    return articles;
  }
  
  // 首先检查并去除articles中的重复（防御性编程）
  const uniqueArticles = [];
  const seenArticleIds = new Set();
  articles.forEach(article => {
    if (!seenArticleIds.has(article.id)) {
      seenArticleIds.add(article.id);
      uniqueArticles.push(article);
    } else {
      console.warn(`applyArticleOrder: 发现重复的文章ID ${article.id}，已跳过`);
    }
  });
  
  // 如果发现重复，使用去重后的文章列表
  if (uniqueArticles.length !== articles.length) {
    console.warn(`applyArticleOrder: 输入文章列表中有重复，已自动去重`, {
      originalCount: articles.length,
      uniqueCount: uniqueArticles.length
    });
    articles = uniqueArticles;
  }
  
  // 调试信息
  console.log('applyArticleOrder:', {
    inputCount: articles.length,
    customOrderLength: customOrder.length,
    customOrder: customOrder,
    hasDuplicatesInCustomOrder: customOrder.length !== new Set(customOrder).size
  });
  
  // 创建id到文章的映射（统一用字符串key，避免数字/字符串类型不一致）
  const articleMap = {};
  articles.forEach(article => {
    articleMap[String(article.id)] = article;
  });
  
  // 按照自定义顺序重新排序
  const orderedArticles = [];
  const remainingArticles = [...articles];
  
  // 首先添加自定义顺序中存在的文章，同时去重
  const seenIds = new Set();
  customOrder.forEach(id => {
    // 统一转换为字符串，避免数字/字符串类型不一致导致的比较问题
    const strId = String(id);
    
    // 如果已经处理过这个ID，跳过（避免重复）
    if (seenIds.has(strId)) {
      console.log(`applyArticleOrder: 跳过重复ID ${strId}`);
      return;
    }
    
    if (articleMap[strId]) {
      orderedArticles.push(articleMap[strId]);
      seenIds.add(strId);
      // 从剩余列表中移除所有匹配的文章（使用字符串比较，防止类型不一致）
      let index;
      while ((index = remainingArticles.findIndex(a => String(a.id) === strId)) !== -1) {
        remainingArticles.splice(index, 1);
      }
    } else {
      console.log(`applyArticleOrder: ID ${strId} 不在当前文章列表中`);
    }
  });
  
  const result = [...orderedArticles, ...remainingArticles];
  console.log('applyArticleOrder: 结果', {
    orderedCount: orderedArticles.length,
    remainingCount: remainingArticles.length,
    resultCount: result.length,
    resultIds: result.map(a => a.id)
  });
  
  // 然后添加剩余的文章（新添加的文章）
  return result;
}

/* ─────────────────────────────────────────────
   初始化
───────────────────────────────────────────── */

function toggleSection(sectionName) {
  if (isSidebarSectionLocked(sectionName)) return;
  const header = document.querySelector(`[onclick="toggleSection('${sectionName}')"]`);
  const content = document.getElementById(`section-${sectionName}`);

  if (!header || !content) return;

  header.classList.toggle('collapsed');
  content.classList.toggle('collapsed');
}

/* ─────────────────────────────────────────────
   侧边栏折叠状态
───────────────────────────────────────────── */
const SIDEBAR_COLLAPSED_KEY = 'legal_kb_sidebar_collapsed';

function saveSidebarState() {
  const sidebar = $('sidebar');
  if (sidebar) {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, sidebar.classList.contains('collapsed') ? '1' : '0');
  }
}

function restoreSidebarState() {
  // 刷新页面后默认展开侧边栏，不再恢复之前保存的状态
  // 用户可以手动折叠，但刷新后会重置为展开状态
  const sidebar = $('sidebar');
  if (!sidebar) return;
  sidebar.classList.remove('collapsed');
  document.body.classList.remove('sidebar-collapsed');
}

/* ─────────────────────────────────────────────
   侧边栏分组拖拽排序
───────────────────────────────────────────── */

const SIDEBAR_ORDER_KEY = 'legal_kb_sidebar_order';
const SORTABLE_SIDEBAR_SECTIONS = Object.freeze(['domain', 'author', 'customLib']);

function getSortableSidebarSections(nav = document.getElementById('sidebar-nav')) {
  if (!nav) return [];
  return Array.from(nav.querySelectorAll('.nav-section[data-section]'))
    .filter(section => SORTABLE_SIDEBAR_SECTIONS.includes(section.dataset.section));
}

function saveSidebarOrder() {
  const order = getSortableSidebarSections().map(section => section.dataset.section);
  try {
    localStorage.setItem(SIDEBAR_ORDER_KEY, JSON.stringify(order));
  } catch (e) {
    console.warn('保存侧边栏分组顺序失败:', e);
  }
}

function restoreSidebarOrder() {
  let detachedSections = [];
  let nav = null;
  let insertionPoint = null;
  try {
    nav = document.getElementById('sidebar-nav');
    if (!nav) return;
    const currentSections = getSortableSidebarSections(nav);
    if (!currentSections.length) return;
    // 必须在把节点移入 DocumentFragment 之前记录其后的锚点。
    // 旧实现使用 currentSections[0] 作为 insertBefore 的锚点，但该节点
    // 已经被 appendChild(fragment) 移出 nav，会抛出 NotFoundError 并使三个分组消失。
    insertionPoint = currentSections[currentSections.length - 1].nextSibling;

    const saved = localStorage.getItem(SIDEBAR_ORDER_KEY);
    const savedOrder = saved ? JSON.parse(saved) : [];
    const validSavedOrder = Array.isArray(savedOrder)
      ? savedOrder.filter((name, index) => SORTABLE_SIDEBAR_SECTIONS.includes(name) && savedOrder.indexOf(name) === index)
      : [];
    const order = [
      ...validSavedOrder,
      ...currentSections.map(section => section.dataset.section)
        .filter(name => !validSavedOrder.includes(name))
    ];
    const sectionsByName = new Map(currentSections.map(section => [section.dataset.section, section]));
    const fragment = document.createDocumentFragment();
    order.forEach(name => {
      const section = sectionsByName.get(name);
      if (section) {
        fragment.appendChild(section);
        detachedSections.push(section);
      }
    });
    nav.insertBefore(fragment, insertionPoint);
    detachedSections = [];
  } catch (e) {
    console.warn('恢复侧边栏分组顺序失败:', e);
    // 即使浏览器遇到异常，也要把已移出的分组放回侧边栏，避免整个标签区消失。
    if (nav && detachedSections.length) {
      const recoveryFragment = document.createDocumentFragment();
      detachedSections.forEach(section => recoveryFragment.appendChild(section));
      nav.insertBefore(recoveryFragment, insertionPoint && insertionPoint.parentNode === nav ? insertionPoint : null);
    }
  }
}

function initSidebarDrag() {
  const nav = document.getElementById('sidebar-nav');
  if (!nav) return;

  let dragSrc = null;
  let sidebarDropCommitted = false;
  const isTagTreeTarget = target => !!(target && target.closest('.tag-category, .tag-item, .tag-drop-zone'));

  // ── 关键修复：默认所有 section 不可拖拽，只有从手柄 mousedown 时才临时开启 ──
  // 这样 dragstart 时 e.target 必然是当前被授权拖拽的 section，无需再判断来源
  getSortableSidebarSections(nav).forEach(sec => {
    sec.removeAttribute('draggable');
    const handle = sec.querySelector('.nav-section-drag-handle');
    if (!handle) return;

    handle.addEventListener('mousedown', () => {
      sec.setAttribute('draggable', 'true');
    });
    // 防止 mouseup 时没有触发 dragend（e.g. 用户点击但不拖拽），也要重置
    handle.addEventListener('mouseup', () => {
      if (!dragSrc) sec.removeAttribute('draggable');
    });
  });

  nav.addEventListener('dragstart', e => {
    // 如果拖拽的是内部标签树，不触发 section 级别的拖拽
    if (isTagTreeTarget(e.target)) return;
    const section = e.target.closest('.nav-section[data-section]');
    // 必须是被手柄 mousedown 授权过 draggable 的 section
    if (!section || !SORTABLE_SIDEBAR_SECTIONS.includes(section.dataset.section) || section.getAttribute('draggable') !== 'true') return;
    dragSrc = section;
    sidebarDropCommitted = false;
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', section.dataset.section);
    setTimeout(() => section.classList.add('dragging'), 0);
  });

  nav.addEventListener('dragend', e => {
    const section = e.target.closest('.nav-section[data-section]');
    if (section) {
      section.classList.remove('dragging');
      section.removeAttribute('draggable');
      if (sidebarDropCommitted) markApexReorderCommitted(section);
    }
    nav.querySelectorAll('.nav-section').forEach(s => s.classList.remove('drag-over'));
    dragSrc = null;
    sidebarDropCommitted = false;
  });

  nav.addEventListener('dragover', e => {
    // 内部标签树拖拽不干扰 section 级别排序
    if (isTagTreeTarget(e.target)) return;
    if (!dragSrc) return;
    e.preventDefault();
    const section = e.target.closest('.nav-section[data-section]');
    nav.querySelectorAll('.nav-section').forEach(s => s.classList.remove('drag-over'));
    if (section && SORTABLE_SIDEBAR_SECTIONS.includes(section.dataset.section) && section !== dragSrc) {
      section.classList.add('drag-over');
    }
    e.dataTransfer.dropEffect = 'move';
  });

  nav.addEventListener('dragleave', e => {
    const section = e.target.closest('.nav-section[data-section]');
    if (section) section.classList.remove('drag-over');
  });

  nav.addEventListener('drop', e => {
    // 内部标签树拖拽不干扰 section 级别排序
    if (isTagTreeTarget(e.target)) return;
    if (!dragSrc) return;
    e.preventDefault();
    const target = e.target.closest('.nav-section[data-section]');
    nav.querySelectorAll('.nav-section').forEach(s => s.classList.remove('drag-over'));
    if (!target || !SORTABLE_SIDEBAR_SECTIONS.includes(target.dataset.section) || target === dragSrc) return;

    // 判断拖拽方向：插到目标前或后
    const targetRect = target.getBoundingClientRect();
    const midY = targetRect.top + targetRect.height / 2;
    const beforeRects = captureApexReorderRects(nav, ':scope > .nav-section');
    if (e.clientY < midY) {
      nav.insertBefore(dragSrc, target);
    } else {
      nav.insertBefore(dragSrc, target.nextSibling);
    }
    sidebarDropCommitted = true;
    animateApexReorder(nav, beforeRects, { skip: dragSrc });
    saveSidebarOrder();
  });
}

async function initApp() {
  // 最优先恢复主题，防止黑夜模式下页面闪白
  loadKnowledgeColorTheme();
  loadTheme();
  initThemeSync();
  loadBrandLogo();
  applySidebarGreetingVisibility();
  initMobileZoomLock();
  initOpenPagesOverview();

  const forceResetTabs = localStorage.getItem('legal_kb_force_reset') === '1';
  const activeTabIdBeforeReload = forceResetTabs ? 'main' : getSavedActiveTabId();
  let restoredTabs = false;
  localStorage.removeItem('legal_kb_force_reset');
  // 清除 URL 时间戳参数（不刷新页面，只替换 history）
  if (/[?&]_=\d+/.test(location.search)) {
    history.replaceState(null, '', location.pathname);
  }
  // 清除旧的正文渲染缓存（确保使用最新的渲染逻辑）
  state.bodyCache.clear();

  if (forceResetTabs) {
    localStorage.removeItem('legal_kb_tabs');
    resetTabsToDefault();
  } else {
    restoredTabs = restoreTabsState();
    if (!restoredTabs) {
      resetTabsToDefault();
    }
  }

  // 恢复侧边栏折叠状态（默认展开）
  restoreSidebarState();

  // 恢复侧边栏分组顺序
  restoreSidebarOrder();
  // 初始化侧边栏拖拽排序
  initSidebarDrag();
  // 恢复三个一级菜单的固定展开状态。
  initSidebarSectionLocks();
  // 初始化一级区块的悬停宽限，避免移动到内部标签时意外收起。
  initSidebarHoverIntent();

  // 初始化标签栏点击事件（事件委托）
  initTabBarEvents();
  renderLegalAssistantTools();
  loadLegalAssistantToolOrder();
  initMainPageWheelScroll();
  window.addEventListener('beforeunload', () => {
    saveTabsState();
    flushAllArticleReadPositions();
  });

  // 监听子 iframe 发送的消息（如法答网页面点击标题跳转）
  window.addEventListener('message', (e) => {
    if (e.data && e.data.type === 'openExternalTab') {
      const { url, title } = e.data;
      if (url) {
        openTab(TAB_TYPES.EXTERNAL, title || '外部链接', { url, title });
      }
    } else if (e.origin === location.origin && e.data?.type === 'openCaseResearch') {
      openCaseResearchForCase(e.data.caseId, e.data.section);
    } else if (e.origin === location.origin && e.data?.type === 'openCaseFiles') {
      const sourceCaseTab = getCaseManagerTabForMessageSource(e.source);
      openCaseFilesTab(e.data.caseId, e.data.caseTitle || '案件', sourceCaseTab?.id || '');
    } else if (e.origin === location.origin && e.data?.type === 'apex:open-case-archive') {
      openCaseArchiveTab(e.data.caseId, e.data.caseTitle || '');
    } else if (e.origin === location.origin && e.data?.type === 'apex:open-case-manager') {
      openCaseManagerTab();
    } else if (e.origin === location.origin && e.data?.type === 'apex:case-archive-case-selected') {
      const tab = tabState.tabs.find(item => item.type === TAB_TYPES.CASE_ARCHIVE &&
        document.getElementById(item.id)?.querySelector('iframe')?.contentWindow === e.source);
      if (tab) {
        tab.data = { ...(tab.data || {}), caseId: Number(e.data.caseId || 0) };
        tab.title = `${e.data.caseTitle || '案件'} · 案卷归档`;
        saveTabsState();
        renderTabs();
      }
    } else if (e.origin === location.origin && e.data?.type === 'openCaseFilesAsk') {
      const context = e.data.context || null;
      if (!context?.caseId || !Array.isArray(context.paths) || !context.paths.length) {
        showToast('没有可用于问答的案件文件', 'warning');
        return;
      }
      askContext = context;
      askSourceMode = 'hybrid';
      openAskPanel();
    } else if (e.origin === location.origin && e.data?.type === 'openCaseAuthorizationTool') {
      const caseId = Number(e.data.caseId || 0);
      if (e.data.tool === 'power-attorney') openPowerAttorneyTab(caseId);
      else if (e.data.tool === 'suohan') openSuohanTab(caseId);
      else if (e.data.tool === 'rep-identity-cert') openRepIdentityCertTab(caseId);
      else if (e.data.tool === 'document-bundle') openDocumentBundleTab(caseId);
    } else if (e.origin === location.origin && e.data?.type === 'openInvoiceCenter') {
      openInvoiceCenterTab(e.data.account || 'qq_mail');
    } else if (e.origin === location.origin && e.data?.type === 'openPagesCommandKey') {
      if (!getCaseManagerTabForMessageSource(e.source) && !getCaseFilesTabForMessageSource(e.source)) return;
      handleCaseManagerCommandMessage(e.data);
    } else if (e.origin === location.origin && e.data?.type === 'caseManagerContext') {
      const caseTab = getCaseManagerTabForMessageSource(e.source);
      if (!caseTab) return;
      const caseId = Number(e.data.caseId || 0);
      const caseTitle = String(e.data.caseTitle || '').trim();
      const nextData = {
        ...(caseTab.data || {}),
        contextLabel: String(e.data.contextLabel || e.data.pageLabel || '案件列表'),
        pageLabel: String(e.data.pageLabel || '案件管理'),
        detailLabel: String(e.data.detailLabel || '')
      };
      // 只有明确打开案件详情时才保留案件名称；返回列表或其他功能页时要清除，
      // 否则旧案件名称会错误地留在新的页面上。
      if (caseId > 0 && caseTitle) {
        nextData.caseId = caseId;
        nextData.caseTitle = caseTitle;
      } else {
        delete nextData.caseId;
        delete nextData.caseTitle;
      }
      caseTab.data = {
        ...nextData
      };
      renderTabs();
      saveTabsState();
    } else if (e.origin === location.origin && e.data?.type === 'caseManagerViewState') {
      const caseTab = getCaseManagerTabForMessageSource(e.source);
      if (!caseTab) return;
      const seriesId = Number(e.data.seriesId || 0);
      caseTab.data = {
        ...(caseTab.data || {}),
        viewState: seriesId > 0 ? {
          seriesId,
          seriesTab: e.data.seriesTab === 'public' ? 'public' : 'children',
          bodyScrollTop: Math.max(0, Number(e.data.bodyScrollTop || 0)),
          tableScrollTop: Math.max(0, Number(e.data.tableScrollTop || 0)),
          tableScrollLeft: Math.max(0, Number(e.data.tableScrollLeft || 0)),
        } : null,
      };
      saveTabsState();
    } else if (e.origin === location.origin && e.data?.type === 'apex:knowledge-prefill-ask') {
      const sourceTab = tabState.tabs.find(tab =>
        tab.type === TAB_TYPES.LEGAL_KNOWLEDGE &&
        document.getElementById(tab.id)?.querySelector('iframe')?.contentWindow === e.source);
      if (!sourceTab || e.data.version !== 1 || typeof e.data.question !== 'string') return;
      const question = e.data.question.trim().slice(0, 6000);
      if (!question) return;
      openAskPanel({ noFresh: true });
      const input = document.getElementById('ask-input');
      if (input) {
        input.value = input.value.trim() ? `${input.value.trim()}\n\n${question}` : question;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.focus();
      }
    } else if (e.origin === location.origin && e.data?.type === 'openKnowledgeSource') {
      const articleId = Number(e.data.articleId || 0);
      if (!articleId) return;
      state.pendingScrollOffset = Number.isFinite(Number(e.data.charStart)) ? Number(e.data.charStart) : null;
      state.pendingCitationQuote = e.data.quote || null;
      state.pendingHighlight = state.pendingScrollOffset === null ? (e.data.quote || null) : null;
      openArticleInTab(articleId, e.data.title || '文章详情');
    } else if (e.origin === location.origin && e.data?.type === 'setTheme') {
      state.darkMode = !!e.data.dark;
      applyTheme();
      saveTheme();
    }
  });

  const launchParams = new URLSearchParams(location.search);
  const launchResearchCaseId = Number(launchParams.get('open_case_research') || 0);
  if (launchResearchCaseId) {
    const launchResearchSection = launchParams.get('section') === 'memo' ? 'memo' : 'ledger';
    launchParams.delete('open_case_research');
    launchParams.delete('section');
    const cleanQuery = launchParams.toString();
    history.replaceState(null, '', `${location.pathname}${cleanQuery ? `?${cleanQuery}` : ''}${location.hash}`);
    window.setTimeout(() => openCaseResearchForCase(launchResearchCaseId, launchResearchSection), 0);
  }
  const launchCaseFilesId = Number(launchParams.get('open_case_files') || 0);
  if (launchCaseFilesId) {
    const launchCaseFilesTitle = launchParams.get('title') || '案件';
    launchParams.delete('open_case_files');
    launchParams.delete('title');
    const cleanQuery = launchParams.toString();
    history.replaceState(null, '', `${location.pathname}${cleanQuery ? `?${cleanQuery}` : ''}${location.hash}`);
    window.setTimeout(() => openCaseFilesTab(launchCaseFilesId, launchCaseFilesTitle), 0);
  }
  const launchCaseArchiveId = Number(launchParams.get('open_case_archive') || 0);
  if (launchCaseArchiveId) {
    launchParams.delete('open_case_archive');
    const cleanQuery = launchParams.toString();
    history.replaceState(null, '', `${location.pathname}${cleanQuery ? `?${cleanQuery}` : ''}${location.hash}`);
    window.setTimeout(() => openCaseArchiveTab(launchCaseArchiveId), 0);
  }

  // 恢复排序模式偏好
  state.sortMode = loadSortModePreference();
  // 恢复文章列表密度偏好
  state.articleDensity = loadArticleDensityPreference();
  // 恢复默认搜索范围偏好
  applySearchScopePreference();
  // 恢复每页文章数量偏好
  state.pageSize = loadArticlePageSizePreference();
  applyArticleDensity();
  await initArticleOfflineSupport();
  await initCaseResearchOfflineSupport();
  const hasOfflineCases = await hasCaseManagerOfflineSnapshot();
  const initialServerProbe = isServerReachable(5000);
  const quickProbe = await Promise.race([
    initialServerProbe.then(online => ({ settled: true, online })),
    new Promise(resolve => setTimeout(() => resolve({ settled: false, online: false }), 250)),
  ]);
  const serverReachable = quickProbe.online;
  applyServerConnectionState(serverReachable, !serverReachable);
  if (!quickProbe.settled) {
    initialServerProbe.then(online => handleServerProbeResult(online)).catch(() => {});
  }
  startConnectivityMonitor();
  startSmartHibernationMonitor();
  if (serverReachable) {
    syncPendingKnowledgeLinks(true);
    scheduleOfflineSnapshotRefresh({ delay: 30000 });
  }
  renderPendingKnowledgeQueue();
  try {
    state.healthFilter = sessionStorage.getItem(HEALTH_FILTER_KEY) || null;
  } catch (e) {
    state.healthFilter = null;
  }
  await syncSavedViewsFromServer();
  // 从服务端同步默认搜索范围（不阻塞启动；本地无缓存时也能恢复用户设置）
  syncSearchScopeFromServer();

  // 初始化键盘快捷键
  initKeyboardShortcuts();

  const startupResults = serverReachable
    ? await Promise.allSettled([loadStats(), loadDomains(), loadAuthors(), loadCustomTags()])
    : await Promise.allSettled([loadDomains(true), loadAuthors(true), loadTagGroups(true)]);
  const startupOffline = startupResults.some(result => result.status === 'rejected');
  try {
    await loadArticles();
  } catch (e) {
    if (!startupOffline) console.warn('文章列表加载失败:', e);
  }
  // 设置文本选中功能
  setupTextSelection();
  // 渲染视图切换按钮
  renderListViewToggle();
  // 渲染排序模式按钮
  renderSortModeToggle();
  // 渲染文章列表密度控件
  renderArticleDensityControl();
  // 今日推荐首页模块
  applyHomeRecommendationVisibility();
  // 首页提醒中心：案件时限、司法短信与中文未读邮件。
  initHomeReminderCenter();

  if (
    restoredTabs &&
    activeTabIdBeforeReload !== 'main' &&
    tabState.activeTabId === 'main' &&
    tabState.tabs.some(tab => tab.id === activeTabIdBeforeReload)
  ) {
    switchTab(activeTabIdBeforeReload);
  }
  if ((hasOfflineCases && (!serverReachable || startupOffline)) && tabState.activeTabId === 'main') {
    openCaseManagerTab();
  }
}

function initMobileZoomLock() {
  if (window.__legalKbMobileZoomLocked) return;
  window.__legalKbMobileZoomLocked = true;

  const preventZoomGesture = (e) => {
    e.preventDefault();
  };

  ['gesturestart', 'gesturechange', 'gestureend'].forEach(eventName => {
    document.addEventListener(eventName, preventZoomGesture, { passive: false });
  });

  document.addEventListener('touchmove', (e) => {
    if (e.touches && e.touches.length > 1) {
      e.preventDefault();
    }
  }, { passive: false });
}

/**
 * 保存标签页状态到 localStorage
 */
function saveTabsState() {
  try {
    const state = {
      tabs: tabState.tabs,
      activeTabId: tabState.activeTabId,
      tabCounter: tabState.tabCounter
    };
    localStorage.setItem('legal_kb_tabs', JSON.stringify(state));
  } catch (e) {
    console.warn('保存标签页状态失败:', e);
  }
}

function getSavedActiveTabId() {
  try {
    const saved = localStorage.getItem('legal_kb_tabs');
    if (!saved) return 'main';

    const savedState = JSON.parse(saved);
    if (
      savedState &&
      Array.isArray(savedState.tabs) &&
      savedState.activeTabId &&
      savedState.tabs.some(tab => tab.id === savedState.activeTabId)
    ) {
      return savedState.activeTabId;
    }
  } catch (e) {
    console.warn('读取标签页激活状态失败:', e);
  }
  return 'main';
}

function getSavedActiveTab() {
  try {
    const saved = localStorage.getItem('legal_kb_tabs');
    if (!saved) return null;
    const savedState = JSON.parse(saved);
    if (!savedState || !Array.isArray(savedState.tabs) || !savedState.activeTabId) return null;
    return savedState.tabs.find(tab => tab && tab.id === savedState.activeTabId) || null;
  } catch (e) {
    console.warn('读取当前标签页失败:', e);
    return null;
  }
}

/**
 * 从 localStorage 恢复标签页状态
 */
function restoreTabsState() {
  try {
    const saved = localStorage.getItem('legal_kb_tabs');
    if (!saved) return false;
    
    const state = JSON.parse(saved);
    if (!state.tabs || !Array.isArray(state.tabs) || state.tabs.length === 0) return false;
    let restoredTabs = state.tabs.filter(tab => tab && tab.type !== 'oa_system');
    if (!restoredTabs.length) return false;

    // 旧会话可能保留了重复打开的法院通讯录；恢复时只保留当前页（若有），
    // 否则保留第一个，确保该页面始终只有一个实例。
    const courtDirectoryTabs = restoredTabs.filter(tab => tab.type === TAB_TYPES.COURT_DIRECTORY);
    if (courtDirectoryTabs.length > 1) {
      const keptCourtDirectoryTab = courtDirectoryTabs.find(tab => tab.id === state.activeTabId)
        || courtDirectoryTabs[0];
      restoredTabs = restoredTabs.filter(tab =>
        tab.type !== TAB_TYPES.COURT_DIRECTORY || tab.id === keptCourtDirectoryTab.id
      );
    }

    // 工具已扩展为利息、诉讼仲裁费及风险代理律师费计算；同步迁移旧会话中保存的标签标题。
    // 法院在线服务更名为“一张网”，同步迁移旧会话中已打开标签的标题。
    restoredTabs.forEach(tab => {
      if (tab.type === TAB_TYPES.INTEREST_CALC) tab.title = '计算工具';
      if (tab.type === TAB_TYPES.COURT_ONLINE) tab.title = '一张网';
      if (tab.type === TAB_TYPES.QQ_EXMAIL) tab.title = '腾讯企业邮箱 · 邮件管理';
    });
    
    // 恢复标签状态
    tabState.tabs = restoredTabs;
    tabState.activeTabId = state.activeTabId || 'main';
    if (tabState.activeTabId !== 'main' && !restoredTabs.some(tab => tab.id === tabState.activeTabId)) {
      tabState.activeTabId = 'main';
    }
    tabState.tabCounter = state.tabCounter || 0;
    normalizeCaseManagerTabs();
    
    // 重新渲染标签栏
    renderTabs();
    restoredTabs
      .filter(tab => tab.type === TAB_TYPES.LEGAL_KNOWLEDGE && Number(tab.data?.claimId || 0) > 0)
      .forEach(tab => updateLegalKnowledgeTabTitle(tab.id, tab.data.claimId));
    
    if (tabState.activeTabId !== 'main') {
      const activeTab = restoredTabs.find(tab => tab.id === tabState.activeTabId);
      if (activeTab) createTabPage(activeTab);
    } else {
      const mainPage = $('tab-page-main');
      if (mainPage) mainPage.classList.add('active');
    }
    
    // 切换到活动标签页
    switchTab(tabState.activeTabId);
    saveTabsState();
    
    return true;
  } catch (e) {
    console.warn('恢复标签页状态失败:', e);
    return false;
  }
}

/**
 * 重置标签页到默认状态（主页）
 */
function resetTabsToDefault() {
  if (tabState.tabs.some(tab => tab.type === TAB_TYPES.AI_ASK)) detachAskPanelFromTab();
  // 1. 隐藏所有标签页内容
  const allPages = document.querySelectorAll('.tab-page');
  allPages.forEach(page => {
    page.classList.remove('active');
    page.style.display = 'none';
  });
  
  // 2. 移除所有已打开的标签页内容元素
  tabState.tabs.forEach(tab => {
    const pageEl = $(tab.id);
    if (pageEl) pageEl.remove();
  });
  
  // 3. 重置标签状态
  tabState.tabs = [];
  tabState.activeTabId = 'main';
  researchStatesByTabId.clear();
  
  // 4. 清除保存的标签页状态
  localStorage.removeItem('legal_kb_tabs');
  
  // 5. 关闭工具弹窗
  const toolsPopup = document.getElementById('tools-popup');
  const toolsHeader = document.getElementById('tools-header');
  if (toolsPopup) {
    toolsPopup.classList.remove('show');
    toolsPopup.setAttribute('aria-hidden', 'true');
  }
  if (toolsHeader) {
    toolsHeader.classList.remove('active');
    toolsHeader.setAttribute('aria-expanded', 'false');
  }
  window.toolsMenuOpen = false;
  // 兜底：按移动端外壳移植规则把效率中心外壳送回锚点并复位定位。
  window.positionToolsPopup?.();
  if (window.toolsShowTimer) { clearTimeout(window.toolsShowTimer); window.toolsShowTimer = null; }
  if (window.toolsHideTimer) { clearTimeout(window.toolsHideTimer); window.toolsHideTimer = null; }
  
  // 6. 确保主页可见
  const mainPage = $('tab-page-main');
  if (mainPage) {
    mainPage.classList.add('active');
    mainPage.style.display = 'flex';
    mainPage.style.flexDirection = 'column';
    mainPage.style.flex = '1';
    mainPage.style.minHeight = '0';
    mainPage.style.overflow = 'hidden';
  }
  
  // 7. 展开侧边栏
  expandSidebar();
  
  // 8. 重置侧边栏导航状态 - 只保留"全部知识"为激活状态
  document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));
  const allNavItem = document.querySelector('[data-view="all"]');
  if (allNavItem) allNavItem.classList.add('active');
  
  // 9. 重置状态筛选条件
  state.view = 'all';
  state.domain = null;
  state.author = null;
  state.customTag = null;
  state.currentTagGroupId = null;
  state.customCategory = null;
  state.customCategoryTags = null;
  state.q = '';
  state.page = 1;
  $('page-title').textContent = '全部知识';
  
  // 10. 渲染空标签栏（只显示主页按钮）
  renderTabs();
  
  // 11. 更新主页按钮状态
  const homeBtn = $('tab-bar-home-btn');
  if (homeBtn) {
    homeBtn.classList.remove('active');
  }
}

/**
 * 初始化标签栏点击事件（事件委托）
 */
function initTabBarEvents() {
  const tabsContainer = $('tab-bar-tabs');
  if (!tabsContainer) return;
  initArticleTabMenuEvents();
  
  tabsContainer.addEventListener('click', (e) => {
    if (tabReorderState.suppressClick) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }

    // 处理关闭按钮点击
    const closeBtn = e.target.closest('.tab-close');
    if (closeBtn) {
      e.stopPropagation();
      const tabId = closeBtn.dataset.closeTab;
      if (tabId) {
        closeTab(tabId);
        hideArticleTabMenuUntilPointerLeaves();
      }
      return;
    }

    // 处理标签项点击
    const tabItem = e.target.closest('.tab-item');
    if (tabItem) {
      const workspaceKind = tabItem.dataset.workspaceGroup || '';
      if (workspaceKind) {
        e.preventDefault();
        e.stopPropagation();
        showWorkspaceTabMenu(workspaceKind);
        return;
      }
      if (tabItem.classList.contains('article-tab-group')) {
        e.preventDefault();
        e.stopPropagation();
        showArticleTabMenu();
        return;
      }
      const tabId = tabItem.dataset.tabId;
      if (tabId) switchTab(tabId);
    }
  });

  tabsContainer.addEventListener('keydown', (e) => {
    const group = e.target.closest('.article-tab-group, .workspace-tab-group');
    if (!group) return;
    const workspaceKind = group.dataset.workspaceGroup || '';

    if (e.key === 'ArrowDown' && e.target === group) {
      e.preventDefault();
      if (workspaceKind) showWorkspaceTabMenu(workspaceKind, true);
      else showArticleTabMenu(true);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      if (workspaceKind) hideWorkspaceTabMenu(workspaceKind);
      else hideArticleTabMenu();
      group.blur();
    }
  });

  tabsContainer.addEventListener('pointerdown', (e) => {
    if (e.button !== undefined && e.button !== 0) return;
    if (e.target.closest('.tab-close')) return;

    const tabItem = e.target.closest('.tab-item');
    if (!tabItem) return;
    const tabId = tabItem.dataset.tabId;
    if (!tabId) return;

    // 桌面端采用浏览器原生标签的交互：按下即切换。外接屏缩放、全屏布局变化或
    // iframe 抢走 pointerup/click 时，也不会丢失本次切换。
    const activateImmediately = e.pointerType !== 'touch';
    if (activateImmediately && tabState.activeTabId !== tabId) {
      switchTab(tabId);
    }

    if (tabId === 'main' || tabItem.dataset.reorderableTab !== 'true') return;

    tabReorderState.pointerId = e.pointerId;
    tabReorderState.tabId = tabId;
    tabReorderState.startX = e.clientX;
    tabReorderState.startY = e.clientY;
    tabReorderState.dragging = false;
    tabReorderState.moved = false;
    tabReorderState.activatedOnPointerDown = activateImmediately;
  });

  window.addEventListener('pointermove', (e) => {
    if (tabReorderState.pointerId !== e.pointerId || !tabReorderState.tabId) return;

    const dx = e.clientX - tabReorderState.startX;
    const dy = e.clientY - tabReorderState.startY;
    if (!tabReorderState.dragging) {
      // 标签只做横向排序。单击时常见的轻微斜向/纵向抖动不应吞掉切换操作。
      if (Math.abs(dx) < TAB_DRAG_THRESHOLD || Math.abs(dx) <= Math.abs(dy)) return;
      const draggedEl = getTabElementById(tabReorderState.tabId);
      if (!draggedEl) {
        finishTabReorder();
        return;
      }
      tabReorderState.dragging = true;
      draggedEl.classList.add('tab-dragging');
      document.body.classList.add('tab-reordering');
    }

    e.preventDefault();
    const draggedEl = getTabElementById(tabReorderState.tabId);
    const targetEl = document.elementFromPoint(e.clientX, e.clientY)?.closest('.tab-item[data-reorderable-tab="true"]');
    if (!draggedEl || !targetEl || targetEl === draggedEl || targetEl.dataset.tabId === 'main') return;

    const targetRect = targetEl.getBoundingClientRect();
    const placeAfterTarget = e.clientX > targetRect.left + targetRect.width / 2;
    if (reorderOpenTabState(tabReorderState.tabId, targetEl.dataset.tabId, placeAfterTarget)) {
      const beforeRects = captureApexReorderRects(tabsContainer, ':scope > .tab-item');
      moveTabElement(draggedEl, targetEl, placeAfterTarget);
      tabReorderState.moved = true;
      animateApexReorder(tabsContainer, beforeRects, { skip: draggedEl });
    }
  }, { passive: false });

  window.addEventListener('pointerup', (e) => {
    if (tabReorderState.pointerId !== e.pointerId) return;
    const pressedTabId = tabReorderState.tabId;
    const wasDragging = tabReorderState.dragging;
    const activatedOnPointerDown = tabReorderState.activatedOnPointerDown;
    const releasedTab = e.target instanceof Element ? e.target.closest('.tab-item') : null;
    const shouldActivate = !activatedOnPointerDown &&
      !wasDragging &&
      releasedTab?.dataset.tabId === pressedTabId;
    finishTabReorder();
    if (activatedOnPointerDown || shouldActivate) {
      // 吞掉随后可能到达的 click，避免已在 pointerdown 完成的切换被重复执行。
      suppressNextTabClick();
      if (shouldActivate) switchTab(pressedTabId);
    }
  });

  window.addEventListener('pointercancel', (e) => {
    if (tabReorderState.pointerId !== e.pointerId) return;
    finishTabReorder();
  });
}

function initArticleTabMenuEvents() {
  if (articleTabMenuEventsInitialized) return;
  articleTabMenuEventsInitialized = true;

  document.addEventListener('pointermove', event => {
    workspaceTabMenusHeldOpen.forEach(kind => {
      const menu = document.getElementById(`${kind}-tab-floating-menu`);
      const group = document.querySelector(`#tab-bar-tabs .${kind}-tab-group`);
      if (menu?.contains(event.target) || group?.contains(event.target)) return;
      workspaceTabMenusHeldOpen.delete(kind);
      scheduleWorkspaceTabMenuHide(kind);
    });
  }, { passive: true });

  document.addEventListener('click', (e) => {
    if (e.target.closest('.article-tab-group, .workspace-tab-group')) return;

    const workspaceMenu = e.target.closest('.workspace-tab-menu');
    if (workspaceMenu) {
      const kind = workspaceMenu.dataset.workspaceMenu;
      const closeAllBtn = e.target.closest('.workspace-tab-close-all-btn');
      if (closeAllBtn) {
        e.preventDefault();
        e.stopPropagation();
        if (kind === 'case-manager') closeAllCaseManagerTabs();
        if (kind === 'court-online') closeAllTabsByType(TAB_TYPES.COURT_ONLINE, '已关闭所有一张网页面');
        if (kind === 'research') closeAllResearchTabs();
        if (kind === 'case-files') closeAllCaseFileTabs();
        if (kind === 'knowledge-center') closeAllKnowledgeCenterTabs();
        if (kind === 'tools') closeAllToolsTabs();
        if (kind === 'settings') closeAllSettingsTabs();
        return;
      }
      const addBtn = e.target.closest('.workspace-tab-add-btn');
      if (addBtn) {
        e.preventDefault();
        e.stopPropagation();
        hideWorkspaceTabMenu(kind);
        if (kind === 'case-manager') openCaseManagerTab();
        if (kind === 'research') openResearchProjectsTab();
        return;
      }
      const closeBtn = e.target.closest('.article-tab-menu-close');
      if (closeBtn) {
        e.preventDefault();
        e.stopPropagation();
        const tabId = closeBtn.dataset.closeTab;
        // 设置、知识中心和效率中心菜单内关闭单页时保持菜单展开；只有指针离开整个菜单范围才收起。
        if (tabId) {
          const keepOpen = kind === 'settings' || kind === 'tools' || kind === 'knowledge-center';
          const groupStillHasTabs = () => {
            if (kind === 'settings') return tabState.tabs.some(tab => SETTINGS_TAB_TYPES.has(tab.type));
            if (kind === 'knowledge-center') return tabState.tabs.some(tab => KNOWLEDGE_CENTER_TAB_TYPES.has(tab.type));
            return tabState.tabs.some(tab => TOOL_TAB_TYPES.has(tab.type));
          };
          if (keepOpen) workspaceTabMenusHeldOpen.add(kind);
          closeTab(tabId, false, kind === 'settings');
          if (keepOpen && groupStillHasTabs()) {
            // 关闭当前页会重绘整条标签栏；重绘完成后重新锁定并展开新菜单实例。
            workspaceTabMenusHeldOpen.add(kind);
            showWorkspaceTabMenu(kind);
            requestAnimationFrame(() => {
              if (!groupStillHasTabs()) return;
              workspaceTabMenusHeldOpen.add(kind);
              showWorkspaceTabMenu(kind);
              ensureWorkspaceTabMenuHoverGuard(kind);
            });
          }
        }
        return;
      }
      const item = e.target.closest('.workspace-tab-menu-item');
      if (item) {
        e.preventDefault();
        e.stopPropagation();
        const tabId = item.dataset.workspaceTabId;
        if (tabId) switchTab(tabId);
        hideWorkspaceTabMenu(kind);
        return;
      }
    }

    const menu = e.target.closest('#article-tab-floating-menu');
    if (!menu) {
      hideAllTabGroupMenus();
      return;
    }

    const closeAllBtn = e.target.closest('[data-article-close-all]');
    if (closeAllBtn) {
      e.preventDefault();
      e.stopPropagation();
      closeAllArticleTabs();
      return;
    }

    const closeBtn = e.target.closest('.article-tab-menu-close');
    if (closeBtn) {
      e.preventDefault();
      e.stopPropagation();
      const tabId = closeBtn.dataset.closeTab;
      if (tabId) closeTab(tabId);
      return;
    }

    const item = e.target.closest('.article-tab-menu-item');
    if (item) {
      e.preventDefault();
      e.stopPropagation();
      const tabId = item.dataset.articleTabId;
      if (tabId) switchTab(tabId);
      hideArticleTabMenu();
    }
  });

  document.addEventListener('keydown', (e) => {
    const workspaceItem = e.target.closest?.('.workspace-tab-menu .workspace-tab-menu-item');
    if (workspaceItem) {
      const menu = workspaceItem.closest('.workspace-tab-menu');
      const kind = menu?.dataset.workspaceMenu || '';
      const items = Array.from(menu?.querySelectorAll('.workspace-tab-menu-item') || []);
      const index = items.indexOf(workspaceItem);
      if (e.key === 'Escape') {
        e.preventDefault();
        hideWorkspaceTabMenu(kind);
        document.querySelector(`#tab-bar-tabs .${kind}-tab-group`)?.focus();
      } else if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        const tabId = workspaceItem.dataset.workspaceTabId;
        if (tabId) switchTab(tabId);
        hideWorkspaceTabMenu(kind);
      } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        const delta = e.key === 'ArrowDown' ? 1 : -1;
        items[(index + delta + items.length) % items.length]?.focus();
      }
      return;
    }

    const item = e.target.closest?.('#article-tab-floating-menu .article-tab-menu-item');
    if (!item) return;
    const items = Array.from(document.querySelectorAll('#article-tab-floating-menu .article-tab-menu-item'));
    const index = items.indexOf(item);

    if (e.key === 'Escape') {
      e.preventDefault();
      hideArticleTabMenu();
      document.querySelector('#tab-bar-tabs .article-tab-group')?.focus();
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      const tabId = item.dataset.articleTabId;
      if (tabId) switchTab(tabId);
      hideArticleTabMenu();
    } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const delta = e.key === 'ArrowDown' ? 1 : -1;
      items[(index + delta + items.length) % items.length]?.focus();
    }
  });

  window.addEventListener('resize', () => {
    if (document.getElementById('article-tab-floating-menu')?.classList.contains('open')) {
      positionArticleTabMenu();
    }
    ['case-manager', 'court-online', 'research', 'case-files', 'knowledge-center', 'tools', 'settings'].forEach(kind => {
      if (document.getElementById(`${kind}-tab-floating-menu`)?.classList.contains('open')) {
        positionWorkspaceTabMenu(kind);
      }
    });
    if (document.getElementById('ask-skill-menu') && !document.getElementById('ask-skill-menu').hidden) {
      closeAskSkillMenu();
    }
  });
}

// 等待DOM完全加载后执行初始化
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  // DOM已经加载完毕，立即执行
  initApp();
}

