function askCapabilityIcon(name) {
  const paths = {
    scope:'<circle cx="8" cy="8" r="5.2"/><path d="M8 4.5v7M4.5 8h7"/>', terms:'<path d="M3 4h10M3 8h7M3 12h5"/>', case:'<path d="M3 5h10M5 3v10M11 3v10M3 11h10"/>', parallel:'<path d="M3 4h4l2 8h4M3 12h4l2-8h4"/>', entity:'<circle cx="8" cy="5" r="2.3"/><path d="M3.5 13c.5-3 2-4.2 4.5-4.2s4 1.2 4.5 4.2"/>', verify:'<path d="M3 8l3 3 7-7"/>', files:'<path d="M2.5 4.5h4l1.3 1.5h5.7v7h-11z"/>', router:'<circle cx="4" cy="4" r="1.3"/><circle cx="12" cy="4" r="1.3"/><circle cx="8" cy="12" r="1.3"/><path d="m5 5 2.2 5.5M11 5l-2.2 5.5M5.5 4h5"/>', law:'<path d="M4 3h8v10H4zM6 6h4M6 9h4"/>', company:'<path d="M3 13V5h6v8M9 8h4v5M5.5 7h1M5.5 10h1M11 10h.5"/>', history:'<circle cx="8" cy="8" r="5.3"/><path d="M8 5v3.3l2.2 1.5M4.2 3.8 3 3.5l.3 1.2"/>', people:'<circle cx="6" cy="5.5" r="2"/><circle cx="11.2" cy="6.3" r="1.6"/><path d="M2.8 13c.4-2.5 1.6-3.7 3.5-3.7s3.1 1.2 3.5 3.7M9.1 12.8c.3-1.8 1.1-2.8 2.5-2.8 1.3 0 2.2.9 2.5 2.8"/>', risk:'<path d="m8 2 6 11H2zM8 6v3M8 11.5h.01"/>', chart:'<path d="M3 13V9h2v4M7 13V5h2v8M11 13V3h2v10"/>'
  };
  return `<svg viewBox="0 0 16 16" fill="none" aria-hidden="true">${paths[name] || paths.router}</svg>`;
}

function renderAskCapabilityMap() {
  const catalog = document.getElementById('ask-capability-catalog');
  if (!catalog) return;
  const counts = {
    all: ASK_CAPABILITY_ITEMS.length,
    strategy: ASK_CAPABILITY_ITEMS.filter(item => item.type === 'strategy').length,
    tool: ASK_CAPABILITY_ITEMS.filter(item => item.type === 'tool').length,
  };
  Object.entries(counts).forEach(([type, count]) => {
    const button = document.querySelector(`[data-capability-filter="${type}"]`);
    const countEl = button?.querySelector('span');
    if (countEl) countEl.textContent = String(count);
  });
  const query = (document.getElementById('ask-capability-search')?.value || '').trim().toLowerCase();
  const selected = getSelectedAskMcpSources();
  const items = ASK_CAPABILITY_ITEMS.filter(item => {
    if (askCapabilityFilter !== 'all' && item.type !== askCapabilityFilter) return false;
    return !query || [item.title,item.desc,item.trigger,item.path,item.group,...item.tags].join(' ').toLowerCase().includes(query);
  });
  const groups = [...new Set(items.map(item => item.group))];
  catalog.innerHTML = groups.map(group => `<section class="ask-capability-group"><div class="ask-capability-group-head"><h3>${escapeHtml(group)}</h3><span>${items.filter(i => i.group === group).length} 项</span></div><div class="ask-capability-grid">${items.filter(i => i.group === group).map(item => {
    const enabled = item.type === 'strategy' || askSourceMode === 'hybrid' || selected.includes(item.source);
    return `<article class="ask-capability-card" data-type="${item.type}" tabindex="0" role="button" aria-label="查看${escapeHtml(item.title)}详细规则" onclick="openAskStrategyDetail('${escapeHtml(item.title).replace(/'/g, '&#39;')}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openAskStrategyDetail('${escapeHtml(item.title).replace(/'/g, '&#39;')}')}"><div class="ask-capability-card-top"><span class="ask-capability-icon">${askCapabilityIcon(item.icon)}</span><span class="ask-capability-kind">${item.type === 'strategy' ? '策略' : (enabled ? '可调用' : '未选用')}</span></div><h4>${escapeHtml(item.title)}</h4><p>${escapeHtml(item.desc)}</p><dl><div><dt>触发</dt><dd>${escapeHtml(item.trigger)}</dd></div><div><dt>路径</dt><dd>${escapeHtml(item.path)}</dd></div></dl><div class="ask-capability-card-bottom"><div class="ask-capability-tags">${item.tags.map(tag => `<span>${escapeHtml(tag)}</span>`).join('')}</div><span class="ask-capability-more">详细规则 →</span></div></article>`;
  }).join('')}</div></section>`).join('') || '<div class="ask-capability-empty">没有匹配的能力或策略，请换个关键词。</div>';
}

let askCapabilityViewportListenerActive = false;

function updateAskCapabilityBounds() {
  const overlay = document.getElementById('ask-capability-overlay');
  if (!overlay || overlay.hidden) return;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;
  let topBoundary = 0;
  let bottomBoundary = 0;
  const tabBar = document.querySelector('.tab-bar');
  if (tabBar) {
    const style = getComputedStyle(tabBar);
    const rect = tabBar.getBoundingClientRect();
    const isVisible = style.display !== 'none' && style.visibility !== 'hidden'
      && Number(style.opacity || 1) > 0 && rect.width > 0 && rect.height > 0;
    if (isVisible) {
      const isTopNavigation = rect.top <= Math.max(8, viewportHeight * 0.08)
        && rect.bottom < viewportHeight * 0.5;
      const isBottomNavigation = rect.bottom >= viewportHeight - Math.max(8, viewportHeight * 0.08)
        && rect.top > viewportHeight * 0.5;
      if (isTopNavigation) topBoundary = Math.max(0, Math.ceil(rect.bottom));
      if (isBottomNavigation) bottomBoundary = Math.max(0, Math.ceil(viewportHeight - rect.top));
    }
  }
  const safeGap = viewportWidth <= 800 ? 10 : (viewportWidth <= 1180 || viewportHeight <= 760 ? 16 : 28);
  overlay.style.top = `${topBoundary}px`;
  overlay.style.right = '0px';
  overlay.style.bottom = `${bottomBoundary}px`;
  overlay.style.left = '0px';
  overlay.style.setProperty('--ask-capability-safe-gap', `${safeGap}px`);
}

function startAskCapabilityViewportTracking() {
  if (askCapabilityViewportListenerActive) return;
  window.addEventListener('resize', updateAskCapabilityBounds, { passive: true });
  window.visualViewport?.addEventListener('resize', updateAskCapabilityBounds, { passive: true });
  askCapabilityViewportListenerActive = true;
}

function stopAskCapabilityViewportTracking() {
  if (!askCapabilityViewportListenerActive) return;
  window.removeEventListener('resize', updateAskCapabilityBounds);
  window.visualViewport?.removeEventListener('resize', updateAskCapabilityBounds);
  askCapabilityViewportListenerActive = false;
}

async function openAskCapabilityMap() {
  closeAskMcpMenu();
  const overlay = document.getElementById('ask-capability-overlay');
  if (!overlay) return;
  const selected = getSelectedAskMcpSources();
  const mode = document.getElementById('ask-capability-current-mode');
  if (mode) mode.textContent = askSourceMode === 'local_only' ? '仅本地知识库 · 不调用 MCP' : selected.length ? `指定来源 · ${selected.map(s => ASK_MCP_SOURCE_LABELS[s]).join('、')}` : '综合问答 · 自动选择相关 MCP';
  overlay.hidden = false;
  document.body.classList.add('ask-capability-open');
  updateAskCapabilityBounds();
  startAskCapabilityViewportTracking();
  renderAskCapabilityMap();
  await loadActiveAskStrategy();
  setTimeout(() => document.getElementById('ask-capability-search')?.focus(), 80);
}

function closeAskCapabilityMap() {
  if (askStrategyState.dirty && !confirm('策略还有尚未保存的修改，确定关闭吗？')) return;
  closeAskStrategyDetail();
  stopAskCapabilityViewportTracking();
  const overlay = document.getElementById('ask-capability-overlay');
  if (overlay) {
    overlay.hidden = true;
    overlay.style.removeProperty('top');
    overlay.style.removeProperty('right');
    overlay.style.removeProperty('bottom');
    overlay.style.removeProperty('left');
    overlay.style.removeProperty('--ask-capability-safe-gap');
  }
  document.body.classList.remove('ask-capability-open');
  document.getElementById('ask-capability-map-btn')?.focus();
}

function setAskCapabilityFilter(filter, button) {
  askCapabilityFilter = ['all','strategy','tool'].includes(filter) ? filter : 'all';
  document.querySelectorAll('[data-capability-filter]').forEach(item => item.classList.toggle('active', item === button));
  renderAskCapabilityMap();
}

function filterAskCapabilityMap() { renderAskCapabilityMap(); }

function openAskStrategyDetail(title) {
  const item = ASK_CAPABILITY_ITEMS.find(entry => entry.title === title);
  if (!item) return;
  const detail = ASK_STRATEGY_DETAILS[title] || (() => {
    const tool = ASK_TOOL_DETAILS[item.source] || {};
    return { code:tool.code || 'TOOL', summary:item.desc,
      inputs:[`用户问题及触发场景：${item.trigger}`, `当前来源模式与「${item.title}」是否允许调用`],
      rules:tool.rules || [item.desc], branches:[['满足触发条件',item.path],['未满足或未选用','跳过该来源，不产生调用']],
      output:['只保留该来源实际返回且可核验的字段'], fallback:'单源模式返回明确错误；综合模式记录失败并继续其他证据路径。' };
  })();
  document.getElementById('ask-strategy-detail-code').textContent = detail.code || '';
  document.getElementById('ask-strategy-detail-title').textContent = title;
  document.getElementById('ask-strategy-detail-summary').textContent = detail.summary || item.desc;
  const list = values => `<ol>${(values || []).map(value => `<li>${escapeHtml(value)}</li>`).join('')}</ol>`;
  document.getElementById('ask-strategy-detail-body').innerHTML = `
    <section><h4>输入与前置状态</h4>${list(detail.inputs)}</section>
    <section class="wide"><h4>具体判断与执行规则</h4>${list(detail.rules)}</section>
    <section class="wide"><h4>分支与流转</h4><div class="ask-strategy-branches">${(detail.branches || []).map((branch,index) => `<div><span>${String(index + 1).padStart(2,'0')}</span><b>${escapeHtml(branch[0])}</b><i>→</i><p>${escapeHtml(branch[1])}</p></div>`).join('')}</div></section>
    <section><h4>形成的中间结果</h4>${list(detail.output)}</section>
    <section><h4>失败与兜底</h4><p>${escapeHtml(detail.fallback || '不使用未核实内容补写。')}</p></section>`;
  const panel = document.getElementById('ask-strategy-detail');
  askStrategyState.selectedTitle = title;
  askStrategyState.mode = 'view';
  syncAskStrategyWorkspaceControls();
  panel.hidden = false;
  requestAnimationFrame(() => panel.classList.add('open'));
}

function cloneAskStrategy(value) { return JSON.parse(JSON.stringify(value)); }

async function loadActiveAskStrategy(force = false) {
  if (askStrategyState.active && !force) return askStrategyState.active;
  try {
    const response = await fetch('/api/ai-strategies/active');
    const data = await response.json();
    if (!response.ok) throw new Error(data.detail || '读取策略失败');
    askStrategyState.active = data;
    askStrategyState.draft = cloneAskStrategy(data.config);
    askStrategyState.original = JSON.stringify(data.config);
    askStrategyState.dirty = false;
    const badge = document.getElementById('ask-strategy-version');
    if (badge) badge.innerHTML = `策略版本 <b>${escapeHtml(data.version_label)}</b> · 已生效`;
    if (data.recovery_notice) showToast(data.recovery_notice, 'warning');
    syncAskStrategyWorkspaceControls();
    return data;
  } catch (error) {
    const badge = document.getElementById('ask-strategy-version');
    if (badge) badge.innerHTML = '策略版本 <b>后端当前版本</b> · 配置页暂不可用';
    showToast(error.message || '策略配置暂不可用，AI 问答不受影响', 'warning');
    return null;
  }
}

function setAskStrategyWorkspaceMode(mode) {
  if (!['view','edit','test','versions'].includes(mode)) return;
  if (!askStrategyState.active) return void loadActiveAskStrategy(true);
  askStrategyState.mode = mode;
  if (mode === 'view') openAskStrategyDetail(askStrategyState.selectedTitle);
  else if (mode === 'edit') renderAskStrategyEditor();
  else if (mode === 'test') renderAskStrategyTester();
  else loadAskStrategyVersions();
  syncAskStrategyWorkspaceControls();
}

function syncAskStrategyWorkspaceControls() {
  const mode = askStrategyState.mode;
  ['view','edit','test','versions'].forEach(name => document.getElementById(`ask-strategy-${name === 'versions' ? 'versions' : name}-btn`)?.classList.toggle('active', mode === name));
  const save = document.getElementById('ask-strategy-save-btn');
  if (save) save.hidden = mode !== 'edit';
  const state = document.getElementById('ask-strategy-save-state');
  if (state) {
    state.className = askStrategyState.dirty ? 'dirty' : '';
    state.textContent = askStrategyState.dirty ? '尚未保存 · 不会影响当前问答' : `已保存并生效 · ${askStrategyState.active?.version_label || ''}`;
  }
}

