/** AI 增强模型目录缓存（与 AI API 管理页共享后端配置，短时缓存避免频繁请求） */
let askModelCatalogCache = null;
const ASK_MODEL_CATALOG_TTL = 20000;

async function loadAskModelCatalog(force = false) {
  if (!force && askModelCatalogCache && (Date.now() - askModelCatalogCache.at) < ASK_MODEL_CATALOG_TTL) {
    return askModelCatalogCache.data;
  }
  try {
    const response = await fetch('/api/ai-ask-models', { headers: { 'Content-Type': 'application/json' } });
    if (!response.ok) return null;
    const data = await response.json();
    if (!data || !Array.isArray(data.groups)) return null;
    askModelCatalogCache = { at: Date.now(), data };
    return data;
  } catch (_) {
    return null;
  }
}

function clearAskModelCatalogCache() {
  askModelCatalogCache = null;
}

// 管理页修改默认模型/可见性后，回到本页面时立即重新读取，保证实时生效
document.addEventListener('visibilitychange', () => {
  if (!document.hidden) clearAskModelCatalogCache();
});
window.addEventListener('focus', clearAskModelCatalogCache);

function buildAskModelSelect(catalog) {
  const sel = document.getElementById('ask-model-select');
  if (!sel || !catalog || !catalog.groups.length) return;
  sel.innerHTML = catalog.groups.map(group => {
    const options = group.models.map(model => {
      const isDefault = model.value === catalog.default_model;
      return `<option value="${escapeAttr(model.value)}">${escapeHtml(model.label)}${isDefault ? '【默认】' : ''}</option>`;
    }).join('');
    return `<optgroup label="── ${escapeHtml(group.label)} ──">${options}</optgroup>`;
  }).join('') || '<option value="">暂无可选模型</option>';

  // 优先沿用用户曾选择的模型（仍可见时），否则回退到管理页设置的默认模型
  const savedModelRaw = localStorage.getItem('ask-default-model');
  const savedModel = LEGACY_AI_ASK_MODEL_MAP[savedModelRaw] || savedModelRaw;
  const savedExists = savedModel && Array.from(sel.options).some(opt => opt.value === savedModel);
  if (savedExists) sel.value = savedModel;
  else if (catalog.default_model && Array.from(sel.options).some(opt => opt.value === catalog.default_model)) {
    sel.value = catalog.default_model;
  } else {
    sel.value = sel.options[0].value;
  }
  renderAskModelMenu();
  updateAskModelMenuUI();
  return sel.value;
}

/** 清理分组标签上的装饰横线 */
function cleanAskModelGroupLabel(label) {
  return String(label || '其他').replace(/^[\s─]+|[\s─]+$/g, '').trim() || '其他';
}

/** 依据隐藏原生选择框渲染自定义大模型选择列表（分组分栏，参照 MCP 扩展菜单） */
function renderAskModelMenu() {
  const columns = document.getElementById('ask-model-menu-columns');
  const countEl = document.getElementById('ask-model-menu-count');
  const sel = document.getElementById('ask-model-select');
  if (!columns || !sel) return;

  const groups = [];
  const seenValues = new Set();
  for (const option of sel.options) {
    const groupLabel = option.parentElement && option.parentElement.tagName === 'OPTGROUP' ? option.parentElement.label : '';
    let group = groups.find(item => item.rawLabel === groupLabel);
    if (!group) {
      group = { rawLabel: groupLabel, label: cleanAskModelGroupLabel(groupLabel), models: [] };
      groups.push(group);
    }
    if (!option.value || seenValues.has(option.value)) continue;
    seenValues.add(option.value);
    const rawLabel = option.textContent.replace('【默认】', '').trim();
    const unavailable = rawLabel.includes('暂不可用');
    const isDefault = option.textContent.includes('【默认】');
    group.models.push({
      value: option.value,
      label: unavailable ? rawLabel.replace('（暂不可用）', '').trim() : rawLabel,
      unavailable,
      isDefault,
    });
  }
  const visibleGroups = groups.filter(group => group.models.length);

  if (countEl) countEl.textContent = `共 ${seenValues.size} 个模型`;
  columns.innerHTML = visibleGroups.map(group => `
    <div class="ask-model-menu-column">
      <div class="ask-model-menu-col-title">${escapeHtml(group.label)}</div>
      ${group.models.map(model => `
        <button type="button" role="menuitemradio" data-model-value="${escapeAttr(model.value)}" aria-checked="false">
          <span class="ask-model-menu-check"><svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M3.5 8.5 6.5 11.5 12.5 5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>
          <span>
            <strong><span class="ask-model-menu-name">${escapeHtml(model.label)}</span>${model.isDefault ? '<em class="ask-model-menu-badge ask-model-menu-badge-default">默认</em>' : ''}${model.unavailable ? '<em class="ask-model-menu-badge ask-model-menu-badge-off">暂不可用</em>' : ''}</strong>
            <small>${escapeHtml(ASK_MODEL_DESCRIPTIONS[model.value] || ASK_MODEL_GROUP_DESCRIPTIONS[group.label] || '通用问答模型')}</small>
          </span>
        </button>`).join('')}
    </div>`).join('');
}

function toggleAskModelMenu(event) {
  if (event) event.stopPropagation();
  const menu = document.getElementById('ask-model-menu');
  const button = document.getElementById('ask-model-picker-btn');
  if (!menu || !button) return;
  const willOpen = menu.hidden;
  if (willOpen) {
    const columns = document.getElementById('ask-model-menu-columns');
    if (columns && !columns.children.length) renderAskModelMenu();
    closeAskMcpMenu();
  }
  menu.hidden = !willOpen;
  button.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
  if (willOpen) {
    updateAskModelMenuUI();
    const selected = menu.querySelector('.selected') || menu.querySelector('button');
    setTimeout(() => selected?.focus(), 0);
  }
}

function closeAskModelMenu() {
  const menu = document.getElementById('ask-model-menu');
  const button = document.getElementById('ask-model-picker-btn');
  if (menu) menu.hidden = true;
  if (button) button.setAttribute('aria-expanded', 'false');
}

function selectAskModel(value) {
  const sel = document.getElementById('ask-model-select');
  if (!sel || !value) return;
  if (sel.value !== value) {
    sel.value = value;
    sel.dispatchEvent(new Event('change', { bubbles: true }));
  }
  updateAskModelMenuUI();
  closeAskModelMenu();
}

/** 同步自定义列表的选中态与选择器按钮文案 */
function updateAskModelMenuUI() {
  const sel = document.getElementById('ask-model-select');
  const current = sel?.value;
  document.querySelectorAll('#ask-model-menu [data-model-value]').forEach(item => {
    const selected = item.dataset.modelValue === current;
    item.classList.toggle('selected', selected);
    item.setAttribute('aria-checked', selected ? 'true' : 'false');
  });
  const buttonLabel = document.getElementById('ask-model-picker-label');
  if (buttonLabel && current) {
    const option = Array.from(sel.options).find(opt => opt.value === current);
    buttonLabel.textContent = option
      ? option.textContent.replace('【默认】', '').trim()
      : (ASK_MODEL_LABELS[current] || current);
  }
}

async function initAskModelSelect() {
  const sel = document.getElementById('ask-model-select');
  if (!sel) return;

  // 从后端读取（受 AI API 管理页控制）的可见模型列表并重建选项
  const catalog = await loadAskModelCatalog();
  if (catalog) buildAskModelSelect(catalog);

  // 更新标签 + 保存到 localStorage（仅绑定一次）
  const updateModelLabel = function() {
    const val = this.value || sel.value;
    const labelEl = document.getElementById('ask-model-label');
    const hintEl  = document.getElementById('ask-model-hint-reasoner');
    const option = sel.options[sel.selectedIndex];
    const display = option ? option.textContent.replace('【默认】', '').trim() : (ASK_MODEL_LABELS[val] || val);
    if (labelEl) labelEl.textContent = display;
    const pickerLabel = document.getElementById('ask-model-picker-label');
    if (pickerLabel) pickerLabel.textContent = display;
    if (hintEl)  hintEl.style.display = ASK_SLOW_MODELS.has(val) ? 'block' : 'none';
    // 持久化保存
    localStorage.setItem('ask-default-model', val);
    updateAskModelMenuUI();
  };

  if (!sel._bound) {
    sel._bound = true;
    sel.addEventListener('change', updateModelLabel);
  }

  // 立即更新一次
  updateModelLabel.call(sel);
}

async function sendAskQuestion() {
  if (askIsLoading) return;

  await ensureAskHistoryLoaded();

  const input = document.getElementById('ask-input');
  const question = input.value.trim();
  if (!question) return;

  // 读取用户选择的模型
  const modelSelect = document.getElementById('ask-model-select');
  const selectedModel = modelSelect ? modelSelect.value : DEFAULT_AI_ASK_MODEL;
  const requestContext = cloneAskContext(askContext);
  const requestHistoryKey = getAskHistoryKey(requestContext);
  const requestSourceMode = askSourceMode;
  const progressRequestId = `ask_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;

  // 清空输入框，禁用发送按钮
  input.value = '';
  input.style.height = 'auto';
  askIsLoading = true;
  askActiveRequestId = progressRequestId;
  askActiveRequestContext = requestContext;
  askActiveRequestHistoryKey = requestHistoryKey;
  askAbortController = new AbortController();
  const sendButton = document.getElementById('ask-send-btn');
  if (sendButton) sendButton.disabled = true;

  // 显示用户问题（存储时带当前上下文）
  const questionRecord = await appendAskMessage('user', question, null, requestContext, null, null, false, '', '', null, requestHistoryKey);
  // The recovery marker must never point at a question that has not reached the database yet.
  // Otherwise a refresh in this tiny window could incorrectly treat the task as abandoned.
  const questionSave = askHistorySaveQueues.get(requestHistoryKey);
  if (questionSave) await questionSave;
  savePendingAskTask({
    requestId: progressRequestId,
    historyKey: requestHistoryKey,
    questionId: questionRecord.id,
    context: askContext ? JSON.parse(JSON.stringify(askContext)) : null,
    model: selectedModel,
    startedAt: Date.now(),
  });

  // 显示加载中（推理/慢速模型加提示）
  const selectedMcpLabels = requestSourceMode.startsWith('mcp:')
    ? getSelectedAskMcpSources().map(source => ASK_MCP_SOURCE_LABELS[source]) : [];
  const loadingExtra = requestSourceMode === 'local_only'
    ? '（正在仅基于本地知识库检索…）'
    : selectedMcpLabels.length
    ? `（正在从 ${selectedMcpLabels.join('、')} MCP 检索…）`
    : requestSourceMode === 'aluris_only'
    ? '（正在拆解争点、检索正反案例并核验权威原文…）'
    : (requestSourceMode === 'national_law_only'
      ? '（正在仅从国家法规库 MCP 检索现行法条…）'
      : (requestSourceMode === 'mcp_both'
        ? '（正在同时检索法随案例库与国家法规库 MCP…）'
        : (ASK_SLOW_MODELS.has(selectedModel) ? '（深度推理中，约需 15–30 秒…）' : '')));
  showAskLoading(loadingExtra);

  try {
    const formData = new FormData();
    formData.append('question', question);
    formData.append('model', selectedModel);
    formData.append('source_mode', requestSourceMode);
    const followUpContext = buildAskFollowUpContext(requestHistoryKey, questionRecord.id);
    if (followUpContext.length) formData.append('conversation_context', JSON.stringify(followUpContext));
    if (askSkillId) formData.append('skill_id', askSkillId);

    let apiUrl = '/api/ask';

    if (requestSourceMode.startsWith('mcp:') || ['aluris_only', 'national_law_only', 'mcp_both', 'local_only'].includes(requestSourceMode)) {
      apiUrl = '/api/ask';
    } else if (requestContext && requestContext.type === 'article') {
      // 文章内问答模式
      apiUrl = '/api/ask-article';
      formData.append('article_id', requestContext.id);
    } else if (requestContext && requestContext.type === 'tag') {
      // 标签模式
      apiUrl = '/api/ask-tag';
      formData.append('tag', requestContext.tag);
    } else if (requestContext && requestContext.type === 'category') {
      // 二级目录模式
      apiUrl = '/api/ask-category';
      formData.append('category_id', requestContext.catId);
    } else if (requestContext && requestContext.type === 'domain') {
      // 专业领域模式
      apiUrl = '/api/ask-domain';
      formData.append('domain', requestContext.domain);
    } else if (requestContext && requestContext.type === 'author') {
      // 作者模式
      apiUrl = '/api/ask-author';
      formData.append('author', requestContext.author);
    } else if (requestContext && requestContext.type === 'section') {
      // 一级目录模式：走全库 /api/ask（范围太广，用全库接口）
      apiUrl = '/api/ask';
    } else if (requestContext && requestContext.type === 'results') {
      // 当前检索结果模式：后端按文章 ID 白名单严格限制检索和引用范围
      apiUrl = '/api/ask';
      formData.append('article_ids', (requestContext.ids || []).join(','));
    } else if (requestContext && requestContext.type === 'case_files') {
      apiUrl = `/api/case-manager/cases/${Number(requestContext.caseId || 0)}/local-files/ask`;
      formData.append('paths', JSON.stringify(requestContext.paths || []));
      formData.append('include_authoritative', requestContext.includeAuthoritative ? 'true' : 'false');
      formData.append('include_public_web', requestContext.includePublicWeb ? 'true' : 'false');
      const cloudOcrStillAuthorized = Number(requestContext.ocrConsentUntil || 0) > Date.now();
      formData.append('allow_cloud_ocr', cloudOcrStillAuthorized ? 'true' : 'false');
    } else if (requestContext && requestContext.type === 'local_attachments') {
      apiUrl = '/api/ai-ask/local-files/ask';
      formData.append('session_id', requestContext.sessionId || '');
      formData.append('file_ids', JSON.stringify((requestContext.files || []).map(file => String(file.id))));
    }
    // 否则走全库 /api/ask

    // 无论哪种范围模式都携带 request_id，以便“停止生成”时通知后端中断任务
    formData.append('request_id', progressRequestId);
    startAskProgressPolling(progressRequestId);

    const response = await fetch(apiUrl, {
      method: 'POST',
      body: formData,
      signal: askAbortController ? askAbortController.signal : undefined,
    });

    removeAskLoading();

    if (response.status === 499) {
      await appendAskMessage('ai', '⏹ 任务已停止，未生成回答', null, requestContext, null, null, false, '', progressRequestId, null, requestHistoryKey);
      clearPendingAskTask(progressRequestId);
      return;
    }

    if (!response.ok) {
      const errData = await response.json().catch(() => ({}));
      const errMsg = errData.detail || `请求失败（${response.status}）`;
      await appendAskMessage('ai', `⚠️ ${errMsg}`, null, requestContext, null, null, false, selectedModel, progressRequestId, null, requestHistoryKey);
      clearPendingAskTask(progressRequestId);
      return;
    }

    const data = await response.json();
    // 来源标签：文章模式 = 该文章，标签模式 = 检索到的文章列表，全库模式 = 相关文章
    const sources = (data.sources && data.sources.length ? data.sources : null)
      || (data.external_sources && data.external_sources.length ? data.external_sources : null)
      || (data.article_title ? [{ id: data.article_id, title: data.article_title }] : []);
    const citedSources = data.cited_sources || null;
    const trace = Array.isArray(data.research_trace)
      ? data.research_trace.map((step, index) => `（第 ${index + 1} 步）${step}`).join('\n') : '';
    // 只保存后端返回的客观检索步骤；reasoning_content 属模型内部草稿，不能展示或导出。
    const reasoning = trace || null;
    const isReasoningModel = data.is_reasoning_model || false;
    const warningText = Array.isArray(data.warnings) && data.warnings.length
      ? `\n\n> 来源提示：${data.warnings.join('；')}` : '';
    await appendAskMessage('ai', data.answer + warningText, sources, requestContext, citedSources, reasoning, isReasoningModel, data.model_used || selectedModel, progressRequestId, data, requestHistoryKey);
    const finalSave = askHistorySaveQueues.get(requestHistoryKey);
    if (finalSave) await finalSave;
    clearPendingAskTask(progressRequestId);
    if (requestSourceMode.includes('yuandian') || requestSourceMode === 'hybrid') {
      refreshAskYuandianBalance(true);
    }

    // 如果后端触发了备用模型，提示用户
    if (data.model_used && data.model_used !== selectedModel) {
      const fallbackLabel = ASK_MODEL_LABELS[data.model_used] || data.model_used;
      showToast(`⚡ 当前模型暂不可用，已自动切换为 ${fallbackLabel} 完成回答`, 'warning');
    }

  } catch (e) {
    removeAskLoading();
    // 用户点击“停止生成”会主动 abort 请求，不当作网络错误提示
    if (e && e.name === 'AbortError') return;
    try {
      await appendAskMessage(
        'ai',
        '⚠️ 与本地法律操作系统服务的连接意外中断（服务可能正在重启）。请稍候数秒后重新生成；若持续出现，请检查服务状态。',
        null, requestContext, null, null, false, selectedModel, progressRequestId, null, requestHistoryKey
      );
      const finalSave = askHistorySaveQueues.get(requestHistoryKey);
      if (finalSave) await finalSave;
      clearPendingAskTask(progressRequestId);
    } catch (_) {}
  } finally {
    askIsLoading = false;
    askActiveRequestId = null;
    askActiveRequestContext = null;
    askActiveRequestHistoryKey = '';
    askAbortController = null;
    if (sendButton) sendButton.disabled = false;
    input.focus();
  }
}

/* ─────────────────────────────────────────────
   服务器状态自检与重启（点击 logo 触发）
───────────────────────────────────────────── */
let legalKbRestartInProgress = false;

function waitForRestartDelay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function waitForRestartedServer(previousPid) {
  const deadline = Date.now() + 30000;
  while (Date.now() < deadline) {
    await waitForRestartDelay(1000);
    try {
      const response = await fetch(`/api/server-status?_=${Date.now()}`, { cache: 'no-store' });
      if (!response.ok) continue;
      const data = await response.json();
      if (data && data.status === 'running'
        && String(data.pid) !== String(previousPid)
        && data.source_status === 'current') {
        return true;
      }
    } catch (e) {
      // 服务退出和重新监听端口期间连接失败属于正常现象。
    }
  }
  return false;
}

async function restartLegalKnowledgeBase() {
  // 移动端保留原来的轻量状态检查，避免窄屏侧边栏误触发重启。
  if (window.matchMedia('(max-width: 760px)').matches) {
    await checkServerStatus();
    return;
  }
  if (legalKbRestartInProgress) {
    showToast('法律操作系统正在重启，请稍候', 'warning');
    return;
  }
  if (!window.confirm('确定要重启法律操作系统吗？\n\n重启期间页面会短暂断开，恢复后将自动刷新。')) {
    return;
  }

  legalKbRestartInProgress = true;
  showToast('正在重启法律操作系统，请稍候…', 'warning');
  let previousPid = null;
  try {
    const response = await fetch('/api/restart-server', {
      method: 'POST',
      cache: 'no-store',
      headers: { 'X-Legal-KB-Restart': 'confirmed' },
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.detail || data.error || '服务器拒绝了重启请求');
    }
    previousPid = data.current_pid;
  } catch (e) {
    legalKbRestartInProgress = false;
    showToast(`无法重启：${e.message || '请求失败'}`, 'error');
    return;
  }

  const restarted = await waitForRestartedServer(previousPid);
  if (restarted) {
    showToast('法律操作系统已重启，正在刷新页面…', 'success');
    setTimeout(() => window.location.reload(), 600);
    return;
  }

  legalKbRestartInProgress = false;
  showToast('服务恢复时间较长，请稍后手动刷新页面', 'warning');
}

async function checkServerStatus() {
  try {
    const r = await fetch('/api/server-status', { cache: 'no-store' });
    if (r.ok) {
      const data = await r.json();
      if (data && data.status === 'running') {
        const appVersion = data.app_version || '未知版本';
        if (data.restart_required) {
          showToast('检测到源码已更新，服务正在自动重启，请稍候再试', 'warning');
          return;
        }
        const jsVersion = data.frontend_versions && data.frontend_versions['app.js'];
        showToast(`✓ 服务器运行正常（端口 ${data.port || 8000}，后端 ${appVersion}，前端 ${jsVersion || CLIENT_VERSION}，源码已同步）`, 'success');
      } else {
        showToast('服务器状态异常，请手动重启', 'error');
      }
    } else {
      showToast('服务器未响应，请检查是否已启动', 'error');
    }
  } catch (e) {
    showToast('无法连接服务器，请手动重启', 'error');
  }
}

