// 从 localStorage 恢复或初始化已显示过的格言索引列表
function _loadUsedQuoteIndices() {
  try {
    const raw = localStorage.getItem('greeting_used_quotes');
    return raw ? JSON.parse(raw) : [];
  } catch (e) { return []; }
}

function _saveUsedQuoteIndices(arr) {
  try { localStorage.setItem('greeting_used_quotes', JSON.stringify(arr)); } catch (e) {}
}

// 随机取下一句（避免近期重复，50% 用完后重置）
function _pickNextQuote() {
  let used = _loadUsedQuoteIndices();
  const total = GREETING_QUOTES.length;
  // 用完一半后重置
  if (used.length >= Math.floor(total / 2)) {
    used = [];
    _saveUsedQuoteIndices([]);
  }
  let available = GREETING_QUOTES.map((_, i) => i).filter(i => !used.includes(i));
  const idx = available[Math.floor(Math.random() * available.length)];
  used.push(idx);
  _saveUsedQuoteIndices(used);
  return GREETING_QUOTES[idx];
}

// 根据时间获取问候语前缀
function _getTimeGreeting() {
  const h = new Date().getHours();
  if (h >= 5  && h < 9)  return '早上好，';
  if (h >= 9  && h < 11) return '上午好，';
  if (h >= 11 && h < 13) return '中午好，';
  if (h >= 13 && h < 17) return '下午好，';
  if (h >= 17 && h < 19) return '傍晚了，';
  if (h >= 19 && h < 22) return '晚上好，';
  return '夜深了，';
}

// 初始化问候区域
function initGreetingBar() {
  // 恢复用户名
  const savedName = localStorage.getItem('greeting_username');
  const usernameEl = document.getElementById('greetingUsername');
  if (usernameEl && savedName) usernameEl.textContent = savedName;

  // 监听用户名编辑（失焦时保存）
  if (usernameEl) {
    usernameEl.addEventListener('blur', function () {
      const name = this.textContent.trim();
      if (name) localStorage.setItem('greeting_username', name);
      else { this.textContent = '刘律师'; localStorage.setItem('greeting_username', '刘律师'); }
    });
    // Enter 键失焦
    usernameEl.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') { e.preventDefault(); this.blur(); }
    });
  }

  // 时间问候
  const greetingEl = document.getElementById('greetingTimeText');
  if (greetingEl) greetingEl.textContent = _getTimeGreeting();

  // 显示格言（先从当天缓存取，没有就随机新一句）
  const today = new Date().toDateString();
  const cachedDate = localStorage.getItem('greeting_quote_date');
  const cachedQuote = localStorage.getItem('greeting_quote_today');
  let quote;
  if (cachedDate === today && cachedQuote) {
    quote = cachedQuote;
  } else {
    quote = _pickNextQuote();
    localStorage.setItem('greeting_quote_today', quote);
    localStorage.setItem('greeting_quote_date', today);
  }
  const quoteEl = document.getElementById('greetingQuoteText');
  if (quoteEl) quoteEl.textContent = quote;
}

// 点击切换下一条格言（带动画）
function nextGreetingQuote() {
  const quoteContainer = document.getElementById('greetingQuote');
  const quoteEl = document.getElementById('greetingQuoteText');
  if (!quoteEl || !quoteContainer) return;

  const newQuote = _pickNextQuote();
  // 存为今天的格言
  localStorage.setItem('greeting_quote_today', newQuote);
  localStorage.setItem('greeting_quote_date', new Date().toDateString());

  // 触发翻转动画
  quoteContainer.classList.remove('flipping');
  void quoteContainer.offsetWidth; // reflow
  quoteContainer.classList.add('flipping');
  quoteEl.textContent = newQuote;

  setTimeout(() => quoteContainer.classList.remove('flipping'), 400);
}

// DOMContentLoaded 时初始化
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initGreetingBar);
} else {
  initGreetingBar();
}
